import { retainProviderError } from './providerError'
import type { SessionKind } from '@shared/types/providerKind'
import type {
  SemanticLiveBlock,
  SemanticLiveTurn,
  SemanticRuntimeState,
} from '@renderer/session-runtime/state'

import {
  SEMANTIC_ERROR_CAP,
  SEMANTIC_LOG_CAP,
  appendSemanticHistory,
  deriveSemanticTaskSnapshot,
  emptySemanticLookupSnapshot,
  emptySemanticTaskSnapshot,
  flattenSemanticUsage,
  hasPendingSemanticTools,
  semanticToIndex,
} from '@renderer/session-runtime/semantic/helpers'
import { summarizeSemanticEvent } from '@renderer/session-runtime/semantic/summarize'
import { isSemanticRawCaptureEnabled } from '@renderer/session-runtime/semantic/rawCapture'
import { asRecord } from '@shared/lib/asRecord'
import { isAgentProviderKind } from '@shared/types/providerKind'
import { getRendererProviderCapabilities } from '@providers/registry.renderer.capabilities'
import type { SemanticFoldPolicy } from '@shared/types/providerConfig'

// ---------------------------------------------------------------------------
// foldSemanticEvent — the one-session-one-reducer contract
// ---------------------------------------------------------------------------
//
// WHY centralize semantic folding here instead of letting Feed,
// ReaderView, and the proxy debug UI each subscribe separately:
//
// The old architecture created three subtly different truths about the
// same live turn. Feed still derived structure from screen scraping,
// Reader kept a local semantic turn, and the debug panel had yet
// another reducer. That split is exactly how we ended up under-using
// the proxy stream: every UI surface only consumed the subset it
// happened to care about.
//
// The invariant now is "one session => one semantic reducer". Every
// semantic event, including late tool_result and connector/citation
// deltas, must flow through this fold before any UI reads it. If a
// future surface wants live model structure, it should select from
// `runtime.semantic`, not open its own transport subscription.

function eventTargetsDifferentTurn(
  ev: Record<string, unknown>,
  currentTurn: SemanticLiveTurn,
): boolean {
  // The active reducer turn is the UI source of truth. The bundle from
  // 2026-04-24 had a rollout turn (`019dbf35...`) open while proxy
  // block events from older `resp_*` flows were still being published.
  // Letting those block/text/completion events mutate the active turn
  // mixed proxy tool blocks into the rollout live row, which is one of
  // the concrete paths to a message appearing pinned at the bottom.
  //
  // We only reject events that carry an explicit, different turnId.
  // Some legacy semantic events are intentionally turnless and are
  // still reconciled by block index or tool call id; dropping those
  // here would trade the observed cross-turn corruption for missing
  // valid updates.
  return typeof ev.turnId === 'string' && ev.turnId !== currentTurn.turnId
}

// ---------------------------------------------------------------------------
// Per-provider fold policy (2026-07-06 opencode rendering fix)
// ---------------------------------------------------------------------------
//
// Turn ownership used to be hard-gated on `sessionKind === 'codex'` /
// `'claude'` literals at five sites in this reducer. Any third provider
// fell into Codex's strict path by default — but every Codex recovery
// hatch below is keyed on `ev.source === 'proxy'`, and opencode's only
// stream is `source: 'opencode-sse'`, so NO hatch ever applied and
// mismatched events were hard-dropped. The 2026-07-06 opencode debug
// bundle showed the amplification: 200 semantic events → 1 committed
// entry (tool blocks keyed on sessionID mismatched the text turn keyed
// on messageID; the headless keying is fixed separately, but the
// renderer must degrade gracefully, not drop wholesale).
//
// The literals are now a SemanticFoldPolicy on the renderer provider
// capabilities (same pattern as conditionPolicy). Claude and Codex
// policies are bit-identical to the old literal gates; see
// providers/<kind>/renderer/semanticFoldPolicy.ts for each provider's
// rationale.

function resolveFoldPolicy(sessionKind: SessionKind): SemanticFoldPolicy {
  if (isAgentProviderKind(sessionKind)) {
    return getRendererProviderCapabilities(sessionKind).semanticFoldPolicy
  }
  return NON_AGENT_FOLD_POLICY
}

// 'terminal' panes never produce semantic events, so this is a
// type-safety fallback, not a real code path. It reproduces the old
// behavior for non-claude/non-codex kinds exactly (strict turn gates
// with the proxy hatches, no block-level soft-open/replace) so that IF
// a semantic event ever reached a terminal pane, folding would behave
// as before this refactor.
const NON_AGENT_FOLD_POLICY: SemanticFoldPolicy = {
  autoReplaceOnTurnMismatch: false,
  softOpenTurnFromBlockSources: [],
  canReplaceTurnFromBlock: false,
  trustedReplaceSources: ['proxy'],
  allowReplaceOfLiveTurn: false,
}

function isTerminalProxyBlock(block: SemanticLiveBlock): boolean {
  // WHY status/finalized are treated as equivalent here:
  // Codex proxy message items usually reach us as
  // `block_completed` with `finalized: true`, but the upstream
  // Responses item also carries `status: "completed"`. The
  // 2026-05-16T18:42 persistent log showed the dangerous hybrid:
  // a final_answer message block had both terminal block markers,
  // while the turn-level `turn_completed` was missing because the
  // strict headless lifecycle had rejected the finish. If we only
  // trust `endedAt`, that old final answer squats in `currentTurn`
  // forever and every later proxy `resp_*` is dropped as a supposed
  // racing producer.
  return block.finalized === true || block.status === 'completed'
}

function isCompletedProxyTurnReadyToYield(
  currentTurn: SemanticLiveTurn,
): boolean {
  // WHY this ignores `hasPendingSemanticTools` on purpose:
  // the original strict Codex gate exists because two live producers
  // can emit different turn ids for the same user-visible moment
  // (proxy stream vs screen/rollout fallback). Replacing a live turn
  // on a stray mismatched event recreated the 0/1/0/1 semantic row
  // flicker. The 2026-05-16T19:08 bundle proved the opposite failure:
  // a proxy turn with a completed message + completed function_call
  // never received turn_completed, so `hasPendingSemanticTools`
  // treated the completed function_call as "pending" forever and the
  // strict mismatch guard dropped every later `resp_*` block. From the
  // renderer's perspective, "all known blocks are terminal" is the
  // decisive yield signal. If Codex later sends the tool output in a
  // new Responses turn, that new turn must be allowed to become the
  // live owner; keeping the stale function_call mounted is what breaks
  // streaming.
  if (currentTurn.source !== 'proxy') return false
  if (currentTurn.endedAt != null) return false
  const blocks = Object.values(currentTurn.blocks)
  if (blocks.length === 0) return false
  return blocks.every(isTerminalProxyBlock)
}

function isEmptyNonProxyShellTurn(currentTurn: SemanticLiveTurn): boolean {
  return (
    currentTurn.source !== 'proxy' &&
    currentTurn.endedAt === null &&
    currentTurn.text.length === 0 &&
    currentTurn.blockOrder.length === 0 &&
    Object.keys(currentTurn.blocks).length === 0
  )
}

function canReplaceMismatchedTurn(
  policy: SemanticFoldPolicy,
  currentTurn: SemanticLiveTurn,
  ev: Record<string, unknown>,
): boolean {
  // Ended turns are replaceable for EVERY provider (formerly
  // codexCanReplaceEndedTurn). WHY: the strict gate exists to stop
  // concurrent producers from thrashing the single live-turn slot while
  // a response is still streaming. MCP and other client-executed tools
  // have a different lifecycle: the function_call response completes,
  // the UI keeps that turn open as "awaiting tool" so the tool row
  // stays pending, and Codex then sends the function_call_output in the
  // NEXT Responses turn. If we keep applying the strict mismatch rule
  // to an already ended pending-tool turn, every valid follow-up turn
  // is dropped and the feed looks blank except for the phase indicator.
  // `endedAt` separates the safe sequential case from the unsafe
  // concurrent streaming case; live, unended turns still reject
  // mismatched ids unless the source is trusted below.
  if (currentTurn.endedAt != null) return true
  const source = typeof ev.source === 'string' ? ev.source : null
  if (source === null || !policy.trustedReplaceSources.includes(source)) {
    return false
  }
  // Trusted source, live turn. OpenCode sets allowReplaceOfLiveTurn:
  // its single server-authoritative stream has no racing producer, so
  // a new turnId is always a legitimate new turn.
  if (policy.allowReplaceOfLiveTurn) return true
  // Codex (trusted source = proxy, allowReplaceOfLiveTurn = false):
  // only the narrow yield hatches may displace a live turn.
  if (isCompletedProxyTurnReadyToYield(currentTurn)) return true
  // WHY proxy can replace an empty rollout/screen shell:
  // rollout can open a placeholder Codex turn immediately after
  // submit, before the proxy emits the real Responses turn carrying
  // reasoning/message blocks. The strict mismatch guard then drops
  // every proxy block, so the feed shows no streaming. Keep the guard
  // for live content, but let proxy claim ownership while the current
  // non-proxy turn is still empty.
  return isEmptyNonProxyShellTurn(currentTurn)
}

function shouldArchiveReplacedTurn(currentTurn: SemanticLiveTurn): boolean {
  return !isEmptyNonProxyShellTurn(currentTurn)
}

function semanticTurnFromEvent(
  ev: Record<string, unknown>,
  now: number,
  turnId: string,
): SemanticLiveTurn {
  return {
    turnId,
    text: '',
    source: typeof ev.source === 'string' ? ev.source : null,
    blocks: {},
    blockOrder: [],
    stopReason: null,
    usage: null,
    task: emptySemanticTaskSnapshot(),
    lookups: emptySemanticLookupSnapshot(),
    startedAt: now,
    endedAt: null,
    ...(ev.isCompactionSynthesis === true ? { isCompactionSynthesis: true } : {}),
  }
}

export function foldSemanticEvent(
  state: SemanticRuntimeState,
  ev: Record<string, unknown>,
  sessionKind: SessionKind,
  sessionRunId?: string | null,
): SemanticRuntimeState {
  const now = Date.now()
  const policy = resolveFoldPolicy(sessionKind)

  const t = String(ev.type ?? '')
  let flows = state.flows
  let currentTurn = state.currentTurn
  let history = state.history
  let errors = state.errors

  switch (t) {
    case 'prompt_suggestion':
      // Ephemeral next-prompt hint (issue #174). Handled out-of-band in
      // useIpcSubscriptions (it writes the per-session runtime field). It is
      // NOT a turn and must never touch semantic state — returning `state`
      // unchanged keeps it out of currentTurn/history and out of the debug
      // "unknown event" log. The explicit case exists so a future reader
      // doesn't mistake the absence for an oversight.
      return state
    case 'flow_selected': {
      const flowId = String(ev.flowId ?? '')
      const prev = flows[flowId]
      flows = {
        ...flows,
        [flowId]: {
          flowId,
          attribution: 'active',
          reason: String(ev.reason ?? ''),
          turnId: typeof ev.turnId === 'string' ? ev.turnId : null,
          firstSeen: prev?.firstSeen ?? now,
          lastSeen: now,
          bytesEstimate: prev?.bytesEstimate ?? 0,
          chunkCount: prev?.chunkCount ?? 0,
        },
      }
      break
    }
    case 'flow_ignored': {
      const flowId = String(ev.flowId ?? '')
      const prev = flows[flowId]
      flows = {
        ...flows,
        [flowId]: {
          flowId,
          attribution: 'ignored',
          reason: String(ev.reason ?? ''),
          turnId: typeof ev.turnId === 'string' ? ev.turnId : null,
          firstSeen: prev?.firstSeen ?? now,
          lastSeen: now,
          bytesEstimate: prev?.bytesEstimate ?? 0,
          chunkCount: prev?.chunkCount ?? 0,
        },
      }
      break
    }
    case 'turn_started': {
      const turnId = String(ev.turnId ?? '')
      if (!turnId) break
      // Policy-gated turn ownership (see SemanticFoldPolicy and the
      // per-provider semanticFoldPolicy.ts files for the full WHYs).
      //
      // Codex (strict while live): mismatched turnIds are DROPPED
      // while the current turn is still streaming because they come
      // from racing producers (proxy flow + screen fallback, or two
      // concurrent proxy flows). Replacing currentTurn on their say-so
      // wipes the block map the live renderer is already showing —
      // the 0/1/0/1 flicker documented in
      // docs/superpowers/plans/2026-04-17-codex-semantic-flicker-fix.md.
      //
      // Claude (autoReplaceOnTurnMismatch): archive the stuck turn and
      // open the new one. Claude legitimately keeps currentTurn alive
      // across turn boundaries while a cross-turn tool_result is pending
      // (turn_completed below retains the turn when
      // hasPendingSemanticTools is true). The NEXT assistant turn's
      // message_start carries a fresh msg_id that mismatches the
      // pinned turnId; dropping it would silently hide every
      // subsequent Claude turn. This restores the reducer's pre-flicker-fix
      // behavior for Claude only. See
      // docs/superpowers/plans/2026-04-17-claude-semantic-provider-gating.md.
      //
      // OpenCode (trusted single stream): 'opencode-sse' is the only
      // producer, so a mismatched turnId from it is always a
      // legitimate new turn and replaces the live one (archived, not
      // lost). Before this policy existed, opencode inherited Codex's
      // strict path whose proxy-keyed hatches could never fire.
      //
      // Same-turnId refresh (re-entry / source promotion) is
      // identical for both providers.
      // Compaction-synthesis flag rides on `turn_started` only — it's
      // a turn-scope attribute set by ClaudeProxyAdapter from the
      // request-body sniff. Read once here; subsequent delta events
      // don't carry it. Defaults to false on every shape that isn't
      // an explicit boolean true (other source events, older proxy
      // adapters, codex/screen sources) so the placeholder UI fails
      // closed.
      const isCompactionSynthesis = ev.isCompactionSynthesis === true
      if (!currentTurn) {
        currentTurn = {
          turnId,
          text: '',
          source: typeof ev.source === 'string' ? ev.source : null,
          blocks: {},
          blockOrder: [],
          stopReason: null,
          usage: null,
          task: emptySemanticTaskSnapshot(),
          lookups: emptySemanticLookupSnapshot(),
          startedAt: now,
          endedAt: null,
          ...(isCompactionSynthesis ? { isCompactionSynthesis: true } : {}),
        }
      } else if (currentTurn.turnId === turnId) {
        // Same-turn refresh (source promotion / re-entry). Preserve
        // the existing flag rather than letting a flagless later
        // event clear it. The proxy is the only source that sets the
        // flag and it sets it on the very first turn_started.
        currentTurn = {
          ...currentTurn,
          source: typeof ev.source === 'string' ? ev.source : currentTurn.source,
          ...(isCompactionSynthesis ? { isCompactionSynthesis: true } : {}),
        }
      } else if (
        policy.autoReplaceOnTurnMismatch ||
        canReplaceMismatchedTurn(policy, currentTurn, ev)
      ) {
        if (shouldArchiveReplacedTurn(currentTurn)) {
          history = appendSemanticHistory(history, currentTurn)
        }
        currentTurn = semanticTurnFromEvent(ev, now, turnId)
      }
      // Untrusted live mismatched turnId falls through — drop the
      // event. Already-ended pending-tool turns are archived/replaced
      // above; see canReplaceMismatchedTurn for the
      // MCP/function_call_output lifecycle that requires that exception.
      break
    }
    case 'source_changed': {
      if (!currentTurn) break
      if (eventTargetsDifferentTurn(ev, currentTurn)) break
      currentTurn = {
        ...currentTurn,
        source: typeof ev.source === 'string' ? ev.source : currentTurn.source,
      }
      break
    }
    case 'turn_delta': {
      const turnId = typeof ev.turnId === 'string' ? ev.turnId : null
      if (!turnId) break
      // Soft-open allowed when there's no currentTurn (e.g. Codex's
      // rollout agent_message_delta can arrive before task_started).
      //
      // On turnId mismatch (policy-gated, same rules as turn_started):
      //   - Claude: archive the pinned old turn and open a new one.
      //   - Codex: drop while the current turn is still live. Racing
      //     producers must not mutate a currentTurn that doesn't
      //     belong to them (flicker defense). Ended pending-tool turns
      //     are a valid sequential handoff and are replaced.
      //   - OpenCode: its single trusted stream replaces live turns.
      if (!currentTurn) {
        currentTurn = {
          turnId,
          text: '',
          source: typeof ev.source === 'string' ? ev.source : null,
          blocks: {},
          blockOrder: [],
          stopReason: null,
          usage: null,
          task: emptySemanticTaskSnapshot(),
          lookups: emptySemanticLookupSnapshot(),
          startedAt: now,
          endedAt: null,
        }
      } else if (currentTurn.turnId !== turnId) {
        if (
          policy.autoReplaceOnTurnMismatch ||
          canReplaceMismatchedTurn(policy, currentTurn, ev)
        ) {
          if (shouldArchiveReplacedTurn(currentTurn)) {
            history = appendSemanticHistory(history, currentTurn)
          }
          currentTurn = semanticTurnFromEvent(ev, now, turnId)
        } else {
          break
        }
      }
      currentTurn = {
        ...currentTurn,
        text: typeof ev.fullText === 'string' ? ev.fullText : currentTurn.text,
        source: typeof ev.source === 'string' ? ev.source : currentTurn.source,
      }
      break
    }
    case 'block_started': {
      const turnId = typeof ev.turnId === 'string' ? ev.turnId : null
      if (!currentTurn) {
        // WHY block_started can soft-open a turn (policy-gated by
        // source): Codex proxy blocks are the render-critical source,
        // and the 2026-05-16 failure class proved the stricter headless
        // lifecycle can lose a ceremonial turn opener/closer while
        // still delivering block_started/text/tool events. OpenCode
        // needs the same recovery for 'opencode-sse': its headless
        // currently keys tool blocks on sessionID while text rides
        // messageID, so a tool block can be the first event of a turn
        // the reducer ever sees. Claude and fallback producers stay
        // excluded (empty source list) — they have older late-event
        // failure modes where opening from a stray block after
        // currentTurn was already archived would resurrect stale
        // semantic rows.
        const source = typeof ev.source === 'string' ? ev.source : null
        if (
          !turnId ||
          source === null ||
          !policy.softOpenTurnFromBlockSources.includes(source)
        ) {
          break
        }
        currentTurn = semanticTurnFromEvent(ev, now, turnId)
      } else if (eventTargetsDifferentTurn(ev, currentTurn)) {
        // THIS was the primary opencode block-loss site: with the old
        // `sessionKind === 'codex'` literal, every opencode tool block
        // that mismatched the live text turn was hard-dropped here —
        // 200 events in, 1 entry out (2026-07-06 bundle). Now gated by
        // policy.canReplaceTurnFromBlock + the shared replacement rule.
        const turnId = typeof ev.turnId === 'string' ? ev.turnId : null
        if (
          policy.canReplaceTurnFromBlock &&
          turnId &&
          canReplaceMismatchedTurn(policy, currentTurn, ev)
        ) {
          if (shouldArchiveReplacedTurn(currentTurn)) {
            history = appendSemanticHistory(history, currentTurn)
          }
          currentTurn = semanticTurnFromEvent(ev, now, turnId)
        } else {
          break
        }
      }
      const idx = semanticToIndex(ev.blockIndex)
      if (idx === null) break
      // Codex emits `callId` where Claude emits `toolUseId`. Both feed
      // the same downstream tool-result pairing logic — populate
      // whichever the upstream sent, and mirror into the other so
      // existing consumers (e.g. the tool_result match in this file
      // at the toolUseId path) work regardless of source provider.
      const callId = typeof ev.callId === 'string' ? ev.callId : undefined
      const toolUseId = typeof ev.toolUseId === 'string' ? ev.toolUseId : callId
      const messagePhase =
        ev.messagePhase === 'commentary' || ev.messagePhase === 'final_answer'
          ? (ev.messagePhase as 'commentary' | 'final_answer')
          : undefined
      currentTurn = {
        ...currentTurn,
        blocks: {
          ...currentTurn.blocks,
          [idx]: {
            blockIndex: idx,
            kind: String(ev.kind ?? 'other'),
            toolName: typeof ev.toolName === 'string' ? ev.toolName : undefined,
            toolUseId,
            callId,
            itemId: typeof ev.itemId === 'string' ? ev.itemId : undefined,
            messagePhase,
            status: typeof ev.status === 'string' ? ev.status : undefined,
            text: '',
            thinking: '',
            inputJson: '',
          },
        },
        blockOrder: currentTurn.blockOrder.includes(idx)
          ? currentTurn.blockOrder
          : [...currentTurn.blockOrder, idx],
      }
      // Task/lookups derivation intentionally skipped here. The
      // trailing `finalCurrentTurn` computation at the bottom of
      // this reducer unconditionally re-derives from
      // `currentTurn.blocks`, so doing it inline would just be dead
      // work overwritten on the same event. The tool_result branch
      // DOES need its own inline derive because that branch can
      // push the turn to history and set currentTurn=null, skipping
      // the trailing computation.
      break
    }
    case 'text_delta': {
      if (!currentTurn) break
      if (eventTargetsDifferentTurn(ev, currentTurn)) break
      const idx = semanticToIndex(ev.blockIndex)
      if (idx === null) break
      const block = currentTurn.blocks[idx]
      if (!block) break
      currentTurn = {
        ...currentTurn,
        blocks: {
          ...currentTurn.blocks,
          [idx]: {
            ...block,
            text:
              typeof ev.textSoFar === 'string'
                ? ev.textSoFar
                : (block.text ?? '') + String(ev.textDelta ?? ''),
          },
        },
      }
      break
    }
    case 'connector_text_delta': {
      if (!currentTurn) break
      if (eventTargetsDifferentTurn(ev, currentTurn)) break
      const idx = semanticToIndex(ev.blockIndex)
      if (idx === null) break
      const block = currentTurn.blocks[idx]
      if (!block) break
      currentTurn = {
        ...currentTurn,
        blocks: {
          ...currentTurn.blocks,
          [idx]: {
            ...block,
            text:
              typeof ev.connectorTextSoFar === 'string'
                ? ev.connectorTextSoFar
                : (block.text ?? '') + String(ev.connectorTextDelta ?? ''),
          },
        },
      }
      break
    }
    case 'thinking_delta': {
      if (!currentTurn) break
      if (eventTargetsDifferentTurn(ev, currentTurn)) break
      const idx = semanticToIndex(ev.blockIndex)
      if (idx === null) break
      const block = currentTurn.blocks[idx]
      if (!block) break
      currentTurn = {
        ...currentTurn,
        blocks: {
          ...currentTurn.blocks,
          [idx]: {
            ...block,
            thinking:
              typeof ev.thinkingSoFar === 'string'
                ? ev.thinkingSoFar
                : (block.thinking ?? '') + String(ev.thinkingDelta ?? ''),
          },
        },
      }
      break
    }
    case 'citations_delta': {
      if (!currentTurn) break
      if (eventTargetsDifferentTurn(ev, currentTurn)) break
      const idx = semanticToIndex(ev.blockIndex)
      if (idx === null) break
      const block = currentTurn.blocks[idx]
      if (!block) break
      const citations = Array.isArray(ev.citationsSoFar)
        ? [...ev.citationsSoFar]
        : [...(block.citations ?? []), ev.citationsDelta]
      currentTurn = {
        ...currentTurn,
        blocks: {
          ...currentTurn.blocks,
          [idx]: {
            ...block,
            citations,
          },
        },
      }
      break
    }
    case 'signature': {
      if (!currentTurn) break
      if (eventTargetsDifferentTurn(ev, currentTurn)) break
      const idx = semanticToIndex(ev.blockIndex)
      if (idx === null) break
      const block = currentTurn.blocks[idx]
      if (!block) break
      currentTurn = {
        ...currentTurn,
        blocks: {
          ...currentTurn.blocks,
          [idx]: {
            ...block,
            signature: typeof ev.signature === 'string' ? ev.signature : block.signature,
          },
        },
      }
      break
    }
    case 'tool_input_delta': {
      if (!currentTurn) break
      if (eventTargetsDifferentTurn(ev, currentTurn)) break
      const idx = semanticToIndex(ev.blockIndex)
      if (idx === null) break
      const block = currentTurn.blocks[idx]
      if (!block) break
      currentTurn = {
        ...currentTurn,
        blocks: {
          ...currentTurn.blocks,
          [idx]: {
            ...block,
            inputJson:
              typeof ev.inputJsonSoFar === 'string'
                ? ev.inputJsonSoFar
                : (block.inputJson ?? '') + String(ev.partialJson ?? ''),
            toolName: block.toolName ?? (typeof ev.toolName === 'string' ? ev.toolName : undefined),
            toolUseId: block.toolUseId ?? (typeof ev.toolUseId === 'string' ? ev.toolUseId : undefined),
          },
        },
      }
      break
    }
    case 'tool_input_finalized': {
      if (!currentTurn) break
      if (eventTargetsDifferentTurn(ev, currentTurn)) break
      const idx = semanticToIndex(ev.blockIndex)
      if (idx === null) break
      const block = currentTurn.blocks[idx]
      if (!block) break
      currentTurn = {
        ...currentTurn,
        blocks: {
          ...currentTurn.blocks,
          [idx]: {
            ...block,
            inputJson: typeof ev.inputJson === 'string' ? ev.inputJson : block.inputJson,
            inputJsonValid: Boolean(ev.parsed),
            parsedInput: asRecord(ev.parsed) ?? block.parsedInput,
            parseError:
              typeof ev.parseError === 'string' ? ev.parseError : block.parseError,
            finalized: true,
          },
        },
      }
      break
    }
    case 'block_completed': {
      if (!currentTurn) break
      if (eventTargetsDifferentTurn(ev, currentTurn)) break
      const idx = semanticToIndex(ev.blockIndex)
      if (idx === null) break
      const block = currentTurn.blocks[idx]
      if (!block) break
      // Codex sends typed fields for each ResponseItem variant; Claude
      // sends `parsed` for tool input. Merge both shapes here so the
      // renderer doesn't have to branch on provider. `parsed` (Claude)
      // and `parsedArguments` (Codex) populate the same `parsedInput`
      // slot; `inputJson` (Claude) and `argumentsJson` (Codex) populate
      // the same `inputJson` slot.
      const parsedObj =
        asRecord(ev.parsed) ??
        asRecord(ev.parsedArguments) ??
        block.parsedInput
      const argsRaw =
        typeof ev.inputJson === 'string'
          ? ev.inputJson
          : typeof ev.argumentsJson === 'string'
            ? ev.argumentsJson
            : block.inputJson
      const callId = typeof ev.callId === 'string' ? ev.callId : block.callId
      const rawRecord = asRecord(ev.raw)
      const rawCitations = Array.isArray(rawRecord?.citations)
        ? rawRecord.citations
        : null
      currentTurn = {
        ...currentTurn,
        blocks: {
          ...currentTurn.blocks,
          [idx]: {
            ...block,
            kind: typeof ev.kind === 'string' ? ev.kind : block.kind,
            text: typeof ev.text === 'string' ? ev.text : block.text,
            signature: typeof ev.signature === 'string' ? ev.signature : block.signature,
            toolName: typeof ev.toolName === 'string' ? ev.toolName : block.toolName,
            toolUseId:
              typeof ev.toolUseId === 'string'
                ? ev.toolUseId
                : (callId ?? block.toolUseId),
            callId,
            inputJson: argsRaw,
            argumentsJson:
              typeof ev.argumentsJson === 'string' ? ev.argumentsJson : block.argumentsJson,
            inputJsonValid:
              parsedObj === block.parsedInput ? block.inputJsonValid : Boolean(parsedObj),
            parsedInput: parsedObj,
            parseError:
              typeof ev.parseError === 'string' ? ev.parseError : block.parseError,
            status: typeof ev.status === 'string' ? ev.status : block.status,
            finalized: true,
            citations: rawCitations ? [...rawCitations] : block.citations,
            // Codex-specific typed variant payloads. Forward as-is;
            // the renderer picks the right one based on `kind`.
            output: ev.output !== undefined ? ev.output : block.output,
            webSearchAction:
              ev.webSearchAction && typeof ev.webSearchAction === 'object'
                ? (ev.webSearchAction as SemanticLiveBlock['webSearchAction'])
                : block.webSearchAction,
            imageGeneration:
              ev.imageGeneration && typeof ev.imageGeneration === 'object'
                ? (ev.imageGeneration as SemanticLiveBlock['imageGeneration'])
                : block.imageGeneration,
            localShellCall:
              ev.localShellCall && typeof ev.localShellCall === 'object'
                ? (ev.localShellCall as SemanticLiveBlock['localShellCall'])
                : block.localShellCall,
            reasoningSummary:
              typeof ev.reasoningSummary === 'string'
                ? ev.reasoningSummary
                : block.reasoningSummary,
            reasoningText:
              typeof ev.reasoningText === 'string'
                ? ev.reasoningText
                : block.reasoningText,
          },
        },
      }
      break
    }
    case 'tool_result': {
      // WHY attach results onto the originating tool block instead of creating a
      // fresh pseudo-entry here:
      //
      // The semantic stream's job is to preserve the model's live structure. A
      // tool result is not a new assistant block; it is the resolution of a
      // previous tool_use. Storing it on the tool block keeps the renderer's
      // pairing logic trivial and avoids inventing extra ordering rules in the
      // store. If we later build a richer agent/task panel, it can still derive
      // timeline rows from this normalized shape.
      if (!currentTurn || typeof ev.toolUseId !== 'string') break
      if (eventTargetsDifferentTurn(ev, currentTurn)) break
      const match = Object.entries(currentTurn.blocks).find(([, block]) => block.toolUseId === ev.toolUseId)
      if (!match) break
      const idx = Number(match[0])
      const block = match[1]
      currentTurn = {
        ...currentTurn,
        blocks: {
          ...currentTurn.blocks,
          [idx]: {
            ...block,
            resultContent: typeof ev.content === 'string' ? ev.content : block.resultContent,
            resultIsError: ev.isError === true,
            resultAt: now,
          },
        },
      }
      {
        const derived = deriveSemanticTaskSnapshot(currentTurn.blocks)
        const nextTurn = {
          ...currentTurn,
          task: derived.task,
          lookups: derived.lookups,
        }
        if (nextTurn.endedAt != null && !hasPendingSemanticTools(nextTurn)) {
          history = appendSemanticHistory(history, nextTurn)
          currentTurn = null
        } else {
          currentTurn = nextTurn
        }
      }
      break
    }
    case 'tool_started': {
      const callId = typeof ev.callId === 'string' ? ev.callId : null
      if (!callId) break
      const turnId =
        typeof ev.turnId === 'string'
          ? ev.turnId
          : currentTurn?.turnId ?? `codex-${now}`
      // Policy-gated turn ownership (see turn_started for full
      // rationale). Codex drops live mismatches (flicker defense) but
      // archives/replaces already-ended pending-tool turns; Claude
      // archives and replaces more broadly (self-heals the stuck-
      // pending-tool case); opencode's trusted single stream replaces
      // live turns. tool_started is Codex-only in practice today, but
      // routing through the shared policy keeps this branch consistent
      // with the others and avoids a subtle divergence for future
      // emitters.
      if (!currentTurn) {
        currentTurn = {
          turnId,
          text: '',
          source: typeof ev.source === 'string' ? ev.source : null,
          blocks: {},
          blockOrder: [],
          stopReason: null,
          usage: null,
          task: emptySemanticTaskSnapshot(),
          lookups: emptySemanticLookupSnapshot(),
          startedAt: now,
          endedAt: null,
        }
      } else if (currentTurn.turnId !== turnId) {
        if (
          policy.autoReplaceOnTurnMismatch ||
          canReplaceMismatchedTurn(policy, currentTurn, ev)
        ) {
          if (shouldArchiveReplacedTurn(currentTurn)) {
            history = appendSemanticHistory(history, currentTurn)
          }
          currentTurn = semanticTurnFromEvent(ev, now, turnId)
        } else {
          break
        }
      }
      const existing = Object.values(currentTurn.blocks).find(block => block.toolUseId === callId)
      if (existing) break
      const numericIndices = Object.keys(currentTurn.blocks)
        .map(value => Number(value))
        .filter(value => Number.isFinite(value))
      const nextIndex =
        numericIndices.length > 0 ? Math.max(...numericIndices) + 1 : 0
      const label = typeof ev.label === 'string' ? ev.label : ''
      const toolKind = ev.tool === 'mcp' ? 'mcp_tool_use' : 'tool_use'
      const toolName =
        ev.tool === 'exec'
          ? 'exec_command'
          : ev.tool === 'mcp'
            ? label || 'mcp'
            : label || (typeof ev.tool === 'string' ? ev.tool : 'tool')
      currentTurn = {
        ...currentTurn,
        source: typeof ev.source === 'string' ? ev.source : currentTurn.source,
        blocks: {
          ...currentTurn.blocks,
          [nextIndex]: {
            blockIndex: nextIndex,
            kind: toolKind,
            toolName,
            toolUseId: callId,
            text: '',
            thinking: '',
            inputJson: label,
          },
        },
        blockOrder: [...currentTurn.blockOrder, nextIndex],
      }
      break
    }
    case 'tool_output_delta': {
      if (!currentTurn) break
      const callId = typeof ev.callId === 'string' ? ev.callId : null
      if (!callId) break
      const match = Object.entries(currentTurn.blocks).find(([, block]) => block.toolUseId === callId)
      if (!match) break
      const idx = Number(match[0])
      const block = match[1]
      currentTurn = {
        ...currentTurn,
        blocks: {
          ...currentTurn.blocks,
          [idx]: {
            ...block,
            resultContent:
              typeof ev.textDelta === 'string'
                ? (block.resultContent ?? '') + ev.textDelta
                : block.resultContent,
          },
        },
      }
      break
    }
    case 'tool_completed': {
      if (!currentTurn) break
      const callId = typeof ev.callId === 'string' ? ev.callId : null
      if (!callId) break
      const match = Object.entries(currentTurn.blocks).find(([, block]) => block.toolUseId === callId)
      if (!match) break
      const idx = Number(match[0])
      const block = match[1]
      const nextTurn = {
        ...currentTurn,
        blocks: {
          ...currentTurn.blocks,
          [idx]: {
            ...block,
            resultContent: block.resultContent ?? '',
            resultIsError:
              typeof ev.exitCode === 'number' ? ev.exitCode !== 0 : block.resultIsError,
            resultAt: now,
          },
        },
      }
      // Mirror the Anthropic-style `tool_result` branch above.
      //
      // WHY this matters for MCP/client-executed tools:
      // Codex rollout emits `mcp_tool_call_begin/end` and
      // `exec_command_begin/end` as tool_started/tool_completed
      // side-channel events, not as Claude-shaped `tool_result`
      // entries. The `turn_completed` branch intentionally keeps an
      // ended turn mounted while a client tool is pending so the
      // live row does not disappear. Once `tool_completed` resolves
      // the last pending tool, keeping that ended turn in the
      // single currentTurn slot is wrong: it blocks the renderer
      // from treating the turn as completed-history and makes MCP
      // sessions look like they keep replacing the bottom of the
      // feed instead of growing it. Archive it through the same
      // bounded history path used by `tool_result`; Feed will render
      // that archived copy until JSONL supersedes it.
      {
        const derived = deriveSemanticTaskSnapshot(nextTurn.blocks)
        const completedTurn = {
          ...nextTurn,
          task: derived.task,
          lookups: derived.lookups,
        }
        if (completedTurn.endedAt != null && !hasPendingSemanticTools(completedTurn)) {
          history = appendSemanticHistory(history, completedTurn)
          currentTurn = null
        } else {
          currentTurn = completedTurn
        }
      }
      break
    }
    case 'usage_updated': {
      if (!currentTurn) break
      if (eventTargetsDifferentTurn(ev, currentTurn)) break
      const usage = asRecord(ev.usage)
      if (!usage) break
      currentTurn = { ...currentTurn, usage: flattenSemanticUsage(usage) }
      break
    }
    case 'turn_stopped': {
      if (!currentTurn) break
      if (eventTargetsDifferentTurn(ev, currentTurn)) break
      const stopReason = typeof ev.stopReason === 'string' ? ev.stopReason : null

      // Ghost-render fix (PR-4), narrowed after review: dismiss an unresolved
      // AskUserQuestion only for TERMINAL stops, not normal `tool_use` pauses.
      //
      // WHY this is needed: an AskUserQuestion tool_use BLOCKS the agent and
      // only resolves when a tool_result lands. If the user INTERRUPTS instead
      // of answering (Esc, or just sends a new prompt), NO tool_result is ever
      // emitted, so the block stays `resultAt == null` forever and BlockRow
      // keeps routing it to the live, clickable AskUserQuestionRow — the picker
      // "ghosts" in the feed many messages later (the precise bug reported:
      // "a question being interrupted might still render even tho we are 4
      // messages past").
      //
      // The important constraint: Claude also emits `turn_stopped` for the
      // ordinary assistant stop_reason `tool_use`, which is exactly when a LIVE
      // AskUserQuestion picker first appears. Stamping on that stop would unmount
      // the clickable picker while the terminal is still blocked waiting for an
      // answer. So only non-`tool_use` stops are transcript-backed dismissal
      // signals; `tool_use` is a normal pause, not a cancellation.
      //
      // SCOPED STRICTLY to `toolName === 'AskUserQuestion'`: every OTHER pending
      // tool (a long Bash, an in-flight MCP call) can still legitimately resolve
      // with a late tool_result even across a stop, so stamping them here would
      // DROP their real result and show a tool as "done" with no output. The
      // AskUserQuestion case is unique — it cannot resolve after an interrupt
      // because it needs interactive input that is no longer being collected —
      // which is exactly why this dismissal is safe ONLY for it.
      //
      // Copy-on-write: we only clone `blocks` once we find a block to stamp, so
      // the common no-pending-picker stop allocates nothing new.
      let stoppedBlocks = currentTurn.blocks
      if (stopReason !== 'tool_use') {
        let stampedPicker = false
        for (const [key, block] of Object.entries(currentTurn.blocks)) {
          if (block.toolName === 'AskUserQuestion' && block.resultAt == null) {
            if (!stampedPicker) {
              stoppedBlocks = { ...currentTurn.blocks }
              stampedPicker = true
            }
            // `blocks` is keyed by NUMERIC index; Object.entries hands back string
            // keys, so coerce back to number for the write (same `Number(...)`
            // dance the tool_result branch does above).
            stoppedBlocks[Number(key)] = { ...block, resultAt: now }
          }
        }
      }

      currentTurn = {
        ...currentTurn,
        blocks: stoppedBlocks,
        stopReason,
        endedAt: now,
        // #963/#1040: carried onto the turn (and into history when it
        // archives) so the feed can say the turn was CUT OFF rather than
        // finished — by sleep, or by a stream whose socket died. Dropping the
        // transport case left an unexplained half-answer on desktop and
        // phone, which share this pipeline.
        ...(ev.interruption === 'system-suspended' || ev.interruption === 'transport-error'
          ? { interruption: ev.interruption }
          : {}),
      }
      break
    }
    case 'turn_completed': {
      if (!currentTurn) break
      if (eventTargetsDifferentTurn(ev, currentTurn)) break
      const completedTurn = { ...currentTurn, endedAt: currentTurn.endedAt ?? now }
      if (hasPendingSemanticTools(completedTurn)) {
        currentTurn = completedTurn
      } else {
        history = appendSemanticHistory(history, completedTurn)
        currentTurn = null
      }
      break
    }
    case 'api_error':
    case 'stream_error': {
      const error = retainProviderError(ev, t, state.nextLogId, now, sessionRunId)
      // The same transport event can be replayed. Distinct attempts still have
      // distinct request IDs even when the provider repeats identical prose.
      if (error.requestId && errors.some(prior => prior.id === error.id)) break
      errors = [...errors, error].slice(-SEMANTIC_ERROR_CAP)
      break
    }
  }

  // WHY the trailing derive is conditional on event type:
  //   `deriveSemanticTaskSnapshot` is O(n_blocks) and rebuilds
  //   `toolCallsById` from scratch. At streaming peak we get many
  //   text_delta / thinking_delta / signature events per second that
  //   ONLY mutate fields the derivation doesn't read (block.text,
  //   block.thinking, block.signature). Running the derive on those
  //   events is pure waste. Events in the allow-list below are the
  //   only ones that can change what derive sees — block lifecycle,
  //   tool input (goes into inputJson), finalized parse (TodoWrite
  //   parsedInput), or completed `turn_completed` where the result
  //   is pushed to history even if currentTurn survives this tick.
  //
  //   block_started and tool_result already derive inline, so for
  //   them the trailing run is a second computation — intentional
  //   here, because their inline branch leaves currentTurn with the
  //   derived values and the trailing run is a cheap no-op pass that
  //   keeps this block the single place responsible for derived
  //   fields when currentTurn remains live.
  //
  //   Codex also emits `tool_started` / `tool_output_delta` /
  //   `tool_completed` (non-Anthropic tool lifecycle — see the
  //   `tool_started` / `tool_completed` branches above, which synthesize
  //   tool_use blocks and stamp resultAt / resultIsError). Those MUST be
  //   in this allow-list: without them `deriveSemanticTaskSnapshot`
  //   never sees a new block entering `in_progress`, never sees it
  //   transition to `completed`/`error`, and `lookups.toolCallsById`,
  //   `lookups.resolvedToolUseIds`, `task.activeToolNames`, and
  //   `task.inProgressToolUseIds` go stale until some Anthropic-style
  //   event happens to retrigger derive. The user-visible symptom was
  //   Codex tool rows stuck showing "running" forever after completion.
  const DERIVE_EVENT_TYPES = new Set([
    'block_started',
    'tool_input_delta',
    'tool_input_finalized',
    'tool_result',
    'tool_started',
    'tool_output_delta',
    'tool_completed',
  ])
  const finalCurrentTurn = currentTurn
    ? DERIVE_EVENT_TYPES.has(t)
      ? (() => {
          const derived = deriveSemanticTaskSnapshot(currentTurn.blocks)
          return {
            ...currentTurn,
            task: derived.task,
            lookups: derived.lookups,
          }
        })()
      : currentTurn
    : null

  // No-op short-circuit: every event used to allocate a new log array
  // and bump nextLogId at the top of the function, which meant the
  // returned state was never === state, even for events that changed
  // nothing (tool_result without a matching turn, usage_updated with
  // unchanged usage, etc.). That fired setRuntimes + the whole
  // reactive chain on every dead event — eight of them at bootstrap
  // alone per the 2026-04-20 evidence log.
  //
  // Reference equality on flows/currentTurn/history/errors is the
  // correct signal here because every branch that mutates those
  // fields rebinds the local to a new reference. If all four locals
  // still point at state.* AND finalCurrentTurn is identically
  // currentTurn (the derive skipped), this event was a no-op and we
  // return state unchanged. The log append for the event is skipped
  // too — dead events don't belong in the debug log either.
  if (
    flows === state.flows &&
    finalCurrentTurn === state.currentTurn &&
    history === state.history &&
    errors === state.errors
  ) {
    return state
  }

  const summary = summarizeSemanticEvent(ev)
  // Raw-payload compaction (#375 part C): the log used to retain `raw: ev`
  // unconditionally — 200 full semantic events (text deltas, tool payloads)
  // per session, forever. The compact row (type/ts/summary) is what the
  // debug panels actually render in their list views; the full payload is
  // only worth its heap when someone is actively debugging, so it now rides
  // the dev-debug flag (see rawCapture.ts for why that flag and not a new
  // one).
  const logEntry = {
    id: state.nextLogId,
    type: String(ev.type ?? '?'),
    ts: now,
    summary,
    ...(isSemanticRawCaptureEnabled() ? { raw: ev } : {}),
  }
  const log = [...state.log, logEntry]
  if (log.length > SEMANTIC_LOG_CAP) {
    log.splice(0, log.length - SEMANTIC_LOG_CAP)
  }

  return {
    ...state,
    flows,
    currentTurn: finalCurrentTurn,
    history,
    errors,
    log,
    nextLogId: state.nextLogId + 1,
  }
}

