import { useCallback } from 'react'

import { navigateToAgentIndexTarget } from '@renderer/workspace/agentIndexNavigation'
import type { AgentIndexNavigationIntent } from '@renderer/workspace/agentIndexNavigation'
import { resolveAgentPaneLabel, resolveAgentSessionTarget } from '@renderer/workspace/tile-tree/paneLabels'
import type { WorkspaceSetRuntimes, WorkspaceSetState } from '@renderer/workspace/hook/context'
import { clearPooledSpawnBadge } from '@renderer/workspace/hook/actions/pooledSpawnBadge'
import type { WorkspaceRefs } from '@renderer/workspace/hook/refs'
import type { AgentPaneLabelTarget } from '@renderer/workspace/tile-tree/paneLabels'
import type { WorkspaceState } from '@renderer/workspace/types'
import type { SessionActions } from '@renderer/workspace/hook/actions/session'

export function useAgentIndexNavigationActions(
  setState: WorkspaceSetState,
  setRuntimes: WorkspaceSetRuntimes,
  refs: WorkspaceRefs,
  sessionActions: SessionActions,
  showToast: (message: string, durationMs?: number) => void,
): {
  focusAgentBySessionId: (sessionId: string, intent?: AgentIndexNavigationIntent) => Promise<boolean>
  focusAgentByPaneLabel: (
    label: string,
    intent?: AgentIndexNavigationIntent,
  ) => Promise<boolean>
} {
  const focusTarget = useCallback(
    async (
      resolve: (state: WorkspaceState) => AgentPaneLabelTarget | null,
      intent: AgentIndexNavigationIntent = 'reuse-existing-view',
    ): Promise<boolean> => {
      const initialTarget = resolve(refs.stateRef.current)
      if (!initialTarget) return false
      const initialResult = navigateToAgentIndexTarget(
        refs.stateRef.current,
        initialTarget,
        intent,
      )
      if (!initialResult) return false
      // The destination a `replace-` result would overwrite: the focused
      // lane of the active project. (It used to include the grid's focused
      // pane and the Tile Tabs slot; both died with #992.)
      const destination = (state: WorkspaceState) => JSON.stringify([
        state.activeTabId,
        state.stage.focusedLane,
      ])
      const initialDestination = destination(refs.stateRef.current)

      // Wake unless the runtime says a backend is already up. A parked session
      // survives a restart as metadata with no provider process, and exposing
      // one in a lane un-woken means the first keystroke lands on a dead
      // backend (#690). 'started' is the only status that proves otherwise;
      // 'idle', 'failed' and 'exited' all need the wake path, which is also
      // the retry path. (Until #992 the test was "has a detachedSessions
      // record", a structural stand-in for this.)
      const processStatus = refs.latestRuntimesRef.current[initialTarget.sessionId]?.processStatus
      if (processStatus !== 'started') {
        try {
          // Detached agents survive reload as metadata without a provider
          // process. Wake under the SAME SessionId before exposing one in a
          // lane/grid slot; otherwise the navigation appears to work but the
          // first keystroke lands on a dead backend. ensureSessionLive is also
          // safe for an already-running detached agent, so this single branch
          // covers both fresh and restored workspaces.
          await sessionActions.ensureSessionLive(initialTarget.sessionId, 'agent-index.navigate')
        } catch (error) {
          showToast(
            error instanceof Error && error.message.length > 0
              ? error.message
              : `Could not wake agent ${initialTarget.label}.`,
          )
          return false
        }
      }

      let committed = false
      setState(current => {
        // Re-resolve at commit time because the label is positional. A close,
        // detach, or tab reorder can change what "A2" means while a hibernated
        // target is waking. Never redirect the user's already-confirmed action
        // to a different session just because that new session inherited the
        // coordinate during the await.
        const currentTarget = resolve(current)
        if (currentTarget?.sessionId !== initialTarget.sessionId) return current
        const result = navigateToAgentIndexTarget(
          current,
          currentTarget,
          intent,
        )
        if (!result) return current
        // A wake can take seconds. Replacing a slot is meaningful only for the
        // slot captured when navigation began; focus moving meanwhile must not
        // silently repurpose the user's newly focused pane or Dispatch lane.
        if (result.kind.startsWith('replace-')
          && destination(current) !== initialDestination) return current
        committed = true
        return result.state
      })

      if (!committed) {
        showToast(`Agent index ${initialTarget.label} changed; open the command palette again`)
        return false
      }
      // The session is on screen now, so its "new" badge has been answered
      // (pooledSpawnBadge.ts).
      clearPooledSpawnBadge(setRuntimes, initialTarget.sessionId)
      return true
    },
    [refs.stateRef, sessionActions, setRuntimes, setState, showToast],
  )

  // Both UI coordinates and stable SDK targets use the same wake/commit path.
  // The label resolver retains its positional race guard; the ID resolver can
  // survive a reorder without turning that coordinate into a different agent.
  const focusAgentByPaneLabel = useCallback((label: string, intent?: AgentIndexNavigationIntent) =>
    focusTarget(state => resolveAgentPaneLabel(state, label), intent), [focusTarget])
  const focusAgentBySessionId = useCallback((sessionId: string, intent?: AgentIndexNavigationIntent) =>
    focusTarget(state => resolveAgentSessionTarget(state, sessionId), intent), [focusTarget])
  return { focusAgentByPaneLabel, focusAgentBySessionId }
}

import { getRendererProviderCapabilities } from '@providers/registry.renderer.capabilities'
import { useCallback } from 'react'

import type { ProviderSwitchBatchAgent, SessionId } from '@renderer/workspace/types'
import { DEFAULT_PROVIDER, isAgentProviderKind } from '@shared/types/providerKind'
import type { AgentProviderKind } from '@shared/types/providerKind'
import type { WorkspaceRefs } from '@renderer/workspace/hook/refs'
import type { WorkspaceSetRuntimes, WorkspaceSetState } from '@renderer/workspace/hook/context'
import type { SessionActions } from '@renderer/workspace/hook/actions/session'
import { LOSSY_SWITCH_TOAST_MS, switchAgentProvider } from '@renderer/workspace/hook/actions/providerSwitchCore'
import type { SwitchStrategy } from '@renderer/workspace/hook/actions/providerSwitchCore'
import { pluralAgents } from '@renderer/features/workspace/lib/sessionDisplay'

// Bulk provider switch + remembered-batch return.
//
// This is the "I hit a usage limit" escape hatch: move a whole batch of agents
// from one provider to another in one action, and remember that exact batch
// so it can be sent back later (limit reset) without re-selecting everything.
//
// Both directions go through the SAME single-agent core (switchAgentProvider),
// so "return" is literally the forward switch pointed the other way on a
// remembered set. We deliberately re-translate on return rather than
// snapshot-restoring the pre-switch transcript: the whole point of parking
// agents on the target provider is to KEEP WORKING there, and a snapshot restore
// would silently drop every turn done after the switch.

function providerLabel(kind: AgentProviderKind): string {
  // Registry-derived (#394 phase 4).
  return getRendererProviderCapabilities(kind).shortLabel
}

/**
 * What a batch is allowed to spend, decided ONCE by the modal for the whole
 * batch.
 *
 * WHY the caller owns this instead of the action defaulting it: the two halves
 * cost the user completely different things. `allowSourceTurns` spends the
 * SOURCE provider's quota — the one that is usually exhausted, which is why the
 * transaction defaults it off — and `compactOnArrival` spends the TARGET's.
 * Only the surface that showed the exhaustion banner knows which of those the
 * user just agreed to, and per the spec it asks once for the batch rather than
 * once per agent.
 */
export type BulkSwitchPolicy = {
  allowSourceTurns: boolean
  compactOnArrival: boolean
  sourceCompactionConfirmed: boolean
}

/** The return path has no modal, so it carries the batch's recorded consent.
 *
 *  `allowSourceTurns: false` because the source here is the provider the user
 *  parked on, and a return usually happens because the ORIGINAL provider's
 *  window reset — nothing licenses spending the parking provider's quota, and
 *  the whole feature exists to avoid needing to.
 *
 *  `compactOnArrival` was previously hard-coded to `targetKind === 'claude'`,
 *  which meant one Return click spent Claude quota once per agent and locked
 *  every one of those composers for the arrival wait plus the compaction wait
 *  — minutes each, no cancel — with no checkbox and none of the quota
 *  disclosure the forward modal shows. It now reuses the consent the user gave
 *  for this exact batch. `&& targetKind === 'claude'` still applies because
 *  Claude is the one destination with a compaction the renderer can drive
 *  (compactAfterSwitch reports every other kind as a no-op), so consenting to
 *  it on a Codex return would promise something that cannot happen. */
function returnPolicy(
  targetKind: AgentProviderKind,
  batchConsentedToArrivalCompaction: boolean,
): BulkSwitchPolicy {
  return {
    allowSourceTurns: false,
    compactOnArrival: batchConsentedToArrivalCompaction && targetKind === 'claude',
    sourceCompactionConfirmed: false,
  }
}

/**
 * Build the one toast a bulk operation gets.
 *
 * WHY the reasons ride along instead of only the counts: "Switched 0 agents to
 * Claude (12 failed)" tells the user nothing they can act on, and the core
 * deliberately produces strings that do — the poisoned-carrier abort names its
 * remedy, and the shrink ladder's summary exists so no lossy step is silent.
 * Deduped because a batch usually fails for one shared reason, and capped
 * because PaneToast clamps to three lines and an uncapped list would push the
 * counts out of view.
 */
const MAX_SUMMARY_NOTES = 2

function summarize(
  base: string,
  counts: { skipped: number; failed: number },
  notes: ReadonlySet<string>,
): string {
  const tally: string[] = []
  if (counts.skipped > 0) tally.push(`${counts.skipped} skipped`)
  if (counts.failed > 0) tally.push(`${counts.failed} failed`)
  let message = tally.length > 0 ? `${base} (${tally.join(', ')})` : base
  const shown = [...notes].slice(0, MAX_SUMMARY_NOTES)
  if (shown.length > 0) {
    const remaining = notes.size - shown.length
    message += ` · ${shown.join(' · ')}${remaining > 0 ? ` · +${remaining} more` : ''}`
  }
  return message
}

export function useBulkProviderSwitchActions(
  refs: WorkspaceRefs,
  setState: WorkspaceSetState,
  setRuntimes: WorkspaceSetRuntimes,
  showToast: (message: string, durationMs?: number) => void,
  sessionActions: SessionActions,
): {
  switchAgentsToProvider: (
    sessionIds: SessionId[],
    targetKind: AgentProviderKind,
    policy: BulkSwitchPolicy,
    control?: { shouldStop?: () => boolean },
  ) => Promise<void>
  returnLastProviderSwitchBatch: (control?: { shouldStop?: () => boolean }) => Promise<void>
} {
  const switchAgentsToProvider = useCallback(
    async (
      sessionIds: SessionId[],
      targetKind: AgentProviderKind,
      policy: BulkSwitchPolicy,
      control?: { shouldStop?: () => boolean },
    ) => {
      if (sessionIds.length === 0) return

      // Sequential, not concurrent. switchAgentProvider → replaceSession mutates
      // load-bearing shared state (tile tree, detached map, runtime maps) per
      // agent. Firing N switches at once would make each read a stale snapshot
      // and could drop layout bookkeeping. This mirrors Close Old Agents'
      // sequential close loop and its rationale; a usage-limit escape is rare
      // enough that predictable mutation beats raw speed.
      const switched: ProviderSwitchBatchAgent[] = []
      let failed = 0
      // 'skipped' used to be silently dropped here. Two of the core's most
      // common outcomes — mid-turn, and "still finishing a provider switch" —
      // are skips, not failures, and a batch where every agent was busy would
      // otherwise print "Switched 0 agents" with no hint that anything was
      // even attempted.
      let skipped = 0
      // WHY the strings are kept rather than only counted: the core writes
      // messages that name the exact remedy (the poisoned-carrier abort) and
      // the exact loss (the shrink ladder's summary, added specifically so
      // "no lossy step is silent"). Bulk discarded both and printed
      // "Switched 0 agents to Claude (12 failed)" / "12 raw", which is
      // unactionable — a point the sibling model-switch function in the modal
      // already argues in its own comment. Deduped and capped, because twenty
      // agents usually fail for the same one reason.
      const notes = new Set<string>()
      // Per-strategy tally, not a single "compacted" flag: a batch where nine
      // agents crossed losslessly and two had to be shrunk is a materially
      // different outcome from one where all eleven were shrunk, and the user
      // is the only one who can decide whether the loss mattered.
      const counts: Record<SwitchStrategy, number> = { native: 0, raw: 0, shrunk: 0 }

      // #1271: the modal locks the app while this runs, and with compaction
      // each agent can take up to five minutes, so a batch of N could hold
      // every input for N x 5 min with reload the only way out. The user can
      // now ask to stop: checked BEFORE each agent, never mid-switch, because
      // interrupting a replaceSession could strand the agent between
      // providers. The agent in flight finishes; the rest are not attempted.
      let notAttempted = 0
      for (const [index, sessionId] of sessionIds.entries()) {
        if (control?.shouldStop?.()) {
          notAttempted = sessionIds.length - index
          break
        }
        // Read meta fresh each iteration — earlier switches have already mutated
        // the session map. We capture originalKind/cwd/title BEFORE the switch
        // because afterward this id is dead (replaceSession mints a new one).
        const meta = refs.stateRef.current.sessions[sessionId]
        const originalKind =
          isAgentProviderKind(meta?.kind) ? meta.kind : null

        const result = await switchAgentProvider({
          sessionId,
          targetKind,
          refs,
          setRuntimes,
          sessionActions,
          contextPolicy: {
            allowSourceTurns: policy.allowSourceTurns,
            compactOnArrival: policy.compactOnArrival,
          },
          sourceCompactionConfirmed: policy.sourceCompactionConfirmed,
          onProgress: event => showToast(event.message, 305_000),
          // Arrival compaction fires long after this loop has moved on, so its
          // failure cannot join the batch summary. One toast per failing agent
          // is the honest report: the switch itself succeeded and the pane is
          // live with its full history.
          onArrivalFailure: message => showToast(message),
        })

        // The tally counts exactly the agents the summary counts. A switch that
        // succeeded but lost its meta mid-loop is not in `switched`, so counting
        // its strategy would produce "Switched 2 agents to Claude: 3 native" —
        // a summary that contradicts itself.
        // Branch on status FIRST so each arm narrows cleanly. The old shape
        // folded `&& meta && originalKind` into the success test, which pushed
        // a switched-but-meta-less result into the skipped arm.
        if (result.status === 'failed') {
          failed += 1
          notes.add(result.message)
        } else if (result.status === 'skipped') {
          skipped += 1
          notes.add(result.reason)
        } else if (meta && originalKind) {
          counts[result.strategy] += 1
          if (result.shrinkSummary) notes.add(result.shrinkSummary)
          switched.push({
            sessionId: result.newSessionId,
            cwd: meta.cwd,
            originalKind,
            switchedToKind: targetKind,
            title: meta.title,
          })
        } else {
          // Switched, but its meta vanished mid-loop so it cannot be recorded
          // as a batch member. Counting its strategy would produce a summary
          // that contradicts itself ("Switched 2 agents: 3 native"), and
          // silently dropping it would under-report the work done.
          skipped += 1
          notes.add('An agent switched but was closed before it could be recorded')
        }
      }

      // Replace the remembered batch outright — one level of memory only. If
      // nothing actually switched (all failed/skipped) we leave any prior batch
      // untouched: clobbering it with an empty record would needlessly forget a
      // batch the user might still want to return.
      if (switched.length > 0) {
        setState(prev => ({
          ...prev,
          lastProviderSwitchBatch: {
            id: `provider-switch-${Date.now()}`,
            switchedAt: Date.now(),
            sourceKind: switched[0].originalKind,
            targetKind,
            agents: switched,
            // Recorded so Return can reuse this consent instead of deciding
            // for the user. See returnPolicy.
            compactOnArrival: policy.compactOnArrival,
          },
        }))
      }

      const tally = [
        counts.native > 0 ? `${counts.native} native` : null,
        counts.raw > 0 ? `${counts.raw} raw` : null,
        counts.shrunk > 0 ? `${counts.shrunk} shrunk` : null,
      ].filter(Boolean).join(', ')
      const base = `Switched ${pluralAgents(switched.length)} to ${providerLabel(targetKind)}${tally ? `: ${tally}` : ''}`
      // Notes exist only when some agent's switch lost something; those are the
      // summaries worth reading, so they get the lossy duration.
      const stopped = notAttempted > 0 ? `Stopped: ${pluralAgents(notAttempted)} not attempted. ` : ''
      showToast(stopped + summarize(base, { skipped, failed }, notes), notes.size > 0 || stopped ? LOSSY_SWITCH_TOAST_MS : undefined)
    },
    [refs, sessionActions, setRuntimes, setState, showToast],
  )

  const returnLastProviderSwitchBatch = useCallback(async (control?: { shouldStop?: () => boolean }) => {
    const batch = refs.stateRef.current.lastProviderSwitchBatch
    if (!batch) {
      showToast('No switched batch to return')
      return
    }

    let returned = 0
    let skipped = 0
    let failed = 0
    const notes = new Set<string>()
    // Agents that did NOT make it home. See the batch update below for why
    // these have to survive: this modal is the only return affordance there is.
    const unreturned: typeof batch.agents = []

    // Same stop as the forward switch (#1312 review A): Return runs under the
    // same modal lock. Agents after the stop are NOT attempted and stay in
    // the remembered batch, so a later Return finishes them.
    let notAttempted = 0
    for (const [index, agent] of batch.agents.entries()) {
      if (control?.shouldStop?.()) {
        const rest = batch.agents.slice(index)
        notAttempted = rest.length
        unreturned.push(...rest)
        break
      }
      const meta = refs.stateRef.current.sessions[agent.sessionId]
      // Only return agents still sitting where the forward switch left them.
      // Closed (no meta) or manually-moved (kind changed) agents are skipped so
      // we never yank an agent off a provider the user intentionally chose.
      if (!meta) {
        skipped += 1
        continue
      }
      const currentKind = meta.kind ?? DEFAULT_PROVIDER
      if (currentKind !== agent.switchedToKind) {
        skipped += 1
        continue
      }

      const policy = returnPolicy(agent.originalKind, batch.compactOnArrival)
      const result = await switchAgentProvider({
        sessionId: agent.sessionId,
        targetKind: agent.originalKind,
        refs,
        setRuntimes,
        sessionActions,
        contextPolicy: {
          allowSourceTurns: policy.allowSourceTurns,
          compactOnArrival: policy.compactOnArrival,
        },
        sourceCompactionConfirmed: policy.sourceCompactionConfirmed,
        onProgress: event => showToast(event.message, 305_000),
        onArrivalFailure: message => showToast(message),
      })
      if (result.status === 'switched') {
        returned += 1
        if (result.shrinkSummary) notes.add(result.shrinkSummary)
      } else if (result.status === 'failed') {
        failed += 1
        notes.add(result.message)
        unreturned.push(agent)
      } else {
        notes.add(result.reason)
        // 'skipped' here means the pane refused the switch right now — most
        // often "still finishing a provider switch". It is still sitting on
        // the target provider, so it is still returnable later.
        skipped += 1
        unreturned.push(agent)
      }
    }

    // WHY the batch is trimmed rather than dropped:
    //
    // "Returning consumes the batch" is right only for agents that actually
    // returned. Dropping it wholesale meant a return in which NOTHING came
    // back still destroyed the record, and this modal is the only return
    // affordance in the app — there is no other way to get those agents home.
    //
    // That is not a rare case. Arrival compaction is on by default whenever
    // the largest conversation exceeds 150k chars (the population this
    // feature exists for), and it holds `providerSwitch` set for the arrival
    // readiness wait plus the compaction wait — minutes per pane. Every agent
    // in a batch returned during that window is refused with "This pane is
    // still finishing a provider switch", so returned === 0, and the user
    // lost the batch by clicking the button that was supposed to restore it.
    // Partial returns lost the remainder the same way: 1 of 20 home, 19
    // records discarded.
    //
    // Keeping the unreturned agents means Return stays available and is
    // simply retried. The batch is cleared only once it is empty.
    setState(prev => {
      if (prev.lastProviderSwitchBatch?.id !== batch.id) return prev
      if (unreturned.length === 0) return { ...prev, lastProviderSwitchBatch: null }
      return {
        ...prev,
        lastProviderSwitchBatch: { ...prev.lastProviderSwitchBatch, agents: unreturned },
      }
    })

    const base = `Returned ${pluralAgents(returned)} to ${providerLabel(batch.sourceKind)}`
    const stopped = notAttempted > 0 ? `Stopped: ${pluralAgents(notAttempted)} not returned yet. ` : ''
    showToast(stopped + summarize(base, { skipped, failed }, notes), notes.size > 0 || stopped ? LOSSY_SWITCH_TOAST_MS : undefined)
  }, [refs, sessionActions, setRuntimes, setState, showToast])

  return { switchAgentsToProvider, returnLastProviderSwitchBatch }
}

import { useCallback } from 'react'

import type {
  DispatchGridRow,
  SessionId,
  SessionMeta,
  TabId,
  WorkspaceState,
} from '@renderer/workspace/types'
import { withLaneSession } from '@renderer/workspace/dispatch/tiledDispatchSelectors'
import type { GridShapeRow } from '@renderer/workspace/dispatch/gridShape'
import {
  clampIndexFraction,
  insertLaneRightIntoGrid,
  insertRowBelowInGrid,
  normalizeGridShape,
  removeLaneFromGrid,
  removeRowFromGrid,
  rowIndexForLane,
  rowStartIndex,
  setGridShape,
} from '@renderer/workspace/dispatch/gridShape'
import type {
  WorkspaceSetRuntimes,
  WorkspaceSetState,
} from '@renderer/workspace/hook/context'
import type { WorkspaceRefs } from '@renderer/workspace/hook/refs'
import type { SessionActions } from '@renderer/workspace/hook/actions/session'
import { isProcessSessionKind } from '@shared/types/providerKind'
import { clearPooledSpawnBadge } from '@renderer/workspace/hook/actions/pooledSpawnBadge'

/**
 * Write row METADATA without touching any row length.
 *
 * WHY metadata gets its own writer instead of each reducer spreading `rows`
 * itself: a hand-rolled spread is one keystroke away from also writing a
 * `length`, which silently breaks sum(rows[].length) === lanes.length — the one
 * invariant nothing downstream re-derives. Routing every metadata write through
 * a helper that CANNOT change lengths makes that class of bug unreachable
 * rather than merely unlikely.
 *
 * Normalizes first so a row index is meaningful even against state persisted
 * before the grid existed.
 */
function patchRow(
  prev: WorkspaceState,
  rowIndex: number,
  patch: Partial<Omit<DispatchGridRow, 'length'>>,
): WorkspaceState {
  const tiled = prev.stage
  const grid = normalizeGridShape(tiled)
  if (!Number.isInteger(rowIndex) || rowIndex < 0 || rowIndex >= grid.rows.length) {
    return prev
  }
  return {
    ...prev,
    stage: {
      ...tiled,
      rows: grid.rows.map((row, i) => (i === rowIndex ? { ...row, ...patch } : row)),
      // Carried explicitly: normalizeGridShape may have just split a legacy
      // `ratios` array, and spreading `tiled` alone would put the stale one
      // back beside the fields it was split into.
      laneWeights: grid.laneWeights,
      ratios: undefined,
    },
  }
}

export function useDispatchActions(
  setState: WorkspaceSetState,
  setRuntimes: WorkspaceSetRuntimes,
  refs: WorkspaceRefs,
  ensureSessionLive: SessionActions['ensureSessionLive'],
  showToast: (message: string, durationMs?: number) => void,
): {
  pinSession: (sessionId: SessionId) => void
  unpinSession: (sessionId: SessionId) => void
  setPinnedSessionIds: (ids: SessionId[]) => void
  // ---- Lanes (issue #248) ----
  selectTiledLaneSession: (laneIndex: number, sessionId: SessionId) => Promise<void>
  clearTiledLane: (laneIndex: number) => void
  insertTiledLaneRight: (laneIndex: number) => boolean
  removeTiledLane: (laneIndex: number) => void
  setTiledFocusedLane: (laneIndex: number) => void
  // ---- Grid Dispatch rows (issue #681) ----
  insertDispatchRowBelow: (rowIndex: number) => boolean
  removeDispatchRow: (rowIndex: number) => void
  setDispatchGridShape: (rows: GridShapeRow[]) => boolean
  setDispatchLaneWeights: (weights: number[]) => void
  setDispatchRowIndexFraction: (rowIndex: number, fraction: number) => void
  setDispatchRowHeights: (heights: number[]) => void
  setDispatchRowProjects: (rowIndex: number, tabIds: TabId[]) => void
  setDispatchRowCapChildren: (rowIndex: number, cap: boolean) => void
  toggleDispatchRowExpandedParent: (rowIndex: number, sessionId: SessionId) => void
} {
  // enterDispatchMode, exitDispatchMode, setDispatchScope, focusDispatchSession,
  // enterTiledDispatch and exitTiledDispatch lived here until #992. They
  // turned the lane grid ON and OFF, switched a layout-wide project/global
  // scope, and tracked a classic single-selection focus. The stage is a
  // required field now: nothing is entered or exited, every index lists every
  // project (a row's projectTabIds is the only filter), and the focused lane
  // is the one focus. The entry seed (#977) survives only in the v2 migration.
  //
  // Every reducer below reads and writes `stage` directly. They used to guard
  // on `dispatchMode?.tiled` being present; that guard is gone because the
  // state it protected against can no longer be represented.

  // Assign a lane's agent. NOT exposed on the workspace: every caller must go
  // through `selectTiledLaneSession` below, which wakes a hibernated agent
  // first. Handing out the raw writer is what let four separate call sites
  // place a dead backend in a lane (#690), and a wrapper that can be bypassed
  // only fixes the callers that exist today.
  //
  // Duplicates ARE allowed — the same session may sit
  // in multiple lanes (the views mirror; see DispatchLane). No-op for
  // out-of-range indexes so a stale keybind targeting a since-removed lane is
  // harmless, and a no-op when the lane already shows this session.
  const setTiledLaneSession = useCallback(
    (laneIndex: number, sessionId: SessionId) => {
      let wrote = false
      setState(prev => {
        const tiled = prev.stage
        if (laneIndex < 0 || laneIndex >= tiled.lanes.length) return prev
        if (tiled.lanes[laneIndex]?.selectedSessionId === sessionId) return prev
        wrote = true
        const lanes = tiled.lanes.map((lane, i) =>
          i === laneIndex ? withLaneSession(lane, sessionId) : lane,
        )
        return { ...prev, stage: { ...tiled, lanes } }
      })
      // Placing a session is the user ANSWERING the "new in the pool" badge
      // (#992 §4.3). The index click, lane strip, ⌘N and the ⌥↑/↓ walk place
      // through here; label navigation and every control-plane "show" place
      // through agentIndexNavigation, which clears it the same way. Without
      // that, the chip outlives its question and trains the user to ignore it.
      if (wrote) clearPooledSpawnBadge(setRuntimes, sessionId)
    },
    [setRuntimes, setState],
  )

  /**
   * Put a session into a lane, WAKING it first when it has no backend.
   *
   * Rehydrate deliberately does not respawn parked sessions — they survive a
   * restart as metadata with no provider process (see rehydrate.ts). Something
   * has to wake them before they are used, and agent-index navigation already
   * says exactly why:
   *
   *   "Wake under the SAME SessionId before exposing one in a lane/grid slot;
   *    otherwise the navigation appears to work but the first keystroke lands
   *    on a dead backend."
   *
   * That was true of every OTHER way a session reaches a lane. The index click,
   * the strip click, ⌥↑/↓ and ⌘N all wrote straight through
   * `setTiledLaneSession`, so a hibernated agent could be selected, rendered,
   * and typed into — and main rejected the prompt as "not a live agent session"
   * with `reason: never-owned` (#690). The composer's own retry papers over it
   * inconsistently, which made the failure look intermittent.
   *
   * WHY the wake completes BEFORE the lane is written: writing first exposes a
   * dead pane the user can type into during the gap, which is the very state
   * this is fixing.
   *
   * The cost is paid once per session per app run: after the first wake its
   * runtime reads 'started' and every later selection is the synchronous path.
   * (Until #992 the fork was "is it a detached record", which EVERY lane agent
   * was, so every gesture paid a `session:recover` round-trip and a transient
   * `spawning` flip even for an agent that was already running.)
   */
  const selectTiledLaneSession = useCallback(
    async (laneIndex: number, sessionId: SessionId) => {
      // Already has a backend: stays synchronous, so no coordinate can shift
      // underneath it.
      //
      // The test is the RUNTIME. Until #992 it was "has no detachedSessions
      // record" (i.e. is a tile leaf), which was a structural guess with a
      // documented gap: a leaf whose respawn failed at rehydrate, or whose
      // process died since, was written into the lane un-woken and needed the
      // pane's own Retry. `processStatus` closes that gap — 'failed' and
      // 'exited' now take the wake path below, which is also the retry path —
      // and removes its mirror image, re-waking an agent that was already up.
      // Agent-index navigation uses the identical predicate.
      if (refs.latestRuntimesRef.current[sessionId]?.processStatus === 'started') {
        setTiledLaneSession(laneIndex, sessionId)
        return
      }

      // The gesture targets a (row, column), not a flat index.
      //
      // WHY that distinction matters once the write is async: `lanes` is flat
      // and row-major, so a lane added or removed in an EARLIER row shifts
      // every later index. `setTiledLaneSession`'s bounds check catches an
      // index that fell off the end, but an index that is merely now a
      // DIFFERENT row's lane is still in range — the write would land in the
      // wrong row. Re-deriving from the coordinate after the wake fixes that.
      //
      // The follow is gated on the ROW DESCRIPTOR surviving by reference, not
      // on its index still being in range.
      //
      // WHY reference identity is the right test: a row index is positional and
      // is only stable against changes to row LENGTHS, never to row MEMBERSHIP.
      // Checking range alone drops correctly in a 2-row grid (the stale index
      // falls off the end) and silently writes into the WRONG row from three
      // rows up — removing row 0 of [1,2,2] would have written the agent into
      // what used to be row 2. Every grid mutation preserves untouched row
      // objects (`insertLaneRightIntoGrid`/`removeLaneFromGrid` map, the row ops
      // slice/filter), so identity follows exactly the grow/shrink cases and
      // drops every membership change.
      //
      // Dropping is the honest outcome for a membership change — silently
      // retargeting a slot the user did not choose is the surprise this whole
      // change removes. If rows ever gain durable ids this becomes a real
      // follow instead.
      //
      // The window is NOT narrow, which is why this matters: a cold wake allows
      // up to 30s, and Remove Row / Close Agent sit on a confirmation dialog
      // inside it.
      const before = normalizeGridShape(refs.stateRef.current.stage)
      const rowIndex = rowIndexForLane(before.rows, laneIndex)
      const column = rowIndex >= 0 ? laneIndex - rowStartIndex(before.rows, rowIndex) : -1
      // Checked BEFORE the wake: an unresolvable coordinate can never produce a
      // write, and spawning a provider process only to discard it is waste.
      if (rowIndex < 0 || column < 0) return

      try {
        await ensureSessionLive(sessionId, 'dispatch-lane.select')
      } catch (error) {
        // Do NOT place a session we could not wake: leaving the lane on its
        // previous occupant is honest, where showing a dead pane is not.
        showToast(
          error instanceof Error && error.message.length > 0
            ? error.message
            : 'Could not wake agent.',
        )
        return
      }

      const after = normalizeGridShape(refs.stateRef.current.stage)
      const row = after.rows[rowIndex]
      // Not the same row any more (removed, or displaced by an insert above),
      // or it shrank past the column the user aimed at.
      if (!row || row !== before.rows[rowIndex] || column >= row.length) return
      setTiledLaneSession(rowStartIndex(after.rows, rowIndex) + column, sessionId)
    },
    [refs, ensureSessionLive, showToast, setTiledLaneSession],
  )

  /**
   * Empty ONE lane without ending anything: the occupant returns to the pool
   * alive (#992 §4.4, "Clear Lane"). The lane is NOT removed — Remove Lane
   * owns that — and nothing refills it (#681): the user asked for the space
   * back, not for a different agent in it.
   *
   * WHY this is an action and not just a command-local state write: it is the
   * non-destructive half of a pair whose destructive half (Close Agent and
   * Remove Lane) is an action, and closeAgentRemoveLane's suite pins their
   * shared lane-index semantics. A command-local write would drift from
   * whatever lane validation the close path settles on.
   *
   * No undo entry, deliberately: the undo stack is for CLOSES (things whose
   * sessions are gone). Undoing a lane clear is just selecting the session
   * back into the lane — one click in the index it never left.
   */
  const clearTiledLane = useCallback(
    (laneIndex: number) => {
      setState(prev => {
        const tiled = prev.stage
        if (laneIndex < 0 || laneIndex >= tiled.lanes.length) return prev
        if (tiled.lanes[laneIndex]?.selectedSessionId === undefined) return prev
        const lanes = tiled.lanes.map((lane, i) =>
          i === laneIndex ? { ...lane, selectedSessionId: undefined } : lane,
        )
        return { ...prev, stage: { ...tiled, lanes } }
      })
    },
    [setState],
  )

  /**
   * Insert ONE lane beside an existing lane without changing command focus.
   *
   * WHY this has an explicit lane index rather than reading focusedLane inside
   * the helper: command invocation captures one coherent UI snapshot. Passing
   * that coordinate makes a stale invocation harmless instead of letting a
   * later focus movement insert beside a different agent than the user saw.
   */
  const insertTiledLaneRight = useCallback(
    (laneIndex: number) => {
      let inserted = false
      setState(prev => {
        const tiled = prev.stage
        const next = insertLaneRightIntoGrid(tiled, laneIndex)
        if (!next) return prev
        inserted = true
        return { ...prev, stage: next }
      })
      // Zustand's workspace setter applies functional updaters synchronously,
      // so this reports the reducer's ACTUAL admission rather than the command
      // palette's earlier render snapshot. That distinction is what prevents a
      // stale programmatic invocation from announcing a lane that was refused
      // at the ceiling or after its coordinate disappeared.
      return inserted
    },
    [setState],
  )

  /**
   * Remove ONE lane, shrinking the grid by one.
   *
   * The splice/clamp/weight rules live in `removeLaneFromGrid` so they can be
   * tested as a pure function; this is only the state wiring. A null return
   * means the removal was refused (at the lane floor, or a bad index), in
   * which case we hand back `prev` untouched rather than writing an identical
   * object and forcing a re-render.
   */
  const removeTiledLane = useCallback(
    (laneIndex: number) => {
      setState(prev => {
        const tiled = prev.stage
        const next = removeLaneFromGrid(tiled, laneIndex)
        if (!next) return prev
        return { ...prev, stage: next }
      })
    },
    [setState],
  )

  // Move keyboard-selection focus between lanes. Clamped. Must never touch
  // any lane's selection — that's what keeps lanes independent.
  const setTiledFocusedLane = useCallback(
    (laneIndex: number) => {
      setState(prev => {
        const tiled = prev.stage
        const clamped = Math.max(0, Math.min(laneIndex, tiled.lanes.length - 1))
        if (clamped === tiled.focusedLane) return prev
        return { ...prev, stage: { ...tiled, focusedLane: clamped } }
      })
    },
    [setState],
  )

  // ---- Grid Dispatch row reducers (issue #681) ----
  //
  // Structural changes (insert/remove row, reshape) delegate to gridShape, which
  // returns a COMPLETE coherent shape or null. Row METADATA changes (project,
  // density, sizing) never touch lengths, so they go through patchRow below.
  // Keeping those two categories apart is what stops a metadata write from
  // silently breaking sum(rows[].length) === lanes.length.

  const insertDispatchRowBelow = useCallback(
    (rowIndex: number) => {
      let inserted = false
      setState(prev => {
        const tiled = prev.stage
        const next = insertRowBelowInGrid(tiled, rowIndex)
        if (!next) return prev
        inserted = true
        return { ...prev, stage: next }
      })
      // Reports the reducer's ACTUAL admission rather than the palette's earlier
      // render snapshot, so a stale invocation cannot announce a row that was
      // refused at the row or lane ceiling. Same contract as
      // insertTiledLaneRight.
      return inserted
    },
    [setState],
  )

  const removeDispatchRow = useCallback(
    (rowIndex: number) => {
      setState(prev => {
        const tiled = prev.stage
        const next = removeRowFromGrid(tiled, rowIndex)
        if (!next) return prev
        return { ...prev, stage: next }
      })
    },
    [setState],
  )

  const setDispatchGridShape = useCallback(
    (rows: GridShapeRow[]) => {
      let applied = false
      setState(prev => {
        const tiled = prev.stage
        const next = setGridShape(tiled, rows)
        if (!next) return prev
        applied = true
        return { ...prev, stage: next }
      })
      return applied
    },
    [setState],
  )

  const setDispatchLaneWeights = useCallback(
    (weights: number[]) => {
      setState(prev => {
        const tiled = prev.stage
        // Length-checked here as well as on read: a weights array that does not
        // describe every lane is dropped by normalizeGridShape anyway, and
        // storing one would make the next drag start from a silently discarded
        // value.
        if (weights.length !== tiled.lanes.length) return prev
        return { ...prev, stage: { ...tiled, laneWeights: weights } }
      })
    },
    [setState],
  )

  const setDispatchRowIndexFraction = useCallback(
    (rowIndex: number, fraction: number) => {
      setState(prev => patchRow(prev, rowIndex, { indexFraction: clampIndexFraction(fraction) }))
    },
    [setState],
  )

  const setDispatchRowHeights = useCallback(
    (heights: number[]) => {
      setState(prev => {
        const tiled = prev.stage
        const grid = normalizeGridShape(tiled)
        if (heights.length !== grid.rows.length) return prev
        return {
          ...prev,
          stage: {
            ...tiled,
            rows: grid.rows.map((row, i) => ({ ...row, height: heights[i] })),
          },
        }
      })
    },
    [setState],
  )

  const setDispatchRowProjects = useCallback(
    (rowIndex: number, tabIds: TabId[]) => {
      setState(prev => {
        // Empty normalizes to ABSENT here, not to an empty array: "any project"
        // must have exactly one representation or every reader needs to test
        // for both.
        // (Binding used to PROMOTE a layout-wide scope to 'global' so a row
        // bound to another project did not list nothing. The scope is gone —
        // every index already lists every project — so this is the whole write.)
        return patchRow(prev, rowIndex, {
          projectTabIds: tabIds.length > 0 ? tabIds : undefined,
        })
      })
    },
    [setState],
  )

  const setDispatchRowCapChildren = useCallback(
    (rowIndex: number, cap: boolean) => {
      // Flipping the row default also clears its per-parent overrides: those
      // are exceptions TO the default, so carrying them across a change of the
      // default would leave the row in a state the toggle cannot describe.
      setState(prev => patchRow(prev, rowIndex, { capChildren: cap, expandedParents: undefined }))
    },
    [setState],
  )

  const toggleDispatchRowExpandedParent = useCallback(
    (rowIndex: number, sessionId: SessionId) => {
      setState(prev => {
        const tiled = prev.stage
        const current = normalizeGridShape(tiled).rows[rowIndex]?.expandedParents ?? []
        const next = current.includes(sessionId)
          ? current.filter(id => id !== sessionId)
          : [...current, sessionId]
        return patchRow(prev, rowIndex, {
          expandedParents: next.length > 0 ? next : undefined,
        })
      })
    },
    [setState],
  )

  // Pin reducers. Three callbacks share the same invariant:
  //   pinnedSessionIds[i] -> state.sessions[id] exists. Any session kind can be
  //   pinned (#865); terminals were excluded until shells became full Dispatch
  //   rows (#671) made that exclusion a leftover of the #152 v1 scope.
  //
  // append-on-pin ordering is the user-facing spec: "order you pin in is
  // the order it displays." First pin lands at index 0; subsequent pins
  // sink to the tail. Reordering is intentionally out of scope for v1.
  const pinSession = useCallback(
    (sessionId: SessionId) => {
      setState(prev => {
        if (prev.pinnedSessionIds.includes(sessionId)) return prev
        const meta = prev.sessions[sessionId]
        if (!meta || !isProcessSessionKind(meta.kind)) return prev
        return {
          ...prev,
          pinnedSessionIds: [...prev.pinnedSessionIds, sessionId],
        }
      })
    },
    [setState],
  )

  const unpinSession = useCallback(
    (sessionId: SessionId) => {
      setState(prev => {
        if (!prev.pinnedSessionIds.includes(sessionId)) return prev
        return {
          ...prev,
          pinnedSessionIds: prev.pinnedSessionIds.filter(id => id !== sessionId),
        }
      })
    },
    [setState],
  )

  const setPinnedSessionIds = useCallback(
    (ids: SessionId[]) => {
      setState(prev => {
        // Filter against the live sessions snapshot at write time so a
        // stale modal selection (the user pinned X, then X was killed
        // before they hit Enter) can never reintroduce an orphan into
        // the array. Same defensive shape as buildPinnedDispatchRows
        // at render time.
        const filtered = ids.filter(id => {
          const meta = prev.sessions[id]
          return meta !== undefined && isProcessSessionKind(meta.kind)
        })
        // Deduplicate while preserving caller order (first occurrence wins).
        // The modal already enforces this client-side, but a programmatic
        // caller could pass duplicates; keeping the dedupe here means the
        // invariant "pinnedSessionIds is unique" doesn't depend on the caller.
        const seen = new Set<SessionId>()
        const ordered: SessionId[] = []
        for (const id of filtered) {
          if (seen.has(id)) continue
          seen.add(id)
          ordered.push(id)
        }
        // No-op fast path: if the resulting list matches what's already there
        // (same ids in the same order), don't churn the reference — same
        // pattern as the rest of the reducers in this file.
        if (
          ordered.length === prev.pinnedSessionIds.length &&
          ordered.every((id, i) => id === prev.pinnedSessionIds[i])
        ) {
          return prev
        }
        return { ...prev, pinnedSessionIds: ordered }
      })
    },
    [setState],
  )

  return {
    pinSession,
    unpinSession,
    setPinnedSessionIds,
    selectTiledLaneSession,
    clearTiledLane,
    insertTiledLaneRight,
    removeTiledLane,
    setTiledFocusedLane,
    insertDispatchRowBelow,
    removeDispatchRow,
    setDispatchGridShape,
    setDispatchLaneWeights,
    setDispatchRowIndexFraction,
    setDispatchRowHeights,
    setDispatchRowProjects,
    setDispatchRowCapChildren,
    toggleDispatchRowExpandedParent,
  }
}

import { useCallback } from 'react'

import { emptyRuntime } from '@renderer/session-runtime/state'
import type { SessionRuntime } from '@renderer/session-runtime/state'
import type { SessionId } from '@renderer/workspace/types'
import type { WorkspaceSetRuntimes } from '@renderer/workspace/hook/context'

// Draft input + image actions.
//
// Called from TileLeaf on every onChange/onKeyDown that mutates the
// composer text. Lives in runtime so it survives TileLeaf unmount
// when the user switches tabs. See SessionRuntime.draftInput for
// the reasoning.
//
// Draft version counter — bumped on every draft change so the save
// effect picks it up without watching the full runtimes object.

/**
 * Last cleared draft per session, so `Clear Composer` is reversible.
 *
 * WHY module state rather than a `SessionRuntime` field: nothing RENDERS from
 * this. Undo is a command, exactly like `undo-close`, not an affordance drawn
 * in the pane — so putting it on the runtime would add a field every reducer,
 * every debug bundle and every replay fixture carries around for a value the
 * UI never reads. Keyed by sessionId and deliberately not cleaned up on
 * session close: the map holds one short string per session the user actually
 * cleared, and a stale entry is unreachable once its session is gone.
 *
 * WHY it survives a subsequent edit rather than being dropped the moment the
 * user types again: the mistake this exists for is "I cleared, then realised."
 * Clearing the stash on the next keystroke would make undo unavailable in
 * precisely the moment the user reaches for it.
 */
const clearedDrafts = new Map<SessionId, string>()

export function useDraftActions(
  setRuntimes: WorkspaceSetRuntimes,
  updateRuntime: (sessionId: SessionId, patch: Partial<SessionRuntime>) => void,
  bumpDraftChanges: () => void,
): {
  setDraftInput: (sessionId: SessionId, text: string) => void
  setDraftImages: (
    sessionId: SessionId,
    next:
      | SessionRuntime['draftImages']
      | ((prev: SessionRuntime['draftImages']) => SessionRuntime['draftImages']),
  ) => void
  clearDraft: (sessionId: SessionId) => boolean
  undoClearDraft: (sessionId: SessionId) => boolean
} {
  const setDraftInput = useCallback(
    (sessionId: SessionId, text: string) => {
      updateRuntime(sessionId, { draftInput: text })
      bumpDraftChanges()
    },
    [bumpDraftChanges, updateRuntime],
  )

  const setDraftImages = useCallback(
    (
      sessionId: SessionId,
      next:
        | SessionRuntime['draftImages']
        | ((prev: SessionRuntime['draftImages']) => SessionRuntime['draftImages']),
    ) => {
      setRuntimes(prev => {
        const current = prev[sessionId] ?? emptyRuntime()
        const draftImages =
          typeof next === 'function'
            ? next(current.draftImages)
            : next
        return {
          ...prev,
          [sessionId]: {
            ...current,
            draftImages,
          },
        }
      })
      bumpDraftChanges()
    },
    [bumpDraftChanges, setRuntimes],
  )

  /**
   * Empty the composer, stashing what was there. Returns false when there was
   * nothing to clear, so the caller can stay silent instead of toasting about
   * a no-op.
   *
   * Reads the previous draft through `setRuntimes` rather than taking it as an
   * argument: the command layer has no live runtime snapshot, and passing a
   * stale draft in would stash the wrong text.
   */
  const clearDraft = useCallback(
    (sessionId: SessionId) => {
      let cleared = false
      setRuntimes(prev => {
        const current = prev[sessionId] ?? emptyRuntime()
        if (current.draftInput.length === 0 && current.draftImages.length === 0) {
          return prev
        }
        cleared = true
        // Do NOT overwrite an existing stash with an empty string. Clearing a
        // composer that holds only images has `draftInput === ''`, and blindly
        // stashing that destroyed the text an earlier clear had saved — while
        // the toast still promised it was restorable, and Undo then no-opped
        // in total silence. An empty clear has nothing worth remembering, so
        // it leaves the previous stash alone.
        if (current.draftInput.length > 0) clearedDrafts.set(sessionId, current.draftInput)
        return {
          ...prev,
          [sessionId]: { ...current, draftInput: '', draftImages: [] },
        }
      })
      if (cleared) bumpDraftChanges()
      return cleared
    },
    [bumpDraftChanges, setRuntimes],
  )

  /**
   * Put back the last cleared draft. Returns false when there is nothing
   * stashed — the Undo command is always visible (mirroring `undo-close`,
   * which also carries no `when` guard), so it has to no-op gracefully rather
   * than assume a stash exists.
   *
   * Deliberately does NOT restore draft images: they are large binary
   * attachments and re-inserting them silently could resurrect an image the
   * user removed on purpose in the same gesture. Text is the thing people
   * mourn losing.
   */
  const undoClearDraft = useCallback(
    (sessionId: SessionId) => {
      const stashed = clearedDrafts.get(sessionId)
      if (stashed === undefined || stashed.length === 0) return false
      // SWAP, not a one-way restore. Undo deliberately survives further
      // typing, so "clear, start retyping, change your mind" is a sequence the
      // description actively invites — and a plain overwrite silently threw
      // away whatever had been typed since, with the stash already consumed so
      // there was no second undo. For a command whose entire purpose is not
      // losing typed text, losing typed text was the wrong failure mode.
      // Swapping makes it a toggle: run it again to get back where you were.
      let previous = ''
      setRuntimes(prev => {
        const current = prev[sessionId] ?? emptyRuntime()
        previous = current.draftInput
        return { ...prev, [sessionId]: { ...current, draftInput: stashed } }
      })
      if (previous.length > 0) clearedDrafts.set(sessionId, previous)
      else clearedDrafts.delete(sessionId)
      bumpDraftChanges()
      return true
    },
    [bumpDraftChanges, setRuntimes],
  )

  return { setDraftInput, setDraftImages, clearDraft, undoClearDraft }
}

import { DEFAULT_PROVIDER, isAgentProviderKind } from '@shared/types/providerKind'
import { useCallback } from 'react'

import { emptyRuntime } from '@renderer/session-runtime/state'
import type { SessionRuntime } from '@renderer/session-runtime/state'
import type { SessionId } from '@renderer/workspace/types'
import type { Entry } from '@shared/types/transcript'
import {
  admitMappedEntries,
  isPaginationAnchor,
  reindexToolsAfterMerge,
  type CommittedSeenLedger,
} from '@renderer/session-runtime/ingest/committedRecords'
import {
  isUuidTrimmed,
  noteOlderHistoryPrepend,
  releaseTrimmedUuid,
} from '@renderer/session-runtime/liveEntryWindow'
import { getRendererProviderCapabilities } from '@providers/registry.renderer.capabilities'
import {
  deriveAgentWorkContext,
  ingestWorktreeRawEvent,
} from '@shared/work-context/tracker'

import type { WorkspaceSetRuntimes } from '@renderer/workspace/hook/context'
import type { WorkspaceRefs } from '@renderer/workspace/hook/refs'
import * as perf from '@renderer/performance/client'
import type { SessionFeed } from '@shared/sessionFeed/SessionFeed'

// Older history loader — called by Feed's scroll handler when the
// user scrolls near the top.
//
// Walks the rollout stream linearly; the rolling Codex turn id is
// maintained from both `turn_context` and payload-level `turn_id`
// markers so paged response_items get the same ownership metadata as
// entries that arrived live.

/** What one older-history request did. `failed` means the page could not be
 *  read (the IPC rejected, or the transcript could not be parsed); `skipped`
 *  means nothing was asked (no provider session, nothing older, a load
 *  already running). Only `failed` is worth telling the user about. */
export type OlderHistoryLoadResult = 'loaded' | 'skipped' | 'failed'

export function useHistoryActions(
  setRuntimes: WorkspaceSetRuntimes,
  refs: WorkspaceRefs,
  updateRuntime: (sessionId: SessionId, patch: Partial<SessionRuntime>) => void,
  // The SessionFeed the workspace mounted (#1177): older pages are read through
  // the contract, like every other session read, instead of `window.api`.
  // Required here, unlike the initial loader's default, because this is a hook
  // and its one caller already holds the feed from context.
  feed: Pick<SessionFeed, 'loadHistory'>,
): {
  loadOlderHistory: (sessionId: SessionId) => Promise<OlderHistoryLoadResult>
} {
  const loadOlderHistory = useCallback(
    async (sessionId: SessionId): Promise<OlderHistoryLoadResult> => {
      const span = perf.span('workspace.history.loadOlder', { sessionId })
      const currentState = refs.stateRef.current
      const meta = currentState.sessions[sessionId]
      const runtime = refs.latestRuntimesRef.current[sessionId] ?? emptyRuntime()
      if (!meta) {
        span.end({ skipped: 'missing-meta' })
        return 'skipped'
      }

      const kind = meta.kind ?? DEFAULT_PROVIDER
      // No providerRuntime check: a terminal-runtime pane never mounts the
      // Feed that pages, but its runtime holds the same durable history as
      // any agent's (see loadInitialHistoryForSession), so a caller that
      // does page it gets the same answer.
      if (!isAgentProviderKind(kind) || !meta.providerSessionId) {
        span.end({ skipped: 'unsupported-or-missing-provider-session', kind })
        return 'skipped'
      }
      if (!runtime.hasOlderHistory || runtime.loadingOlderHistory) {
        span.end({
          skipped: runtime.loadingOlderHistory ? 'already-loading' : 'no-older-history',
          kind,
        })
        return 'skipped'
      }
      if (!runtime.historyOldestMarker) {
        updateRuntime(sessionId, { hasOlderHistory: false, loadingOlderHistory: false })
        span.end({ skipped: 'missing-marker', kind })
        return 'skipped'
      }

      updateRuntime(sessionId, { loadingOlderHistory: true })

      try {
        const chunk = await feed.loadHistory({
          sessionId,
          transcript: { kind, cwd: meta.cwd, providerSessionId: meta.providerSessionId },
          beforeMarker: runtime.historyOldestMarker,
          // The byte position of that marker's line when we have it — the
          // loader anchors exactly there instead of hunting the marker,
          // which is what keeps paging exact and terminating when markers
          // repeat (see historyLoader.ts). Absent → marker-only fallback.
          beforeOffset: runtime.historyOldestOffset ?? undefined,
          limit: 200,
        })

        const seen = (refs.seenUuidsRef.current[sessionId] ??= new Set())
        const seenLedger: CommittedSeenLedger = {
          seen,
          isTrimmed: uuid => isUuidTrimmed(sessionId, uuid),
          releaseTrimmed: uuid => releaseTrimmedUuid(sessionId, uuid),
        }
        const prepend: Entry[] = []
        const worktreesResult = await window.api.gitWorktrees(meta.cwd)
        const worktrees = worktreesResult.ok ? worktreesResult.worktrees : []
        let workActivity = runtime.workActivity
        let workContext = runtime.workContext
        let oldestMarker: string | null = runtime.historyOldestMarker
        let oldestOffset: number | null = runtime.historyOldestOffset
        let cursorSelected = false
        // Registry-owned mapper (#394 phase 2b). Chunk-scoped: starts
        // with a null turn cursor, which for Codex means pagination
        // chunks that begin mid-turn rely on `payload.turn_id` — the
        // only durable source in many chunks (see the mapper's cursor
        // sequencing docs). Without stamping these older response
        // items, the live feed and paged history disagree about which
        // committed messages belong to the Codex task, and duplicate
        // suppression becomes dependent on where the scroll boundary
        // landed.
        const mapper = getRendererProviderCapabilities(kind).createTranscriptEntryMapper()

        for (const [rawIndex, rawEntry] of chunk.entries.entries()) {
          // Older-history pagination walks records that predate the current
          // tail. Use them only to backfill an unknown badge; never let old
          // worktree evidence replace fresher live/current context.
          if (!workContext) {
            workActivity = ingestWorktreeRawEvent({
              state: workActivity,
              raw: rawEntry,
              worktrees,
              sessionCwd: meta.cwd,
            })
            workContext = deriveAgentWorkContext(workActivity)
          }

          const { entries: mapped, historyMarker: marker } = mapper.map(rawEntry)
          // Marker policy (site-owned): only the FIRST kept line of the
          // chunk replaces the pagination cursor — `oldestMarker` must
          // stay pinned to where the NEXT older page should start.
          // WHY selection needs its own latch: markers are not unique. The
          // first older record may have the SAME marker as the current anchor,
          // at an earlier byte position. Marker equality would leave selection
          // armed and let a later record move the cursor forward within this
          // page, or prevent its offset from advancing at all on commit.
          if (!cursorSelected && isPaginationAnchor(mapped, marker)) {
            cursorSelected = true
            oldestMarker = marker
            // The offset of THIS raw line, not the chunk's first: the
            // cursor is the first kept line, and leading records the
            // mapper drops (Codex turn_context, Claude snapshots) would
            // otherwise make the loader's marker-at-offset check fail and
            // silently degrade every page to the slow scan.
            oldestOffset = chunk.offsets?.[rawIndex] ?? null
          }
          // ASYMMETRIC dedupe (#375 part B), the `older` rule in
          // session-runtime/ingest/committedRecords.ts: a uuid the live window
          // TRIMMED is still in `seen` (it must never re-append at the tail via
          // a live replay burst), but this older-history path is exactly how
          // trimmed entries come back — in order, at the head. So trimmed
          // membership OVERRIDES seen here, and the uuid leaves the trimmed
          // set as it reloads (it is back in the window and re-enters the trim
          // cycle normally). Reloaded entries get their marker rider back so
          // they are re-trimmable later. Indexing happens once below, against
          // the committed window.
          prepend.push(...admitMappedEntries(mapped, marker, 'older', seenLedger).admitted)
        }

        // Suspend live-window trimming for a grace period: the user just
        // paged history in and is reading the TOP of the window — the exact
        // rows a trim would remove, with no shrink-anchoring in Feed to
        // keep their scroll position. See liveEntryWindow.ts for the WHY.
        if (prepend.length > 0) noteOlderHistoryPrepend(sessionId)

        setRuntimes(prev => {
          const current = prev[sessionId] ?? emptyRuntime()
          const entries = prepend.length > 0 ? [...prepend, ...current.entries] : current.entries
          // Fold the paged-in entries' tool blocks into the live indices.
          // This was a latent gap (pagination never indexed, so a paged-in
          // tool_result row couldn't resolve its command cross-entry) that
          // became LOAD-BEARING with the live window: a trim rebuilds the
          // indices from retained entries only, so reloading the trimmed
          // region MUST restore its pairings or the reloaded rows would
          // paint permanently degraded. Same in-place-mutate + version-bump
          // contract as the ingest sites (see entries.ts).
          //
          // INTENTIONAL BEHAVIOR CHANGE for never-trimmed sessions too
          // (evaluated for the #511 review, kept deliberately): scroll-back
          // in an ordinary session now also indexes what it pages in, so
          // rows that previously painted the degraded generic fallback
          // (Read/Edit/TodoWrite/git/AskUserQuestion cards missing their
          // source-tool metadata) now render rich.
          //
          // Since #1177 the fold REBUILDS the indexes in window order instead
          // of appending the page's blocks (reindexToolsAfterMerge explains
          // why; the phone already did this). The earlier argument that an
          // old block can never overwrite a live pairing assumed ids never
          // repeat; the rebuild is correct either way and identical when they
          // don't. A page with no tool block leaves the maps and the version
          // alone. The version bump rides a state update that already
          // replaces the entries array, so Feed re-renders exactly once either
          // way — it changes what mounted tool rows can RESOLVE, not how often
          // they paint.
          const toolIndexChanged = prepend.length > 0 && reindexToolsAfterMerge(prepend, entries, {
            toolUseIndex: current.toolUseIndex,
            toolResultIndex: current.toolResultIndex,
          })
          return {
            ...prev,
            [sessionId]: {
              ...current,
              entries,
              toolIndexVersion: toolIndexChanged
                ? current.toolIndexVersion + 1
                : current.toolIndexVersion,
              historyOldestMarker: oldestMarker ?? current.historyOldestMarker,
              // Commit the selected pair even when only the byte position
              // changed. Repeated marker strings still represent distinct
              // physical records; retaining the old offset re-requests a page.
              historyOldestOffset: cursorSelected
                ? oldestOffset
                : current.historyOldestOffset,
              // Trust `chunk.hasMore` as the authoritative "is there
              // more history to fetch" signal. The old rule OR'd in
              // `prepend.length === 0` — i.e. "re-enable loading
              // when nothing renderable came back" — which loops
              // forever when the loader legitimately returns a tail
              // chunk whose entries are all non-renderable Codex
              // metadata (turn_context, session_meta, event_msg
              // variants the mapper drops). Those chunks have
              // `hasMore: false`; honoring that ends the pagination
              // even when `prepend.length === 0`. If a chunk with
              // `hasMore: true` produces zero renderable entries,
              // we still fall through with hasOlderHistory=true and
              // the user can request the next chunk manually.
              hasOlderHistory: chunk.hasMore,
              loadingOlderHistory: false,
              workContext,
              workActivity,
            },
          }
        })
        span.end({
          kind,
          fetched: chunk.entries.length,
          prepended: prepend.length,
          hasMore: chunk.hasMore,
        })
        return 'loaded'
      } catch (err) {
        span.fail(err, { kind })
        console.warn('[history] load older failed', err)
        // `hasOlderHistory` is left as it was, so the next scroll to the top
        // retries. The caller is TOLD (#1250 row 12): this used to be the
        // whole of it, and the feed then looked as if it had nothing older.
        updateRuntime(sessionId, { loadingOlderHistory: false })
        return 'failed'
      }
    },
    [refs.latestRuntimesRef, refs.seenUuidsRef, refs.stateRef, setRuntimes, updateRuntime, feed],
  )

  return { loadOlderHistory }
}

import { useCallback } from 'react'

import { CLIPBOARD_WRITE_FAILED } from '@renderer/lib/clipboardFailure'
import { emptyRuntime } from '@renderer/session-runtime/state'
import type { SessionId } from '@renderer/workspace/types'
import {
  assistantUuidsWithText,
  extractAssistantByUuid,
} from '@renderer/lib/copyAssistant'

import type { WorkspaceSetRuntimes } from '@renderer/workspace/hook/context'
import type { WorkspaceRefs } from '@renderer/workspace/hook/refs'

// ---- Copy Assistant picker actions ----
//
// pickerEnter      — toggles the picker on/off. On entry, picks
//                    the most-recent assistant entry with text.
//                    No-op (picker stays null) if the session has
//                    no assistant entries with text yet.
// pickerMove       — direction is +1 (Down → newer) or -1 (Up →
//                    older). Walks the assistantUuidsWithText
//                    list; clamps at the ends rather than wrapping
//                    (less surprising, matches macOS list pickers).
// pickerConfirm    — copies the selected entry's text to clipboard,
//                    shows a pane toast, clears the picker.
// pickerCancel     — clears the picker without copying.
//
// setCodeBlockPicker — bare setter for the Copy Code Block picker.
//                    Unlike the assistant picker above, this one has
//                    no Enter/Move logic in the store: code blocks
//                    have no transcript identity, so enumeration and
//                    navigation are DOM-driven and live in the
//                    copy-code-block feature + useKeybinds. The store
//                    only parks the current `selectedId` (or null).

export function usePickerActions(
  setRuntimes: WorkspaceSetRuntimes,
  refs: WorkspaceRefs,
  showPaneToast: (sessionId: SessionId, message: string, durationMs?: number) => void,
): {
  pickerEnter: (sessionId: SessionId) => void
  pickerMove: (sessionId: SessionId, direction: -1 | 1) => void
  pickerCancel: (sessionId: SessionId) => void
  pickerConfirm: (sessionId: SessionId) => Promise<void>
  setCodeBlockPicker: (
    sessionId: SessionId,
    picker: { selectedId: string } | null,
  ) => void
} {
  const pickerEnter = useCallback(
    (sessionId: SessionId) => {
      setRuntimes(prev => {
        const current = prev[sessionId] ?? emptyRuntime()
        if (current.assistantPicker) {
          const renderedViewLeases = { ...current.renderedViewLeases }
          delete renderedViewLeases['copy-assistant-message']
          return {
            ...prev,
            [sessionId]: { ...current, renderedViewLeases, assistantPicker: null },
          }
        }
        const uuids = assistantUuidsWithText(current.entries)
        if (uuids.length === 0) return prev
        return {
          ...prev,
          [sessionId]: {
            ...current,
            renderedViewLeases: {
              ...current.renderedViewLeases,
              'copy-assistant-message':
                (current.renderedViewLeases['copy-assistant-message'] ?? 0) + 1,
            },
            assistantPicker: { selectedUuid: uuids[uuids.length - 1] },
          },
        }
      })
    },
    [setRuntimes],
  )

  const pickerMove = useCallback(
    (sessionId: SessionId, direction: -1 | 1) => {
      setRuntimes(prev => {
        const current = prev[sessionId] ?? emptyRuntime()
        const picker = current.assistantPicker
        if (!picker) return prev
        const uuids = assistantUuidsWithText(current.entries)
        if (uuids.length === 0) return prev
        const idx = uuids.indexOf(picker.selectedUuid)
        if (idx === -1) {
          // Selected uuid disappeared mid-flight — snap to the
          // newest available so the user keeps a stable reference.
          return {
            ...prev,
            [sessionId]: {
              ...current,
              assistantPicker: { selectedUuid: uuids[uuids.length - 1] },
            },
          }
        }
        const nextIdx = Math.max(0, Math.min(uuids.length - 1, idx + direction))
        if (nextIdx === idx) return prev
        return {
          ...prev,
          [sessionId]: {
            ...current,
            assistantPicker: { selectedUuid: uuids[nextIdx] },
          },
        }
      })
    },
    [setRuntimes],
  )

  const pickerCancel = useCallback(
    (sessionId: SessionId) => {
      setRuntimes(prev => {
        const c = prev[sessionId]
        if (!c?.assistantPicker) return prev
        const renderedViewLeases = { ...c.renderedViewLeases }
        delete renderedViewLeases['copy-assistant-message']
        return { ...prev, [sessionId]: { ...c, renderedViewLeases, assistantPicker: null } }
      })
    },
    [setRuntimes],
  )

  const pickerConfirm = useCallback(
    async (sessionId: SessionId) => {
      const current = refs.latestRuntimesRef.current[sessionId]
      if (!current?.assistantPicker) return
      const text = extractAssistantByUuid(
        current.entries,
        current.assistantPicker.selectedUuid,
      )
      // Clear the picker first so the UI returns to normal even if
      // the clipboard write fails (rare — only with a permission
      // denial, which we surface via toast).
      setRuntimes(prev => {
        const c = prev[sessionId]
        if (!c) return prev
        const renderedViewLeases = { ...c.renderedViewLeases }
        delete renderedViewLeases['copy-assistant-message']
        return { ...prev, [sessionId]: { ...c, renderedViewLeases, assistantPicker: null } }
      })
      if (!text) {
        showPaneToast(sessionId, 'Nothing to copy')
        return
      }
      try {
        await navigator.clipboard.writeText(text)
        showPaneToast(sessionId, 'Copied assistant message')
      } catch {
        // The shared sentence (#1421 review c), with its advice.
        showPaneToast(sessionId, CLIPBOARD_WRITE_FAILED)
      }
    },
    [refs.latestRuntimesRef, setRuntimes, showPaneToast],
  )

  const setCodeBlockPicker = useCallback(
    (sessionId: SessionId, picker: { selectedId: string } | null) => {
      setRuntimes(prev => {
        const c = prev[sessionId]
        if (!c) return prev
        // No-op guard: avoid a runtimes object churn (and the Feed
        // re-render it triggers) when the selection didn't actually
        // change — Up/Down at a clamp end calls this with the same id.
        if ((c.codeBlockPicker?.selectedId ?? null) === (picker?.selectedId ?? null)) {
          return prev
        }
        const renderedViewLeases = { ...c.renderedViewLeases }
        if (picker && !c.codeBlockPicker) {
          // WHY the code-block picker owns a render lease:
          // code block identity lives in rendered DOM attributes, not in the
          // transcript. In Hybrid, opening the picker must keep TileLeaf
          // mounted for arrow navigation, highlighting, clipboard lookup, and
          // stale-id recovery. Clearing the picker releases the lease so Hybrid
          // can fall back to the raw terminal immediately after the copy/cancel
          // interaction finishes.
          renderedViewLeases['copy-code-block'] =
            (renderedViewLeases['copy-code-block'] ?? 0) + 1
        } else if (!picker && c.codeBlockPicker) {
          delete renderedViewLeases['copy-code-block']
        }
        return {
          ...prev,
          [sessionId]: {
            ...c,
            renderedViewLeases,
            codeBlockPicker: picker,
          },
        }
      })
    },
    [setRuntimes],
  )

  return { pickerEnter, pickerMove, pickerCancel, pickerConfirm, setCodeBlockPicker }
}

import { describeRewindAttachmentLoss } from '@renderer/workspace/hook/actions/rewindAttachmentLoss'
import { sessionMcpOverrides } from '@renderer/workspace/mcpDomains'
import { getRendererProviderCapabilities } from '@providers/registry.renderer.capabilities'
import { tldrIdentityForSession } from '@renderer/features/tldr/identity'
import { DEFAULT_PROVIDER, isAgentProviderKind } from '@shared/types/providerKind'
import type { AgentProviderKind, AgentProviderRuntime } from '@shared/types/providerKind'
import type { RewindPromptAddress } from '@shared/types/transcriptRewind'
import { useCallback } from 'react'

import type { SessionId } from '@renderer/workspace/types'
import type { ClaudeDraftImage } from '@renderer/session-runtime/state'
import { commandTargetSessionIdForState } from '@renderer/workspace/hook/selectors/commandTargetSessionId'

import type { WorkspaceSetRuntimes } from '@renderer/workspace/hook/context'
import type { WorkspaceRefs } from '@renderer/workspace/hook/refs'
import type { SessionActions } from '@renderer/workspace/hook/actions/session'
import { resumableProviderSessionId } from '@renderer/workspace/providerSessionIdentity'
import {
  LOSSY_SWITCH_TOAST_MS,
  switchAgentProvider,
  type SwitchAgentProviderResult,
} from '@renderer/workspace/hook/actions/providerSwitchCore'
import { providerChoiceLabel } from '@renderer/workspace/providerChoices'

// Provider-level actions on the focused pane.
//
// switchSessionProvider   — translate one captured session to an explicit
//                           provider/runtime destination and re-home its pane.
// reloadFocusedAgent      — respawn the focused agent session with
//                           resume so the conversation history replays.
// rewindFocusedToPrompt   — user picks a past user prompt; pane
//                           re-homes onto a truncated transcript with
//                           the prompt prefilled as an unsent draft.
// removeFocusedCyberPolicyBlock — Codex-only: drop the last model step
//                           after a cyber_policy complete and re-home.

// Domain outcomes are shared by UI commands and external control. A returned
// Promise<void> cannot distinguish a declined operation from a replacement;
// the transport must not infer success from a toast or a changed session census.
export type AgentLifecycleResult =
  | { status: 'completed'; sourceSessionId: SessionId; newSessionId: SessionId }
  | { status: 'skipped'; reason: string }
  | { status: 'failed'; message: string }

export function useProviderActions(
  refs: WorkspaceRefs,
  setRuntimes: WorkspaceSetRuntimes,
  showPaneToast: (sessionId: SessionId, message: string, durationMs?: number) => void,
  sessionActions: SessionActions,
): {
  switchSessionProvider: (
    sourceSessionId: SessionId,
    targetKind: AgentProviderKind,
    targetProviderRuntime?: AgentProviderRuntime,
  ) => Promise<SwitchAgentProviderResult>
  reloadSessionAgent: (sourceSessionId: SessionId) => Promise<AgentLifecycleResult>
  rewindSessionToPrompt: (sourceSessionId: SessionId, anchor: RewindPromptAddress) => Promise<AgentLifecycleResult>
  undoSessionRewind: (sourceSessionId: SessionId) => Promise<AgentLifecycleResult>
  removeCodexCyberPolicyBlock: (sourceSessionId: SessionId) => Promise<AgentLifecycleResult>
  reloadFocusedAgent: () => Promise<void>
  rewindFocusedToPrompt: (
    anchor: RewindPromptAddress,
  ) => Promise<void>
  undoLastRewind: () => Promise<void>
  removeFocusedCyberPolicyBlock: () => Promise<void>
} {
  const switchSessionProvider = useCallback(async (
    sourceSessionId: SessionId,
    targetKind: AgentProviderKind,
    targetProviderRuntime?: AgentProviderRuntime,
  ): Promise<SwitchAgentProviderResult> => {
    const current = refs.stateRef.current
    const meta = current.sessions[sourceSessionId]
    if (!meta) return { status: 'skipped', reason: 'Session no longer exists' }

    const sourceKind = meta.kind ?? DEFAULT_PROVIDER
    if (!isAgentProviderKind(sourceKind)) {
      // Non-agent (terminal) pane — nothing to switch.
      showPaneToast(sourceSessionId, 'Only agent panes can switch provider')
      return { status: 'skipped', reason: 'Only agent panes can switch provider' }
    }
    const result = await switchAgentProvider({
      sessionId: sourceSessionId,
      targetKind,
      targetProviderRuntime,
      refs,
      setRuntimes,
      sessionActions,
      onProgress: event => showPaneToast(sourceSessionId, event.message, 305_000),
    })

    if (result.status === 'switched') {
      // The strategy rides the pane toast because it is the only place a
      // per-agent cost can be reported (#821, spec §Renderer: "Pane toast per
      // agent shows its strategy"). `native` is silent on purpose — the common,
      // lossless case should not add noise to every switch; the two lossy
      // strategies name themselves, and `shrunk` carries the one line saying
      // what the ladder had to remove.
      const note = result.strategy === 'native'
        ? ''
        : ` · ${result.strategy}${result.shrinkSummary ? ` (${result.shrinkSummary})` : ''}`
      showPaneToast(
        result.newSessionId,
        `Switched to ${providerChoiceLabel(result.targetKind, targetProviderRuntime)}${note}`,
        // A lossy strategy's note is the whole disclosure; see the constant.
        note ? LOSSY_SWITCH_TOAST_MS : undefined,
      )
    } else if (result.status === 'failed') {
      showPaneToast(sourceSessionId, result.message)
    } else {
      showPaneToast(sourceSessionId, result.reason)
    }
    return result
  }, [refs, sessionActions, setRuntimes, showPaneToast])

  const reloadSessionAgent = useCallback(async (sourceSessionId: SessionId): Promise<AgentLifecycleResult> => {
    const current = refs.stateRef.current
    const meta = current.sessions[sourceSessionId]
    if (!meta) return { status: 'skipped', reason: 'Session no longer exists' }

    const kind = meta.kind ?? DEFAULT_PROVIDER
    if (!isAgentProviderKind(kind)) {
      // Toast text is registry-driven — "Only agent panes can reload" reads
      // right for any current OR future provider set. The previous
      // "Claude and Codex" wording rotted the moment OpenCode was registered.
      showPaneToast(sourceSessionId, 'Only agent panes can reload')
      return { status: 'skipped', reason: 'Only agent panes can reload' }
    }
    const resumeSessionId = resumableProviderSessionId(meta)
    if (!resumeSessionId) {
      showPaneToast(sourceSessionId, 'Provider session id is not ready yet')
      return { status: 'skipped', reason: 'Provider session id is not ready yet' }
    }

    try {
      const newSessionId = await sessionActions.replaceSession(meta.cwd, {
        kind,
        targetSessionId: sourceSessionId,
        resumeSessionId,
      })
      if (!newSessionId) return { status: 'failed', message: 'Replacement was not committed' }
      showPaneToast(
        newSessionId,
        `${getRendererProviderCapabilities(kind).shortLabel} reloaded`,
      )
      return { status: 'completed', sourceSessionId, newSessionId }
    } catch (err) {
      const message =
        err instanceof Error && err.message.length > 0
          ? err.message
          : 'Reload failed'
      showPaneToast(sourceSessionId, message)
      return { status: 'failed', message }
    }
  }, [refs.stateRef, sessionActions, showPaneToast])

  // Rewind the focused pane to a selected earlier user prompt.
  //
  // Contract (see docs/superpowers/plans for the full rationale):
  //   1. The source session's on-disk transcript is NOT touched.
  //   2. Main produces a fresh provider session id whose transcript
  //      ends strictly before the anchor.
  //   3. The focused pane is re-homed to the new id via
  //      `replaceSession(...)`, so the pane stays in place; only its
  //      backing session swaps. This matches resume semantics.
  //   4. The anchored prompt's text is stuffed into the new pane's
  //      `draftInput` — the rewound session opens with the prompt
  //      prefilled and UNSENT, so the user can edit or re-send.
  //
  // Bail-outs:
  //   - No providerSessionId yet (pane still spawning): toast and
  //     return. Rewinding a session we can't locate on disk is a
  //     nonsense operation.
  //   - Session is mid-turn (processActive or live currentTurn):
  //     toast and return. Rewinding while a response is streaming
  //     exercises every race we have around the live-to-committed
  //     handoff at once; requiring idle is the safe path.
  const rewindSessionToPrompt = useCallback(
    async (sourceSessionId: SessionId, anchor: RewindPromptAddress): Promise<AgentLifecycleResult> => {
      const current = refs.stateRef.current
      const meta = current.sessions[sourceSessionId]
      if (!meta) return { status: 'skipped', reason: 'Session no longer exists' }

      const kind = meta.kind ?? DEFAULT_PROVIDER
      if (!isAgentProviderKind(kind)) {
        // Registry-driven toast — see the reload-agent counterpart above.
        // Terminal panes are the only non-agent kind today; the wording will
        // continue to read right when future providers register.
        showPaneToast(sourceSessionId, 'Only agent panes support rewind')
        return { status: 'skipped', reason: 'Only agent panes support rewind' }
      }
      const previousProviderSessionId = resumableProviderSessionId(meta)
      if (!previousProviderSessionId) {
        showPaneToast(sourceSessionId, 'Provider session id is not ready yet')
        return { status: 'skipped', reason: 'Provider session id is not ready yet' }
      }
      if (kind !== anchor.provider) {
        showPaneToast(
          sourceSessionId,
          `Prompt address is for ${anchor.provider} but focused pane is ${kind}`,
        )
        return { status: 'skipped', reason: 'Prompt provider differs from this session' }
      }

      const currentRuntime = refs.latestRuntimesRef.current[sourceSessionId]
      if (currentRuntime?.processActive || currentRuntime?.semantic.currentTurn) {
        showPaneToast(sourceSessionId, 'Wait for the current turn to finish before rewinding')
        return { status: 'skipped', reason: 'Wait for the current turn to finish before rewinding' }
      }

      try {
        const result = await window.api.rewindToPrompt({
          provider: kind,
          sourceProviderSessionId: previousProviderSessionId,
          cwd: meta.cwd,
          anchor,
        })

        const newSessionId = await sessionActions.replaceSession(meta.cwd, {
          kind,
          resumeSessionId: result.newProviderSessionId,
          targetSessionId: sourceSessionId,
        })
        if (!newSessionId) return { status: 'failed', message: 'Replacement was not committed' }

        // `replaceSession` copied the PRIOR pane's draft forward.
        // For rewind we deliberately clobber that draft with the
        // anchored prompt text — the whole feature is "open this
        // prompt in unsent form so I can edit/re-send it".
        //
        // Bash mode: Claude Code exposes a `bash` input mode that
        // prefixes `!` when composing. Agent Code's composer doesn't
        // have a discrete bash mode yet, but it DOES treat a
        // leading `!` as bash. Mirroring CC's behavior means
        // "rewinding to a /bash-input prompt rehydrates as
        // `!<body>`" so the next Enter submits as bash again.
        //
        // Images: convert the main-process image records (base64 +
        // mediaType) into `ClaudeDraftImage` shape the composer
        // already renders and can send. The preview URL uses a
        // data: URL so no blob lifecycle is needed.
        const draftText =
          result.promptMode === 'bash' && result.promptText.length > 0
            ? `!${result.promptText}`
            : result.promptText

        // WHY the registry capability and not `kind === 'claude'`: the
        // hardcode predates the provider registry and was already stale —
        // `supportsImageAttachments` is the field every other image path
        // consults, so a provider that gains image support would have had to
        // remember this line too (#1073 review, finding 2).
        const draftImages: ClaudeDraftImage[] =
          getRendererProviderCapabilities(kind).supportsImageAttachments
            ? result.promptImages.map((image, index) => ({
                id: `rewind-${Date.now()}-${index}`,
                mediaType: image.mediaType,
                base64Data: image.data,
                previewUrl: `data:${image.mediaType};base64,${image.data}`,
                filename: `rewind-${index + 1}`,
              }))
            : []

        setRuntimes(prev => {
          const runtime = prev[newSessionId]
          if (!runtime) return prev
          return {
            ...prev,
            [newSessionId]: {
              ...runtime,
              draftInput: draftText,
              draftImages,
              // Runtime-only rewind undo records the provider transcript we just
              // left, not the local Agent Code session id we killed. Local ids
              // are routing handles for this renderer launch; provider ids are
              // the durable resume identity that `replaceSession` already knows
              // how to swap back into the same pane. The record intentionally
              // rides on the replacement runtime so command visibility follows
              // the rewound pane, including detached Dispatch rows.
              pendingRewindUndo: {
                createdAt: Date.now(),
                provider: kind,
                cwd: meta.cwd,
                previousProviderSessionId,
                previousTldrIdentity: tldrIdentityForSession(sourceSessionId, meta),
                rewoundProviderSessionId: result.newProviderSessionId,
                rewoundPromptText: result.promptText,
                rewoundPromptTimestamp: result.promptTimestamp,
                // The replacement owner just transferred the latest draft.
                // Save that here, not the pre-export snapshot: edits made while
                // native rewind/spawn awaited must remain recoverable by Undo.
                previousDraftInput: runtime.draftInput,
                previousDraftImages: runtime.draftImages.slice(),
                // The ORIGINAL conversation's choices, beside its original
                // transcript: undo restores the pane the user actually had.
                builtInMcpOverrides: sessionMcpOverrides(meta),
              },
            },
          }
        })

        // What did NOT come back (#1075). Main has produced this report since
        // #1073 and the Rewind picker uses it; nothing used it after the
        // rewind, so a user who picked a row labelled `[Image prompt]` got an
        // empty composer and no explanation. The capability is part of the
        // question: a perfectly restored image is still a loss when the
        // provider's composer cannot carry it, which is every provider except
        // Claude today.
        const attachmentLoss = describeRewindAttachmentLoss(result.promptAttachments, {
          composerCarriesImages: getRendererProviderCapabilities(kind).supportsImageAttachments,
        })
        showPaneToast(
          newSessionId,
          attachmentLoss
            ? `Rewound to prompt, but ${attachmentLoss} Undo Rewind available until next submit`
            : 'Rewound to prompt - Undo Rewind available until next submit',
          // WHY a longer toast for the loss case (#1100 review): the default is
          // 2000 ms and `PaneToast` clamps to three lines, which for a sentence
          // naming two files and two reasons is a message nobody finishes
          // reading. The house numbers for a toast carrying something to act on
          // are 5-6 s (a copied command, a saved path), and this is the same
          // kind of thing. The ordinary success toast keeps the default,
          // because "it worked" needs no reading time.
          attachmentLoss ? 6000 : undefined,
        )
        return { status: 'completed', sourceSessionId, newSessionId }
      } catch (err) {
        const message =
          err instanceof Error && err.message.length > 0
            ? err.message
            : 'Rewind failed'
        showPaneToast(sourceSessionId, message)
        return { status: 'failed', message }
      }
    },
    [refs.latestRuntimesRef, refs.stateRef, sessionActions, setRuntimes, showPaneToast],
  )

  const undoSessionRewind = useCallback(async (sourceSessionId: SessionId): Promise<AgentLifecycleResult> => {
    const current = refs.stateRef.current
    const meta = current.sessions[sourceSessionId]
    if (!meta) return { status: 'skipped', reason: 'Session no longer exists' }

    const runtime = refs.latestRuntimesRef.current[sourceSessionId]
    const pending = runtime?.pendingRewindUndo ?? null
    if (!pending) {
      showPaneToast(sourceSessionId, 'No rewind to undo')
      return { status: 'skipped', reason: 'No rewind to undo' }
    }

    const kind = meta.kind ?? DEFAULT_PROVIDER
    if (kind !== pending.provider) {
      showPaneToast(sourceSessionId, 'Rewind undo no longer matches this pane')
      return { status: 'skipped', reason: 'Rewind undo no longer matches this pane' }
    }
    if (meta.providerSessionId !== pending.rewoundProviderSessionId) {
      showPaneToast(sourceSessionId, 'Rewind undo is no longer available')
      return { status: 'skipped', reason: 'Rewind undo is no longer available' }
    }
    if (runtime.processActive || runtime.semantic.currentTurn) {
      showPaneToast(sourceSessionId, 'Wait for the current turn to finish before undoing rewind')
      return { status: 'skipped', reason: 'Wait for the current turn to finish before undoing rewind' }
    }

    try {
      const newSessionId = await sessionActions.replaceSession(pending.cwd, {
        kind: pending.provider,
        resumeSessionId: pending.previousProviderSessionId,
        restoreTldrIdentity: pending.previousTldrIdentity,
        builtInMcpOverrides: pending.builtInMcpOverrides,
        targetSessionId: sourceSessionId,
      })
      if (!newSessionId) return { status: 'failed', message: 'Replacement was not committed' }

      setRuntimes(prev => {
        const restored = prev[newSessionId]
        if (!restored) return prev
        return {
          ...prev,
          [newSessionId]: {
            ...restored,
            // Undo Rewind restores the composer to the user's pre-rewind draft
            // because the rewound draft is the selected historical prompt, not
            // the user's current unsent work. Clearing the pending record here
            // keeps undo one-way; a redo-style stack would need a separate
            // product model and should not appear accidentally from this swap.
            draftInput: pending.previousDraftInput,
            draftImages: pending.previousDraftImages,
            pendingRewindUndo: null,
          },
        }
      })

      showPaneToast(newSessionId, 'Undid rewind')
      return { status: 'completed', sourceSessionId, newSessionId }
    } catch (err) {
      const message =
        err instanceof Error && err.message.length > 0
          ? err.message
          : 'Undo rewind failed'
      showPaneToast(sourceSessionId, message)
      return { status: 'failed', message }
    }
  }, [refs.latestRuntimesRef, refs.stateRef, sessionActions, setRuntimes, showPaneToast])

  // UI commands capture focus once, before any asynchronous work. External
  // callers use the explicit methods directly and never move selection as a
  // substitute for specifying an operation target.
  const reloadFocusedAgent = useCallback(async () => {
    const id = commandTargetSessionIdForState(refs.stateRef.current)
    if (id) await reloadSessionAgent(id)
  }, [refs.stateRef, reloadSessionAgent])
  const rewindFocusedToPrompt = useCallback(async (anchor: RewindPromptAddress) => {
    const id = commandTargetSessionIdForState(refs.stateRef.current)
    if (id) await rewindSessionToPrompt(id, anchor)
  }, [refs.stateRef, rewindSessionToPrompt])
  const undoLastRewind = useCallback(async () => {
    const id = commandTargetSessionIdForState(refs.stateRef.current)
    if (id) await undoSessionRewind(id)
  }, [refs.stateRef, undoSessionRewind])

  // Same replace-in-place transaction as rewind, with a smaller cut: keep
  // the last user prompt and earlier assistant work, drop only the last
  // Codex model step after a cyber_policy task_complete. Reuses
  // pendingRewindUndo so Undo Rewind can restore the original rollout
  // until the next submit — a second undo stack would hide the same
  // provider-id swap behind a different name.
  const removeCodexCyberPolicyBlock = useCallback(
    async (sourceSessionId: SessionId): Promise<AgentLifecycleResult> => {
      const current = refs.stateRef.current
      const meta = current.sessions[sourceSessionId]
      if (!meta) return { status: 'skipped', reason: 'Session no longer exists' }

      const kind = meta.kind ?? DEFAULT_PROVIDER
      if (kind !== 'codex') {
        showPaneToast(sourceSessionId, 'Remove Cybersecurity Block is a Codex command')
        return { status: 'skipped', reason: 'Remove Cybersecurity Block is a Codex command' }
      }
      const previousProviderSessionId = resumableProviderSessionId(meta)
      if (!previousProviderSessionId) {
        showPaneToast(sourceSessionId, 'Provider session id is not ready yet')
        return { status: 'skipped', reason: 'Provider session id is not ready yet' }
      }

      const currentRuntime = refs.latestRuntimesRef.current[sourceSessionId]
      if (currentRuntime?.processActive || currentRuntime?.semantic.currentTurn) {
        showPaneToast(sourceSessionId, 'Wait for the current turn to finish before removing the cybersecurity block')
        return { status: 'skipped', reason: 'Wait for the current turn to finish before removing the cybersecurity block' }
      }

      try {
        const result = await window.api.stripCodexCyberPolicy({
          provider: 'codex',
          sourceProviderSessionId: previousProviderSessionId,
          cwd: meta.cwd,
        })

        const newSessionId = await sessionActions.replaceSession(meta.cwd, {
          kind: 'codex',
          resumeSessionId: result.newProviderSessionId,
          targetSessionId: sourceSessionId,
        })
        if (!newSessionId) return { status: 'failed', message: 'Replacement was not committed' }

        setRuntimes(prev => {
          const runtime = prev[newSessionId]
          if (!runtime) return prev
          return {
            ...prev,
            [newSessionId]: {
              ...runtime,
              pendingRewindUndo: {
                createdAt: Date.now(),
                provider: 'codex',
                cwd: meta.cwd,
                previousProviderSessionId,
                previousTldrIdentity: tldrIdentityForSession(sourceSessionId, meta),
                rewoundProviderSessionId: result.newProviderSessionId,
                // Not a prompt rewind. Undo restores previousProviderSessionId
                // and previousDraftInput; this field exists because the
                // rewind undo record requires it.
                rewoundPromptText: '',
                rewoundPromptTimestamp: null,
                previousDraftInput: runtime.draftInput,
                previousDraftImages: runtime.draftImages.slice(),
                // The ORIGINAL conversation's choices, beside its original
                // transcript: undo restores the pane the user actually had.
                builtInMcpOverrides: sessionMcpOverrides(meta),
              },
            },
          }
        })

        showPaneToast(newSessionId, 'Removed cybersecurity block — Undo Rewind available until next submit')
        return { status: 'completed', sourceSessionId, newSessionId }
      } catch (err) {
        const message =
          err instanceof Error && err.message.length > 0
            ? err.message
            : 'Remove cybersecurity block failed'
        showPaneToast(sourceSessionId, message)
        return { status: 'failed', message }
      }
    },
    [refs.latestRuntimesRef, refs.stateRef, sessionActions, setRuntimes, showPaneToast],
  )

  const removeFocusedCyberPolicyBlock = useCallback(async () => {
    const id = commandTargetSessionIdForState(refs.stateRef.current)
    if (id) await removeCodexCyberPolicyBlock(id)
  }, [refs.stateRef, removeCodexCyberPolicyBlock])

  return { switchSessionProvider, reloadSessionAgent, rewindSessionToPrompt, undoSessionRewind,
    removeCodexCyberPolicyBlock, reloadFocusedAgent, rewindFocusedToPrompt, undoLastRewind,
    removeFocusedCyberPolicyBlock }
}

import { DEFAULT_PROVIDER, isAgentProviderKind } from '@shared/types/providerKind'
import { useCallback } from 'react'

import type { SessionId } from '@renderer/workspace/types'
import {
  buildVisibleDispatchRows,
} from '@renderer/workspace/dispatch/dispatchSelectors'
import { resolveFocusSurfaceTarget } from '@renderer/workspace/hook/actions/focusSurfaceTarget'
import { sessionHasTranscript } from '@renderer/workspace/transcriptAvailability'

import type {
  WorkspaceSetReaderMode,
  WorkspaceSetSpotlight,
  WorkspaceSetState,
} from '@renderer/workspace/hook/context'
import type { WorkspaceRefs } from '@renderer/workspace/hook/refs'

// ReaderMode toggle. Mirrors toggleSpotlight: enters with the same command
// target the palette/keybind layer exposes, exits whenever Reader is already
// open. Closes Spotlight on entry; tile-tabs are preserved in state and
// suppressed by App.tsx render precedence.

export function useReaderActions(
  setReaderMode: WorkspaceSetReaderMode,
  setSpotlight: WorkspaceSetSpotlight,
  setState: WorkspaceSetState,
  refs: WorkspaceRefs,
): {
  setReaderModeTarget: (sessionId: SessionId | null) => boolean
  toggleReaderMode: () => void
  setReaderModeSession: (sessionId: SessionId) => void
} {
  // Explicit desired state lets command clients select a non-focused agent
  // without a focus-then-toggle race. Ownership uses the same placement query
  // as UI toggles, including detached and related sessions.
  const setReaderModeTarget = useCallback((sessionId: SessionId | null) => {
    if (sessionId === null) { setReaderMode(null); return true }
    const current = refs.stateRef.current
    const target = resolveFocusSurfaceTarget(current, sessionId)
    if (!target) return false
    if (!isAgentProviderKind(current.sessions[sessionId]?.kind ?? DEFAULT_PROVIDER)) return false
    setSpotlight(null)
    setState(prev => ({ ...prev, activeTabId: target.tabId }))
    setReaderMode({ tabId: target.tabId, focusedSessionId: sessionId })
    return true
  }, [refs.stateRef, setReaderMode, setState, setSpotlight])

  const toggleReaderMode = useCallback(() => {
    const current = refs.stateRef.current
    const target = resolveFocusSurfaceTarget(current)
    setSpotlight(null)
    setReaderMode(prev => {
      if (prev) return null
      if (!target) return prev
      const kind = current.sessions[target.sessionId]?.kind ?? DEFAULT_PROVIDER
      // Reader Mode reads the pane's committed transcript through the
      // provider-registered renderer/extractor. Registry membership — not a
      // hardcoded pair — is the correct predicate: every registered
      // AgentProviderKind ships a transcript view (see
      // src/providers/<kind>/renderer/), so OpenCode is just as valid a
      // Reader target as Claude or Codex.
      if (!isAgentProviderKind(kind)) return prev
      return {
        tabId: target.tabId,
        focusedSessionId: target.sessionId,
      }
    })
  }, [refs.stateRef, setReaderMode, setSpotlight])

  // Switch which session is being read inside ReaderMode.
  //
  // WHY this never writes a lane or a tree focus: Reader is a takeover with its
  // own focusedSessionId. The original implementation mirrored every selection
  // into Tab.focusedSessionId, which corrupted the tab whenever the selected
  // row was not a tree leaf; the Dispatch-era fix moved the mirror to a classic
  // focus field. Both fields are gone (#992) and nothing replaces them.
  const setReaderModeSession = useCallback(
    (sessionId: SessionId) => {
      const snapshot = refs.stateRef.current
      // WHY this needs a guard like setReaderModeTarget/toggleReaderMode's
      // (#865): Reader Mode is agent-only by design (Design D2) because it
      // renders a provider-registered transcript view, and a terminal has no
      // such view. Those two siblings already refuse a non-agent kind before
      // touching state; this one — the "switch which session Reader is
      // showing" entry point — did not, so it was relying only on ReaderView's
      // own filter to keep a terminal off screen. That filter is a rendering
      // accident, not a contract: any caller reaching this action directly
      // (e.g. the external operator's agents.show, which after #865 no longer
      // refuses terminals for placement/metadata capabilities) could point
      // Reader Mode at a session it cannot render. Refuse without changing
      // reader state — on the same transcript predicate the command surface
      // uses, so visibility and this direct-entry guard cannot disagree (see
      // the M5 note below for how that predicate evolved).
      //
      // WHY sessionHasTranscript instead of isAgentProviderKind (M5): the two
      // predicates used to diverge — isAgentProviderKind admits sessions with
      // no entries at all, and sessionHasTranscript existed to name that
      // difference. Since #971 they agree on OpenCode Terminal (its committed
      // entries load per #882, and Reader renders them as an overlay), so the
      // remaining gap this guard closes is a plain terminal slipping in
      // directly. readerCommands.ts gates on sessionHasTranscript for the same
      // reason; this guard must agree with its own command's own visibility
      // rule.
      if (!sessionHasTranscript(snapshot.sessions[sessionId])) return
      const rows = buildVisibleDispatchRows(snapshot)
      const dispatchRow = rows.find(row => row.sessionId === sessionId) ?? null
      setReaderMode(prev => (
        prev
          ? {
              ...prev,
              tabId: dispatchRow?.tabId ?? prev.tabId,
              focusedSessionId: sessionId,
            }
          : prev
      ))
      // Only the active PROJECT follows the Reader selection; see the matching
      // note in spotlight.ts. Reader holds its own focusedSessionId, and
      // paging through transcripts is not the user naming a lane occupant
      // (U2, #681), so no lane — and no tree focus, which no longer exists —
      // is written here.
      setState(prev => {
        const activeTabId = dispatchRow?.tabId ?? prev.activeTabId
        return activeTabId === prev.activeTabId ? prev : { ...prev, activeTabId }
      })
    },
    [refs.stateRef, setReaderMode, setState],
  )

  return { setReaderModeTarget, toggleReaderMode, setReaderModeSession }
}

