// -----------------------------------------------------------------------------
// Session lifecycle actions.
//
// spawn              — main process call to create a new session. Returns the
//                      new sessionId. Updates state.sessions + runtimes
//                      synchronously. Schedules ghost-log bootstrap via
//                      setTimeout(0) so the fresh runtime lands first.
// killSession        — main process call to kill a session. Cleans up
//                      runtime, state.sessions, and per-session refs.
// replaceSession     — kill current focused session + spawn a new one in
//                      the same tile-tree slot. Used by resume picker and
//                      provider switch.
// reloadAgentSessions — recreate every live agent session (any provider,
//                       either runtime) with fresh dangerous-mode settings.
//                       Remaps panes + buried records onto the new ids and
//                       reloads each durable session's history.
// -----------------------------------------------------------------------------

export type SessionActions = {
  spawn: (
    cwd: string,
    opts?: {
      resumeSessionId?: string
      kind?: SessionKind
      providerRuntime?: AgentProviderRuntime
      dangerousMode?: boolean
      recoverTmuxName?: string
      tldrIdentity?: string
      builtInMcpOverrides?: BuiltInMcpOverrides
      builtInMcpDomains?: BuiltInMcpDomain[]
    },
  ) => Promise<SessionId>
  ensureSessionLive: (
    sessionId: SessionId,
    caller: WakeCaller,
    options?: SessionWakeOptions,
  ) => Promise<SessionWakeResult>
  killSession: (
    sessionId: SessionId,
    caller: KillCaller,
    capturedOwner?: Pick<SessionMeta, 'cwd' | 'kind' | 'providerRuntime'>,
  ) => Promise<void>
  replaceSession: (
    cwd: string,
    opts?: {
      resumeSessionId?: string
      kind?: SessionKind
      providerRuntime?: AgentProviderRuntime
      /** Per-domain MCP choices to ADOPT; omit to continue the pane's own. */
      builtInMcpOverrides?: BuiltInMcpOverrides
      preserveTldr?: boolean
      restoreTldrIdentity?: string
      targetSessionId?: SessionId
      /** The Conversations picker's in-place swap: an UNRELATED conversation
       *  moves into this pane, so the successor must not inherit its
       *  orchestration parentage. See the implementation for why only the
       *  caller can tell. */
      newConversation?: boolean
    },
  ) => Promise<SessionId | undefined>
  reloadAgentSessions: (dangerousMode?: boolean) => Promise<void>
  softReloadAgentView: (sessionId?: SessionId) => Promise<SessionId | null>
}

export type SessionWakeResult = {
  sessionId: SessionId
}

export type SessionWakeOptions = {
  /** Wait for the composer to report input-ready before resolving (the
   *  default; prompt delivery needs it). A raw terminal pane passes false:
   *  readiness is a composer concept and the pane wants to show the TUI
   *  booting, not a blank box for the whole boot (#772). */
  awaitInputReady?: boolean
}

export async function killSessionBackendIfOwned(
  refs: WorkspaceRefs,
  sessionId: SessionId,
  // WHY required, mirroring ensureSessionLive's WakeCaller: main journals
  // `kill.request` with this tag (#1135), and an untagged kill is exactly the
  // gap that made quit, Close Old Agents and recovery replacement
  // indistinguishable. Making every renderer site name itself is the point.
  caller: KillCaller,
  capturedOwner?: Pick<SessionMeta, 'cwd' | 'kind' | 'providerRuntime'>,
): Promise<boolean> {
  // Spawn cleanup may run before React refreshes stateRef. Its caller already
  // knows the exact scope it just created; main still performs the atomic
  // ownership check. Ordinary close paths continue using the live metadata.
  const meta = capturedOwner ?? refs.stateRef.current.sessions[sessionId]
  if (!meta) return false
  // WHY this proof lives in main as one atomic check+kill: renderer runtime
  // flags are advisory and can be reset by retry, soft reload, or a delayed
  // feed event. A stale pane may share its id with another project, but only a
  // matching provider kind and lexical cwd authorize destructive teardown.
  return await window.api.killOwnedSession({
    sessionId,
    kind: meta.kind,
    providerRuntime: meta.providerRuntime,
    cwd: meta.cwd,
    caller,
  })
}

/**
 * Shallow value-equality over two session-meta records.
 *
 * WHY this exists rather than letting the spread decide: several callers use
 * the meta object's IDENTITY as a "is my target still the same pane?" token
 * across an await (deliverTextToSession's isCurrent, both prompt-template
 * insertion paths). A wake that changed nothing but still produced a new
 * object read to them as "the pane was replaced", so the first insertion into
 * any pane that needed waking always failed and the retry always worked.
 *
 * Compared over the union of both key sets rather than over `next` alone.
 * That is defensive rather than load-bearing AT THIS CALL SITE: the caller
 * builds `next` as `{...current, ...recoveredMeta}`, which is always a
 * superset of `current`'s keys, so nothing can actually disappear here. It is
 * written this way so the function stays correct for a caller that composes a
 * meta object differently — a field vanishing must count as a change, or a
 * holder gets a token that outlived the fact it stood for.
 *
 * (Worth knowing, and NOT introduced here: that superset property also means
 * the wake's `withoutProvisionalProviderSession` is inert. It strips
 * `providerSessionId`/`providerSessionIdSource` from `restoredMeta` and the
 * spread puts them straight back from `current`. The same helper does take
 * effect where it is spread into a FRESH object instead. Pre-existing, out of
 * scope for a comparison function, but this is where someone will next look
 * for it.)
 *
 * Values are primitives except for the domain array and flat override map;
 * `metaValuesEqual` compares their leaves because wake rebuilds both.
 */
function metaValuesEqual(a: unknown, b: unknown): boolean {
  if (Object.is(a, b)) return true
  // WHY arrays need an element-wise pass rather than reference equality:
  //
  // `builtInMcpDomains` is the one array field on SessionMeta, and the wake
  // path REBUILDS it every time — `resolveSessionBuiltInMcpDomains` ends in a
  // filter, so it returns a fresh array even when the contents are identical.
  // A pure `Object.is` comparison therefore reported "changed" on every wake
  // of every agent pane, which is precisely the population this whole
  // comparison exists to protect, and would have left the bug fixed only for
  // plain terminals.
  //
  // Elements are a string union, so a shallow pass is exact. The flat MCP
  // override map receives its own leaf comparison below.
  if (Array.isArray(a) && Array.isArray(b)) {
    return a.length === b.length && a.every((value, index) => Object.is(value, b[index]))
  }
  if (a && b && typeof a === 'object' && typeof b === 'object' && !Array.isArray(a) && !Array.isArray(b)) {
    // The only object-valued metadata is the flat MCP override map. Compare
    // its boolean leaves so an idempotent wake cannot rerender every pane.
    const left = a as Record<string, unknown>, right = b as Record<string, unknown>
    return Object.keys(left).length === Object.keys(right).length
      && Object.keys(left).every(key => Object.prototype.hasOwnProperty.call(right, key) && Object.is(left[key], right[key]))
  }
  return false
}

function metaIsUnchanged(current: SessionMeta, next: SessionMeta): boolean {
  const a = current as unknown as Record<string, unknown>
  const b = next as unknown as Record<string, unknown>
  const keys = new Set([...Object.keys(a), ...Object.keys(b)])
  for (const key of keys) if (!metaValuesEqual(a[key], b[key])) return false
  return true
}

/**
 * Drop this session's feed-debug flush cursors (#770).
 *
 * A soft reload of a session WITH a durable provider transcript rebuilds the
 * runtime, so `feedDebugNextId` restarts at 1. (The no-provider arm keeps the
 * runtime and is therefore not a generation boundary — see its call site.)
 * These two refs live OUTSIDE the runtime — they are per-session flush
 * bookkeeping, deliberately kept off the store so a busy agent does not
 * re-render the workspace on every persisted batch — so nothing in the reset
 * above reaches them. Left behind, `selectFeedDebugAppendBatch` filters every
 * entry of the new generation as `id <= lastPersistedId` and the session
 * stops persisting feed-debug entirely, for the rest of the run.
 *
 * Main's half of the same cursor is reset by the epoch carried in each batch;
 * it cannot be cleared from here, and an explicit "reset" message would race
 * an append already in flight.
 */
function forgetFeedDebugCursors(refs: WorkspaceRefs, sessionId: SessionId): void {
  delete refs.persistedFeedDebugIdRef.current[sessionId]
  delete refs.inFlightFeedDebugIdRef.current[sessionId]
}

function softReloadRuntime(current: SessionRuntime, hasProviderSession: boolean): SessionRuntime {
  if (!hasProviderSession) {
    // WHY no-provider soft reload is non-destructive:
    //
    // Soft reload used to mean "discard renderer-derived state, then replay the
    // committed transcript from disk." That only works when a providerSessionId
    // points at a transcript we can load. In the #290 failure mode Claude is
    // still alive through proxy/semantic/screen, but the committed JSONL is
    // missing and the pane may have no provider id yet. Resetting entries,
    // ghosts, and semantic state in that condition erases the only visible
    // progress and then labels the empty pane "ready." Preserve the live-only
    // state and make the durability problem explicit instead.
    return {
      ...current,
      scrollToLatestRequest: current.scrollToLatestRequest + 1,
      hasOlderHistory: false,
      transcriptStatus: 'disconnected',
      transcriptError:
        'Cannot soft reload this agent view because no committed provider transcript is known yet.',
    }
  }

  const reset = emptyRuntime()

  // WHY this is a selective reset instead of a fresh `emptyRuntime()`:
  //
  // Soft reload is meant for "the renderer/feed got weird while the
  // backend is still working". A hard reload can throw the process
  // away and resume from disk, but this action must leave the live
  // provider process alone. That means process lifecycle, input
  // readiness, in-progress phase text, draft text/images, and tail
  // preference are still authoritative and must survive. The things
  // we discard are renderer-derived caches: visible entries, semantic
  // ghosts, screen snapshots, indexes, pickers, and transient prompts.
  //
  // The history loader runs immediately after this reset when a
  // providerSessionId exists. It rebuilds committed transcript rows
  // and worktree context from disk, while any IPC events that arrive
  // during the load merge into this same runtime. Resetting UUID
  // de-dupe state in the caller is the other half of that contract;
  // without it, replay would think every old row was already visible.
  return {
    ...reset,
    draftInput: current.draftInput,
    draftImages: current.draftImages,
    tailMode: current.tailMode,
    scrollToLatestRequest: current.scrollToLatestRequest + 1,
    processActive: current.processActive,
    sessionStatus: current.sessionStatus,
    sessionStatusSource: current.sessionStatusSource,
    processStatus: current.processStatus,
    processError: current.processError,
    recoveryFailureCode: current.recoveryFailureCode,
    inputReady: current.inputReady,
    inputReadinessRevision: current.inputReadinessRevision,
    exited: current.exited,
    projectDir: current.projectDir,
    conditions: current.conditions,
    activityStatus: current.activityStatus,
    unreadSince: current.unreadSince,
    unreadKind: current.unreadKind,
    streamPhase: current.streamPhase,
    streamPhasePendingToolName: current.streamPhasePendingToolName,
    streamPhasePendingToolUseId: current.streamPhasePendingToolUseId,
    turnStartedAt: current.turnStartedAt,
    phaseChangedAt: current.phaseChangedAt,
    submittedAt: current.submittedAt,
    hasOlderHistory: true,
    // A soft reload keeps the same backend. Rebuilding the view cannot
    // restart a stopped channel or undo navigation inside the provider TUI.
    transcriptChannelError: current.transcriptChannelError,
    transcriptStatus: current.transcriptChannelError ? 'error' : 'loading',
    transcriptStatusChangedAt: Date.now(),
    transcriptError: current.transcriptChannelError ?? null,
  }
}

function waitForSessionInputReady(
  refs: WorkspaceRefs,
  sessionId: SessionId,
  timeoutMs = 30_000,
): Promise<void> {
  const startedAt = Date.now()

  return new Promise((resolve, reject) => {
    const tick = () => {
      const runtime = refs.latestRuntimesRef.current[sessionId]
      if (
        runtime &&
        runtime.inputReady &&
        runtime.processStatus === 'started' &&
        runtime.exited === null
      ) {
        resolve()
        return
      }
      if (runtime?.processStatus === 'failed') {
        reject(new Error(runtime.processError ?? 'Agent failed to start'))
        return
      }
      if (runtime?.exited !== null && runtime?.exited !== undefined) {
        reject(new Error('Agent exited before it became ready for input'))
        return
      }
      if (Date.now() - startedAt >= timeoutMs) {
        reject(new Error('Timed out waiting for agent to become ready for input'))
        return
      }
      window.setTimeout(tick, 50)
    }
    tick()
  })
}

/** A reload successor whose agent went away while it spawned. */
type ReloadOrphan = { newId: SessionId; owner: Pick<SessionMeta, 'cwd' | 'kind' | 'providerRuntime'> }

export function useSessionActions(
  state: { activeTabId: string; sessions: Record<SessionId, SessionMeta>; tabs: Tab[] },
  setState: WorkspaceSetState,
  setRuntimes: WorkspaceSetRuntimes,
  refs: WorkspaceRefs,
): SessionActions {
  const wakeInFlightRef = useRef(new Map<SessionId, Promise<SessionWakeResult>>())
  const pendingReplacementSuccessorsRef = useRef(new Set<SessionId>())

  // spawn — wrapped so callers don't have to touch window.api
  // directly. Updates state.sessions synchronously after main
  // responds with an id.
  //
  // `resumeSessionId` (optional) triggers a resume: main spawns
  // claude with `--resume <uuid>` and tails the existing session
  // file, so the renderer receives the full session history as
  // jsonl-entry events immediately after started. Our own sessionId
  // is still fresh — it's a workspace-scoped identifier for routing,
  // distinct from CC's session UUID.
  const spawn = useCallback(
    async (
      cwd: string,
      opts?: {
        resumeSessionId?: string
        predecessorSessionId?: SessionId
        predecessorKillCaller?: KillCaller
        kind?: SessionKind
        providerRuntime?: AgentProviderRuntime
        dangerousMode?: boolean
        recoverTmuxName?: string
        tldrIdentity?: string
        builtInMcpOverrides?: BuiltInMcpOverrides
        builtInMcpDomains?: BuiltInMcpDomain[]
      },
    ): Promise<SessionId> => {
      const kind: SessionKind = opts?.kind ?? DEFAULT_PROVIDER
      const dangerousMode =
        opts?.dangerousMode ??
        (isAgentSessionKind(kind) ? refs.dangerousAgentsRef.current : undefined)
      // Agent providers both accept `useProxy`; terminals ignore it.
      // Claude uses MITM proxy streaming, Codex uses a local Responses
      // proxy via `openai_base_url`.
      const useProxy =
        isAgentSessionKind(kind) ? refs.useProxyStreamingRef.current : undefined
      const builtInMcpOverrides = spawnMcpOverrides(opts)
      const builtInMcpDomains =
        isAgentProviderKind(kind)
          ? resolveSessionBuiltInMcpDomains({
              provider: kind,
              sessionOverrides: builtInMcpOverrides,
              defaultDomains: refs.defaultBuiltInMcpDomainsRef.current,
            })
          : undefined
      const tldrIdentity = kind === 'terminal' ? undefined : opts?.tldrIdentity
        ?? (hasReportingDomain(builtInMcpDomains) ? crypto.randomUUID() : undefined)
      let sessionId: SessionId
      let tmuxName: string | undefined
      let startedProviderSessionId: string | undefined
      let startedUserMcpServerIds: string[] | undefined
      // What this spawn reserved, if anything. `replaceSession` owns the
      // release for every path AFTER spawn resolves, but it never sees an id
      // when spawn THROWS — and by then the successor may already be
      // committed to state.sessions, so a stranded reservation would leave a
      // real pane permanently unnamed. That is the mirror-image bug of the
      // name leak this reservation exists to stop, so spawn owns its own
      // failure path.
      let reservedIdentityCarry: SessionId | null = null
      try {
        try {
          const result = await window.api.spawnSession({
            tldrIdentity,
            kind,
            providerRuntime: opts?.providerRuntime,
            cwd,
            resumeSessionId: opts?.resumeSessionId,
            ...(opts?.predecessorSessionId
              ? {
                  predecessorSessionId: opts.predecessorSessionId,
                  ...(opts.predecessorKillCaller
                    ? { predecessorKillCaller: opts.predecessorKillCaller }
                    : {}),
                }
              : {}),
            dangerousMode,
            useProxy,
            recoverTmuxName: opts?.recoverTmuxName,
            builtInMcpDomains,
            // Only the pane's explicit choices cross; main applies Settings,
            // secrets and support itself (#1143, spec Revision 2 §4).
            ...(isAgentProviderKind(kind) ? { userMcpOverrides: userMcpOverridesFrom(builtInMcpOverrides) } : {}),
          })
          sessionId = result.sessionId
          tmuxName = result.tmuxName
          startedProviderSessionId = result.providerSessionId
          startedUserMcpServerIds = result.userMcpServerIds
          // WHY the reservation happens HERE, before this function's own commit:
          //
          // The gap the reconciler exploits opens the moment the successor's
          // metadata lands in `state.sessions` without an `agentNameId`, and
          // that is the setState a few lines below. `replaceSession` cannot
          // reserve after `await spawn(...)` because by then React has already
          // been given the chance to flush. Only spawn knows the id early
          // enough.
          //
          // WHY this is NOT also gated on the predecessor already HAVING an
          // identity, which a first version tried:
          //
          // The gate has to match the predicate the CARRY uses, and the carry
          // reads `prev.sessions[oldId]?.agentNameId` at COMMIT time, which is
          // later. A predecessor that is still unnamed when spawn runs can be
          // claimed by the reconciler during the await — at which point there
          // IS an identity to carry — and the narrower gate had left the
          // successor claimable in that same window. It allocates a name, the
          // commit overwrites it, and that name is orphaned forever. That is
          // the exact leak this reservation exists to close, one step
          // narrower.
          //
          // Reserving for every replacement costs nothing when there is
          // nothing to carry: the successor simply claims after release, on
          // the next state change, under its own id — the outcome the
          // replacement commit's comment already describes as correct.
          //
          // `predecessorSessionId` is passed by `replaceSession` and nothing
          // else, so this cannot fire for an ordinary spawn.
          if (opts?.predecessorSessionId) {
            reserveIdentityCarry(sessionId)
            reservedIdentityCarry = sessionId
          }
          if (result.replacementTransactionId) {
            // WHY presence, not renderer inference: only main can prove the
            // successor targeted the predecessor's exact Codex rollout and
            // therefore consumed the destructive handoff. replaceSession uses
            // this marker to suppress its legacy predecessor kill; workspace
            // persistence later commits the still-pending main transaction.
            pendingReplacementSuccessorsRef.current.add(sessionId)
          }
        } catch (err) {
          throw new Error(sessionSpawnErrorMessage(kind, err, useProxy === true, cwd))
        }
        const previousMeta = refs.stateRef.current.sessions[sessionId]
        const requestedProviderSessionId = opts?.resumeSessionId ?? startedProviderSessionId
        // WHY spawn does NOT mint agentNameId: replaceSession spawns through this
        // same function, so a seed here lands on the SUCCESSOR and then wins the
        // spread in the replacement commit, renaming a pane that only changed
        // backends. Minting lives in one place — the reconciler — which sees the
        // restored workspace and can tell a new agent from a recovered one.
        const meta: SessionMeta = {
          ...(previousMeta ?? {}),
          tldrIdentity,
          cwd,
          kind,
          // Write the field even when absent so a pathological reused id cannot
          // inherit an alternate runtime from stale metadata.
          providerRuntime: opts?.providerRuntime,
          ...(tmuxName ? { tmuxName } : {}),
          ...(kind !== 'terminal' && requestedProviderSessionId
            ? {
                providerSessionId: requestedProviderSessionId,
                providerSessionIdSource: opts?.resumeSessionId
                  ? 'resume-request' as const
                  : 'runtime-start' as const,
              }
            : {}),
          ...(isAgentProviderKind(kind) && builtInMcpDomains !== undefined
            ? { builtInMcpDomains, builtInMcpOverrides }
            : {}),
          ...(isAgentProviderKind(kind) ? { userMcpServerIds: startedUserMcpServerIds ?? [] } : {}),
        }
        setState(prev => ({
          ...prev,
          sessions: {
            ...prev.sessions,
            // Persist tmuxName when main returns one — that's the
            // signal that this terminal got tmux backing and is
            // eligible for cross-restart recovery on next launch.
            [sessionId]: meta,
          },
        }))
        setRuntimes(prev => {
          const current = prev[sessionId]
          const base = emptyRuntime()
          return {
            ...prev,
            [sessionId]: {
              ...base,
              // Provider-native terminal runtimes seed like any agent: their
              // durable history loads into `entries` below (see
              // loadInitialHistoryForSession for why). Only plain shells
              // have no transcript to load.
              ...(isAgentSessionKind(kind)
                ? seedResumedRuntimeFields(current, meta)
                : {
                    hasOlderHistory: false,
                    transcriptStatus: 'ready' as const,
                    transcriptError: null,
                    processStatus: 'started' as const,
                    processError: null,
                    inputReady: current?.inputReady ?? false,
                    inputReadinessRevision: current?.inputReadinessRevision ?? -1,
                  }),
              exited: current?.exited ?? null,
            },
          }
        })
        if (kind !== 'terminal' && meta.providerSessionId) {
          void loadInitialHistoryForSession({
            sessionId,
            meta,
            refs,
            setRuntimes,
          })
        }

        return sessionId
      } catch (error) {
        // Release ONLY on failure. On success the reservation must survive
        // until replaceSession has committed the carried identity, which is
        // the entire point of it.
        if (reservedIdentityCarry) releaseIdentityCarry(reservedIdentityCarry)
        throw error
      }
    },
    [refs.dangerousAgentsRef, refs.useProxyStreamingRef, setRuntimes, setState],
  )

  const ensureSessionLive = useCallback(
    async (
      sessionId: SessionId,
      caller: WakeCaller,
      options?: SessionWakeOptions,
    ): Promise<SessionWakeResult> => {
      // WHY options do not participate in the single-flight key: a wake is a
      // wake; a terminal pane joining a composer's wake simply resolves when
      // that one does. The readiness wait can no longer kill anything (see
      // below), so joining a waiting wake costs latency, never the backend.
      const inFlight = wakeInFlightRef.current.get(sessionId)
      // WHY the joined caller is still recorded: a remount storm shows up as
      // many wake.request events collapsing onto ONE recovery, and that ratio
      // is the fingerprint of the #596 class (every pane remount arming its own
      // wake). Reporting only the winner would hide it.
      if (inFlight) {
        reportWake(caller, sessionId, { reason: 'joined-in-flight' })
        return await inFlight
      }
      reportWake(caller, sessionId)

      const wake = (async (): Promise<SessionWakeResult> => {
        const snapshot = refs.stateRef.current
        const meta = snapshot.sessions[sessionId]
        if (!meta) {
          throw new Error(`Cannot wake ${sessionId}; no persisted session metadata exists.`)
        }
        // ── A PROCESS-LESS LEAF IS ALREADY LIVE ──
        // isSessionKind now accepts 'extension-view', so this function used to sail
        // past the unsupported-kind guard below, call recoverSession, and get main's
        // "extension-view panes have no process to recover" rejection — which it
        // throws. That stranded a pane permanently in three separate flows, all of
        // which funnel through here: Revive Buried, Attach Detached, and Attach All.
        // Bury and Detach-to-Dispatch are both ungated commands, so this was a
        // one-way trip with Kill Buried as the only exit.
        //
        // Fencing at this single choke point covers all three callers and mirrors the
        // two fences main already has. There is nothing to wake: a leaf with no
        // process is live by definition.
        if (meta.kind === 'extension-view') {
          return { sessionId }
        }
        if (meta.kind !== undefined && !isSessionKind(meta.kind)) {
          const message = 'This pane uses an unsupported provider. Update Agent Code or close it.'
          setRuntimes(prev => {
            const current = prev[sessionId]
            if (!current) return prev
            return {
              ...prev,
              [sessionId]: {
                ...current,
                processStatus: 'failed',
                processError: message,
                recoveryFailureCode: 'start-failed',
                inputReady: false,
                inputReadinessReason: null,
                inputReadinessChangedAt: Date.now(),
              },
            }
          })
          throw new Error(message)
        }
        const kind: SessionKind = meta.kind ?? DEFAULT_PROVIDER

        const builtInMcpOverrides = sessionMcpOverrides(meta)
        const builtInMcpDomains =
          isAgentProviderKind(kind)
            ? resolveSessionBuiltInMcpDomains({
                provider: kind,
                sessionOverrides: builtInMcpOverrides,
                defaultDomains: refs.defaultBuiltInMcpDomainsRef.current,
              })
            : undefined
        const resumeSessionId = isAgentSessionKind(kind) ? resumableProviderSessionId(meta) : undefined
        const restoredMeta = withoutProvisionalProviderSession(meta)
        const priorRecoveryFailureCode =
          refs.latestRuntimesRef.current[sessionId]?.recoveryFailureCode ?? null
        // WHY capture this before the RPC: `session:started` is delivered on a
        // separate IPC channel and may announce a replacement while recovery
        // is awaiting its snapshot. The post-await reconciliation below must
        // distinguish that newer run from the predecessor value that prompted
        // this wake in the first place.
        const sessionRunIdBeforeRecovery =
          refs.latestRuntimesRef.current[sessionId]?.sessionRunId ?? null

        setRuntimes(prev => {
          const current = prev[sessionId]
          if (!current) return prev
          return {
            ...prev,
            [sessionId]: {
              ...current,
              processStatus: 'spawning',
              processError: null,
              // WHY an ownership-conflict fence survives the retry RPC: feed
              // events and close actions can race while main decides whether
              // this pane may adopt the id. Only a successful matching
              // snapshot proves the unrelated-backend quarantine can clear.
              recoveryFailureCode: current.recoveryFailureCode,
              exited: null,
            },
          }
        })

        // WHY this recovers under the SAME SessionId instead of using
        // replaceSession/idMap or renderer get-kind-then-spawn:
        //
        // This action repairs a split-brain state created by process restart:
        // renderer workspace metadata survived, but main's provider registry did
        // not. The renderer id is already referenced by Dispatch rows, buried
        // records, tiled lanes, pins, grid-related selections, orchestration MCP
        // ownership, and possibly a tool call that is currently trying to send
        // to that exact id. A new id would force a broad remap while a command is
        // in flight. Reusing the id makes wake equivalent to "main caught up with
        // workspace.json" and keeps every existing reference valid. The main
        // recovery claim is the ownership lock: renderer single-flight only
        // suppresses duplicate UI transitions and is never relied on for
        // provider, proxy, or MCP exactly-once behavior.
        let readyError: unknown = null
        let recoveryFailureCode: SessionRecoverFailureCode | null = null
        let ownershipProven = false
        let recoverySnapshot: Awaited<ReturnType<typeof window.api.getBackendSnapshot>> = null
        let recoveredTmuxName: string | undefined
        // Did THIS call start the process, or did it adopt one that was
        // already running? The distinction decides whether the readiness
        // wait below is meaningful and whether the kill on its timeout is
        // legitimate. Main already answers it; this used to be discarded.
        let recoveryDisposition: 'adopted' | 'spawned' | 'joined' | null = null
        const recoverStartedAt = Date.now()
        try {
          reportLifecycle('recover.request', sessionId, {
            kind,
            caller,
            hasResumeId: Boolean(resumeSessionId),
          })
          const recovery = await window.api.recoverSession({
            tldrIdentity: tldrIdentityForSession(sessionId, meta),
            sessionId,
            kind,
            providerRuntime: meta.providerRuntime,
            cwd: meta.cwd,
            resumeSessionId,
            builtInMcpDomains,
            ...(isAgentProviderKind(kind) ? { userMcpOverrides: userMcpOverridesFrom(builtInMcpOverrides) } : {}),
            recoverTmuxName: kind === 'terminal' ? meta.tmuxName : undefined,
            dangerousMode: isAgentSessionKind(kind) ? refs.dangerousAgentsRef.current : undefined,
            useProxy: isAgentSessionKind(kind) ? refs.useProxyStreamingRef.current : undefined,
          })
          if (!recovery.ok) {
            readyError = new Error(recovery.message)
            reportLifecycle('recover.request', sessionId, {
              caller,
              ok: false,
              code: recovery.code,
              durationMs: Date.now() - recoverStartedAt,
            })
            recoveryFailureCode = priorRecoveryFailureCode === 'ownership-conflict'
              ? 'ownership-conflict'
              : recovery.code
          } else {
            ownershipProven = true
            recoverySnapshot = recovery.snapshot
            recoveredTmuxName = recovery.tmuxName
            recoveryDisposition = recovery.disposition
            // disposition + readiness together are the #596 fingerprint: an
            // ADOPTED backend reporting ready:false is the state whose 30s
            // timeout used to kill a healthy busy agent.
            reportLifecycle('recover.request', sessionId, {
              caller,
              ok: true,
              disposition: recovery.disposition,
              lifecycle: recovery.snapshot.lifecycle,
              ready: recovery.snapshot.input.ready,
              reason: recovery.snapshot.input.reason ?? null,
              durationMs: Date.now() - recoverStartedAt,
            })
            setRuntimes(prev => {
              const current = prev[sessionId]
              if (!current) return prev
              // Any failed/exited state observed AFTER the wake transition to
              // spawning is a real provider event and outranks the returned
              // snapshot. The stale failure that initiated retry was cleared
              // above, so a successful retry is not trapped in "failed".
              const preserveObservedTerminalProcess = current.processStatus === 'failed' ||
                current.processStatus === 'exited'
              const snapshotIsAuthoritative = recovery.snapshot.input.revision >=
                current.inputReadinessRevision
              const observedReplacementWhileRecovering =
                current.sessionRunId !== null &&
                current.sessionRunId !== sessionRunIdBeforeRecovery
              // WHY this ordering is load-bearing for replacement safety:
              // adoption/recovery snapshots repair the missing started edge on
              // reload and replace a retained predecessor id, but a different
              // started id observed during the await is newer evidence. Never
              // let the delayed recovery response relabel successor events as
              // belonging to the backend that produced the response.
              const recoveredSessionRunId = observedReplacementWhileRecovering
                ? current.sessionRunId
                : recovery.snapshot.sessionRunId ?? current.sessionRunId
              return {
                ...prev,
                [sessionId]: {
                  ...current,
                  sessionRunId: recoveredSessionRunId,
                  ...(preserveObservedTerminalProcess
                    ? {}
                    : {
                        processStatus: recovery.snapshot.lifecycle === 'live'
                          ? 'started' as const
                          : 'spawning' as const,
                        processError: null,
                        recoveryFailureCode: null,
                        ...(snapshotIsAuthoritative
                          ? {
                              inputReady: recovery.snapshot.input.ready,
                              inputReadinessRevision: recovery.snapshot.input.revision,
                              // WHY the reason and clock are seeded here too:
                              // main's setInputReadiness DEDUPES, so a backend
                              // that was already non-ready before this wake
                              // will never emit another readiness event. Without
                              // seeding, the pane falls back to a generic
                              // "starting agent" with no elapsed time —
                              // precisely the wedged case the readout exists
                              // for. The reason is already on the wire.
                              inputReadinessReason: recovery.snapshot.input.reason ?? null,
                              inputReadinessChangedAt: Date.now(),
                            }
                          : {}),
                        exited: null,
                      }),
                },
              }
            })
            // The runtime exists and the backend is live, so main can re-emit
            // what it is blocked on (#895). A parked agent woken onto a
            // backend that is ALREADY sitting on a permission or a question
            // hears nothing otherwise: providers publish conditions only when
            // they CHANGE, and this renderer has never seen one for it.
            void window.api.reseedSessionConditions?.([sessionId])
          }
        } catch {
          // WHY unexpected IPC errors use a fixed message: rejected invokes
          // can contain provider commands, environment fragments, or scoped
          // MCP URLs. Typed recovery results carry the safe operational detail;
          // transport failures never become pane content or toast text.
          readyError = new Error('Backend recovery failed unexpectedly. Retry this pane.')
          recoveryFailureCode = priorRecoveryFailureCode
        }

        // An ADOPTED live backend is already up. Waiting on its input
        // readiness is not just pointless, it is actively destructive.
        //
        // `input.ready` is false for a healthy Claude agent whenever a
        // provider condition is on screen OR the raw composer holds any
        // text (`derivePromptGateState`, claudeSession.ts). In terminal
        // mode the user types straight into the TUI and answers permission
        // prompts there, so "draft present" is the NORMAL state.
        //
        // Note what the problem was NOT: readiness does get re-published.
        // `publishPromptGate` emits on every transition into ready and
        // `setInputReadiness` only dedupes unchanged values, so clearing the
        // draft or answering the prompt unblocks the poll. The timeout was
        // guaranteed for one reason only — the pane the user would have used
        // to do either was BLANK, because AgentTerminalLeaf chained its
        // attach behind this wake. (That chaining is gone now; the attach
        // happens first.) Recording this because the edge-trigger theory is
        // the tempting one and it sends you to the wrong file.
        //
        // Either way the wait is meaningless for a backend that was already
        // running before this call, and it ended in
        // killSessionBackendIfOwned() below. That is issue #596: opening
        // Spotlight, or switching tabs, killed a live, busy, perfectly
        // healthy agent 30 seconds later.
        //
        // The `lifecycle === 'live'` conjunct is redundant today — `adopted`
        // is only returned when a RegistryEntry already existed, which is
        // exactly what makes the snapshot 'live'. It is kept so the skip
        // stays anchored to observed liveness rather than to a disposition
        // label a future recover() might widen.
        // `joined` (#772) is the same situation from the other side: another
        // caller — normally the rehydrate recovery — started this backend and
        // this wake merely attached to that start. A readiness deadline on the
        // joiner used to kill the shared start under the restart herd.
        const adoptedLiveBackend =
          (recoveryDisposition === 'adopted' || recoveryDisposition === 'joined') &&
          recoverySnapshot?.lifecycle === 'live'
        // WHY the terminal runtime never waits: its "ready" is first PTY byte
        // + 250 ms (opencodeTerminalSession), a boot-latency measurement, and
        // a caller that opted out (AgentTerminalLeaf) shows the booting TUI
        // and lets the user type at it.
        const skipReadinessWait =
          options?.awaitInputReady === false ||
          // Effective: Pi panes are terminal-only even without a stored runtime.
          effectiveProviderRuntime(meta.kind ?? DEFAULT_PROVIDER, meta.providerRuntime) === 'terminal'
        let readyTimedOut = false
        if (
          !readyError &&
          recoverySnapshot &&
          !recoverySnapshot.input.ready &&
          !adoptedLiveBackend &&
          !skipReadinessWait
        ) {
          try {
            await waitForSessionInputReady(refs, sessionId)
          } catch (err) {
            // WHY a timeout with a LIVE backend is not a failure (#772): the
            // wait rejects immediately for a backend that exited or failed to
            // start, so reaching the deadline means the process is alive and
            // merely slow — an opencode TUI booting under a dozen concurrent
            // CLI starts, a Codex resume of a 90 MB rollout. Killing it made
            // every restart a 30 s wait followed by a dead pane the user had
            // to retry by hand (observed 94 s, 217 s and 556 s after boot).
            // The pane stays at its current status, not-ready, and readiness
            // arrives whenever the composer does. Only an observed exit or
            // start failure keeps the destructive path below.
            const observed = refs.latestRuntimesRef.current[sessionId]
            const backendAlive =
              observed !== undefined &&
              observed.processStatus !== 'failed' &&
              (observed.exited === null || observed.exited === undefined)
            if (backendAlive) {
              readyTimedOut = true
            } else {
              readyError = err
            }
            // A provider that started but never reached its real composer
            // boundary must be replaced, not repeatedly re-adopted on Retry.
            // Main rechecks kind+cwd atomically, so a stale/conflicted pane
            // cannot use this timeout to stop another workspace's backend.
            //
            // SPAWNED ONLY. That reasoning (from #548) is about a process
            // THIS call just started which never came up. Applied to an
            // adopted backend it means "this agent is busy, so destroy it",
            // and the kind+cwd ownership proof cannot catch that — it is
            // the same entry we successfully adopted moments ago, so the
            // proof passes trivially. The guard above already skips the
            // wait for adopted+live; this second check is deliberate belt
            // and braces, so a future caller that reaches the wait some
            // other way still cannot turn a timeout into a kill.
            //
            // ACCEPTED COST, stated plainly: `lifecycle: 'live'` means a
            // RegistryEntry exists, not that the process is healthy — and
            // `sessions.set()` runs before `await session.start()`. So a
            // provider that registers and then wedges before its composer
            // (hung MCP handshake, say) is now adopted and skipped rather
            // than killed. Before this change the 30s timeout would have
            // killed it and marked the pane `failed`, which is what surfaces
            // the Retry button; now it sits at `started` + not-ready with no
            // in-app retry short of closing the pane. That trade is
            // deliberate — wrongly killing a busy healthy agent is far more
            // common and far worse than a stuck pane on a wedged one — but
            // it does mean #548's self-heal no longer covers this class, and
            // nothing has replaced it.
            if (readyError && recoveryDisposition === 'spawned') {
              void killSessionBackendIfOwned(refs, sessionId, 'wake.spawn-failed').catch(() => undefined)
            }
          }
        }

        if (readyError) {
          const message = readyError instanceof Error && readyError.message.length > 0
            ? readyError.message
            : `Could not wake session ${sessionId}.`
          // WHY this is here and not beside the recovery result: recovery
          // succeeding is NOT the wake succeeding. After a successful recover
          // this function still waits on readiness, and on timeout it kills a
          // spawned backend and fails the pane. Recording ok:true at the
          // recovery boundary meant the #548/#596 path — the exact incident
          // this instrumentation exists for — was journaled as a success.
          reportLifecycle('wake.result', sessionId, {
            caller,
            ok: false,
            disposition: recoveryDisposition,
            code: recoveryFailureCode ?? 'start-failed',
            durationMs: Date.now() - recoverStartedAt,
          })
          setRuntimes(prev => {
            const current = prev[sessionId]
            if (!current) return prev
            return {
              ...prev,
              [sessionId]: {
                ...current,
                processStatus: 'failed',
                processError: message,
                recoveryFailureCode: ownershipProven
                  ? 'start-failed'
                  : recoveryFailureCode ?? priorRecoveryFailureCode ?? 'start-failed',
                inputReady: false,
                inputReadinessReason: null,
                inputReadinessChangedAt: Date.now(),
              },
            }
          })
          throw readyError
        }

        const recoveredBuiltInMcpDomains =
          isAgentProviderKind(kind)
            ? resolveSessionBuiltInMcpDomains({
                provider: kind,
                // WHY the backend snapshot wins after successful recovery:
                // `adopted` means main kept an already-running provider whose
                // launch-time MCP token cannot be changed by this renderer
                // request. Falling back preserves compatibility with an older
                // or test recovery response that predates this observed fact.
                sessionDomains:
                  recoverySnapshot?.builtInMcpDomains ?? builtInMcpDomains,
                defaultDomains: [],
              })
            : undefined
        const recoveredMeta: SessionMeta = {
          ...restoredMeta,
          builtInMcpOverrides,
          ...(recoverySnapshot?.tldrIdentity ? { tldrIdentity: recoverySnapshot.tldrIdentity } : {}),
          providerRuntime: recoverySnapshot?.providerRuntime ?? meta.providerRuntime,
          ...(recoveredBuiltInMcpDomains !== undefined
            ? { builtInMcpDomains: recoveredBuiltInMcpDomains }
            : {}),
          // Same rule as the built-in domains above: an adopted backend keeps
          // the servers it was launched with, and only main knows which.
          ...(recoverySnapshot?.userMcpServerIds !== undefined
            ? { userMcpServerIds: recoverySnapshot.userMcpServerIds }
            : {}),
          ...(recoveredTmuxName ? { tmuxName: recoveredTmuxName } : {}),
        }
        // The wake genuinely succeeded: recovery resolved, readiness either
        // arrived or was legitimately skipped for an adopted live backend, and
        // nothing killed the pane on the way through.
        reportLifecycle('wake.result', sessionId, {
          caller,
          ok: true,
          disposition: recoveryDisposition,
          ready: recoverySnapshot?.input.ready ?? null,
          // The #772 fingerprint: ok:true with code:'ready-timeout' is a
          // backend that outlived the deadline instead of being killed by it.
          ...(readyTimedOut ? { code: 'ready-timeout' } : {}),
          durationMs: Date.now() - recoverStartedAt,
        })

        setState(prev => {
          const current = prev.sessions[sessionId]
          if (!current) return prev
          const next = { ...current, ...recoveredMeta }
          // WHY a no-op wake must preserve the meta object's IDENTITY:
          //
          // Callers that survive an await across a wake use this object as
          // their "is my target still the same pane?" token —
          // deliverTextToSession's isCurrent(), and both prompt-template
          // insertion paths, all compare
          // `workspaceState.sessions[id] === originalSession`. This setState
          // ran unconditionally, so ANY wake replaced the object even when
          // every field was unchanged, and those guards then read "the pane
          // changed underneath me" and cancelled.
          //
          // The user-visible bug: inserting a prompt template or a vault key
          // into a pane that was exited, parked, or still spawning ALWAYS
          // failed the first time with "target pane is gone" / "Focused pane
          // is no longer available", then worked on the retry — because by
          // then the session was 'started', no wake ran, and no replacement
          // happened. That is the whole "flaky, works the second time"
          // signature.
          //
          // Comparing content rather than trusting the spread is the correct
          // fix and not merely the local one: recoveredMeta genuinely changes
          // fields some of the time (withoutProvisionalProviderSession can
          // drop them), so a real change must still produce a new object and
          // still invalidate those guards. Only a no-op is made free.
          if (metaIsUnchanged(current, next)) return prev
          return {
            ...prev,
            sessions: {
              ...prev.sessions,
              [sessionId]: next,
            },
          }
        })

        if (
          isAgentSessionKind(kind) &&
          resumeSessionId &&
          refs.stateRef.current.sessions[sessionId] &&
          refs.latestRuntimesRef.current[sessionId]
        ) {
          // Parked/buried sessions do not hydrate history at app bootstrap.
          // Their explicit wake is therefore the first safe moment to rebuild
          // the durable feed, including legacy Claude metadata whose kind was
          // absent and defaulted above.
          void loadInitialHistoryForSession({
            sessionId,
            meta: recoveredMeta,
            refs,
            setRuntimes,
          })
        }

        // This used to also return the recovered capability list, because
        // provider switching resolved MCP itself and could not safely re-read
        // `stateRef` straight after an await: Zustand updates the store
        // synchronously, but React may not have refreshed a render-owned ref
        // yet. That batching window no longer matters for MCP. Replacement
        // resolves from the pane's CHOICES, and a wake never changes those — it
        // only refreshes the observed list — so reading the pre- or post-wake
        // meta produces the same decision. If a future caller needs a fact this
        // wake established, return it here rather than re-reading the ref.
        return { sessionId }
      })()

      wakeInFlightRef.current.set(sessionId, wake)
      try {
        return await wake
      } finally {
        if (wakeInFlightRef.current.get(sessionId) === wake) {
          wakeInFlightRef.current.delete(sessionId)
        }
      }
    },
    [
      refs.dangerousAgentsRef,
      refs.stateRef,
      refs.useProxyStreamingRef,
      setRuntimes,
      setState,
    ],
  )

  // Everything the renderer holds for a session, dropped once its backend is
  // gone. Shared by killSession and reload's orphan kill (#1326 second
  // verification A/C): an orphan's startup feed can create a runtime entry
  // before its spawn resolves, and a kill that skipped this left that entry
  // behind as unreachable `started` state.
  const forgetSessionLocally = useCallback(
    (sessionId: SessionId) => {
      setRuntimes(prev => {
        const next = { ...prev }
        delete next[sessionId]
        return next
      })
      // One removal for the whole workspace (pool.ts): the row leaves the pool,
      // every lane that showed it goes EMPTY and stays empty (U2, #681), its
      // pin is dropped, and a project it leaves with no sessions goes with it.
      // Until #992 this site deleted the row and the detachedSessions record
      // and left the tree to its callers, which is how a killed leaf could
      // outlive its metadata.
      setState(prev => workspaceWithoutSessions(prev, [sessionId]))
      delete refs.seenUuidsRef.current[sessionId]
      // Live-window bookkeeping follows the seen-uuid lifecycle (see
      // liveEntryWindow.ts: trimmed ⊆ ever-seen must hold).
      clearLiveEntryWindowSession(sessionId)
      // If a bootstrap debounce was in flight for this session,
      // cancel it — the session is gone; firing the deferred
      // bootstrapping→false flip later would be a no-op against a
      // missing runtime but it's cleaner to release the timer
      // immediately.
      const timer = refs.bootstrapTimersRef.current.get(sessionId)
      if (timer) {
        clearTimeout(timer)
        refs.bootstrapTimersRef.current.delete(sessionId)
      }
    },
    [refs.bootstrapTimersRef, refs.seenUuidsRef, setRuntimes, setState],
  )

  const killSession = useCallback(
    async (
      sessionId: SessionId,
      caller: KillCaller,
      capturedOwner?: Pick<SessionMeta, 'cwd' | 'kind' | 'providerRuntime'>,
    ) => {
      await killSessionBackendIfOwned(refs, sessionId, caller, capturedOwner)
      forgetSessionLocally(sessionId)
    },
    [forgetSessionLocally, refs],
  )

  // Kills the current session in the focused leaf and spawns a new
  // one in the same position. Used by the resume flow to swap a
  // session without changing the tile tree structure — the pane
  // stays where it is, only its backing session changes.
  const replaceSession = useCallback(
    async (
      cwd: string,
      opts?: {
        resumeSessionId?: string
        kind?: SessionKind
        providerRuntime?: AgentProviderRuntime
        /** Per-domain choices this replacement should ADOPT. Omit to continue
         * the pane's existing choices; replacement never takes the previous
         * process's effective capability list as intent. */
        builtInMcpOverrides?: BuiltInMcpOverrides
        preserveTldr?: boolean
        restoreTldrIdentity?: string
        targetSessionId?: SessionId
        /**
         * True when what runs in the pane becomes an UNRELATED conversation —
         * the Conversations picker's in-place swap, where the user pulls some
         * past conversation into the pane they are looking at.
         *
         * WHY the callee cannot work this out for itself (#1090 review): every
         * other caller continues the SAME agent (reload, provider switch,
         * resume, rewind, undo-rewind, an MCP-domain reload), and from inside
         * `replaceSession` they are indistinguishable from the picker — all of
         * them pass a `resumeSessionId` that differs from the pane's current
         * `providerSessionId`, and a provider switch changes `kind` too, so
         * neither "same id" nor "same provider" separates them. Only the
         * caller knows which of the two things it is doing.
         *
         * What it turns off is the relationship carry below. Without it, the
         * picker made an unrelated conversation inherit the pane's
         * orchestration parentage: `wait_agents` would poll a stranger's
         * activity, `read_agent` would report its last message as the child's
         * answer to a task it never saw, `close_run` would kill the user's
         * resumed conversation, and the bootstrap-delivered flag would claim a
         * brief that conversation never received. Position, project membership
         * and the pane's MCP choices still carry — it is still that pane.
         */
        newConversation?: boolean
      },
    ): Promise<SessionId | undefined> => {
      const snapshot = refs.stateRef.current
      const { targetSessionId: _targetSessionId, preserveTldr, restoreTldrIdentity, ...spawnOpts } = opts ?? {}
      // `replaceSession` powers resume, reload, provider-switch, and rewind.
      // Those commands target the thing the user is visibly commanding — the
      // focused lane's occupant. Targeting anything else would make the
      // palette labels talk about one agent while the destructive replacement
      // happened to another.
      // WHY callers may pin the target:
      // Most command actions should follow the *current* command target at the
      // moment replacement begins. Rewind is different: main may spend time
      // cloning a provider transcript before the pane swap, and the user can
      // legitimately focus another pane during that await. Re-reading focus
      // after the clone would replace the wrong pane with the rewound provider
      // id. `targetSessionId` lets those two-phase operations say "replace the
      // pane I validated before the await" while preserving the default
      // Dispatch-aware targeting for simple one-shot commands.
      const oldId = _targetSessionId ?? commandTargetSessionIdForState(snapshot)
      if (!oldId) return
      const oldMeta = snapshot.sessions[oldId]
      if (!oldMeta) return
      const nextKind = spawnOpts.kind ?? oldMeta?.kind ?? DEFAULT_PROVIDER
      // Reload/resume of the same provider preserves its execution surface;
      // switching providers drops it because runtime capabilities are owned by
      // the target provider, not transferable pane decoration.
      const providerRuntime = spawnOpts.providerRuntime ?? (
        nextKind === (oldMeta.kind ?? DEFAULT_PROVIDER)
          ? oldMeta.providerRuntime
          : undefined
      )
      // WHY replacement resolves MCP here instead of trusting a caller-supplied
      // list: every path through here (reload, resume, provider switch, rewind,
      // undo, a capability toggle) CONTINUES one pane, so the pane's own
      // per-domain choices are the intent, and the effective capability list of
      // the process being replaced is merely an observation of how it happened
      // to launch. Treating that observation as intent is exactly what froze
      // agents at their creation-time defaults (#904) — a Settings change could
      // reach new agents and never existing ones. Callers that genuinely change
      // the intent (the capability toggles, Use Global MCP Settings, Undo
      // Rewind restoring a captured choice) pass `builtInMcpOverrides`; nobody
      // needs to restate the domains, so there is one source of truth.
      //
      // Resolving against nextKind rather than the source provider matters on a
      // switch: Claude cannot advertise Workflow MCP, so a Claude-filtered
      // snapshot would otherwise record "refused" and permanently strip the
      // capability from the Codex pane the user switched to.
      const builtInMcpOverrides = spawnOpts.builtInMcpOverrides ?? sessionMcpOverrides(oldMeta)
      const builtInMcpDomains =
        isAgentProviderKind(nextKind)
          ? resolveSessionBuiltInMcpDomains({
              provider: nextKind,
              sessionOverrides: builtInMcpOverrides,
              defaultDomains: refs.defaultBuiltInMcpDomainsRef.current,
            })
          : undefined
      const canCommit = (state: WorkspaceState) => {
        const current = state.sessions[oldId]
        return Boolean(current && current.cwd === oldMeta.cwd && current.kind === oldMeta.kind
          && current.providerRuntime === oldMeta.providerRuntime
          // Still owned: its project still exists. (A `buried` check sat here
          // too until #992 folded burial into the pool.)
          && collectOwnedSessionIds(state).has(oldId))
      }
      if (!canCommit(snapshot)) return
      const draftFallback = refs.latestRuntimesRef.current[oldId]
      const newId = await spawn(cwd, {
        // Undo Rewind verifies its original/rewound transcript pair before
        // supplying the saved original identity. Ordinary resume/reload must
        // still derive continuity from the current conversation; preserving
        // the rewound branch's identity would lose the original summary.
        tldrIdentity: restoreTldrIdentity ?? tldrIdentityForReplacement(oldId, oldMeta, {
          kind: nextKind, resumeSessionId: spawnOpts.resumeSessionId, preserveTldr,
        }),
        ...spawnOpts,
        providerRuntime,
        // WHY main needs the local predecessor even though the renderer kills
        // it below: resumed Codex owns an exact rollout lease before its PTY
        // starts. The historical start-success-before-old-stop ordering makes
        // the successor collide with the pane it is replacing (#638). Naming
        // this exact local owner lets main perform only the unavoidable
        // same-rollout handoff; Claude, OpenCode, fresh Codex, and different-
        // transcript swaps retain the rollback-friendly ordering here.
        predecessorSessionId: oldId,
        // The same tag the renderer's own predecessor kill below uses, so a
        // replaceSession journals 'replace.predecessor' whether main (Codex
        // same-rollout handoff) or the renderer (every other swap) does it.
        predecessorKillCaller: 'replace.predecessor',
        ...(builtInMcpDomains !== undefined ? { builtInMcpDomains, builtInMcpOverrides } : {}),
      })
      // WHY a finally, and why it wraps EVERY exit path including the bail-outs:
      // a stranded reservation would leave that pane permanently unnamed, which is
      // the mirror-image bug and just as bad as the leak it prevents. Releasing an
      // id that was never reserved is a no-op, so an ordinary spawn costs nothing.
      try {
        const mainHandledPredecessor =
          pendingReplacementSuccessorsRef.current.delete(newId)
        // A source can close or be buried while spawn awaits. Metadata alone
        // is not ownership: committing an unplaced successor creates an invisible
        // process and a false "completed" lifecycle receipt (#815). Read through
        // the synchronous domain setter because React-owned refs can lag the last
        // close action. A no-op updater preserves store identity and notifications.
        let sourceOwned = false
        setState(prev => { sourceOwned = canCommit(prev); return prev })
        if (!sourceOwned) {
          await killSession(newId, 'replace.orphaned-successor', { cwd, kind: nextKind, providerRuntime })
          return
        }
        if (!mainHandledPredecessor) {
          await killSessionBackendIfOwned(refs, oldId, 'replace.predecessor', oldMeta)
        }
        // Swap the sessionId everywhere it is referenced: the pool row, the
        // lanes, the pins and other rows' relationship pointers.
        const idMap = new Map<SessionId, SessionId>([[oldId, newId]])

        let committed = false
        setState(prev => {
          // Backend retirement is another await. Recheck inside the actual remap
          // commit, before touching the source draft or returning a successor ID.
          if (!canCommit(prev)) return prev
          committed = true
          const sessions = { ...prev.sessions }
          // WHY read the title from `prev` here instead of the pre-spawn
          // snapshot: provider switches and rewinds can wait on backend work,
          // and the user may edit or clear the pane's title during that window.
          // The replacement is the same logical pane with a fresh transport id,
          // so its durable glance label must follow using the latest state rather
          // than being lost—or resurrected from a stale snapshot—on completion.
          const replacementTitle = prev.sessions[oldId]?.title
          // `prev.sessions[oldId]` is still readable here: only the local
          // `sessions` copy has had oldId deleted.
          const carriedAgentNameId = prev.sessions[oldId]?.agentNameId
          // The successor IS the same row in the same project at the same
          // place in its index — only the backend changed. Until #992 this was
          // implicit: the id was swapped inside the tile leaf or the detached
          // record that owned it, so position came for free. Ownership lives
          // on the row now, so it has to be carried like the title is.
          const carriedMembership = inheritedMembership(prev.sessions[oldId])
          // The successor is the same CHILD of the same parent in the same run
          // (#879). `remapSessionsRelationships` below fixes every OTHER
          // session that points AT the old id; it cannot restore the swapped
          // row's own outbound pointers, because spawn never gave it any. An
          // orchestration child that lost them went invisible to its parent,
          // and `orchestration_wait_agents` computes `done` over the
          // parent-visible list — so the parent was told every child had
          // finished while this one was still working.
          const carriedRelationshipFields = opts?.newConversation
            ? {}
            : carriedRelationships(prev.sessions[oldId])
          delete sessions[oldId]
          // Persist the replacement provider metadata immediately
          // instead of waiting for the first transcript line to
          // round-trip back from main. That wait window is usually
          // short, but it is still a real race: a workspace save or
          // pane action that snapshots SessionMeta in that gap would
          // see "new session id, but no providerSessionId yet" and
          // could forget how to resume the pane on the next launch.
          //
          // Keeping the requested resumeSessionId here makes
          // replaceSession the single source of truth for "this pane
          // now points at provider X's persisted transcript Y",
          // whether the trigger was the resume picker or the new
          // switch-provider flow.
          sessions[newId] = {
            ...(sessions[newId] ?? { cwd, kind: nextKind }),
            cwd,
            kind: nextKind,
            providerRuntime,
            ...(spawnOpts.resumeSessionId
              ? {
                  providerSessionId: spawnOpts.resumeSessionId,
                  providerSessionIdSource: 'resume-request' as const,
                }
              : {}),
            ...(builtInMcpDomains !== undefined ? { builtInMcpDomains, builtInMcpOverrides } : {}),
            ...(replacementTitle !== undefined ? { title: replacementTitle } : {}),
            // Last on purpose. `...(sessions[newId] ?? …)` earlier in this
            // literal is the successor's OWN freshly-spawned metadata, so any
            // earlier position is overwritten by it — which is exactly how the
            // sketch renamed a pane on every provider switch.
            //
            // Conditional, not `?? oldId`: this site CARRIES an identity, it
            // never creates one. If the predecessor had none — names were off,
            // or the reconciler had not run — then no name was ever allocated to
            // preserve, and inventing `oldId` here would make replacement a
            // second minting site competing with the reconciler for that
            // decision. Leaving it absent lets the reconciler claim the
            // successor under its own id, which is the same outcome by the one
            // rule the feature has.
            ...(carriedAgentNameId !== undefined ? { agentNameId: carriedAgentNameId } : {}),
            // After the spread for the same reason: the successor's own row
            // was written by `spawn` and is un-filed.
            ...carriedMembership,
            ...carriedRelationshipFields,
            // The user's per-pane view choice, which this literal dropped
            // (found in the #1090 review). It is not a relationship, so the
            // keep-list above deliberately does not cover it — but it is the
            // same class of loss: `agentViewModeOverride` is the user saying
            // "show THIS pane as a terminal whatever the global default is",
            // `undoClose` restores it, and every reload silently reverted it.
            ...(prev.sessions[oldId]?.agentViewModeOverride
              ? { agentViewModeOverride: prev.sessions[oldId]!.agentViewModeOverride }
              : {}),
            // Same class as agentViewModeOverride: user-owned state on the pane.
            // The pocketId inside it names the live page and its cookie jar,
            // so dropping it here would reload the page and log the user out
            // of their dev app on every reload / provider switch / rewind.
            ...(prev.sessions[oldId]?.browserPocket
              ? { browserPocket: prev.sessions[oldId]!.browserPocket }
              : {}),
          }
          return {
            ...prev,
            // The other half of the carry above (#879), and the reason the
            // carry can hand over a pointer without checking it first: this
            // pass drops any pointer whose target survived under neither a new
            // nor an old id, so a predecessor that outlived its parent yields
            // an orphan rather than a link into nothing.
            //
            // Remap relationship pointers across ALL sessions: a linked /
            // orchestration CHILD of the swapped session carries oldId in its
            // linkedParentId/orchestrationParentId/orchestrationRootId, so the
            // swap has to update those too or the child renders top-level and
            // parent-scoped orchestration reads break. (rehydrate already does
            // this; reload/switch/resume/rewind funnel through here and didn't.)
            sessions: remapSessionsRelationships(sessions, idMap),
            // A pinned agent that gets a fresh id on reload/switch must follow
            // to the new id instead of silently dropping out of the Pinned list.
            pinnedSessionIds: remapPinnedSessionIds(prev.pinnedSessionIds, idMap),
            // Remap the swapped session id in every lane that shows it
            // (stage.lanes[].selectedSessionId). reload / provider-switch /
            // resume / rewind all funnel through here; before this, the
            // focused lane kept pointing at the now-dead oldId and went blank
            // under the user mid-conversation. Same lane-vs-owner divergence
            // as #266/#267/#271, fixed at the swap. (A classic-Dispatch focus
            // was remapped beside the lanes until #992 removed the field.)
            stage: remapTiledLanes(prev.stage, idMap),
          }
        })
        if (!committed) {
          await killSession(newId, 'replace.orphaned-successor', { cwd, kind: nextKind, providerRuntime })
          return
        }
        // Not for a DIFFERENT conversation swapped into the pane (the picker's
        // newConversation), and not into a process without Goal Loop tools:
        // it could never call goal_loop_complete (#1287 review A).
        if (!opts?.newConversation && builtInMcpDomains?.includes('goal_loop')) carryGoalLoops(idMap)
        else stopGoalLoops([oldId])
        // Workflow runs follow the same conversation into its successor
        // (#1280). A different conversation swapped into the pane does not
        // inherit them: they belong to the conversation that started them.
        if (!opts?.newConversation) carryWorkflowRuns(idMap)
        setRuntimes(prev => {
          // Replacement can await spawn and backend retirement while the user
          // keeps editing. Transfer the latest draft in the same state update
          // that retires its owner; a pre-await snapshot silently loses edits.
          // All replacement paths share this contract. Rewind deliberately
          // substitutes its historical prompt afterwards and keeps an undo copy.
          const draft = prev[oldId] ?? draftFallback
          const next = {
            ...prev,
            [newId]: {
              ...(prev[newId] ?? emptyRuntime()),
              draftInput: draft?.draftInput ?? '',
              // Unsupported invisible attachments participate in submit guards.
              // Preserve images only when the destination can expose them.
              draftImages: isAgentProviderKind(nextKind) && getRendererProviderCapabilities(nextKind).supportsImageAttachments
                ? (draft?.draftImages ?? []) : [],
            },
          }
          delete next[oldId]
          return next
        })
        delete refs.seenUuidsRef.current[oldId]
        clearLiveEntryWindowSession(oldId)

        return newId
      } finally {
        releaseIdentityCarry(newId)
      }
    },
    [
      refs.latestRuntimesRef,
      refs.seenUuidsRef,
      refs.stateRef,
      setRuntimes,
      setState,
      spawn,
      killSession,
    ],
  )

  // Recreates every registered agent session with the requested
  // dangerous mode, then remaps visible panes and buried records
  // onto the fresh session ids. Plain terminal sessions are left
  // untouched.
  // Successors of a reload whose agent was closed while they spawned, and
  // whose kill has failed twice; keyed by successor id.
  const unstoppedReloadSuccessorsRef = useRef(new Map<SessionId, ReloadOrphan>())
  // WHY a failed orphan kill is retried and remembered instead of swallowed
  // (#1326 round-2 review C3): the successor is filed nowhere, so no pane
  // exists from which the user could close it, and a swallowed rejection
  // meant a hidden backend with no owner at all. A rejection here is an IPC
  // or main-side failure, not "already gone" (that resolves false), so one
  // immediate retry covers a transient one. After that the successor stays in
  // `unstoppedReloadSuccessorsRef`, which the next reload retries first, and
  // application quit kills every backend regardless (applicationShutdown's
  // killAll), so it is never ownerless. It does not throw: the other agents
  // of this reload must still be restarted and filed (#1326 review A4).
  // The log line is curated: IPC error text can carry env values (q22).
  //
  // WHY a `false` answer is NOT treated as stopped (#1326 verification C):
  // `session:kill-owned` answers false both for "nothing left to stop" and
  // for "you do not own that backend" (a refused ownership proof or window
  // lease), and in the second case the process is still running. The renderer
  // cannot tell them apart, so only `true` clears the record. A backend that
  // was already gone then costs one IPC call per later reload, which is the
  // price of never forgetting one that is still alive.
  const killOrphan = useCallback(async (orphan: ReloadOrphan): Promise<void> => {
    for (let attempt = 0; attempt < 2; attempt++) {
      try {
        if (await killSessionBackendIfOwned(refs, orphan.newId, 'reload.orphaned-successor', orphan.owner)) {
          unstoppedReloadSuccessorsRef.current.delete(orphan.newId)
          forgetSessionLocally(orphan.newId)
          return
        }
        // Refused (or already gone): not retried at once, a refusal will not
        // change within this reload.
        break
      } catch {
        // Retried once below, then remembered.
      }
    }
    unstoppedReloadSuccessorsRef.current.set(orphan.newId, orphan)
    // eslint-disable-next-line no-console
    console.warn('[workspace] could not confirm a reload successor of a closed agent stopped; retrying on the next reload:', orphan.newId)
  }, [forgetSessionLocally, refs])

  const reloadAgentSessionsNow = useCallback(
    async (dangerousMode: boolean) => {
      const current = refs.stateRef.current
      const ownedIds = collectOwnedSessionIds(current)
      const staleIds = collectUnownedSessionIds(current)
      if (staleIds.length > 0) {
        // WHY reload prunes but does not kill unowned ids directly:
        //
        // `reloadAgentSessions` is a user-visible policy change ("restart the
        // owned agents with the current dangerous-mode setting"), not a
        // workspace garbage collector. If an unowned runtime process exists,
        // it has already escaped the UI ownership model; respawning it here is
        // the bug. Dropping the metadata prevents the stale row from surviving
        // the reload/autosave cycle, while process cleanup can stay best-effort
        // at the explicit kill/session-manager layer.
        // eslint-disable-next-line no-console
        console.warn('[workspace] dropping unowned sessions during agent reload:', staleIds)
      }
      // WHY only sessions that HAVE a backend, not every owned agent:
      //
      // A parked agent has no PTY, no mitmdump, and no provider process to
      // reload. Toggling dangerous mode while parked agents exist once called
      // killSession + spawnSession on every one of them, which re-introduced
      // the #258 fork bomb in a different code path: a single mode toggle
      // resurrected N hibernated agents as live processes. A parked agent
      // picks up the new setting when it is next woken.
      //
      // The test is the RUNTIME, not a structure. Until #992 it was "is a tile
      // leaf" (collectLiveProcessIds), which was only ever a proxy for "was
      // spawned at boot" — and a wrong one, since an agent woken from a lane
      // had a backend and was skipped. `processStatus` is "does a writable
      // backend exist for this session": everything but 'idle' has (or had,
      // and visibly lost) one, which is exactly what a reload should restart.
      const runtimesNow = refs.latestRuntimesRef.current
      const agentEntries = Object.entries(current.sessions).filter(([id, meta]) => {
        if (!ownedIds.has(id)) return false
        const processStatus = runtimesNow[id]?.processStatus
        if (processStatus === undefined || processStatus === 'idle') return false
        const kind = meta.kind ?? DEFAULT_PROVIDER
        return isAgentProviderKind(kind)
      })
      // Successors an earlier reload spawned for an agent closed meanwhile
      // and then could not confirm stopped (see killOrphan). Retried FIRST,
      // before the no-live-agents return below (#1326 verification A/C): the
      // user who closed every agent is exactly the one whose hidden
      // successor would otherwise run until quit.
      for (const orphan of [...unstoppedReloadSuccessorsRef.current.values()]) await killOrphan(orphan)

      // Pruned up front, not only inside each successor's commit
      // (#1326 verification A): a reload whose every respawn failed commits
      // nothing, and it still announced above that it drops these rows.
      if (staleIds.length > 0) setState(prev => ({ ...prev, sessions: pickOwnedSessions(prev.sessions, collectOwnedSessionIds(prev)) }))

      if (agentEntries.length === 0) return

      // Is `oldId` still the agent this loop set out to reload? (#1282) The
      // loop awaits a kill and a spawn per agent while the user keeps
      // working, and it used to re-check nothing: an agent closed meanwhile
      // was respawned under a new id (an invisible orphan if its project had
      // closed too), and one replaced meanwhile (a provider switch) got two
      // successors on one provider transcript. Same rule as replaceSession's
      // canCommit (#815). Read through the setState updater, the one place
      // that sees the state as it is now, not as this closure captured it.
      //
      // Returns the LIVE row (not the captured one) so the commit files the
      // successor with whatever changed meanwhile that does not affect the
      // spawn: a project merge re-files the same id under another project
      // (#1326 review A2), a rename changes its title.
      const liveReloadable = (oldId: SessionId, meta: SessionMeta): SessionMeta | null => {
        let live: SessionMeta | null = null
        setState(prev => {
          const current = prev.sessions[oldId]
          if (current && current.cwd === meta.cwd && current.kind === meta.kind
            && current.providerRuntime === meta.providerRuntime
            && collectOwnedSessionIds(prev).has(oldId)) live = current
          return prev
        })
        return live
      }

      // WHY each agent is committed as soon as ITS spawn returns, and not in
      // one batch at the end (#1326 round-2 review C): while an early
      // successor waited for a later agent's slow spawn it was running but
      // filed nowhere, so closing its pane killed only the OLD backend and the
      // hidden successor kept working (with Dangerous Agents on, after Close).
      // Round 1 had made the batch commit synchronous, which fixed the commit
      // itself but not that interval. Filed immediately, the successor is the
      // pane: a close from then on is an ordinary close of the new id.
      for (const [oldId, meta] of agentEntries) {
        // Closed or replaced since the snapshot: nothing of ours to reload.
        if (!liveReloadable(oldId, meta)) continue
        try {
          await killSessionBackendIfOwned(refs, oldId, 'reload.agent-sessions')
        } catch {
          // Kill failures still fall through to respawn — the old
          // process may already be gone.
        }
        // Again after the kill's await (#1326 round-2 review C1): a close that
        // finished meanwhile must not be followed by a spawn for it.
        if (!liveReloadable(oldId, meta)) continue

        delete refs.seenUuidsRef.current[oldId]
        clearLiveEntryWindowSession(oldId)

        const kind: SessionKind = meta.kind ?? DEFAULT_PROVIDER
        const builtInMcpOverrides = sessionMcpOverrides(meta)
        const builtInMcpDomains =
          isAgentProviderKind(kind)
            ? resolveSessionBuiltInMcpDomains({
                provider: kind,
                sessionOverrides: builtInMcpOverrides,
                defaultDomains: refs.defaultBuiltInMcpDomainsRef.current,
              })
            : undefined
        const resumeSessionId = resumableProviderSessionId(meta)
        const owner = { cwd: meta.cwd, kind, providerRuntime: meta.providerRuntime }
        let spawned: Awaited<ReturnType<typeof window.api.spawnSession>>
        try {
          spawned = await window.api.spawnSession({
            tldrIdentity: tldrIdentityForSession(oldId, meta),
            kind,
            providerRuntime: meta.providerRuntime,
            cwd: meta.cwd,
            resumeSessionId,
            dangerousMode,
            useProxy: isAgentSessionKind(kind) ? refs.useProxyStreamingRef.current : undefined,
            builtInMcpDomains,
            ...(isAgentProviderKind(kind) ? { userMcpOverrides: userMcpOverridesFrom(builtInMcpOverrides) } : {}),
          })
        } catch (err) {
          // WHY only a curated sentence survives (#1252 review, #1324 review
          // C): the pane renders `processError` verbatim. Main now launders
          // the rejection, but the pane keeps the same rule as every create:
          // a missing CLI or folder names its fix, anything else is the fixed
          // sentence main's recovery path uses.
          //
          // A failed respawn whose agent was closed meanwhile has nothing
          // left to show a `failed` pane in (#1326 review A5); recreating its
          // runtime would leave an invisible stale entry under a closed id.
          if (liveReloadable(oldId, meta)) {
            markRespawnFailed(oldId, (err instanceof Error ? curatedSpawnMessage(err.message, meta.cwd) : null) ?? SESSION_START_FAILED_MESSAGE)
          }
          continue
        }
        const newId = spawned.sessionId
        // No await between this check and the commit below: nothing the user
        // does can land in between.
        const live = liveReloadable(oldId, meta)
        if (!live) {
          await killOrphan({ newId, owner })
          continue
        }

        // The provider session the successor actually runs. A resumed one is
        // the id it was asked to resume. A fresh start (the old row had only
        // a provisional proxy-header id, which is never resumed) may report
        // the new process's durable id at startup (#1326 round-2 review A1):
        // dropping it skipped the history load and let an autosave persist a
        // row with no resume identity. Same rule as spawn()'s own commit.
        // The live row's provider fields are never used: the successor did
        // not resume whatever the old process reported meanwhile.
        const restoredMeta = withoutProvisionalProviderSession(meta)
        const { providerSessionId: _liveProviderSessionId, providerSessionIdSource: _liveSource, ...liveRest } = live
        const providerIdentity: Partial<SessionMeta> = resumeSessionId
          ? { providerSessionId: restoredMeta.providerSessionId, providerSessionIdSource: restoredMeta.providerSessionIdSource }
          : spawned.providerSessionId
            ? { providerSessionId: spawned.providerSessionId, providerSessionIdSource: 'runtime-start' }
            : {}
        const fresh: SessionMeta = {
          // `agentNameId` needs no line here: the live row still carries the
          // identity, and `...liveRest` moves it onto the new local id. Do not
          // add a `?? oldId` fallback — a workspace with no identity has no
          // allocated name to lose, and minting here would put a second
          // author on the one decision the reconciler owns.
          ...liveRest,
          ...Object.fromEntries(Object.entries(providerIdentity).filter(([, value]) => value !== undefined)),
          tldrIdentity: tldrIdentityForSession(oldId, meta),
          ...(builtInMcpDomains !== undefined ? { builtInMcpDomains, builtInMcpOverrides } : {}),
          ...(spawned.userMcpServerIds !== undefined ? { userMcpServerIds: spawned.userMcpServerIds } : {}),
        }
        commitSuccessor(oldId, newId, fresh)
        // Reload Agents resolves each successor's domains from CURRENT
        // defaults; one that lost goal_loop keeps no loop it cannot complete
        // (#1287 review A).
        if (builtInMcpDomains?.includes('goal_loop')) carryGoalLoops(new Map([[oldId, newId]]))
        else stopGoalLoops([oldId])
        // Its workflow runs follow it too (#1280): this successor continues its
        // own conversation, and a run needs no tool in the successor. Only
        // here, after commitSuccessor: a successor killed as an orphan (its
        // pane closed or its reload superseded mid-spawn, #1326) never
        // reaches this line, so its predecessor's runs are never handed to a
        // process that is being killed.
        carryWorkflowRuns(new Map([[oldId, newId]]))
        if (hasDurableProviderSession(fresh)) {
          void loadInitialHistoryForSession({ sessionId: newId, meta: fresh, refs, setRuntimes })
        }
      }

      function markRespawnFailed(oldId: SessionId, processError: string): void {
        // A failed respawn keeps its pane, in the same `failed` state a
        // failed wake uses: its backend was killed above, so the pane must
        // say so and offer Retry (which wakes it under the same id).
        //
        // WHY it stays exactly where it was (#1239): this used to delete it,
        // and the project it left empty, with no message. Toggling Dangerous
        // Agents By Default therefore made any agent with a broken CLI, proxy
        // or MCP start vanish from the workspace, its process already killed,
        // and autosave made that permanent.
        setRuntimes(prev => ({
          ...prev,
          [oldId]: {
            ...(prev[oldId] ?? emptyRuntime()),
            processStatus: 'failed',
            processError,
            recoveryFailureCode: 'start-failed',
            inputReady: false,
            inputReadinessReason: null,
            inputReadinessChangedAt: Date.now(),
          },
        }))
      }

      function commitSuccessor(oldId: SessionId, newId: SessionId, fresh: SessionMeta): void {
        const idMap = new Map([[oldId, newId]])
        setRuntimes(prev => {
          const next: Record<SessionId, SessionRuntime> = { ...prev }
          delete next[oldId]
          // WHY merge instead of replacing with a fresh runtime:
          //
          // Codex resume can synchronously replay JSONL and even emit
          // an exit while `window.api.spawnSession()` is still inside
          // provider start. By the time this reload bookkeeping runs,
          // `prev[newId]` may already contain the real lifecycle
          // outcome. Replacing it with `emptyRuntime()` would resurrect
          // a dead process as "started", which is exactly the reload
          // failure mode where the pane looks stuck and Enter reports
          // "Agent has exited".
          const existing = prev[newId]
          const restored: SessionRuntime = { ...(existing ?? emptyRuntime()) }
          // From the LIVE predecessor runtime (#1282), not a snapshot taken
          // before the slow kill/spawn sequence: text typed, images pasted
          // and a "finished, not seen" marker set meanwhile all carry over.
          const predecessor = prev[oldId]
          restored.draftInput = predecessor?.draftInput ?? existing?.draftInput ?? ''
          if (predecessor?.draftImages?.length) restored.draftImages = predecessor.draftImages
          if (predecessor?.unreadSince != null) {
            restored.unreadSince = predecessor.unreadSince
            restored.unreadKind = predecessor.unreadKind
          }
          // Terminal-runtime agents included: their history reloads into
          // `entries` with everyone else's, and the pane stays on the raw TUI
          // regardless (see loadInitialHistoryForSession).
          Object.assign(restored, seedResumedRuntimeFields(existing, fresh))
          next[newId] = restored
          return next
        })
        setState(prev => {
          // Unowned rows are dropped up front (so an all-failed reload drops
          // them too) AND here: a project removed while an earlier spawn was
          // in flight leaves rows that became unowned after that first prune
          // (#1326 second verification A). Both are pinned by tests.
          const sessions = pickOwnedSessions(prev.sessions, collectOwnedSessionIds(prev))
          delete sessions[oldId]
          // The successor carries its predecessor's LIVE pool membership (the
          // `...liveRest` above), so it keeps its project and its place, even
          // when a project merge moved it while the reload ran.
          sessions[newId] = fresh
          return {
            ...prev,
            // A fresh id: remap relationship pointers across all sessions
            // (children keep pointing at the right parent), the pinned list
            // (pins follow) and the lanes.
            sessions: remapSessionsRelationships(sessions, idMap),
            pinnedSessionIds: remapPinnedSessionIds(prev.pinnedSessionIds, idMap),
            stage: remapTiledLanes(prev.stage, idMap),
          }
        })
      }
    },
    [
      refs.dangerousAgentsRef,
      refs.latestRuntimesRef,
      refs.seenUuidsRef,
      refs.stateRef,
      refs.useProxyStreamingRef,
      setRuntimes,
      setState,
      killOrphan,
    ],
  )

  // WHY reloads run one at a time (#1326 review A1): the Dangerous Agents
  // switch does not serialize clicks, and its handler flips the setting and
  // then awaits a reload. On -> off before the first reload settles used to
  // start two loops over the SAME snapshot; the on-reload committed first,
  // the off-reload then found its agents gone, killed its safe successors as
  // orphans, and left the dangerous ones running while Settings said off.
  // Chaining makes the last click the last reload: it starts from the
  // workspace the earlier one committed (refs are store-subscribed, so they
  // are current the moment that commit returns) and restarts those
  // successors with the final setting. A per-call default of the mode is
  // read when the call is queued, which is the setting that click chose.
  const reloadChainRef = useRef<Promise<void>>(Promise.resolve())
  const reloadAgentSessions = useCallback(
    (dangerousMode = refs.dangerousAgentsRef.current): Promise<void> => {
      const run = reloadChainRef.current.then(() => reloadAgentSessionsNow(dangerousMode))
      // A failed reload must not wedge every later one behind a rejection;
      // the caller of THAT reload still sees its own rejection via `run`.
      reloadChainRef.current = run.catch(() => undefined)
      return run
    },
    [refs.dangerousAgentsRef, reloadAgentSessionsNow],
  )

  const softReloadAgentView = useCallback(
    async (sessionIdOverride?: SessionId): Promise<SessionId | null> => {
      const snapshot = refs.stateRef.current
      // WHY use command-target focus here: this command is most useful when
      // triaging from Dispatch Mode. The row the user has highlighted may be
      // detached and absent from the grid's focused leaf, so reading only the
      // active tab would refresh the wrong pane.
      const sessionId = sessionIdOverride ?? commandTargetSessionIdForState(snapshot)
      if (!sessionId) return null

      const meta = snapshot.sessions[sessionId]
      if (!meta) return null
      const kind = meta.kind ?? DEFAULT_PROVIDER
      // Soft reload is provider-neutral: it only replaces the renderer's view
      // state for THIS session, without touching the underlying backend. The
      // registry predicate is the right membership check — any agent provider
      // has a renderer view to soft-reload, terminals don't. Prior two-
      // provider literal would silently no-op on OpenCode.
      if (!isAgentProviderKind(kind)) return null

      const hasProviderSession = hasDurableProviderSession(meta)
      if (!hasProviderSession) {
        const timer = refs.bootstrapTimersRef.current.get(sessionId)
        if (timer) {
          clearTimeout(timer)
          refs.bootstrapTimersRef.current.delete(sessionId)
        }
        // NOT cleared here. The no-provider arm of `softReloadRuntime` is
        // deliberately non-destructive — it keeps the runtime and only marks
        // the transcript disconnected — so the ids keep counting up and the
        // cursors are still true. Clearing them would make the renderer
        // re-send everything it had already persisted.
        setRuntimes(prev => {
          const current = prev[sessionId] ?? emptyRuntime()
          return {
            ...prev,
            [sessionId]: softReloadRuntime(current, false),
          }
        })
        return sessionId
      }

      const timer = refs.bootstrapTimersRef.current.get(sessionId)
      if (timer) {
        clearTimeout(timer)
        refs.bootstrapTimersRef.current.delete(sessionId)
      }
      forgetFeedDebugCursors(refs, sessionId)
      refs.seenUuidsRef.current[sessionId] = new Set()
      // Seen was RESET (not deleted): the trimmed set must reset with it,
      // or the fresh seen set would treat still-trimmed uuids as brand new
      // on the live path while older-history kept releasing them — the
      // trimmed ⊆ ever-seen invariant (liveEntryWindow.ts) would be gone.
      clearLiveEntryWindowSession(sessionId)

      setRuntimes(prev => {
        const current = prev[sessionId] ?? emptyRuntime()
        return {
          ...prev,
          [sessionId]: softReloadRuntime(current, hasProviderSession),
        }
      })

      if (hasProviderSession) {
        await loadInitialHistoryForSession({
          sessionId,
          meta,
          refs,
          setRuntimes,
        })
      }

      return sessionId
    },
    [
      refs.bootstrapTimersRef,
      refs.seenUuidsRef,
      refs.stateRef,
      setRuntimes,
    ],
  )

  return { spawn, ensureSessionLive, killSession, replaceSession, reloadAgentSessions, softReloadAgentView }
}

import { useCallback } from 'react'

import type { SessionId } from '@renderer/workspace/types'
import {
  buildVisibleDispatchRows,
} from '@renderer/workspace/dispatch/dispatchSelectors'
import { resolveFocusSurfaceTarget } from '@renderer/workspace/hook/actions/focusSurfaceTarget'

import type {
  WorkspaceSetSpotlight,
  WorkspaceSetState,
} from '@renderer/workspace/hook/context'
import type { WorkspaceRefs } from '@renderer/workspace/hook/refs'

// Spotlight mode — a full-window takeover of the current command target.
// toggleSpotlight exits whenever Spotlight is already open; otherwise it enters
// on the same command target lifecycle commands use (the focused lane's
// agent). setSpotlightSession switches which session is showing inside
// Spotlight, and while Spotlight is open that session IS the command target
// (commandTargetSessionIdForState reads the takeover first).

export function useSpotlightActions(
  setSpotlight: WorkspaceSetSpotlight,
  setState: WorkspaceSetState,
  refs: WorkspaceRefs,
): {
  setSpotlightTarget: (sessionId: SessionId | null) => boolean
  toggleSpotlight: () => void
  setSpotlightSession: (sessionId: SessionId) => void
} {
  // Explicit desired state lets command clients select a non-focused agent
  // without a focus-then-toggle race. Ownership uses the same placement query
  // as UI toggles, including detached and related sessions.
  const setSpotlightTarget = useCallback((sessionId: SessionId | null) => {
    if (sessionId === null) { setSpotlight(null); return true }
    const current = refs.stateRef.current
    const target = resolveFocusSurfaceTarget(current, sessionId)
    if (!target) return false
    setState(prev => ({ ...prev, activeTabId: target.tabId }))
    setSpotlight({ tabId: target.tabId, focusedSessionId: sessionId })
    return true
  }, [refs.stateRef, setSpotlight, setState])

  const toggleSpotlight = useCallback(() => {
    const current = refs.stateRef.current
    const target = resolveFocusSurfaceTarget(current)
    setSpotlight(prev => {
      if (prev) return null
      if (!target) return prev
      return {
        tabId: target.tabId,
        focusedSessionId: target.sessionId,
      }
    })
  }, [refs.stateRef, setSpotlight])

  const setSpotlightSession = useCallback(
    (sessionId: SessionId) => {
      const snapshot = refs.stateRef.current
      const rows = buildVisibleDispatchRows(snapshot)
      const dispatchRow = rows.find(row => row.sessionId === sessionId) ?? null
      setSpotlight(prev => (
        prev
          ? {
              ...prev,
              tabId: dispatchRow?.tabId ?? prev.tabId,
              focusedSessionId: sessionId,
            }
          : prev
      ))
      // Only the active PROJECT follows the Spotlight selection — it is a label
      // (U4) that decides where the next agent defaults and which header is
      // highlighted, so it should name the project the user is looking at.
      //
      // WHY no lane is written, although this used to mirror the selection
      // into a classic-Dispatch focus (and, outside Dispatch, into the tree's
      // Tab.focusedSessionId): both of those fields are gone (#992), and the
      // stage has no equivalent on purpose. Spotlight is a takeover that holds
      // its own focusedSessionId; browsing agents inside it is not the user
      // naming a lane occupant (U2, #681), so leaving Spotlight returns to the
      // stage exactly as it was left.
      setState(prev => {
        const activeTabId = dispatchRow?.tabId ?? prev.activeTabId
        return activeTabId === prev.activeTabId ? prev : { ...prev, activeTabId }
      })
    },
    [refs.stateRef, setSpotlight, setState],
  )

  return { setSpotlightTarget, toggleSpotlight, setSpotlightSession }
}

import { useCallback, useRef } from 'react'

import { emptyRuntime } from '@renderer/session-runtime/state'
import type { QueuedMessage, SessionRuntime } from '@renderer/session-runtime/state'
import type { SessionId } from '@renderer/workspace/types'
import type { Entry } from '@shared/types/transcript'
import {
  appendFeedDebugLog,
} from '@renderer/session-runtime/feedDebug'
import { withDerivedSessionStatus } from '@renderer/session-runtime/semantic/helpers'
import {
  entryTextContent,
} from '@renderer/session-runtime/entries'
import { isOptimisticCodexUserEntry } from '@providers/codex/renderer/transcript/entries'
import { OPTIMISTIC_PROMPT_UUID_PREFIX, optimisticPromptUuid } from '@renderer/session-runtime/optimisticPrompt'
import {
  hasPendingSemanticTools,
  isSemanticTurnRunning,
} from '@renderer/session-runtime/semantic/helpers'
import {
  buildCommittedAssistantText,
  semanticTurnHasRenderableContent,
} from '@renderer/features/feed/ui/semantic/renderUnits'
import {
  appendCodexTranscriptObservation,
  codexOptimisticRenderCandidateId,
} from '@renderer/lifecycle/codexTranscriptObservationOutbox'

import type { WorkspaceSetRuntimes } from '@renderer/workspace/hook/context'

// Optimistic submit state + optimistic-codex-user entry.
//
// beginOptimisticSubmit is called by TileLeaf on submit. It sets a
// synthetic `submitting` phase and a `submittedAt` timestamp, but only when
// the submit lands on an idle pane. Over work the provider is still doing it
// skips the stamp and returns null instead of the stamp token the queue settle
// matches on (#889; see submitJoinsLiveWork for what counts as live). (It was
// `setStreamingBaseline` while it also stored an assistant block scraped
// off the TUI screen for the old screen-driven streaming card; that card
// and its baseline are gone, see #855.) This covers the gap between the user
// pressing Enter and the adapter's first `requesting` event landing
// (can be 100-500ms on a cold proxy). Without it the in-feed
// WorkIndicator would render nothing during that window, making the
// app look unresponsive to the submit. The adapter's first
// stream_phase event will transition phase → 'requesting' and reuse
// `submittedAt` as turnStartedAt.
//
// The optimistic Codex user entry pair exists because Codex live
// rendering is TUI-first, with rollout JSON as a later source of
// truth. That means a broken/missing rollout attach should NOT leave
// the feed blank after submit. We add a local user row immediately
// and reconcile it away when the real rollout user message shows up
// (see ipc/handleBulkJsonl.ts for the reconciliation side).

/** Why a submit queued instead of painting an optimistic row — recorded on
 *  the optimistic_user_queue feed-debug entry so a stuck-queue bundle says
 *  WHICH branch parked it (residue-plan P0 observability: the 06-24 stuck
 *  bundles required manual rollout forensics to distinguish "live turn"
 *  from "unowned history because the committed tail is dead"). */
export type OptimisticQueueReason = 'live-current-turn' | 'unowned-history'

/**
 * Proof that ONE submit wrote the optimistic `submitting` claim: the exact
 * `submittedAt` value that submit stamped. `beginOptimisticSubmit` returns it
 * (null when it skipped the stamp). Both paths that retract the claim revert
 * only a runtime still carrying this exact value: `settleQueuedSubmit` (the
 * provider queued the prompt) and `unwindOptimisticSubmit` (nothing was
 * written).
 *
 * The two retractions share one ownership rule because they retract the same
 * claim. Scoping only one of them leaves the other able to erase an earlier
 * submit's claim through the same race (#893 review round 2, R2-1): a skipped
 * submit B that fails before any write would unwind A's `submitting` and also
 * clear A's `awaitingAssistant`.
 *
 * WHY a token instead of "is the phase still `submitting`?" (#893 review,
 * Codex major / Claude F1): the phase says SOME submit stamped it, not which
 * one. Submit A on an idle pane stamps and gets a `user` acceptance, so the
 * composer releases its in-flight guard while the stamp waits for A's first
 * provider event (100-500 ms on a cold proxy). Submit B in that gap skips its
 * own stamp (the pane is not idle), Claude queues B, and a phase-only settle
 * then reverted A's legitimate claim, blanking the WorkIndicator and losing
 * A's submit-to-first-event clock. `turn_started` cannot repair that, because
 * its bridge only advances `submitting`/`requesting`, never `idle`.
 *
 * WHY `submittedAt` and not a new SessionRuntime field: a new field would ride
 * into every debug bundle and runtime spread, which is the cost plan D1 already
 * refused, and `submittedAt` is written by exactly one site (the stamp below)
 * and cleared by the paths that retire the claim. What makes it a sound token
 * is that issued values are unique. `beginOptimisticSubmit` clamps them to be
 * strictly increasing, so two stamps within one millisecond can never compare
 * equal.
 */
export type OptimisticSubmitStamp = number

export function optimisticCodexQueueReason(
  current: Pick<
    SessionRuntime,
    'entries' | 'semantic' | 'streamPhase' | 'toolResultIndex' | 'toolUseIndex'
  >,
): OptimisticQueueReason | null {
  // WHY this deliberately ignores `streamPhase`:
  // TileLeaf calls beginOptimisticSubmit() and addOptimisticCodexUserEntry()
  // in the same submit handler. On an idle pane beginOptimisticSubmit moves
  // streamPhase to "submitting" before this function runs, so treating any
  // non-idle streamPhase as "previous turn is live" queues the *first* prompt
  // of an idle Codex session and makes the optimistic feed row path
  // unreachable. (Over live work the stamp is skipped since #889, so the phase
  // here is whatever the running turn left. It is still no ownership signal.)
  //
  // The ordering bug we are preventing is narrower: a follow-up prompt
  // while an existing semantic assistant/tool turn is still visibly live.
  // That is the reliable ownership signal. Stream phase is useful for the
  // work indicator, but it is polluted by the current submit and cannot
  // answer "is there older live feed content this prompt must not jump
  // above?"
  if (isSemanticTurnRunning(current.semantic.currentTurn)) return 'live-current-turn'

  // WHY completed semantic history is part of this ownership test:
  // Feed renders in planes: committed/optimistic entries first, then
  // semantic history/current, then work. A Codex submit that becomes a
  // normal optimistic Entry while a previous completed semantic turn is
  // still renderable therefore lands above the previous turn's semantic
  // bridge and the work row. The prompt is "present" in the DOM, but it
  // is no longer the latest user action visually — exactly the #239
  // failure. Raw history length is too broad because history can linger
  // after committed rows already own its visible content, so mirror the
  // Feed renderability predicate with the same committed text/tool
  // ownership inputs.
  const committedAssistantText = buildCommittedAssistantText(current.entries)
  const unownedHistory = current.semantic.history.some(turn =>
    turn.turnId !== current.semantic.currentTurn?.turnId &&
    semanticTurnHasRenderableContent(
      turn,
      current.toolUseIndex,
      current.toolResultIndex,
      committedAssistantText,
    ),
  )
  return unownedHistory ? 'unowned-history' : null
}

/**
 * Whether a composer submit lands on work the provider is still doing. If so,
 * `beginOptimisticSubmit` must not paint `submitting` over it (#889).
 *
 * WHY skipping the stamp is right for every provider, not only Claude (#893
 * review F2):
 *   - Claude holds a prompt submitted mid-turn in its queue (main reports
 *     `queue`) and drains it into the running turn. No turn starts for it, so
 *     `Sending` overwrote the running turn's real phase and clock with a claim
 *     nothing downstream corrects.
 *   - Codex's composer writes raw PTY bytes and returns no acceptance. While
 *     its task runs, the running turn keeps emitting its own stream_phase
 *     events, and those are the truth the stamp would have hidden.
 *   - OpenCode reports `transport` for every successful HTTP handoff, so the
 *     renderer cannot tell a held prompt from a started turn. Over a live turn
 *     the live phase is accurate either way, and a turn the prompt does start
 *     later paints itself through its own phase events.
 *   The skipped stamp also drops its `awaitingAssistant: true`, which the
 *   running turn's next semantic event would have cleared almost at once.
 *   Orchestration and agent management read `streamPhase !== 'idle'`, which the
 *   live phase already satisfies.
 *
 * WHY `awaiting-tool` is split on pending tools instead of on "is the turn
 * running" (#893 review F2): both adapters close the proxy turn at the response
 * boundary and only THEN publish `awaiting-tool` while the client runs the
 * tool (ClaudeProxyAdapter at message_delta, CodexResponsesAdapter at
 * response.completed). The fold keeps that ended turn mounted while its tool
 * is pending, so `isSemanticTurnRunning` is false for the whole of a Claude
 * Bash or Task run. Counting "awaiting-tool with no running turn" as idle
 * would repaint `Sending` over every Claude tool run, and the queue settle
 * would then blank the indicator for the rest of the run. The shape that can
 * precede a NEW turn is narrower: the phase still says `awaiting-tool`, but the
 * semantic turn holds no pending tool. A Codex tool resolved through
 * `tool_completed` leaves exactly that. The fold archives the turn, while the
 * phase machine only leaves `awaiting-tool` on a matching `tool_result`
 * (streamPhaseMachine.ts). Nothing is running under that phase, so the pre-#889
 * stamp is truthful there and is kept. OpenCode never publishes `awaiting-tool`.
 *
 * Accepted cost, recorded in plan §2 D1: any OTHER non-idle phase that nothing
 * returned to idle (e.g. `requesting` after an interrupted tool loop) still
 * counts as live. A turn that submit starts then relabels the indicator with
 * its first changed phase, but keeps that stale phase's elapsed clock, because
 * the machine stamps `turnStartedAt` only while it is null.
 */
export function submitJoinsLiveWork(
  current: Pick<SessionRuntime, 'semantic' | 'streamPhase'>,
): boolean {
  const turn = current.semantic.currentTurn
  if (isSemanticTurnRunning(turn)) return true
  if (current.streamPhase === 'idle') return false
  if (current.streamPhase === 'awaiting-tool') {
    return turn !== null && hasPendingSemanticTools(turn)
  }
  return true
}

export function codexPromptOwnershipKey(text: string | null | undefined): string {
  return String(text ?? '')
    .normalize('NFKC')
    .replace(/\s+/g, ' ')
    .trim()
}

export function codexPromptsMatchForOwnership(
  queuedText: string | null | undefined,
  committedText: string | null | undefined,
): boolean {
  const queuedKey = codexPromptOwnershipKey(queuedText)
  const committedKey = codexPromptOwnershipKey(committedText)
  return queuedKey !== '' && queuedKey === committedKey
}

// Diagnostic correlation must not become an enumerable field on product rows:
// entry serialization feeds byte estimates, recordings, fixtures, and provider
// adapters. Weak ownership riders disappear with the row, survive normal React
// reference-preserving folds, and make Stage 0 literally removable without
// changing an Entry or QueuedMessage's wire shape.
type SubmissionOwnership = { submissionId: string; sessionRunId: string | null }
const optimisticSubmissionOwnership = new WeakMap<Entry, SubmissionOwnership>()
const queuedSubmissionOwnership = new WeakMap<QueuedMessage, SubmissionOwnership>()

export function optimisticEntrySubmissionId(entry: Entry): string | null {
  return optimisticSubmissionOwnership.get(entry)?.submissionId ?? null
}

export function optimisticEntrySubmissionRunId(entry: Entry): string | null {
  return optimisticSubmissionOwnership.get(entry)?.sessionRunId ?? null
}

export function queuedMessageSubmissionId(message: QueuedMessage): string | null {
  return queuedSubmissionOwnership.get(message)?.submissionId ?? null
}

export function queuedMessageSubmissionRunId(message: QueuedMessage): string | null {
  return queuedSubmissionOwnership.get(message)?.sessionRunId ?? null
}

export function useStreamingActions(
  setRuntimes: WorkspaceSetRuntimes,
  isCodexSession: (sessionId: SessionId) => boolean,
): {
  beginOptimisticSubmit: (sessionId: SessionId) => OptimisticSubmitStamp | null
  unwindOptimisticSubmit: (sessionId: SessionId, stamp: OptimisticSubmitStamp | null) => void
  settleQueuedSubmit: (sessionId: SessionId, stamp: OptimisticSubmitStamp | null) => void
  clearPendingRewindUndo: (sessionId: SessionId) => void
  addOptimisticCodexUserEntry: (
    sessionId: SessionId,
    text: string,
    submissionId?: string,
    sessionRunId?: string | null,
  ) => void
  removeOptimisticCodexUserEntry: (
    sessionId: SessionId,
    text: string,
    submissionId?: string,
    sessionRunId?: string | null,
    releaseCause?: 'before-write-failure' | 'write-status-uncertain',
  ) => void
  addPendingPromptEntry: (sessionId: SessionId, text: string, submissionId: string) => void
  removePendingPromptEntry: (sessionId: SessionId, submissionId: string) => void
} {
  const clearPendingRewindUndo = useCallback(
    (sessionId: SessionId) => {
      setRuntimes(prev => {
        const current = prev[sessionId]
        if (!current?.pendingRewindUndo) return prev
        // WHY this exists separately from beginOptimisticSubmit:
        // Normal composer submits already have a rich optimistic-submit path
        // that can clear Undo Rewind while updating streaming state. Slash-mode
        // commits write directly to the provider PTY and may start a real turn
        // without touching that path. Clearing only this field lets those
        // alternate submit routes honor the same "undo is gone once you
        // continue the rewound branch" contract without lying to the feed that
        // a normal text submit has begun.
        return {
          ...prev,
          [sessionId]: {
            ...current,
            pendingRewindUndo: null,
          },
        }
      })
    },
    [setRuntimes],
  )

  /**
   * Undo the optimistic submit state when the prompt provably never reached the
   * provider.
   *
   * ── THE BUG THIS FIXES ──
   *
   * `beginOptimisticSubmit` sets `streamPhase: 'submitting'` BEFORE the delivery
   * attempt. When delivery failed, the catch in `useComposerKeybinds` recorded
   * the failure and showed a toast — but never touched the phase. And nothing
   * else could: there are exactly three paths back to `'idle'`, and under a
   * before-write failure none of them can fire.
   *
   *   1. `onSessionExit` needs a real exit event. Main holds no registry entry
   *      to exit — that IS the failure.
   *   2. `emptyRuntime()` only happens on a fresh runtime, i.e. an agent
   *      reload. This is why reloading was the only escape.
   *   3. `reduceStreamPhase` needs a provider semantic event. Nothing was
   *      written, so none will arrive — and `streamPhaseMachine` deliberately
   *      refuses to stomp `'submitting'` from screen-derived signals anyway.
   *
   * So `WorkIndicator` rendered `Sending` and `useElapsedSeconds` counted up
   * forever: `Sending · 17s`, `Sending · 4m`, until the agent was reloaded.
   *
   * ── WHY THIS IS NOT THE CONDITIONAL TRAP ──
   *
   * The repeated failure mode in this subsystem is a guard added to protect one
   * path becoming the weapon on another (#548's kill-timeout became #596;
   * TileLeaf's `!inputReady` gate became #598). Both were guards that INFERRED
   * state. This does not infer: the caller unwinds only when main REPORTS that
   * neither the body nor Enter was written. Nothing written means no turn can
   * start, so the optimistic phase is provably a lie — not probably one.
   *
   * The `uncertain` case (something WAS written) is deliberately untouched.
   * There a turn may genuinely be starting and unwinding could hide it.
   *
   * Equally deliberate: this does NOT relax the `submitting`/`requesting` guard
   * in `streamPhaseMachine`. That guard is a shipped regression's tombstone.
   * The unwind belongs at the site that OWNS the optimistic set.
   */
  const unwindOptimisticSubmit = useCallback(
    (sessionId: SessionId, stamp: OptimisticSubmitStamp | null) => {
      setRuntimes(prev => {
        const current = prev[sessionId]
        if (!current) return prev
        // Only unwind what THIS submit set. This is the same ownership rule as
        // settleQueuedSubmit, because both retract the one optimistic claim:
        //   - The phase is still `submitting`. A provider event that arrived
        //     between the optimistic write and the failure is real, and
        //     stomping it would trade a stuck spinner for a lost turn — the
        //     exact suppress-before-replace shape the rendering pipeline is
        //     built to avoid.
        //   - `submittedAt` is this submit's stamp. A null stamp means this
        //     submit painted nothing, because it landed on live work (see
        //     submitJoinsLiveWork). A different value is another submit's
        //     claim, typically an earlier prompt whose turn is genuinely
        //     starting. Unwinding that would blank its indicator, lose its
        //     clock and clear its `awaitingAssistant`, and `turn_started`
        //     could not repair it, because its bridge never leaves `idle`
        //     (#893 review round 2, R2-1).
        if (
          stamp === null ||
          current.streamPhase !== 'submitting' ||
          current.submittedAt !== stamp
        ) return prev
        return {
          ...prev,
          [sessionId]: withDerivedSessionStatus(
            appendFeedDebugLog(
              {
                ...current,
                streamPhase: 'idle',
                streamPhasePendingToolName: null,
                streamPhasePendingToolUseId: null,
                submittedAt: null,
                turnStartedAt: null,
                phaseChangedAt: null,
                awaitingAssistant: false,
              },
              {
                layer: 'STATE',
                kind: 'submit',
                summary: 'submit unwound: nothing was written to the provider',
              },
            ),
          ),
        }
      })
    },
    [setRuntimes],
  )

  /**
   * Settle a stamped `submitting` phase after main reports that the provider
   * accepted the prompt into its QUEUE rather than starting a turn (#889).
   *
   * WHY this exists next to `unwindOptimisticSubmit` instead of reusing it:
   * unwind means "nothing reached the provider" and therefore also drops
   * `awaitingAssistant`. A queued prompt DID reach the provider — Claude holds
   * it and will drain it into the running turn — so the only false claim is
   * the phase. `awaitingAssistant` and `queuedMessages` are owned by the
   * queue-operation reducer, whose enqueue burst can land a few milliseconds
   * before or after this acceptance; touching them here would race it.
   *
   * WHY the phase has to be settled at all: a queued prompt starts no turn, so
   * the `turn_started` bridge in streamPhaseMachine never fires for it, and
   * the machine deliberately refuses to stomp `submitting` from screen
   * signals. Left alone, the WorkIndicator paints `Sending · Ns` until the
   * RUNNING turn happens to emit its next `stream_phase` event — 21 s and 46 s
   * in the 2026-09-11 recordings, over a turn that was visibly thinking.
   *
   * Only ever reverts THIS submit's `submitting`. The rule is shared with
   * unwindOptimisticSubmit, since both retract the same optimistic claim. Two
   * things must both hold:
   *   - The phase is still `submitting`. If a real event moved it between the
   *     stamp and the acceptance, that phase is the truth (the same rule as
   *     unwind).
   *   - `submittedAt` is the stamp this submit wrote. A null stamp means this
   *     submit painted nothing, so there is nothing of its own to settle. A
   *     different value means the claim belongs to another submit, which may
   *     be a turn that is genuinely starting (see OptimisticSubmitStamp for
   *     the recorded two-submit sequence).
   */
  const settleQueuedSubmit = useCallback(
    (sessionId: SessionId, stamp: OptimisticSubmitStamp | null) => {
      setRuntimes(prev => {
        const current = prev[sessionId]
        if (!current) return prev
        if (
          stamp === null ||
          current.streamPhase !== 'submitting' ||
          current.submittedAt !== stamp
        ) return prev
        return {
          ...prev,
          [sessionId]: withDerivedSessionStatus(
            appendFeedDebugLog(
              {
                ...current,
                streamPhase: 'idle',
                streamPhasePendingToolName: null,
                streamPhasePendingToolUseId: null,
                submittedAt: null,
                turnStartedAt: null,
                phaseChangedAt: null,
              },
              {
                layer: 'STATE',
                kind: 'submit',
                summary: 'submit queued: provider accepted the prompt into its queue, optimistic phase settled',
              },
            ),
          ),
        }
      })
    },
    [setRuntimes],
  )

  // The last stamp this controller issued, across every session. It exists
  // only to keep issued stamps strictly increasing; see OptimisticSubmitStamp.
  const lastIssuedStampRef = useRef(0)

  const beginOptimisticSubmit = useCallback(
    (sessionId: SessionId): OptimisticSubmitStamp | null => {
      // Clamped to be strictly increasing rather than raw `Date.now()`: the stamp
      // doubles as the settle's ownership token, and two stamps written in the
      // same millisecond would be indistinguishable. The clamp moves such a stamp
      // by at most a few milliseconds, which the whole-second elapsed counter
      // cannot show. A value burned by a skipped stamp costs nothing.
      const now = Math.max(Date.now(), lastIssuedStampRef.current + 1)
      lastIssuedStampRef.current = now
      // WHY the token is decided INSIDE the updater and read after it: whether
      // this submit stamps can only be judged against the `prev` the write is
      // applied to. Reading the store before or after `setRuntimes` would race
      // any IPC fold that lands in between. `setWorkspaceRuntimes` is a zustand
      // `set` whose updater runs synchronously, exactly once, before it returns
      // (app-state/workspace/slice.ts), so `stamp` holds the committed decision
      // by the time we return it. Each branch assigns it explicitly, so even a
      // re-run reports its last decision. If the updater somehow never ran, the
      // null default fails safe: the settle then does nothing rather than erase
      // a phase it cannot prove it owns.
      let stamp: OptimisticSubmitStamp | null = null
      setRuntimes(prev => {
        const current = prev[sessionId] ?? emptyRuntime()
        // WHY the phase stamp is skipped over live work (#889): a submit into a
        // pane whose provider is still working is not going to START a turn —
        // Claude queues it and drains it into the running turn later. Painting
        // `submitting` here overwrote the turn's real phase and its real
        // clock (`turnStartedAt`) with `Sending · 0s`, and because nothing
        // downstream ever corrects that (see settleQueuedSubmit), the pane lied
        // for as long as the turn stayed quiet. submitJoinsLiveWork owns the
        // precise predicate and its per-provider reasoning, including the
        // stale `awaiting-tool` that must still stamp.
        //
        // Everything that is not a phase claim still happens on this branch —
        // continuing from a rewound branch retires Undo Rewind whether or not
        // the prompt is queued.
        if (submitJoinsLiveWork(current)) {
          stamp = null
          return {
            ...prev,
            [sessionId]: withDerivedSessionStatus(
              appendFeedDebugLog(
                { ...current, pendingRewindUndo: null },
                {
                  layer: 'STATE',
                  kind: 'submit',
                  summary: 'submit started · behind a live turn (provider will queue it)',
                },
              ),
            ),
          }
        }
        stamp = now
        const next = withDerivedSessionStatus(
          appendFeedDebugLog(
            {
              ...current,
              awaitingAssistant: true,
              // Rewind undo is intentionally valid only until the user starts
              // continuing from the rewound branch. Clearing here, at the same
              // "submit started" boundary that drives optimistic streaming,
              // means the command disappears before provider output, JSONL
              // replay, or a failed write can create an ambiguous state where
              // Undo Rewind would hide new branch work from the visible pane.
              pendingRewindUndo: null,
              streamPhase: 'submitting',
              submittedAt: now,
              phaseChangedAt: now,
              turnStartedAt: now,
            },
            {
              layer: 'STATE',
              kind: 'submit',
              summary: 'submit started',
            },
          ),
        )
        return {
          ...prev,
          [sessionId]: next,
        }
      })
      return stamp
    },
    [setRuntimes],
  )

  const addOptimisticCodexUserEntry = useCallback(
    (
      sessionId: SessionId,
      text: string,
      submissionId?: string,
      sessionRunId?: string | null,
    ) => {
      const trimmed = text.trim()
      if (!trimmed) return
      // OpenCode intentionally shares the optimistic-entry mechanics, but the
      // Stage 0 evidence contract is Codex-only. Capture provider kind at the
      // action boundary so a later provider replacement cannot widen or erase
      // this submit's diagnostic blast radius while React evaluates the fold.
      const observeCodex = isCodexSession(sessionId)
      setRuntimes(prev => {
        const current = prev[sessionId] ?? emptyRuntime()
        const submitRunId = sessionRunId === undefined ? current.sessionRunId : sessionRunId
        const last = current.entries[current.entries.length - 1]
        if (isOptimisticCodexUserEntry(last) && entryTextContent(last) === trimmed) {
          // The existing product rule intentionally collapses an identical
          // adjacent optimistic row. Stage 0 must not change that rule, but it
          // must also not erase the fact that a second Enter happened. Record
          // the second submission against the already-owned candidate so two
          // identical prompts remain distinct in diagnostics.
          if (!submissionId || !observeCodex) return prev
          return {
            ...prev,
            [sessionId]: appendCodexTranscriptObservation(
              current,
              'submit.surface',
              { surface: 'duplicate-suppressed', changed: false },
              // The existing row belongs to an EARLIER submission. Reusing
              // its candidate id beside this submission id would assert they
              // are one owner; minting a candidate for this submit would claim
              // a row exists when product dedupe created none. Record only the
              // suppressed submit until Stage 4 defines an explicit many-to-one
              // ownership relation from real fixtures.
              { submissionId, sessionRunId: submitRunId ?? undefined },
            ),
          }
        }
        const queueReason = optimisticCodexQueueReason(current)
        if (queueReason !== null) {
          const alreadyQueued = current.queuedMessages.some(q =>
            codexPromptsMatchForOwnership(q.content, trimmed),
          )
          if (alreadyQueued) {
            if (!submissionId || !observeCodex) return prev
            return {
              ...prev,
              [sessionId]: appendCodexTranscriptObservation(
                current,
                'submit.surface',
                { surface: 'duplicate-suppressed', changed: false, queueReason },
                // Same invariant as the optimistic duplicate above: the
                // existing queue candidate belongs to another submission.
                { submissionId, sessionRunId: submitRunId ?? undefined },
              ),
            }
          }
          const queued = {
            content: trimmed,
            timestamp: String(Date.now()),
          }
          if (submissionId && observeCodex) {
            queuedSubmissionOwnership.set(queued, {
              submissionId,
              sessionRunId: submitRunId,
            })
          }
          const observedCurrent = submissionId && observeCodex
            ? appendCodexTranscriptObservation(
                current,
                'submit.surface',
                { surface: 'queued-strip', changed: true, queueReason },
                {
                  submissionId,
                  renderCandidateId: `queued:${submissionId}`,
                  sessionRunId: submitRunId ?? undefined,
                },
              )
            : current
          return {
            ...prev,
            [sessionId]: appendFeedDebugLog(
              {
                ...observedCurrent,
                queuedMessages: [...current.queuedMessages, queued],
                awaitingAssistant: true,
              },
              {
                layer: 'STATE',
                kind: 'optimistic_user_queue',
                summary: `optimistic user queued (${queueReason}) · ${trimmed.slice(0, 80)}`,
                // WHY queue instead of appending a normal feed row:
                // Codex lets the user submit follow-up prompts while the
                // previous assistant/tool turn is still live. Appending a
                // synthetic user Entry to `entries` during that window puts
                // it in Feed's committed-entry plane used to render before
                // semantic history/current. The 2026-05-16T19-21 bundle
                // captured the result: the future user prompt appeared one
                // level too high, above the active apply_patch plane. Keep
                // mid-turn optimistic prompts in queuedMessages instead;
                // Feed's unified item plan renders that queue surface after
                // current work without lying that the prompt is already a
                // durable transcript row.
                data: {
                  text: trimmed,
                  ...(submissionId && observeCodex ? { submissionId } : {}),
                  queueLengthBefore: current.queuedMessages.length,
                  queueLengthAfter: current.queuedMessages.length + 1,
                  queueReason,
                  streamPhase: current.streamPhase,
                  // Age of the committed tail at queue time. The tailer
                  // unwatch bug (residue plan P0) made 'unowned-history'
                  // queues with a MINUTES-old tail — this field makes the
                  // next dead-tail incident readable straight off the
                  // bundle instead of requiring rollout forensics.
                  committedTailAgeMs:
                    current.lastJsonlEntryAt !== null ? Date.now() - current.lastJsonlEntryAt : null,
                },
              },
            ),
          }
        }
        const optimistic: Entry = {
          type: 'user',
          // Keyed by the submission when there is one, so Feed can dim the row
          // that is still sending (#1181; see optimisticPromptUuid). Callers
          // without a submission id keep the old time-based suffix.
          uuid: submissionId
            ? optimisticPromptUuid(submissionId)
            : `${OPTIMISTIC_PROMPT_UUID_PREFIX}${Date.now()}`,
          parentUuid: null,
          timestamp: new Date().toISOString(),
          message: {
            role: 'user',
            content: [{ type: 'text', text: trimmed }],
          },
        }
        if (submissionId && observeCodex) {
          optimisticSubmissionOwnership.set(optimistic, {
            submissionId,
            sessionRunId: submitRunId,
          })
        }
        const observedCurrent = submissionId && observeCodex
          ? appendCodexTranscriptObservation(
              current,
              'submit.surface',
              { surface: 'optimistic-entry', changed: true },
              {
                submissionId,
                renderCandidateId: codexOptimisticRenderCandidateId(submissionId),
                sessionRunId: submitRunId ?? undefined,
              },
            )
          : current
        return {
          ...prev,
          [sessionId]: appendFeedDebugLog(
            {
              ...observedCurrent,
              entries: [...current.entries, optimistic],
            },
            {
              layer: 'STATE',
              kind: 'optimistic_user_add',
              summary: `optimistic user row added · ${trimmed.slice(0, 80)}`,
              // WHY include counts here:
              // the visible symptom is "the agent reacts to my
              // message, but my message never renders." The old log
              // proved only that the submit path ran; it did not
              // prove the runtime entries array grew. Pairing this
              // with the JSONL reconcile counts below gives the next
              // trace an exact ownership chain for the user row.
              data: {
                text: trimmed,
                ...(submissionId && observeCodex ? { submissionId } : {}),
                entryCountBefore: current.entries.length,
                entryCountAfter: current.entries.length + 1,
                uuid: optimistic.uuid,
              },
            },
          ),
        }
      })
    },
    [isCodexSession, setRuntimes],
  )

  const removeOptimisticCodexUserEntry = useCallback(
    (
      sessionId: SessionId,
      text: string,
      submissionId?: string,
      sessionRunId?: string | null,
      releaseCause: 'before-write-failure' | 'write-status-uncertain' = 'write-status-uncertain',
    ) => {
      const trimmed = text.trim()
      if (!trimmed) return
      const observeCodex = isCodexSession(sessionId)
      setRuntimes(prev => {
        const current = prev[sessionId]
        if (!current || current.entries.length === 0) return prev
        const last = current.entries[current.entries.length - 1]
        if (!isOptimisticCodexUserEntry(last) || entryTextContent(last) !== trimmed) {
          return prev
        }
        // Removing the product row and describing why are intentionally one
        // committed transition, but the caller supplies the evidence strength.
        // Codex can return from the body write and then throw on Enter; calling
        // that `before-write-failure` manufactures a fact we do not possess.
        // The neutral cause preserves the row-ownership edge without claiming
        // whether bytes reached the provider.
        const observedCurrent = submissionId && observeCodex
          ? appendCodexTranscriptObservation(
              current,
              'submit.release',
              { cause: releaseCause },
              {
                submissionId,
                sessionRunId: (
                  sessionRunId === undefined
                    ? optimisticEntrySubmissionRunId(last)
                    : sessionRunId
                ) ?? undefined,
                ...(optimisticEntrySubmissionId(last)
                  ? { renderCandidateId: codexOptimisticRenderCandidateId(optimisticEntrySubmissionId(last)!) }
                  : {}),
              },
            )
          : current
        return {
          ...prev,
          [sessionId]: appendFeedDebugLog(
            {
              ...observedCurrent,
              entries: current.entries.slice(0, -1),
            },
            {
              layer: 'STATE',
              kind: 'optimistic_user_remove',
              summary: `optimistic user row removed · ${trimmed.slice(0, 80)}`,
              data: { text: trimmed },
            },
          ),
        }
      })
    },
    [isCodexSession, setRuntimes],
  )

  /**
   * A pending-only prompt row for providers WITHOUT optimistic echo (Claude,
   * #1181). It lives exactly as long as the send: the composer adds it at
   * Enter and removes it when the send settles, whatever the outcome.
   *
   * WHY Claude never got the ordinary optimistic row: Claude's committed user
   * row arrives at the moment main reports acceptance (the JSONL
   * acknowledgement IS the acceptance), and a mid-turn prompt is represented by
   * Claude's own queue-operation records. A row that outlived the send would
   * double-render every prompt. A row bounded by the send has no after-life to
   * double up.
   *
   * WHY this does not reuse addOptimisticCodexUserEntry: that action's
   * mid-turn branch writes `queuedMessages`, which for Claude is owned by the
   * queue-operation reducer (useIpcSubscriptions' claudeQueue). Writing it from
   * here would race that reducer's enqueue burst. It also carries the Codex
   * Stage 0 observation plumbing and the adjacent-duplicate collapse, neither of
   * which applies to a row that is removed on settle.
   *
   * The narrow overlap: the JSONL tail can reach the renderer a few ms before
   * the acceptance result does. In that gap the ledger's optimistic
   * reconciliation (ownership.ts, 'optimistic-owned-by-committed') already
   * hides this row behind the committed twin, so nothing paints twice.
   */
  const addPendingPromptEntry = useCallback(
    (sessionId: SessionId, text: string, submissionId: string) => {
      const trimmed = text.trim()
      // An image-only submit has no text to show. The composer lock and the
      // WorkIndicator still show that a send is in flight.
      if (!trimmed) return
      const uuid = optimisticPromptUuid(submissionId)
      setRuntimes(prev => {
        const current = prev[sessionId] ?? emptyRuntime()
        if (current.entries.some(entry => entry.uuid === uuid)) return prev
        const pending: Entry = {
          type: 'user',
          uuid,
          parentUuid: null,
          timestamp: new Date().toISOString(),
          message: {
            role: 'user',
            content: [{ type: 'text', text: trimmed }],
          },
        }
        return {
          ...prev,
          [sessionId]: appendFeedDebugLog(
            { ...current, entries: [...current.entries, pending] },
            {
              layer: 'STATE',
              kind: 'optimistic_user_add',
              summary: `pending prompt row added · ${trimmed.slice(0, 80)}`,
              data: { uuid, submissionId },
            },
          ),
        }
      })
    },
    [setRuntimes],
  )

  // By uuid, never by text or tail position: tool-result rows and the
  // committed twin can land after the pending row, and a repeated prompt has
  // an identical twin elsewhere in the transcript.
  const removePendingPromptEntry = useCallback(
    (sessionId: SessionId, submissionId: string) => {
      const uuid = optimisticPromptUuid(submissionId)
      setRuntimes(prev => {
        const current = prev[sessionId]
        if (!current) return prev
        const index = current.entries.findIndex(entry => entry.uuid === uuid)
        if (index === -1) return prev
        return {
          ...prev,
          [sessionId]: appendFeedDebugLog(
            {
              ...current,
              entries: [...current.entries.slice(0, index), ...current.entries.slice(index + 1)],
            },
            {
              layer: 'STATE',
              kind: 'optimistic_user_remove',
              summary: 'pending prompt row removed · send settled',
              data: { uuid, submissionId },
            },
          ),
        }
      })
    },
    [setRuntimes],
  )

  return {
    beginOptimisticSubmit,
    unwindOptimisticSubmit,
    settleQueuedSubmit,
    clearPendingRewindUndo,
    addOptimisticCodexUserEntry,
    removeOptimisticCodexUserEntry,
    addPendingPromptEntry,
    removePendingPromptEntry,
  }
}

import { useCallback } from 'react'
import { withLaneSession } from '@renderer/workspace/dispatch/tiledDispatchSelectors'

import type { SessionId, SessionKind, SessionMeta, Tab, TabId } from '@renderer/workspace/types'
import { titleFromCwd } from '@renderer/workspace/layout/helpers'
import { mergeProjectTabs } from '@renderer/workspace/mergeProjectTabs'
import { fileSessionInProject } from '@renderer/workspace/pool'
import type { MergeProjectTabsResult } from '@renderer/workspace/mergeProjectTabs'
import { tabIndexLabel } from '@renderer/workspace/tile-tree/paneLabelFormat'

import type {
  WorkspaceSetReaderMode,
  WorkspaceSetRuntimes,
  WorkspaceSetSpotlight,
  WorkspaceSetState,
} from '@renderer/workspace/hook/context'
import type { WorkspaceRefs } from '@renderer/workspace/hook/refs'
import type { SessionActions } from '@renderer/workspace/hook/actions/session'
import { markPooledSpawn } from '@renderer/workspace/hook/actions/pooledSpawnBadge'

// Tab actions — open/close + tab-navigation keybinds.

export function useTabActions(
  state: {
    activeTabId: string
    sessions: Record<SessionId, SessionMeta>
    tabs: Tab[]
  },
  setState: WorkspaceSetState,
  setRuntimes: WorkspaceSetRuntimes,
  setSpotlight: WorkspaceSetSpotlight,
  setReaderMode: WorkspaceSetReaderMode,
  refs: WorkspaceRefs,
  showToast: (message: string, durationMs?: number) => void,
  sessionActions: SessionActions,
): {
  newTab: (cwd: string, resumeSessionId?: string, kind?: SessionKind) => Promise<{ tabId: TabId; sessionId: SessionId }>
  activateTab: (tabId: TabId) => void
  activateTabByIndex: (index: number) => void
  reorderTabs: (tabIds: TabId[]) => void
  /** Fold `sourceTabIds` into `targetTabId` without touching any process (#913). */
  mergeTabs: (targetTabId: TabId, sourceTabIds: TabId[]) => MergeProjectTabsResult
  nextTab: () => void
  prevTab: () => void
} {
  // Spawns a new session in the given cwd, creates a tab with one
  // leaf, and makes it active. Pass `resumeSessionId` to resume an
  // existing CC session rather than starting a fresh one.
  const newTab = useCallback(
    async (cwd: string, resumeSessionId?: string, kind?: SessionKind) => {
      let sessionId: SessionId
      try {
        sessionId = await sessionActions.spawn(cwd, { resumeSessionId, kind })
      } catch (err) {
        showToast(
          err instanceof Error && err.message.length > 0
            ? err.message
            : 'Could not create session.',
        )
        throw err
      }
      const tabId = crypto.randomUUID()
      const title = titleFromCwd(cwd)
      let placed = false
      setState(prev => {
        // A project is a title and a position. Its first session belongs to
        // it because the session SAYS so (fileSessionInProject below) — until
        // #992 the tab was created holding a one-leaf tile tree instead.
        const tab: Tab = { id: tabId, title }
        // Context-places (#992, U2's second continuity write): the agent the
        // user just asked for appears where they are looking — but ONLY when
        // that lane is empty. An occupied lane is never displaced; the new
        // agent is then in the pool, at the top of its project's index, one
        // keystroke away. (Opening a lane beside an occupied one is stage 4's
        // job, together with the other spawn paths.)
        //
        // WHY this lives in newTab rather than in bootstrap: a fresh install,
        // the persisted-fallback recovery shell and an ordinary ⌘T are the
        // same event — "first agent of a new project" — and bootstrap used to
        // special-case the first two by entering Tiled Dispatch afterwards.
        // One rule here means a fresh install's single lane shows its single
        // agent without boot knowing anything about lanes.
        //
        // No wake is needed (#690): this session was spawned a few lines up.
        //
        // "Empty" means what it means for every other spawn
        // (applyDispatchSpawnFocus in pane.ts): no occupant, OR an occupant
        // whose session is gone. A lane pointing at a closed session reads
        // empty to the user, and ⌘T used to refuse it as occupied (#1013
        // review B).
        const focusedLane = prev.stage.lanes[prev.stage.focusedLane]
        const occupant = focusedLane?.selectedSessionId
        const stage = focusedLane && (occupant === undefined || prev.sessions[occupant] === undefined)
          ? {
              ...prev.stage,
              lanes: prev.stage.lanes.map((lane, index) =>
                index === prev.stage.focusedLane ? withLaneSession(lane, sessionId) : lane,
              ),
            }
          : prev.stage
        placed = stage !== prev.stage
        return {
          ...prev,
          tabs: [...prev.tabs, tab],
          activeTabId: tabId,
          sessions: fileSessionInProject(prev.sessions, sessionId, tabId),
          stage,
        }
      })
      // A first agent that could not take the lane is in the pool, and it
      // wears the same "new" badge as every other pooled spawn. Without it,
      // ⌘T with an occupied lane looked like it did nothing (#1013 review B).
      if (!placed) markPooledSpawn(setRuntimes, sessionId)
      return { tabId, sessionId }
    },
    [sessionActions, setRuntimes, setState, showToast],
  )

  // WHY Close Tab no longer lives here (#886 review round 2): the command used
  // its own hand-written close — it listed a tab's linked descendants in the
  // dialog but killed only the tab's leaves and rows, pushed its undo entry and
  // "Closed" toast before killing, and killed concurrently, so one rejected kill
  // left a tab whose tree named a deleted session plus an undo entry for a tab
  // that was never removed. The root dialog's "Close Tab" button already ran
  // through the approved-operation executor. Both now do: `closeTab` is exposed
  // by usePaneActions, beside closeSession, and the workspace wires it there.

  const activateTab = useCallback(
    (tabId: TabId) => {
      setState(prev => ({ ...prev, activeTabId: tabId }))
      setSpotlight(null)
    },
    [setSpotlight, setState],
  )

  const activateTabByIndex = useCallback(
    (index: number) => {
      setState(prev => {
        const t = prev.tabs[index]
        return t ? { ...prev, activeTabId: t.id } : prev
      })
      setSpotlight(null)
    },
    [setSpotlight, setState],
  )

  const mergeTabs = useCallback(
    (targetTabId: TabId, sourceTabIds: TabId[]): MergeProjectTabsResult => {
      // The plan is made INSIDE the updater against `prev`, never against
      // `refs.stateRef`, which is refreshed on render and can lag a workspace
      // mutation that landed between the modal's last paint and this click.
      // Reading the result back out of the updater is only sound because
      // `setState` is the zustand store setter, which applies the updater
      // synchronously (pane.ts relies on the same property). Every side
      // effect below is gated on that result: a refused merge must leave
      // tiled tabs, Spotlight, Reader and the toast exactly as they were,
      // otherwise the user is told "merged" while the tabs are still there.
      // No kill, no spawn, no runtime change: every session keeps its
      // process and its runtime; only tab affinity moves.
      const now = Date.now()
      // A holder object rather than a `let`: TypeScript keeps a `let`
      // narrowed to its initial value across the updater call (it cannot see
      // the closure assign), which would type the merged branch as `never`.
      const applied: { result: MergeProjectTabsResult | null } = { result: null }
      setState(prev => {
        const planned = mergeProjectTabs(prev, { targetTabId, sourceTabIds, now })
        applied.result = planned
        return planned.ok ? planned.state : prev
      })
      const result = applied.result ?? { ok: false as const, reason: 'nothing_to_merge' as const }
      if (!result.ok) {
        showToast(
          result.reason === 'target_is_source'
            ? 'Merge cancelled — the target tab cannot be one of the merged tabs.'
            : result.reason === 'unknown_tab'
              ? 'Merge cancelled — a tab changed while the dialog was open. Try again.'
              : 'Nothing to merge.',
        )
        return result
      }
      // A takeover framing a merged-away project FOLLOWS its session into the
      // target: the session it shows is exactly as alive as before, only its
      // project label changed, and a takeover's `tabId` is just which
      // project's sessions its switcher lists. (Until #992 the takeover was
      // dismissed here, because it framed a GRID PANE of the removed tab and
      // that pane had stopped being one.)
      const removed = new Set(sourceTabIds)
      setSpotlight(prev => (prev && removed.has(prev.tabId) ? { ...prev, tabId: targetTabId } : prev))
      setReaderMode(prev => (prev && removed.has(prev.tabId) ? { ...prev, tabId: targetTabId } : prev))
      const { summary } = result
      const moved = summary.movedSessionIds.length
      showToast(
        `Merged ${summary.removedTabIds.length} tab${summary.removedTabIds.length === 1 ? '' : 's'} into `
        + `${tabIndexLabel(summary.targetIndex)} · ${summary.targetTitle} — `
        + `${moved} agent${moved === 1 ? '' : 's'} now listed under it`,
      )
      return result
    },
    [setReaderMode, setSpotlight, setState, showToast],
  )

  const reorderTabs = useCallback(
    (tabIds: TabId[]) => {
      setState(prev => {
        // Reordering tabs is intentionally the smallest possible
        // workspace mutation: the user is changing the top chrome
        // order, not moving sessions, changing pane focus, or
        // touching any runtime. Validate that the modal gave us a
        // strict permutation before mutating so a stale modal opened
        // across tab-close/new-tab events cannot drop or duplicate a
        // project tab in WorkspaceState.
        if (tabIds.length !== prev.tabs.length) return prev
        const byId = new Map(prev.tabs.map(tab => [tab.id, tab]))
        const seen = new Set<TabId>()
        const tabs: Tab[] = []
        for (const id of tabIds) {
          const tab = byId.get(id)
          if (!tab || seen.has(id)) return prev
          seen.add(id)
          tabs.push(tab)
        }
        return { ...prev, tabs }
      })
    },
    [setState],
  )

  const nextTab = useCallback(() => {
    setState(prev => {
      const idx = prev.tabs.findIndex(t => t.id === prev.activeTabId)
      if (idx === -1) return prev
      const next = prev.tabs[(idx + 1) % prev.tabs.length]
      return { ...prev, activeTabId: next.id }
    })
    setSpotlight(null)
  }, [setSpotlight, setState])

  const prevTab = useCallback(() => {
    setState(prev => {
      const idx = prev.tabs.findIndex(t => t.id === prev.activeTabId)
      if (idx === -1) return prev
      const next = prev.tabs[(idx - 1 + prev.tabs.length) % prev.tabs.length]
      return { ...prev, activeTabId: next.id }
    })
    setSpotlight(null)
  }, [setSpotlight, setState])

  return {
    newTab,
    activateTab,
    activateTabByIndex,
    reorderTabs,
    mergeTabs,
    nextTab,
    prevTab,
  }
}

import { carryWorkflowRuns, handOverGoalLoops, stopGoalLoops } from '@renderer/workspace/hook/actions/successorCarry'
import { carriedRelationships } from '@renderer/workspace/idRemap'
import { sessionDisplayTitle } from '@renderer/workspace/sessionDisplayTitle'
import { sessionMcpOverrides } from '@renderer/workspace/mcpDomains'
import { DEFAULT_PROVIDER, isAgentSessionKind } from '@shared/types/providerKind'
import { MISSING_WORKSPACE_FOLDER_PREFIX, SESSION_START_FAILED_MESSAGE } from '@shared/types/session'
import { useCallback, useState } from 'react'

import type {
  SessionId,
  SessionKind,
  SessionMeta,
  Tab,
} from '@renderer/workspace/types'
import { remapTiledLanes } from '@renderer/workspace/dispatch/tiledDispatchSelectors'
import {
  remapMetaLineage,
  remapSingleEntryLineage,
} from '@renderer/lib/undoClose'
import type {
  ClosedEntry,
  ClosedGroup,
  ClosedSession,
  ClosedTab,
  SingleClosedEntry,
  UndoLineage,
} from '@renderer/lib/undoClose'

import type { WorkspaceSetState } from '@renderer/workspace/hook/context'
import type { WorkspaceRefs } from '@renderer/workspace/hook/refs'
import type { SessionActions } from '@renderer/workspace/hook/actions/session'
import { resumableProviderSessionId } from '@renderer/workspace/providerSessionIdentity'

type RestoreResult = 'restored' | 'stale' | 'retryable-failure'

/** A respawn either produced a session, failed in a way a retry may fix
 *  (provider setup, a transient spawn error), or was refused because the
 *  session's folder is gone, which no retry can fix. */
type RespawnOutcome = { sessionId: SessionId; spawned: boolean } | 'failed' | 'folder-missing'

/** Where a successful restore sends its old -> new ids. A top-level entry
 *  publishes to the stack; a group member publishes to the stack AND to the
 *  group's members that have not been replayed yet (restoreGroupEntry). */
type PublishLineage = (lineage: UndoLineage) => void

/**
 * The durable metadata a respawn cannot rebuild, carried onto the new session ID.
 *
 * WHY every restore path must share one answer: `sessionActions.spawn`
 * builds SessionMeta from {cwd, kind, providerRuntime, tmuxName,
 * providerSessionId, builtInMcpDomains} only (session.ts:339-345). Everything
 * else a session owned — its user-authored
 * title, its linked/orchestration parentage, its view-mode override, its
 * bootstrap-delivered flag and its `agentNameId` — exists nowhere but the meta
 * captured on the undo entry. Each path used to answer this differently:
 * `restoreDetachedEntry` had a hand-written allowlist, `restoreTabEntry` built
 * a `freshSessions` map that was populated and then never read (dead from the
 * day it was written), and `restorePaneEntry` patched no session metadata at
 * all. Three answers meant a field could survive one kind of undo and be lost
 * by another, which is not a difference any user could predict.
 *
 * WHY that is more than cosmetic for `agentNameId`: every one of these paths
 * RESUMES the same provider conversation, so the agent the user gets back is
 * the same agent. Dropping the identity makes the reconciler claim a fresh one
 * and the registry allocate a second name, so Cmd-Shift-T renames a live agent
 * and the old name is spent forever — allocation is monotonic and never
 * recycles. That is exactly the silent re-addressing #816 forbids.
 *
 * WHY each field is spread conditionally on top of the spawn's own meta rather
 * than the closed meta being copied wholesale: the respawn's values are the
 * current truth for the volatile fields. `providerSessionId`, `tmuxName` and
 * the freshly minted credentials all belong to the NEW backend, and copying
 * the closed meta over them would reinstate a dead provider session ID and a
 * stale tmux name on top of the live ones the respawn just established.
 *
 * The `spawned` fallback covers the case where the respawn's own registration
 * has not landed in this snapshot; production `spawn` writes SessionMeta into
 * workspace state itself, so in the app it is normally present.
 */
export function carryDurableMeta(spawned: SessionMeta | undefined, closed: SessionMeta): SessionMeta {
  // Extension panes skip spawn entirely: all of their metadata is durable UI
  // identity, including the view ID. The process-specific allowlist below is
  // for real backends whose new connection identity must win after respawn.
  if (closed.kind === 'extension-view') return { ...closed }
  return {
    ...(spawned ?? { cwd: closed.cwd, kind: closed.kind ?? DEFAULT_PROVIDER }),
    ...(closed.title ? { title: closed.title } : {}),
    // The spoken address. Conditional like every other field here so an
    // unnamed agent (the setting off, or a name never allocated) is restored
    // without an empty identity that the reconciler would then have to heal.
    ...(closed.agentNameId ? { agentNameId: closed.agentNameId } : {}),
    // The relationship fields, from the ONE list that decides what a
    // relationship is (#1090 review). This function's own header complains
    // that "three answers meant a field could survive one kind of undo and be
    // lost by another" — and it had become the second answer itself: it
    // listed six of the nine fields, so an undone orchestration child came
    // back without `inheritedParentContext` and its parent then read its own
    // pre-handoff commentary as the child's latest answer. Sharing the list
    // is also what makes the type-level guard in
    // successorRelationships.renderer.test.tsx mean what it claims: a new
    // relationship field is now classified once, for every restore path.
    //
    // `carriedRelationships` omits absent fields rather than writing
    // `undefined`, which is the same conditional-spread discipline as every
    // other line here.
    ...carriedRelationships(closed),
    ...(closed.agentViewModeOverride ? { agentViewModeOverride: closed.agentViewModeOverride } : {}),
    // Same pocketId ⇒ same cookie partition: an undone agent comes back logged in.
    ...(closed.browserPocket ? { browserPocket: closed.browserPocket } : {}),
    // Pool membership (#992). `spawn` writes an UN-FILED row — no project, no
    // position — so without these the restored session would be unowned
    // metadata that no index lists and the next autosave drops. `joinedAt` is
    // carried verbatim for the reason the v2 entries carried `detachedAt`: it
    // alone orders rows inside a project, and undo puts things BACK.
    ...(closed.projectId !== undefined ? { projectId: closed.projectId } : {}),
    ...(closed.joinedAt !== undefined ? { joinedAt: closed.joinedAt } : {}),
    // A terminal's last use (#1178). Undo re-attaches the SAME still-alive
    // tmux session, so its history of use is the closed one's; dropping it
    // would hand the restored shell a fresh floor and make it look unused
    // since the moment it came back (review of #1179).
    ...(closed.lastUsedAt !== undefined ? { lastUsedAt: closed.lastUsedAt } : {}),
  }
}

// Undo-close action. Pops the most recent entry from the undo stack
// and restores it.
//
// For a session: respawns it (with --resume for an agent so the conversation
// comes back, `recoverTmuxName` for a terminal so its still-alive tmux session
// is re-attached) and files it back under its project at its old position.
// The only anchor that has to still exist is the project.
//
// For a project: re-creates it at its original index (clamped to bounds) under
// a NEW id, and respawns the sessions that closed with it.
//
// (Until #992 there were three paths — a split pane re-inserted beside its
// surviving sibling, a Dispatch row re-filed from its record, and a tab whose
// tree was remapped leaf by leaf. See lib/undoClose.ts.)

export function useUndoCloseAction(
  _state: { tabs: Tab[] },
  setState: WorkspaceSetState,
  refs: WorkspaceRefs,
  sessionActions: SessionActions,
  showToast: (message: string, durationMs?: number) => void = () => undefined,
): {
  undoClose: () => Promise<void>
  undoCloseCount: number
} {
  const [, bumpUndoCloseVersion] = useState(0)

  // Respawn one closed session, or mint an id for a process-less one.
  //
  // ── A PROCESS-LESS SESSION IS RESTORED, NOT SPAWNED ──
  // Undo once called spawn() for every kind. Main rejects an extension-view
  // spawn outright, the caller turned that into 'retryable-failure', and
  // undoClose PUSHES A FAILED ENTRY BACK — so the stack head became permanently
  // poisoned: every later Cmd+Shift+T popped the same entry, failed, re-pushed,
  // and returned, and all older undo history was unreachable for the rest of
  // the session. Minting the id mirrors openExtensionViewInPane; there is
  // nothing to recover because there was never a process.
  //
  // Returns 'failed' on a spawn failure a retry may fix, and 'folder-missing'
  // when main refused because the cwd is gone (see RespawnOutcome). `spawned`
  // says whether a backend now exists that a bail-out must kill.
  const respawn = useCallback(
    async (meta: SessionMeta): Promise<RespawnOutcome> => {
      const kind: SessionKind = meta.kind ?? DEFAULT_PROVIDER
      if (kind === 'extension-view') {
        return { sessionId: crypto.randomUUID() as SessionId, spawned: false }
      }
      try {
        const sessionId = await sessionActions.spawn(meta.cwd, {
          kind,
          ...(meta.providerRuntime ? { providerRuntime: meta.providerRuntime } : {}),
          //   - an agent with a durable transcript resumes it;
          //   - a terminal with tmuxName re-attaches the same tmux session,
          //     preserving scrollback and any running process. Without this,
          //     "undo close" on a terminal would respawn an empty shell —
          //     defeating the point of having a tmux backing.
          resumeSessionId: isAgentSessionKind(kind) ? resumableProviderSessionId(meta) : undefined,
          recoverTmuxName: kind === 'terminal' ? meta.tmuxName : undefined,
          // WHY capability intent is restored but credentials are not: closing
          // a session revokes its token. Undo must ask main to mint a fresh one
          // from the session's durable choices; dropping them makes an
          // undo-restored transcript silently lose tools. The effective list is
          // deliberately not restored — the restored session is a NEW provider
          // process, so it resolves those choices against current Settings.
          tldrIdentity: meta.tldrIdentity,
          builtInMcpOverrides: sessionMcpOverrides(meta),
        })
        return { sessionId, spawned: true }
      } catch (error) {
        // The rejection's text is deliberately not kept for the user (steering
        // q22): it is the raw provider exception relayed through IPC and can
        // carry environment values or tokens. See restoreFailureMessage.
        // Only its CLASS is read, and only for the one failure main curates
        // as safe and that no retry can fix: a deleted cwd (#1264 R2-1).
        return isMissingFolderError(error) ? 'folder-missing' : 'failed'
      }
    },
    [sessionActions],
  )

  // Whether a restored session's process has Goal Loop tools. WHY read the
  // successor's meta instead of resolving the closed pane's choices again:
  // `spawn` resolves the domains against CURRENT Settings (see respawn) and
  // writes the result into the meta it files, so that meta is the only
  // record of what the new process can actually call.
  const hasGoalLoopTools = useCallback(
    (sessionId: string) =>
      refs.stateRef.current.sessions[sessionId as SessionId]?.builtInMcpDomains?.includes('goal_loop') === true,
    [refs.stateRef],
  )

  const restoreSessionEntry = useCallback(
    async (entry: ClosedSession, publish: PublishLineage): Promise<RestoreResult> => {
      // The project is a session's only anchor: the index files each row under
      // its `projectId`, so a row whose project is gone renders nowhere —
      // restoring it would spawn a live backend the user can never see or
      // close. Treat that as stale.
      //
      // We deliberately do NOT re-home the session into some surviving
      // project: a close that REMOVED the project recorded a 'tab' entry, so a
      // missing project here means the user closed or merged the project
      // itself afterwards, and undoing THAT is the correct recovery.
      const meta = entry.sessionMeta
      const projectId = meta.projectId
      if (projectId === undefined) return 'stale'
      if (!refs.stateRef.current.tabs.some(tab => tab.id === projectId)) return 'stale'

      const respawned = await respawn(meta)
      if (respawned === 'folder-missing') {
        // WHY 'stale' and not 'retryable-failure' (#1264 R2-1): the entry
        // would be pushed back and re-fail forever — a worktree removed after
        // its branch merged never comes back — so every later Cmd+Shift+T
        // would pop the same entry and every older close would be
        // unreachable (the "poisoned stack head" above). Consuming it lets
        // the walk continue to older entries. The toast names the path main
        // already quotes (the pane header shows it too), never the spawn text.
        showToast(folderMissingMessage(`"${sessionDisplayTitle(meta)}"`, meta.cwd), RESTORE_FAILURE_TOAST_MS)
        return 'stale'
      }
      if (respawned === 'failed') return 'retryable-failure'
      const newSessionId = respawned.sessionId

      // Set inside the updater and read after. Sound because setState is the
      // zustand store setter, which applies updaters synchronously — NOT a
      // React useState setter, whose updater would still be pending here.
      let refiled = false
      setState(prev => {
        // Re-check inside the updater: the project can be closed between the
        // awaited spawn and here. Returning `prev` unchanged would strand the
        // session, so fall through to the kill below instead.
        if (!prev.tabs.some(tab => tab.id === projectId)) return prev
        refiled = true
        return {
          ...prev,
          // The project the row came back into becomes the active one: that is
          // where the user's attention now is, and it is what every path that
          // files a session has always done.
          activeTabId: projectId,
          sessions: {
            ...prev.sessions,
            // carryDurableMeta restores membership too — `projectId` and,
            // critically, `joinedAt`, so the row returns to its old position
            // in the index rather than jumping to the bottom.
            [newSessionId]: carryDurableMeta(prev.sessions[newSessionId], meta),
          },
          // The stage is deliberately NOT written. The close emptied the lane
          // that showed this session, so the visible result of an undo is the
          // row reappearing at its old position in the index — back in the
          // pool, one keystroke from any lane — not a lane takeover.
          // Restoring the lane would need the lane index captured at close
          // time; deliberately not done, because a lane the user has since
          // re-aimed should not be yanked back by an undo (U2).
        }
      })

      if (!refiled) {
        // No backend or renderer metadata was created for an unfiled view.
        if (!respawned.spawned) return 'stale'
        // The spawn already registered a live backend, so a filing that did
        // not happen must not leave it running with no row pointing at it.
        //
        // Kill with the kind/cwd resolved above rather than leaving it to
        // killSession's ownership proof, which re-reads them from
        // `refs.stateRef`. History: that ref used to be a render-body mirror,
        // so immediately after an awaited spawn it did not contain the new
        // session, the proof failed, and the kill silently no-opped —
        // stranding exactly the backend this bail exists to reclaim. #886 made
        // stateRef a synchronous store subscription; the explicit owner stays
        // as defense in depth.
        await window.api
          .killOwnedSession({
            sessionId: newSessionId,
            kind: meta.kind ?? DEFAULT_PROVIDER,
            cwd: meta.cwd,
            caller: 'undo-close.rollback',
          })
          .catch(() => undefined)
        // `.catch`: killSession reaches an IPC invoke that can reject, and this
        // bail runs with the entry already POPPED — a throw here would lose the
        // entry, skip bumpUndoCloseVersion so the palette's count stays stale,
        // and escape into the keybinding handler.
        await sessionActions.killSession(newSessionId, 'undo-close.rollback').catch(() => undefined)
        return 'stale'
      }
      // The closed session is back under a new id. An older entry may point at
      // it — a linked child closed earlier names it as `linkedParentId` — so
      // publish old -> new; see UndoLineage.
      publish({ sessions: new Map([[entry.sessionId, newSessionId]]) })
      return 'restored'
    },
    [refs.stateRef, respawn, sessionActions, setState, showToast],
  )

  const restoreTabEntry = useCallback(
    async (entry: ClosedTab, publish: PublishLineage): Promise<RestoreResult> => {
      if (entry.sessions.length === 0) return 'stale'
      const restoredTab: Tab = { id: crypto.randomUUID(), title: entry.tab.title }

      // Old -> new for EVERY session this restore brings back. It does two
      // jobs: (1) a linked child restored beside its parent must point at the
      // parent's NEW id — carryDurableMeta copies the closed `linkedParentId`
      // verbatim, which used to leave restored children un-nested and no
      // longer cascading; (2) it is published to the stack so older entries
      // anchored on this project or its sessions still resolve.
      const idMap = new Map<SessionId, SessionId>()
      // New session id -> the meta the closed session actually had; applied
      // through carryDurableMeta in the commit at the end.
      const carried = new Map<SessionId, SessionMeta>()

      // Restore what we can. A project is just a group of sessions, so one
      // that fails to respawn (a provider hiccup on one agent out of nine)
      // must not cost the user the other eight.
      //
      // Until #992 the tab's tile-tree leaves were ALL-OR-NOTHING here (a tree
      // cannot contain a missing leaf, so one failed spawn killed every
      // sibling it had just started and pushed the entry back) while its
      // detached rows were best-effort. With no tree there is nothing a
      // missing session could corrupt, so the gentler rule covers everyone.
      let foldersMissing = 0
      for (const member of entry.sessions) {
        const respawned = await respawn(member.meta)
        if (respawned === 'folder-missing') foldersMissing++
        if (typeof respawned === 'string') continue
        idMap.set(member.sessionId, respawned.sessionId)
        carried.set(respawned.sessionId, member.meta)
      }
      // Every member's folder is gone: no retry can bring any of them back,
      // so consume the entry rather than poison the stack head (#1264 R2-1).
      // One shared cwd is named; several are not, because the owner's largest
      // real project spans 22 cwds (21 of them worktrees) and naming the
      // first implied a single folder (#1264 round-2 review).
      if (foldersMissing === entry.sessions.length) {
        const cwds = new Set(entry.sessions.map(member => member.meta.cwd))
        showToast(
          cwds.size === 1
            ? folderMissingMessage(`project "${entry.tab.title}"`, entry.sessions[0].meta.cwd)
            : `Could not restore project "${entry.tab.title}": their folders no longer exist`,
          RESTORE_FAILURE_TOAST_MS,
        )
        return 'stale'
      }
      // Nothing came back: the entry is still good, the provider is not. A
      // MIX of missing folders and provider failures stays retryable — the
      // provider failures may yet succeed, and a retry that restores them
      // then applies the partial rule below to the missing ones.
      if (idMap.size === 0) return 'retryable-failure'
      // Some came back: the rest are gone (#992's best-effort rule), and the
      // user must be told which part of the project is missing (#1264 review).
      // A deleted worktree is not a provider fault, so the reason follows
      // what actually failed: all-folder, all-provider, or both (#1264
      // round-2 review: "retry" advice for a member no retry can fix).
      const missing = entry.sessions.length - idMap.size
      if (missing > 0) {
        const providerFailed = missing - foldersMissing
        const reason = providerFailed === 0
          ? 'their folders no longer exist'
          : foldersMissing === 0
            ? SESSION_START_FAILED_MESSAGE
            : `${foldersMissing} folder${foldersMissing === 1 ? '' : 's'} no longer exist${foldersMissing === 1 ? 's' : ''}; ${SESSION_START_FAILED_MESSAGE}`
        showToast(`Could not restore ${missing} of ${entry.sessions.length} agents in project "${entry.tab.title}": ${reason}`, RESTORE_FAILURE_TOAST_MS)
      }

      setState(prev => {
        const insertIdx = Math.min(entry.tabIndex, prev.tabs.length)
        const tabs = [...prev.tabs]
        tabs.splice(insertIdx, 0, restoredTab)
        const sessions = { ...prev.sessions }
        for (const [newId, closed] of carried) {
          sessions[newId] = {
            // Relationship pointers follow the restore: a linked child
            // restored with this project points at its parent's NEW id.
            ...remapMetaLineage(carryDurableMeta(sessions[newId], closed), idMap),
            // The old project id is dead; membership moves to the new one.
            // `joinedAt` rides through carryDurableMeta, so the restored
            // project lists its sessions in the order it used to.
            projectId: restoredTab.id,
          }
        }
        return {
          ...prev,
          tabs,
          sessions,
          activeTabId: restoredTab.id,
          // Restored sessions get fresh ids; remap any lane that still named
          // one of the closed ids so the lane follows the restored agent
          // instead of dangling. (The close normally emptied those lanes, so
          // this is a no-op unless something re-aimed a lane at a dead id.)
          stage: remapTiledLanes(prev.stage, idMap),
        }
      })
      // The project is back under a NEW id with NEW session ids. An older
      // entry anchored on it — a session closed from this project before the
      // project itself went — must now name the restored ids, or the next undo
      // judges it stale and that session is lost (#886 finding 4).
      publish({
        sessions: idMap,
        tabs: new Map([[entry.tab.id, restoredTab.id]]),
      })
      return 'restored'
    },
    [respawn, setState, showToast],
  )

  // WHY what follows a restored pane is decided here, once, and not at each
  // restore's commit (#1331 review, all three reviewers): main keys goal
  // loops and workflow runs by session id, so every closed id in an entry
  // needs exactly one outcome when the entry leaves the stack. The first
  // version handed over only at the two success commits, and every other
  // exit orphaned the loop for good: a project restore that brought back
  // some agents consumed the entry with the failed members' loops still
  // filed under their dead ids, and a restore judged stale (project closed
  // mid-spawn, folder deleted) did the same. The per-site calls could not
  // see that, because only this level knows the result, and the result is
  // what decides whether the entry is gone.
  //
  // The rule:
  //   - 'retryable-failure' keeps the entry (undoClose pushes it back, or a
  //     group re-files it as leftover), so nothing moves: the retry decides.
  //   - Otherwise the entry is consumed. Each closed id that published a
  //     successor is handed over (runs carried; loop carried when the
  //     successor has Goal Loop tools, else ended). Each one that did not
  //     come back can never be restored, so its loop is ended, the #1287
  //     rule for a loop no pane can reach. Its workflow runs are left alone:
  //     they are finished history in the store, not live state to stop.
  // `publish` is the source of truth for "came back": each restore calls it
  // after its commit and only then, with exactly the old -> new pairs.
  const restoreSingleEntry = useCallback(
    async (entry: SingleClosedEntry, publish: PublishLineage): Promise<RestoreResult> => {
      const successors = new Map<string, string>()
      const recordingPublish: PublishLineage = lineage => {
        for (const [oldId, newId] of lineage.sessions ?? []) successors.set(oldId, newId)
        publish(lineage)
      }
      const result = entry.type === 'session'
        ? await restoreSessionEntry(entry, recordingPublish)
        : await restoreTabEntry(entry, recordingPublish)
      if (result === 'retryable-failure') return result
      carryWorkflowRuns(successors)
      handOverGoalLoops(successors, hasGoalLoopTools)
      const closedIds = entry.type === 'session'
        ? [entry.sessionId]
        : entry.sessions.map(member => member.sessionId)
      stopGoalLoops(closedIds.filter(id => !successors.has(id)))
      return result
    },
    [hasGoalLoopTools, restoreSessionEntry, restoreTabEntry],
  )

  // Replay one close OPERATION's units last-first (see ClosedGroup).
  //
  // WHY last-first with lineage threaded through the members not yet replayed:
  // the last commit is the outermost change — the parent, the tab removal — and
  // older units anchor on what it restores: a child's linkedParentId, a
  // session's projectId. Every restore mints new ids and
  // publishes them, so each older member is re-anchored before it runs, and the
  // rest of the stack is re-anchored as for any other restore.
  //
  // Failure policy mirrors the single-entry loop, per member. A stale member is
  // skipped: the rest of the operation may still be restorable. A retryable
  // failure stops the replay: if nothing had come back yet the whole group is
  // reported retryable and undoClose pushes it back untouched; if some members
  // already came back, the members left (already re-anchored) go back on the
  // stack as a smaller group so the next ⌘⇧T continues where this one stopped
  // instead of respawning the ones that are already live.
  const restoreGroupEntry = useCallback(
    async (entry: ClosedGroup): Promise<RestoreResult> => {
      let remaining: SingleClosedEntry[] = [...entry.entries]
      let restoredAny = false
      // A member consumed as stale (its project gone, or its folder deleted)
      // must not come back with the group. Returning 'retryable-failure'
      // pushes the ORIGINAL group back, so once one member was consumed the
      // leftover is rebuilt instead, as for a partial restore (#1264 round-2
      // review: a deleted-folder member was retried, and re-toasted, on
      // every later ⌘⇧T).
      let consumedAny = false
      while (remaining.length > 0) {
        const member = remaining[remaining.length - 1]
        remaining = remaining.slice(0, -1)
        const result = await restoreSingleEntry(member, lineage => {
          remaining = remaining.map(older => remapSingleEntryLineage(older, lineage))
          refs.undoStackRef.current.remapLineage(lineage)
        })
        if (result === 'restored') {
          restoredAny = true
        } else if (result === 'stale') {
          consumedAny = true
        } else if (result === 'retryable-failure') {
          if (!restoredAny && !consumedAny) return 'retryable-failure'
          const rest = [...remaining, member]
          const leftover: ClosedEntry = rest.length === 1 ? rest[0] : { ...entry, entries: rest }
          refs.undoStackRef.current.push(leftover)
          // Part of the group came back; say what did not (#1242).
          showToast(restoreFailureMessage(leftover), RESTORE_FAILURE_TOAST_MS)
          return 'restored'
        }
      }
      return restoredAny ? 'restored' : 'stale'
    },
    [refs.undoStackRef, restoreSingleEntry, showToast],
  )

  const undoClose = useCallback(async () => {
    // Undo Close is a small LIFO recovery history, not a one-shot
    // toast action. A session entry can go stale during normal cleanup
    // because its only anchor is its project; if that project was closed
    // or merged away since, the entry is no longer restorable in place.
    // We deliberately skip such entries and keep
    // walking backward so one stale close does not block an older valid
    // restore. We still pop stale entries because retaining
    // an entry we already know cannot restore would trap the user on
    // the same failure every time they press Cmd+Shift+T. Transient spawn
    // failures are different: those keep the entry by pushing it back so a
    // provider hiccup does not permanently consume the user's recovery slot.
    let staleEntryConsumed = false
    while (true) {
      const entry = refs.undoStackRef.current.pop()
      if (!entry) {
        if (staleEntryConsumed) {
          bumpUndoCloseVersion(version => version + 1)
        }
        return
      }
      const result = entry.type === 'group'
        ? await restoreGroupEntry(entry)
        : await restoreSingleEntry(entry, lineage => refs.undoStackRef.current.remapLineage(lineage))
      if (result === 'restored') return
      if (result === 'retryable-failure') {
        refs.undoStackRef.current.push(entry)
        // WHY a toast (#1242): keeping the entry is right (the provider, not
        // the entry, is broken), but without saying so, every Cmd+Shift+T
        // after a CLI broke looked like a dead key.
        showToast(restoreFailureMessage(entry), RESTORE_FAILURE_TOAST_MS)
        if (staleEntryConsumed) {
          bumpUndoCloseVersion(version => version + 1)
        }
        return
      }
      staleEntryConsumed = true
    }
  }, [bumpUndoCloseVersion, refs.undoStackRef, restoreGroupEntry, restoreSingleEntry, showToast])

  // Peek at the undo stack length — used by the command palette to
  // show/hide the "Undo Close" command.
  const undoCloseCount = refs.undoStackRef.current.length

  return { undoClose, undoCloseCount }
}

/** Warning-grade toasts elsewhere use 6-10 s; the default 2.5 s vanished
 *  before the sentence could be read (#1264 review). */
const RESTORE_FAILURE_TOAST_MS = 8000

/** What a failed Undo Close tells the user: which close could not come back,
 *  and the same safe, actionable sentence main's recovery and the reload
 *  path show for a provider that would not start. Never the spawn's own
 *  text (steering q22). */
function restoreFailureMessage(entry: ClosedEntry): string {
  const what = entry.type === 'session'
    ? `"${sessionDisplayTitle(entry.sessionMeta)}"`
    : entry.type === 'tab'
      ? `project "${entry.tab.title}"`
      : `${entry.entries.length} closed item${entry.entries.length === 1 ? '' : 's'}`
  return `Could not restore ${what}: ${SESSION_START_FAILED_MESSAGE}`
}

/** A restore whose folder was deleted since the close (typically a worktree
 *  removed after its branch merged). Quoting the path is safe: it is main's
 *  own curated message and the pane header already renders it. */
function folderMissingMessage(what: string, cwd: string): string {
  return `Could not restore ${what}: its folder no longer exists (${cwd})`
}

/** Recognise MissingWorkspaceDirectoryError across IPC. The class does not
 *  survive `ipcRenderer.invoke` (only the wrapped message does), hence the
 *  shared prefix rather than instanceof. */
function isMissingFolderError(error: unknown): boolean {
  return error instanceof Error && error.message.includes(MISSING_WORKSPACE_FOLDER_PREFIX)
}

import { useCallback } from 'react'

import { emptyRuntime } from '@renderer/session-runtime/state'
import type { RenderedViewLeaseFeature, SessionRuntime } from '@renderer/session-runtime/state'
import type { SessionId } from '@renderer/workspace/types'
import { appendFeedDebugLog } from '@renderer/session-runtime/feedDebug'
import type { FeedDebugInput } from '@renderer/session-runtime/feedDebug'
import { withDerivedSessionStatus } from '@renderer/session-runtime/semantic/helpers'

import type {
  WorkspaceSetRuntimes,
  WorkspaceSetState,
} from '@renderer/workspace/hook/context'
import type { WorkspaceRefs } from '@renderer/workspace/hook/refs'
import { commandTargetSessionIdForState } from '@renderer/workspace/hook/selectors/commandTargetSessionId'

// Missing sessions need a stable read-only fallback so merely asking for their
// state cannot invalidate a memo boundary. Reducers still allocate their own.
//
// INVARIANT: this object is SHARED by every session that has no stored runtime
// yet and must never be mutated in place. Update paths always build fresh
// reducer-owned runtimes (spread + patch), so a `getRuntime()` result is only
// ever read. An in-place edit here would leak into every runtime-less session
// at once, because they all read this one object; the corruption would surface
// only after one of them was created, which is the worst moment to debug it.
const EMPTY_RUNTIME = emptyRuntime()

// -----------------------------------------------------------------------------
// Cross-cutting runtime helpers
//
// updateRuntime / appendFeedDebug / getRuntime / toggleTailMode /
// scrollFocusedToLatest are used by many other actions and live here
// so every sub-hook can consume them through the context without
// re-declaring them.
// -----------------------------------------------------------------------------

export function useWorkspaceHelpers(
  setRuntimes: WorkspaceSetRuntimes,
  refs: WorkspaceRefs,
): {
  updateRuntime: (sessionId: SessionId, patch: Partial<SessionRuntime>) => void
  appendFeedDebug: (sessionId: SessionId, input: FeedDebugInput) => void
  acknowledgeSession: (sessionId: SessionId) => void
  getRuntime: (sessionId: SessionId) => SessionRuntime
  toggleTailMode: (sessionId: SessionId) => void
  acquireRenderedViewLease: (sessionId: SessionId, feature: RenderedViewLeaseFeature) => void
  releaseRenderedViewLease: (sessionId: SessionId, feature: RenderedViewLeaseFeature) => void
  releaseAllRenderedViewLeases: (sessionId: SessionId) => void
  scrollFocusedToLatest: () => void
} {
  const updateRuntime = useCallback(
    (sessionId: SessionId, patch: Partial<SessionRuntime>) => {
      setRuntimes(prev => {
        const current = prev[sessionId] ?? emptyRuntime()
        return {
          ...prev,
          [sessionId]: withDerivedSessionStatus({ ...current, ...patch }),
        }
      })
    },
    [setRuntimes],
  )

  const appendFeedDebug = useCallback(
    (sessionId: SessionId, input: FeedDebugInput) => {
      setRuntimes(prev => {
        const current = prev[sessionId] ?? emptyRuntime()
        const next = appendFeedDebugLog(current, input)
        if (next === current) return prev
        return {
          ...prev,
          [sessionId]: next,
        }
      })
    },
    [setRuntimes],
  )

  const acknowledgeSession = useCallback(
    (sessionId: SessionId) => {
      setRuntimes(prev => {
        const current = prev[sessionId]
        if (!current || (current.unreadSince === null && current.unreadKind === null)) return prev
        return {
          ...prev,
          [sessionId]: {
            ...current,
            unreadSince: null,
            unreadKind: null,
          },
        }
      })
    },
    [setRuntimes],
  )

  const getRuntime = useCallback(
    (sessionId: SessionId): SessionRuntime => {
      return refs.latestRuntimesRef.current[sessionId] ?? EMPTY_RUNTIME
    },
    [refs.latestRuntimesRef],
  )

  const toggleTailMode = useCallback(
    (sessionId: SessionId) => {
      setRuntimes(prev => {
        const current = prev[sessionId] ?? emptyRuntime()
        return {
          ...prev,
          [sessionId]: {
            ...current,
            tailMode: !current.tailMode,
          },
        }
      })
    },
    [setRuntimes],
  )

  const acquireRenderedViewLease = useCallback(
    (sessionId: SessionId, feature: RenderedViewLeaseFeature) => {
      setRuntimes(prev => {
        const current = prev[sessionId] ?? emptyRuntime()
        const currentCount = current.renderedViewLeases[feature] ?? 0
        return {
          ...prev,
          [sessionId]: {
            ...current,
            renderedViewLeases: {
              ...current.renderedViewLeases,
              [feature]: currentCount + 1,
            },
          },
        }
      })
    },
    [setRuntimes],
  )

  const releaseRenderedViewLease = useCallback(
    (sessionId: SessionId, feature: RenderedViewLeaseFeature) => {
      setRuntimes(prev => {
        const current = prev[sessionId]
        if (!current) return prev
        const currentCount = current.renderedViewLeases[feature] ?? 0
        if (currentCount <= 0) return prev
        const renderedViewLeases = { ...current.renderedViewLeases }
        if (currentCount === 1) {
          delete renderedViewLeases[feature]
        } else {
          renderedViewLeases[feature] = currentCount - 1
        }
        return {
          ...prev,
          [sessionId]: {
            ...current,
            renderedViewLeases,
          },
        }
      })
    },
    [setRuntimes],
  )

  const releaseAllRenderedViewLeases = useCallback(
    (sessionId: SessionId) => {
      setRuntimes(prev => {
        const current = prev[sessionId]
        if (!current || Object.keys(current.renderedViewLeases).length === 0) return prev
        return {
          ...prev,
          [sessionId]: {
            ...current,
            renderedViewLeases: {},
          },
        }
      })
    },
    [setRuntimes],
  )

  const scrollFocusedToLatest = useCallback(() => {
    const snap = refs.stateRef.current
    // WHY command-target instead of tab.focusedSessionId:
    //
    // In Dispatch Mode the visible row may be a detached session (no
    // tile-tree placement at all) or a grid row that didn't mutate
    // tab.focusedSessionId. Reading tab.focusedSessionId here would
    // scroll the underlying grid pane while the user expects "End" /
    // Jump-to-Latest to act on the row they see highlighted in the
    // Dispatch list. commandTargetSessionIdForState routes through the
    // same row-derived selector the palette and provider actions use,
    // so all "act on the visible thing" commands agree.
    const sessionId = commandTargetSessionIdForState(snap)
    if (!sessionId) return
    setRuntimes(prev => {
      const current = prev[sessionId] ?? emptyRuntime()
      return {
        ...prev,
        [sessionId]: {
          ...current,
          unreadSince: null,
          unreadKind: null,
          scrollToLatestRequest: current.scrollToLatestRequest + 1,
        },
      }
    })
  }, [refs.stateRef, setRuntimes])

  return {
    updateRuntime,
    appendFeedDebug,
    acknowledgeSession,
    getRuntime,
    toggleTailMode,
    acquireRenderedViewLease,
    releaseRenderedViewLease,
    releaseAllRenderedViewLeases,
    scrollFocusedToLatest,
  }
}

// -----------------------------------------------------------------------------
// Pane toast — declared here instead of actions/toast.ts because many
// actions want to show a toast and the helpers+toast pair is atomic
// enough to stay together.
// -----------------------------------------------------------------------------

export function usePaneToast(
  paneToastTimers: WorkspaceRefs['paneToastTimers'],
  updateRuntime: (id: SessionId, patch: Partial<SessionRuntime>) => void,
  stateRef?: WorkspaceRefs['stateRef'],
): (sessionId: SessionId, message: string, durationMs?: number) => void {
  // Single-slot, auto-dismiss. Calling showPaneToast while a previous
  // toast is still visible replaces it and resets the timer. The
  // timeout ref lives outside React state so we can clear it without
  // causing a re-render.
  return useCallback(
    (sessionId: SessionId, message: string, durationMs = 2000) => {
      // A pane that is gone (closed while an async action it started was
      // still running) gets no toast: updateRuntime would recreate a runtime
      // row for the dead id, and its dismiss timer would write it again, so
      // the row was never removed (#1262 review A; builtInMcpReload shared
      // the shape).
      if (stateRef && !stateRef.current.sessions[sessionId]) return
      // Clear any in-flight timer for this pane.
      const prev = paneToastTimers.current[sessionId]
      if (prev) clearTimeout(prev)

      updateRuntime(sessionId, { paneToast: message })

      paneToastTimers.current[sessionId] = setTimeout(() => {
        delete paneToastTimers.current[sessionId]
        // Closed while its toast was showing: clearing it would recreate the
        // dead pane's runtime row, the other half of the same leak.
        if (stateRef && !stateRef.current.sessions[sessionId]) return
        updateRuntime(sessionId, { paneToast: null })
      }, durationMs)
    },
    [paneToastTimers, updateRuntime, stateRef],
  )
}

