import type { AgentActivitySelection } from '@renderer/workspace/agentActivityClose'

// -----------------------------------------------------------------------------
// useWorkspace — the composer.
//
// Every piece of functionality the hook used to contain inline now
// lives in its own file under ./actions, ./ipc, ./persistence, or
// ./invalidation. This composer reads state from zustand, sets up
// refs, setters, and helpers, then wires each sub-hook into a single returned
// object.
//
// Returning a stable shape is the only hard contract: consumers
// destructure fields off `Workspace` and if a sub-hook moves a
// method's name the caller breaks. Keep the return block alphabetic
// and avoid renames.
// -----------------------------------------------------------------------------

export type Workspace = ReturnType<typeof useWorkspace>

export function useWorkspace(
  dangerousAgentsEnabled = false,
  useProxyStreaming = false,
  defaultBuiltInMcpDomains: BuiltInMcpDefaultsInput = [],
) {
  // ---- Zustand subscriptions (these drive re-renders) ----
  const { showToast } = useGlobalToast()
  const openNewAgentPlacement = useAppStore(store => store.openNewAgentPlacement)
  const closeNewAgentPlacement = useAppStore(store => store.closeNewAgentPlacement)

  const state = useAppStore(store => store.workspaceState)
  const setState = useAppStore(store => store.setWorkspaceState)
  // Runtime rendering is owned by session subscribers, not the composition
  // root. The snapshot seeds refs only; an imperative subscription below keeps
  // callbacks current even when no layout render is scheduled.
  const runtimes = useAppStore.getState().workspaceRuntimes
  const setRuntimes = useAppStore(store => store.setWorkspaceRuntimes)
  const spotlight = useAppStore(store => store.workspaceSpotlight)
  const setSpotlight = useAppStore(store => store.setWorkspaceSpotlight)
  const readerMode = useAppStore(store => store.workspaceReaderMode)
  const setReaderMode = useAppStore(store => store.setWorkspaceReaderMode)

  // ---- Refs (identity-stable across renders) ----
  const refs = useWorkspaceRefs(
    state,
    runtimes,
    dangerousAgentsEnabled,
    useProxyStreaming,
    defaultBuiltInMcpDomains,
  )

  // ---- Keep refs in sync with live values on every render ----
  refs.stateRef.current = state
  refs.latestStateRef.current = state
  refs.latestRuntimesRef.current = runtimes
  useLayoutEffect(() => {
    const current = useAppStore.getState()
    refs.latestRuntimesRef.current = current.workspaceRuntimes
    refs.stateRef.current = current.workspaceState
    refs.latestStateRef.current = current.workspaceState
    // Sequential bulk closes resume before React necessarily commits a render.
    // Keep both ownership and activity current synchronously; a render-body
    // mirror can otherwise re-close a promoted root using yesterday's layout.
    const unsubscribeRuntime = useAppStore.subscribe(store => store.workspaceRuntimes, next => {
      refs.latestRuntimesRef.current = next
    })
    const unsubscribeState = useAppStore.subscribe(store => store.workspaceState, next => {
      refs.stateRef.current = next
      refs.latestStateRef.current = next
    })
    return () => { unsubscribeRuntime(); unsubscribeState() }
  }, [refs])
  refs.dangerousAgentsRef.current = dangerousAgentsEnabled
  refs.useProxyStreamingRef.current = useProxyStreaming
  refs.defaultBuiltInMcpDomainsRef.current = defaultBuiltInMcpDomains

  // Draft changes invalidate the autosave service, not the whole controller.
  // The service observes this stable signal even when App does not rerender.
  const draftChanges = useMemo(createDraftChanges, [])
  const [bootstrapComplete, setBootstrapComplete] = useState(false)
  // Surfaces the bootstrap outcome to the UI so it can render a banner
  // when the workspace is in a partial-restore / persisted-fallback
  // state. Lives outside `bootstrapComplete` because that boolean only
  // says "are we past the once-only effect", not "is the on-disk state
  // intact". See useBootstrap for the four possible terminal values.
  const [restoreStatus, setRestoreStatus] = useState<WorkspaceRestoreStatus>('pending')
  // The last save error while saves keep failing, null once one succeeds
  // (#1244). Shown by RestoreBanner; see useAutoSave for the threshold.
  const [saveFailure, setSaveFailure] = useState<string | null>(null)
  const setSessionAgentViewModeOverride = useCallback((
    sessionId: SessionId,
    override: AgentViewModeOverride | null,
  ): boolean => {
    const snapshot = refs.stateRef.current
    const meta = snapshot.sessions[sessionId]
    if (!meta) return false
    const kind = meta.kind ?? DEFAULT_PROVIDER
    if (!isAgentProviderKind(kind)) return false
    if (
      kind === 'opencode' &&
      meta.providerRuntime !== 'terminal' &&
      override === 'terminal'
    ) {
      // WHY this repeats the render-policy guard instead of relying only on
      // getEffectiveAgentSurface: this field is durable workspace metadata.
      // Persisting "terminal" on an OpenCode session today would make
      // workspace.json claim an intent the provider cannot satisfy, then force
      // future native-mode work to distinguish "real user override" from
      // "stale impossible override." Reject it at the write boundary; the
      // display-policy pin remains the read-side safety net.
      showToast('Choose OpenCode Terminal when creating the agent to use the native TUI')
      return false
    }
    if (effectiveProviderRuntime(kind, meta.providerRuntime) === 'terminal' && override === 'agent') {
      // Effective runtime: Pi panes are terminal-only whatever their metadata
      // stored, and the toast names the pane's own provider.
      showToast(`${providerChoiceLabel(kind, 'terminal')} sessions always use the native TUI`)
      return false
    }

    setState(prev => {
      const current = prev.sessions[sessionId]
      if (!current) return prev
      const sessions = { ...prev.sessions }
      if (override === null) {
        const { agentViewModeOverride: _removed, ...rest } = current
        sessions[sessionId] = rest
      } else {
        sessions[sessionId] = {
          ...current,
          agentViewModeOverride: override,
        }
      }
      return {
        ...prev,
        sessions,
      }
    })
    if (override === 'terminal') {
      setRuntimes(prev => {
        const current = prev[sessionId]
        if (!current) return prev
        if (
          !current.assistantPicker &&
          !current.codeBlockPicker &&
          Object.keys(current.renderedViewLeases).length === 0
        ) {
          return prev
        }
        return {
          ...prev,
          [sessionId]: {
            ...current,
            assistantPicker: null,
            codeBlockPicker: null,
            renderedViewLeases: {},
          },
        }
      })
    }
    return true
  }, [refs.stateRef, setRuntimes, setState, showToast])

  const setAgentTitle = useCallback((sessionId: SessionId, title: string): boolean => {
    // Any existing session can carry a title (#865); only a vanished one is refused.
    if (!refs.stateRef.current.sessions[sessionId]) return false

    // WHY the mutation is delegated to a pure workspace helper rather than
    // written inline here: `SessionMeta.title` is already consumed by several
    // surfaces and persisted wholesale. One canonical normalizer makes modal,
    // command, and any future inline-edit entry points converge on the same
    // trimming, clearing, length, and no-op behavior before autosave sees it.
    setState(prev => setAgentTitleInWorkspace(prev, sessionId, title))
    return true
  }, [refs.stateRef, setState])

  // ---- Runtime helpers (updateRuntime / appendFeedDebug / getRuntime / etc) ----
  const {
    updateRuntime,
    appendFeedDebug,
    acknowledgeSession,
    getRuntime,
    toggleTailMode,
    acquireRenderedViewLease,
    releaseRenderedViewLease,
    releaseAllRenderedViewLeases,
    scrollFocusedToLatest,
  } =
    useWorkspaceHelpers(setRuntimes, refs)

  // ---- Pane toast (needs updateRuntime, so after helpers) ----
  const showPaneToast = usePaneToast(refs.paneToastTimers, updateRuntime, refs.stateRef)

  // ---- Actions ----
  const isCodexSession = useCallback(
    (sessionId: SessionId) => refs.stateRef.current.sessions[sessionId]?.kind === 'codex',
    [refs.stateRef],
  )
  const { setDraftInput, setDraftImages, clearDraft, undoClearDraft } = useDraftActions(
    setRuntimes,
    updateRuntime,
    draftChanges.bump,
  )
  const {
    beginOptimisticSubmit,
    unwindOptimisticSubmit,
    settleQueuedSubmit,
    clearPendingRewindUndo,
    addOptimisticCodexUserEntry,
    removeOptimisticCodexUserEntry,
    addPendingPromptEntry,
    removePendingPromptEntry,
  } =
    useStreamingActions(setRuntimes, isCodexSession)
  const { pickerEnter, pickerMove, pickerCancel, pickerConfirm, setCodeBlockPicker } =
    usePickerActions(setRuntimes, refs, showPaneToast)
  const { setSpotlightTarget, toggleSpotlight, setSpotlightSession } = useSpotlightActions(
    setSpotlight,
    setState,
    refs,
  )
  const { setReaderModeTarget, toggleReaderMode, setReaderModeSession } = useReaderActions(
    setReaderMode,
    setSpotlight,
    setState,
    refs,
  )
  // useTileTabsActions and useResizeActions were composed here until the
  // unified layout (#992): Tile Tabs and split resizing both died with the
  // tile tree. Lane/row sizing lives in useDispatchActions.

  // Session lifecycle + derivatives that depend on it
  const sessionActions = useSessionActions(state, setState, setRuntimes, refs)
  const { spawn, ensureSessionLive, killSession, replaceSession, reloadAgentSessions, softReloadAgentView } =
    sessionActions
  const ensureSessionLiveRef = useRef(ensureSessionLive)
  ensureSessionLiveRef.current = ensureSessionLive

  const { focusAgentByPaneLabel, focusAgentBySessionId } = useAgentIndexNavigationActions(
    setState,
    setRuntimes,
    refs,
    sessionActions,
    showToast,
  )

  const tabActions = useTabActions(
    state,
    setState,
    setRuntimes,
    setSpotlight,
    setReaderMode,
    refs,
    showToast,
    sessionActions,
  )

  const paneActions = usePaneActions(
    state,
    setState,
    setRuntimes,
    setSpotlight,
    setReaderMode,
    refs,
    showToast,
    openNewAgentPlacement,
    closeNewAgentPlacement,
    sessionActions,
  )
  const createOrchestrationAgentRef = useRef(paneActions.createOrchestrationAgent)
  createOrchestrationAgentRef.current = paneActions.createOrchestrationAgent
  const closeOrchestrationSessionRef = useRef(paneActions.closeSession)
  closeOrchestrationSessionRef.current = paneActions.closeSession

  useEffect(() => {
    const off = window.api.onOrchestrationRequest(async request => {
      try {
        if (request.type === 'create-agent') {
          const agent = await createOrchestrationAgentRef.current({
            parentId: request.parentSessionId,
            kind: request.kind,
            ...(request.providerRuntime ? { providerRuntime: request.providerRuntime } : {}),
            cwd: request.cwd,
            title: request.title,
            role: request.role,
            runId: request.runId,
            builtInMcpDomains: request.builtInMcpDomains,
            // WHY the request field is intentionally omitted:
            // older MCP tool schemas can still send `inheritParentContext`,
            // but context inheritance is disabled until it can be rebuilt on a
            // stable provider-resume contract. The renderer spawn path is the
            // final authority for whether a child receives a cloned transcript,
            // so forcing clean children here prevents stale clients from
            // accidentally reviving the broken behavior.
          })
          await window.api.resolveOrchestrationRequest({
            requestId: request.requestId,
            ok: true,
            type: 'create-agent',
            agent,
          })
          return
        }

        const snapshot = refs.stateRef.current
        const runtimes = refs.latestRuntimesRef.current
        if (request.type === 'list-agents') {
          const agents: OrchestrationAgentRecord[] = listOrchestrationAgents({
            state: snapshot,
            runtimes,
            parentSessionId: request.parentSessionId,
            runId: request.runId,
          })

          await window.api.resolveOrchestrationRequest({
            requestId: request.requestId,
            ok: true,
            type: 'list-agents',
            agents,
          })
          return
        }

        if (request.type === 'read-agent') {
          const output = readOrchestrationAgent({
            state: snapshot,
            runtimes,
            parentSessionId: request.parentSessionId,
            sessionId: request.sessionId,
            maxMessages: request.maxMessages,
            maxCharsPerMessage: request.maxCharsPerMessage,
            maxCharsPerAgent: request.maxCharsPerAgent,
          })
          await window.api.resolveOrchestrationRequest({
            requestId: request.requestId,
            ok: true,
            type: 'read-agent',
            output,
          })
          return
        }

        if (request.type === 'read-run-outputs') {
          const outputs = readOrchestrationRunOutputs({
            state: snapshot,
            runtimes,
            parentSessionId: request.parentSessionId,
            runId: request.runId,
            maxMessagesPerAgent: request.maxMessagesPerAgent,
            maxCharsPerMessage: request.maxCharsPerMessage,
            maxCharsPerAgent: request.maxCharsPerAgent,
          })
          await window.api.resolveOrchestrationRequest({
            requestId: request.requestId,
            ok: true,
            type: 'read-run-outputs',
            outputs,
          })
          return
        }

        if (request.type === 'close-agent') {
          const result = await closeOrchestrationAgent({
            state: snapshot,
            parentSessionId: request.parentSessionId,
            sessionId: request.sessionId,
            closeSession: closeOrchestrationSessionRef.current,
          })
          await window.api.resolveOrchestrationRequest({
            requestId: request.requestId,
            ok: true,
            type: 'close-agent',
            result,
          })
          return
        }

        if (request.type === 'ensure-agent-live') {
          // WHY orchestration wake is renderer-mediated:
          // main can tell whether a provider process exists, but only the
          // renderer owns durable workspace metadata and orchestration
          // visibility. After a full app restart, parked/listed agents can
          // still be valid children in workspace.json while main's in-memory
          // SessionManager has no PTY for that SessionId. Waking here keeps the
          // same id and therefore preserves Dispatch nesting, parent/root
          // ownership, and any MCP caller that already named the child.
          readOrchestrationAgent({
            state: snapshot,
            runtimes,
            parentSessionId: request.parentSessionId,
            sessionId: request.sessionId,
            maxMessages: 1,
          })
          await ensureSessionLiveRef.current(request.sessionId, 'orchestration.read-agent')
          const agent = readOrchestrationAgent({
            state: refs.stateRef.current,
            runtimes: refs.latestRuntimesRef.current,
            parentSessionId: request.parentSessionId,
            sessionId: request.sessionId,
            maxMessages: 1,
          }).agent
          await window.api.resolveOrchestrationRequest({
            requestId: request.requestId,
            ok: true,
            type: 'ensure-agent-live',
            agent,
          })
          return
        }

        if (request.type === 'mark-bootstrap-prompt-delivered') {
          const output = readOrchestrationAgent({
            state: snapshot,
            runtimes,
            parentSessionId: request.parentSessionId,
            sessionId: request.sessionId,
            maxMessages: 1,
          })
          setState(prev => {
            return markOrchestrationBootstrapPromptDelivered({
              state: prev,
              parentSessionId: request.parentSessionId,
              sessionId: request.sessionId,
            })
          })
          await window.api.resolveOrchestrationRequest({
            requestId: request.requestId,
            ok: true,
            type: 'mark-bootstrap-prompt-delivered',
            agent: {
              ...output.agent,
              orchestrationBootstrapPromptDelivered: true,
            },
          })
          return
        }

        const result = await closeOrchestrationRun({
          state: snapshot,
          parentSessionId: request.parentSessionId,
          runId: request.runId,
          closeSession: closeOrchestrationSessionRef.current,
        })
        await window.api.resolveOrchestrationRequest({
          requestId: request.requestId,
          ok: true,
          type: 'close-run',
          result,
        })
      } catch (err) {
        await window.api.resolveOrchestrationRequest({
          requestId: request.requestId,
          ok: false,
          type: request.type,
          message: err instanceof Error && err.message.length > 0
            ? err.message
            : 'Orchestration request failed',
        })
      }
    })
    return off
  }, [refs.latestRuntimesRef, refs.stateRef, setState])

  useEffect(() => {
    const resolveFailure = async (
      requestId: string,
      type: AgentManagementRendererResponse['type'],
      error: unknown,
      sessionId?: string,
    ): Promise<void> => {
      // A target refusal carries a message written for the calling model
      // (which labels the project shows, why a name did not resolve), so it
      // is forwarded verbatim instead of being flattened to a bare code.
      if (error instanceof ManagedAgentTargetError) {
        await window.api.resolveAgentManagementRequest({
          requestId,
          ok: false,
          type,
          code: error.code,
          message: error.message,
          ...(sessionId ? { sessionId } : {}),
        })
        return
      }
      const candidate = error instanceof Error ? error.message : 'request_failed'
      const knownCodes = new Set([
        'caller_not_found',
        'agent_not_found',
        'agent_not_in_project',
        'self_target_forbidden',
        'transcript_unavailable',
      ] as const)
      const code = knownCodes.has(candidate as never)
        ? candidate as Extract<AgentManagementRendererResponse, { ok: false }>['code']
        : 'request_failed'
      await window.api.resolveAgentManagementRequest({
        requestId,
        ok: false,
        type,
        code,
        message: code === 'request_failed'
          ? (error instanceof Error && error.message.length > 0
              ? error.message
              : 'Agent management request failed.')
          : `Agent management request rejected: ${code}.`,
        ...(sessionId ? { sessionId } : {}),
      })
    }

    // See hydrateTranscript.ts for why reads never wake the agent and why the
    // zustand store (not refs) is what gets read back.
    const hydrateTranscriptWithoutWaking = (
      sessionId: string,
    ): Promise<'transcript_unavailable' | 'not_created' | null> =>
      hydrateManagedTranscript({
        sessionId,
        refs,
        setRuntimes,
        read: () => {
          const current = useAppStore.getState()
          return { state: current.workspaceState, runtimes: current.workspaceRuntimes }
        },
      })

    // Read beside whichever workspace snapshot the caller is about to use, so
    // a name is resolved and published from the same moment as the labels.
    const agentNames = (): ManagedAgentNames => {
      const store = useAppStore.getState()
      return {
        enabled: store.settings.agentNamesEnabled === true,
        names: store.workspaceAgentNames ?? {},
      }
    }
    // The single place a request's target becomes a session id (#1145). See
    // resolveManagedTarget for why a label is resolved here, now, against the
    // live state — and never re-resolved after an await.
    const resolveTarget = (
      callerSessionId: string,
      target: Parameters<typeof resolveManagedTarget>[0]['target'],
    ): string => resolveManagedTarget({
      state: refs.stateRef.current,
      callerSessionId,
      target,
      agentNames: agentNames(),
    })
    const currentLabel = (sessionId: string): string | null => {
      const state = refs.stateRef.current
      return sessionDisplayLabel(state, sessionId, buildVisibleDispatchRows(state))
    }

    const off = window.api.onAgentManagementRequest(async request => {
      // Filled as soon as a target resolves, so a later refusal names the
      // session it was about rather than echoing an unresolved label.
      let resolvedSessionId: string | undefined
      try {
        if (request.type === 'list-agents') {
          const listed = listManagedAgentDescriptors({
            state: refs.stateRef.current,
            runtimes: refs.latestRuntimesRef.current,
            callerSessionId: request.callerSessionId,
            agentNames: agentNames(),
          })
          await window.api.resolveAgentManagementRequest({
            requestId: request.requestId,
            ok: true,
            type: 'list-agents',
            observedAt: Date.now(),
            ...listed,
          })
          return
        }

        if (request.type === 'read-agent') {
          const sessionId = resolveTarget(request.callerSessionId, request.target)
          resolvedSessionId = sessionId
          assertManagedTarget({
            state: refs.stateRef.current,
            callerSessionId: request.callerSessionId,
            sessionId,
            allowSelf: true,
          })
          const unavailable = await hydrateTranscriptWithoutWaking(sessionId)
          if (unavailable) throw new Error('transcript_unavailable')
          const current = useAppStore.getState()
          const output = readManagedAgentOutput({
            state: current.workspaceState,
            runtimes: current.workspaceRuntimes,
            callerSessionId: request.callerSessionId,
            sessionId,
            maxMessages: request.maxMessages,
            maxCharsPerMessage: request.maxCharsPerMessage,
            maxCharsPerAgent: request.maxCharsPerAgent,
            agentNames: agentNames(),
          })
          await window.api.resolveAgentManagementRequest({
            requestId: request.requestId,
            ok: true,
            type: 'read-agent',
            observedAt: Date.now(),
            output,
          })
          return
        }

        if (request.type === 'read-agents') {
          const listed = listManagedAgentDescriptors({
            state: refs.stateRef.current,
            runtimes: refs.latestRuntimesRef.current,
            callerSessionId: request.callerSessionId,
            agentNames: agentNames(),
          })
          const listedIds = new Set(listed.agents.map(item => item.agent.sessionId))
          // Labels and names resolve through the same resolver as the single
          // tools, then join the explicit id list: it is still "an explicit
          // subset" (strict about departures below), however it was named.
          const explicit = request.sessionIds || request.labels || request.names
            ? [
                ...(request.sessionIds ?? []),
                ...(request.labels ?? []).map(label => resolveTarget(request.callerSessionId, { label })),
                ...(request.names ?? []).map(name => resolveTarget(request.callerSessionId, { name })),
              ]
            : undefined
          let targetIds = explicit
            ? [...new Set(explicit)]
            : listed.agents
                .filter(item => request.includeCaller === true || !item.agent.isCaller)
                .map(item => item.agent.sessionId)
          for (const sessionId of targetIds) {
            if (!listedIds.has(sessionId)) throw new Error('agent_not_in_project')
          }
          // loadInitialHistoryForSession contains a two-slot limiter, so this
          // preserves bulk-read latency without turning a large project audit
          // into unbounded filesystem/IPC work.
          const unavailableById = new Map(
            (await Promise.all(targetIds.map(async sessionId => ({
              sessionId,
              reason: await hydrateTranscriptWithoutWaking(sessionId),
            }))))
              .filter((item): item is {
                sessionId: string
                reason: 'transcript_unavailable' | 'not_created'
              } => item.reason !== null)
              .map(item => [item.sessionId, item] as const),
          )
          const current = useAppStore.getState()
          if (!explicit) {
            const originalIds = new Set(targetIds)
            const fresh = listManagedAgentDescriptors({
              state: current.workspaceState,
              runtimes: current.workspaceRuntimes,
              callerSessionId: request.callerSessionId,
            })
            // WHY the implicit fleet read tolerates departures while an
            // explicit subset remains strict: "read all" describes a census,
            // not a transaction over identities the caller selected. Keep the
            // original observation boundary, drop agents the user closed during
            // hydration, and let the fresh inventory still reveal new arrivals.
            targetIds = fresh.agents
              .filter(item => originalIds.has(item.agent.sessionId))
              .filter(item => request.includeCaller === true || !item.agent.isCaller)
              .map(item => item.agent.sessionId)
          }
          const result = readManagedAgentOutputs({
            state: current.workspaceState,
            runtimes: current.workspaceRuntimes,
            callerSessionId: request.callerSessionId,
            sessionIds: targetIds,
            includeCaller: request.includeCaller,
            maxMessagesPerAgent: request.maxMessagesPerAgent,
            maxCharsPerMessage: request.maxCharsPerMessage,
            maxCharsPerAgent: request.maxCharsPerAgent,
            maxTotalChars: request.maxTotalChars,
            agentNames: agentNames(),
          })
          await window.api.resolveAgentManagementRequest({
            requestId: request.requestId,
            ok: true,
            type: 'read-agents',
            observedAt: Date.now(),
            ...result,
            unavailable: targetIds.flatMap(sessionId => {
              const item = unavailableById.get(sessionId)
              return item ? [item] : []
            }),
          })
          return
        }

        if (request.type === 'send-prompt') {
          const sessionId = resolveTarget(request.callerSessionId, request.target)
          resolvedSessionId = sessionId
          // The label the user saw when this was asked, captured BEFORE the
          // wake: waking can reorder nothing today, but the echo must describe
          // the agent as it was addressed, not whatever it shows afterwards.
          const displayLabel = currentLabel(sessionId)
          assertManagedTarget({
            state: refs.stateRef.current,
            callerSessionId: request.callerSessionId,
            sessionId,
          })
          // Sending is the one operation that intentionally wakes a parked
          // target. Re-authorize after the await because the user can move or
          // close a pane while the provider is starting.
          //
          // WHY the re-check uses the RESOLVED id, never the label again: if an
          // earlier row closed during the wake, "B28" now names a different
          // agent. The request was about the agent that showed B28 when it was
          // made; re-resolving would deliver to its neighbour.
          await ensureSessionLiveRef.current(sessionId, 'orchestration.send-prompt')
          assertManagedTarget({
            state: refs.stateRef.current,
            callerSessionId: request.callerSessionId,
            sessionId,
          })
          const delivery = await window.api.deliverPrompt(sessionId, request.prompt)
          await window.api.resolveAgentManagementRequest({
            requestId: request.requestId,
            ok: true,
            type: 'send-prompt',
            sessionId,
            displayLabel,
            delivery,
          })
          return
        }

        // Closing is structurally narrower than the UI close operation. The UI
        // intentionally cascades linked children; MCP must refuse that shape so
        // one named target never silently means several agents.
        //
        // A project's last grid leaf is NOT such a shape any more (#886 review
        // M1). It used to be, because closing it removed the tab with every
        // detached session in it. The close below passes requireConfirmation,
        // which never offers the human-only Close Tab choice, so it is
        // session-scoped and promotes the next Dispatch row into the grid.
        // additionalCloseImpact therefore reports linked descendants only. The
        // model-facing tool adds the separate requirement that the current
        // user explicitly requested closure.
        const closeTargetId = resolveTarget(request.callerSessionId, request.target)
        resolvedSessionId = closeTargetId
        const closeTargetLabel = currentLabel(closeTargetId)
        const affected = additionalCloseImpact({
          state: refs.stateRef.current,
          callerSessionId: request.callerSessionId,
          sessionId: closeTargetId,
        })
        if (affected.length > 0) {
          await window.api.resolveAgentManagementRequest({
            requestId: request.requestId,
            ok: false,
            type: 'close-agent',
            code: 'close_would_affect_additional_sessions',
            message: 'Closing this target would also affect additional project sessions.',
            sessionId: closeTargetId,
            additionalAffectedSessionIds: affected,
          })
          return
        }
        const current = refs.stateRef.current
        const placement = assertManagedTarget({
          state: current,
          callerSessionId: request.callerSessionId,
          sessionId: closeTargetId,
        })
        // A 'buried' placement used to branch to Kill Buried here. Buried
        // records become ordinary pool rows when an old file is migrated
        // (#992, legacyWorkspaceV2.ts legacyMemberships) and live state has no
        // `buried` field at all, so nothing can report one and every
        // managed close takes the one authorized path below. `placement` is
        // still resolved for its side effect: assertManagedTarget throws when
        // the caller does not manage this target.
        void placement
        {
          // THE authorization check for the Agent Management close tool.
          //
          // The tool's rule used to be prose in its description ("never close
          // an agent unless the user's current request named that specific
          // agent"), which is a request to a language model, not a check. The
          // first fix put a single-use grant store in main — right instinct,
          // wrong layer: a grant is issued by a USER ACTION, and main has no
          // user action meaning "the user asked this agent to close that one".
          // Nothing ever issued one, so every close_agent call was denied and
          // the tool was dead in a way no test noticed.
          //
          // Here, at the line that actually mutates, we CAN ask. Forced, so an
          // idle target does not slip through the human-ergonomics exemption
          // the policy grants ⌘W. Declining rejects the tool call.
          const caller = current.sessions[request.callerSessionId]?.title
          const closed = await closeOrchestrationSessionRef.current(closeTargetId, {
            requireConfirmation: {
              headline: caller
                ? `Agent “${caller}” is asking to close this agent.`
                : 'An agent is asking to close this agent.',
            },
            killCaller: 'agent-management.close-agent',
          })
          // The comment above says "declining rejects the tool call" — it did
          // not. The gate RESOLVES false rather than throwing, so the success
          // below fired anyway and the calling agent was told the close took
          // while its target kept running. This is the surface where a decline
          // is still possible, so it is the surface where reporting it matters
          // most.
          if (!closed) {
            throw new Error(
              // false is not only a decline since #886: the close is also
              // refused when the agent changed after approval or a linked
              // session is still open. Say which ones are possible rather than
              // telling the calling model the user said no.
              'close_agent did not close this agent: the user declined, or the agent changed or still had a linked session open when it was about to close.',
            )
          }
        }
        await window.api.resolveAgentManagementRequest({
          requestId: request.requestId,
          ok: true,
          type: 'close-agent',
          closedSessionId: closeTargetId,
          displayLabel: closeTargetLabel,
        })
      } catch (error) {
        await resolveFailure(
          request.requestId,
          request.type,
          error,
          resolvedSessionId,
        )
      }
    })
    return off
  }, [refs, setRuntimes])

  const { switchSessionProvider, reloadSessionAgent, rewindSessionToPrompt, undoSessionRewind, removeCodexCyberPolicyBlock, reloadFocusedAgent, rewindFocusedToPrompt, undoLastRewind, removeFocusedCyberPolicyBlock } =
    useProviderActions(refs, setRuntimes, showPaneToast, sessionActions)

  // Bulk provider switch (Switch Agents modal) + remembered-batch return. Uses
  // the same single-agent core as switchSessionProvider, but reports through the
  // global toast (the operation spans many panes, so a pane-scoped toast would
  // be arbitrary) and records the batch on workspace state.
  const { switchAgentsToProvider, returnLastProviderSwitchBatch } =
    useBulkProviderSwitchActions(refs, setState, setRuntimes, showToast, sessionActions)

  // Close Idle Orchestration Agents (#960). Wired here rather than inside the
  // command because it needs two things a command context does not have: the
  // GLOBAL toast (the operation spans many rows, so a pane toast would land on
  // an arbitrary one, the same reason Switch Agents reports here) and the
  // action's live refs, which the flow reads before and after its dialog.
  const closeIdleOrchestrationAgents = useCallback(
    () => runIdleOrchestrationCleanup({
      readState: () => refs.stateRef.current,
      readRuntimes: () => refs.latestRuntimesRef.current,
      closeSession: paneActions.closeSession,
      confirm: requestCloseConfirmation,
      showToast,
    }),
    [paneActions.closeSession, refs, showToast],
  )

  // Agent Activity's multi-select close (#1170). Wired here for the same two
  // reasons as the idle cleanup above: the global toast, and the live refs the
  // flow reads before and after its confirmation dialog.
  const closeAgentActivitySelection = useCallback(
    (selection: readonly AgentActivitySelection[]) => runAgentActivityClose(selection, {
      readState: () => refs.stateRef.current,
      readRuntimes: () => refs.latestRuntimesRef.current,
      closeSession: paneActions.closeSession,
      confirm: requestCloseConfirmation,
      showToast,
    }),
    [paneActions.closeSession, refs, showToast],
  )

  // Session events AND history reads arrive through whichever SessionFeed the
  // app root mounted (desktop: ipcSessionFeed in app/main.tsx; remote client:
  // its WebSocket feed; tests: FakeSessionFeed). The provider value is a
  // module const, so identity is stable — which the subscription effect's dep
  // array requires; see the WHY on useIpcSubscriptions. Read here, before the
  // history actions, because older-history paging reads through it (#1177).
  const sessionFeed = useSessionFeed()
  const { loadOlderHistory } = useHistoryActions(setRuntimes, refs, updateRuntime, sessionFeed)

  const { undoClose, undoCloseCount } = useUndoCloseAction(
    state,
    setState,
    refs,
    sessionActions,
    showToast,
  )

  const dispatchActions = useDispatchActions(
    setState,
    setRuntimes,
    refs,
    sessionActions.ensureSessionLive,
    showToast,
  )

  // Close Completed Agents… (#1182). Wired here like the two bulk closes above
  // for the global toast and the live refs, plus the lane removal the flow does
  // afterwards — which is why it sits after dispatchActions. The goal records
  // come from the modal: it is the one holding them fresh (read on open, kept
  // current by goal:changed), and the flow reads them again at every kill.
  const closeCompletedGoalAgents = useCallback(
    (
      selection: readonly SessionId[],
      options: { removeLanes: boolean; readGoals: () => Record<string, TldrRecord> },
    ) => runCompletedGoalClose(selection, { removeLanes: options.removeLanes }, {
      readState: () => refs.stateRef.current,
      readRuntimes: () => refs.latestRuntimesRef.current,
      readGoals: options.readGoals,
      closeSession: paneActions.closeSession,
      removeTiledLane: dispatchActions.removeTiledLane,
      showToast,
    }),
    [dispatchActions.removeTiledLane, paneActions.closeSession, refs, showToast],
  )

  // ---- Side-effects (subscriptions, persistence, invalidation) ----
  // `sessionFeed` is read above, next to the history actions.
  useIpcSubscriptions(sessionFeed, refs, setState, setRuntimes, updateRuntime, appendFeedDebug)
  // A terminal's durable last-used record (#1178). One setter for both the
  // foreground hook and the input path below, so the throttle and the
  // floor-never-moves rule live in one pure helper.
  const recordTerminalUsage = useCallback((sessionId: SessionId, usage: 'use' | 'floor') => {
    const at = Date.now()
    setState(prev => usage === 'use'
      ? withTerminalLastUsed(prev, sessionId, at)
      : withTerminalLastUsedFloor(prev, sessionId, at))
  }, [setState])
  const markTerminalUsed = useCallback((sessionId: SessionId) => recordTerminalUsage(sessionId, 'use'), [recordTerminalUsage])
  const readRuntimeForForeground = useCallback(
    (sessionId: SessionId) => refs.latestRuntimesRef.current[sessionId],
    [refs],
  )
  useTerminalForeground(restoreStatus, setRuntimes, readRuntimeForForeground, recordTerminalUsage)
  useSessionRoutingRecovery(refs, setRuntimes, state.sessions)
  useWorkspaceAdoption(refs, setState, setRuntimes, bootstrapComplete)
  useBootstrap(
    refs,
    setState,
    setRuntimes,
    tabActions.newTab,
    setBootstrapComplete,
    setRestoreStatus,
  )
  // The persist effect reads current refs on its own timer, so it needs no
  // render-time snapshot — passing `runtimes` here would suggest a reactivity
  // dependency that deliberately does not exist.
  useFeedDebugPersist(refs)
  useSpotlightSanity(spotlight, state, setSpotlight)
  useReaderModeSanity(readerMode, state, setReaderMode)
  usePinnedSessionIdsSanity(state, setState)
  // Beside the sanity hooks because it is the same kind of thing: a
  // membership-driven correction that keeps an orthogonal slice consistent
  // with the tile tree. It is last so it observes the state the sanity hooks
  // have already settled.
  useAgentNameReconciler(state, setState, restoreStatus)

  // ---- Derived values ----
  const activeTab = useMemo(
    () => state.tabs.find(t => t.id === state.activeTabId) ?? null,
    [state.activeTabId, state.tabs],
  )

  // Silence unused-var warning for useEffect import (may be
  // needed by future sub-hooks added to this composer).
  void useEffect

  // ---- Return the stable Workspace shape ----
  return {
    state,
    // Imperative commands/debug capture read the latest committed store.
    // Renderers must subscribe through useSessionRuntime/useWorkspaceContext.
    get runtimes() { return refs.latestRuntimesRef.current },
    runtimeServices: createElement(WorkspaceRuntimeServices, {
      state, refs, bootstrapComplete, draftChanges, pickerCancel, onSaveHealth: setSaveFailure,
    }),
    activeTab,
    spotlight,
    readerMode,
    // The lane grid. Exposed as `stage`, replacing the nullable `dispatchMode`
    // envelope (#992): consumers used to branch on "is Dispatch on?" and then
    // on "is it tiled?"; both questions are gone, so the field is the grid.
    stage: state.stage,
    restoreStatus,
    saveFailure,
    setReaderModeTarget,
    toggleReaderMode,
    setReaderModeSession,
    getRuntime,
    // Patch a session's runtime (sessionId, partial). Used by TileLeaf for
    // pane toasts and the prompt-suggestion chip's apply/dismiss handlers.
    // It was destructured above and wired into sub-hooks but never exposed
    // on the returned Workspace object, so `workspace.updateRuntime(...)`
    // threw "is not a function" at runtime (vite strips types, so the build
    // never caught the missing member). Exposing it here is the whole fix.
    updateRuntime,
    // Browser pocket config writes (#1142). Takes one of the pure transforms in
    // features/browser-pocket/actions.ts rather than exposing a general
    // setState: those transforms are the only code allowed to change
    // SessionMeta.browserPocket, and they return the SAME object for no-ops,
    // which setWorkspaceState turns into "no store notification, no autosave".
    updateBrowserPocket: (transform: (state: WorkspaceState) => WorkspaceState) => setState(transform),
    // actions
    newTab: tabActions.newTab,
    // Close Tab runs through the pane close executor, beside closeSession, so
    // the command and the root dialog's "Close Tab" button are one operation
    // (#886 review round 2; see the note in tab.ts).
    closeTab: paneActions.closeTab,
    spawn,
    ensureSessionLive,
    killSession,
    splitFocused: paneActions.splitFocused,
    openExtensionViewInPane: paneActions.openExtensionViewInPane,
    startNewAgentPlacement: paneActions.startNewAgentPlacement,
    createDetachedDispatchAgent: paneActions.createDetachedDispatchAgent,
    createDetachedSession: paneActions.createDetachedSession,
    createLinkedAgent: paneActions.createLinkedAgent,
    createOrchestrationAgent: paneActions.createOrchestrationAgent,
    closeFocused: paneActions.closeFocused,
    closeSession: paneActions.closeSession,
    closeIdleOrchestrationAgents,
    closeAgentActivitySelection,
    closeCompletedGoalAgents,
    markTerminalUsed,
    focusSessionInTab: paneActions.focusSessionInTab,
    focusAgentByPaneLabel,
    focusAgentBySessionId,
    setAgentTitle,
    setSessionAgentViewModeOverride,
    activateTab: tabActions.activateTab,
    activateTabByIndex: tabActions.activateTabByIndex,
    reorderTabs: tabActions.reorderTabs,
    mergeTabs: tabActions.mergeTabs,
    nextTab: tabActions.nextTab,
    prevTab: tabActions.prevTab,
    beginOptimisticSubmit,
    unwindOptimisticSubmit,
    settleQueuedSubmit,
    clearPendingRewindUndo,
    acknowledgeSession,
    appendFeedDebug,
    addOptimisticCodexUserEntry,
    removeOptimisticCodexUserEntry,
    addPendingPromptEntry,
    removePendingPromptEntry,
    setDraftInput,
    setDraftImages,
    clearDraft,
    undoClearDraft,
    loadOlderHistory,
    showPaneToast,
    undoClose,
    undoCloseCount,
    replaceSession,
    reloadFocusedAgent,
    softReloadAgentView,
    switchSessionProvider,
    reloadSessionAgent,
    rewindSessionToPrompt,
    removeCodexCyberPolicyBlock,
    undoSessionRewind,
    switchAgentsToProvider,
    returnLastProviderSwitchBatch,
    rewindFocusedToPrompt,
    removeFocusedCyberPolicyBlock,
    undoLastRewind,
    reloadAgentSessions,
    setSpotlightTarget,
    toggleSpotlight,
    setSpotlightSession,
    toggleTailMode,
    acquireRenderedViewLease,
    releaseRenderedViewLease,
    releaseAllRenderedViewLeases,
    scrollFocusedToLatest,
    pickerEnter,
    pickerMove,
    pickerConfirm,
    pickerCancel,
    setCodeBlockPicker,
    pinSession: dispatchActions.pinSession,
    unpinSession: dispatchActions.unpinSession,
    setPinnedSessionIds: dispatchActions.setPinnedSessionIds,
    selectTiledLaneSession: dispatchActions.selectTiledLaneSession,
    clearTiledLane: dispatchActions.clearTiledLane,
    insertTiledLaneRight: dispatchActions.insertTiledLaneRight,
    removeTiledLane: dispatchActions.removeTiledLane,
    setTiledFocusedLane: dispatchActions.setTiledFocusedLane,
    insertDispatchRowBelow: dispatchActions.insertDispatchRowBelow,
    removeDispatchRow: dispatchActions.removeDispatchRow,
    setDispatchGridShape: dispatchActions.setDispatchGridShape,
    setDispatchLaneWeights: dispatchActions.setDispatchLaneWeights,
    setDispatchRowIndexFraction: dispatchActions.setDispatchRowIndexFraction,
    setDispatchRowHeights: dispatchActions.setDispatchRowHeights,
    setDispatchRowProjects: dispatchActions.setDispatchRowProjects,
    setDispatchRowCapChildren: dispatchActions.setDispatchRowCapChildren,
    toggleDispatchRowExpandedParent: dispatchActions.toggleDispatchRowExpandedParent,
  }
}

