 *  healthy pane has entries before `turn_completed`, so this only has to
 *  cover the tail watcher's latency, and a false alarm clears itself on the
 *  first arriving record. */
const TRANSCRIPT_COMMIT_GRACE_MS = 15_000

export function useIpcSubscriptions(
  // WHY feed identity matters: `feed` sits in the effect's dep array, so an
  // unstable reference would tear down + re-attach every subscription each
  // render — the exact pathology the memoized refs factory exists to prevent
  // (see useWorkspaceRefs). ipcSessionFeed is a module const and the context
  // value passes it through untouched, so identity is stable by construction.
  // If a future transport constructs its feed per-render, memoize it at the
  // construction site, not here.
  feed: SessionFeed,
  refs: WorkspaceRefs,
  setState: WorkspaceSetState,
  setRuntimes: WorkspaceSetRuntimes,
  updateRuntime: (sessionId: SessionId, patch: Partial<SessionRuntime>) => void,
  appendFeedDebug: (sessionId: SessionId, input: FeedDebugInput) => void,
): void {
  useEffect(() => {
    let worktreeReconciler!: LiveWorktreeReconciler
    worktreeReconciler = new LiveWorktreeReconciler({
      loadWorktrees: cwd => window.api.gitWorktrees(cwd),
      onCatalogReady: cwd => {
        setRuntimes(prev => {
          let changed = false
          const next = { ...prev }
          for (const [sessionId, runtime] of Object.entries(prev)) {
            const meta = refs.stateRef.current.sessions[sessionId]
            if (meta?.cwd !== cwd) continue
            const projection = worktreeReconciler.project({
              sessionId,
              cwd,
              projection: runtime,
            })
            if (
              projection.workContext === runtime.workContext &&
              projection.workActivity === runtime.workActivity
            ) continue
            next[sessionId] = appendFeedDebugLog(
              { ...runtime, ...projection },
              {
                layer: 'STATE',
                kind: 'worktree_catalog_reconciled',
                summary: 'Git worktree catalog replayed against recent evidence',
                // This summary deliberately excludes raw events, command text,
                // prompts, and file bodies. The cache race needs observability,
                // but duplicating provider content into feed-debug would turn a
                // metadata repair into a second sensitive transcript store.
                data: worktreeReconciler.summarize({
                  sessionId,
                  cwd,
                  projection,
                }),
              },
            )
            changed = true
          }
          return changed ? next : prev
        })
      },
    })
    // Ghost orphan / superseded-GC sweep — see docs/design/ghost-system.md for the
    // canonical explanation. Runs every GHOST_ORPHAN_SWEEP_MS,
    // calls orphanStale to flag any ghost whose updatedAt has been
    // silent for longer than GHOST_ORPHAN_TTL_MS, and drops ghosts
    // that have already been superseded by durable upstream JSONL.
    //
    // WHY GC superseded ghosts here instead of during reconcileUpstream:
    // reconcile needs a short overlap window so UI ownership can move from
    // proxy ghosts to committed entries without a flicker. After that grace
    // window the ghosts are dead weight; keeping them forever turns
    // selectMergedEntries into an O(ghost-map) loop on every TileLeaf render.
    // Both reducers are reference-stable on no-op, so the sweep only replaces
    // runtime state when something actually crossed a threshold.
    const orphanSweepTimer = window.setInterval(() => {
      const now = Date.now()
      setRuntimes(prev => {
        let changed = false
        const next = { ...prev }
        for (const [sessionId, runtime] of Object.entries(prev)) {
          // `working` accumulates every change this tick produces for this
          // session so the two independent passes (ghost GC, then the Codex
          // queued-message reconciliation) compose into a SINGLE setRuntimes
          // patch. We must NOT `continue` between them: a session with no
          // ghosts can still hold a stale Codex queue row, and a session that
          // GC'd ghosts can also need its queue cleared in the same tick.
          let working = runtime

          // --- Pass 1: ghost orphan flagging + superseded GC ---
          // Only runs when there are ghosts to consider; otherwise leaves
          // `working` untouched so the queue pass below still gets a chance.
          if (runtime.ghosts.size > 0) {
            const nextGhosts = sweepGhosts(runtime, now, {
              orphanTtlMs: GHOST_ORPHAN_TTL_MS,
              gcMs: GHOST_SUPERSEDED_GC_MS,
            })
            if (nextGhosts !== runtime.ghosts) {
              working = appendFeedDebugLog(
                { ...working, ghosts: nextGhosts },
                {
                  layer: 'STATE',
                  kind: 'ghost_orphan_sweep',
                  summary: nextGhosts.size < runtime.ghosts.size
                    ? `swept ${runtime.ghosts.size - nextGhosts.size} superseded/hidden ghosts`
                    : 'stale ghosts marked orphaned',
                  data: {
                    ghostCount: nextGhosts.size,
                    evictedCount: runtime.ghosts.size - nextGhosts.size,
                    orphanedCount: [...nextGhosts.values()].filter(
                      ghost => ghost._atp.orphanedAt !== undefined &&
                        runtime.ghosts.get(ghost.uuid)?._atp.orphanedAt === undefined,
                    ).length,
                  },
                },
              )
            }
          }

          // --- Pass 2: local queued-message idle reconciliation (backstop) ---
          // (codex + opencode — the optimistic-echo providers; see
          // queueInvariants.ts for the capability gate.)
          // The edge-site clears are the fast path; this is the convergence
          // backstop for when the last idle signal arrives via a channel that
          // never re-runs the invariant (see issue #241). We re-evaluate the
          // SAME predicate the edge sites use, but only after idle has been
          // STABLE past QUEUE_IDLE_RECONCILE_MS so we never clear in the
          // sub-second gap between a turn_completed and the next queued
          // follow-up's turn_started.
          const sessionKind = refs.stateRef.current.sessions[sessionId]?.kind
          if (
            working.queuedMessages.length > 0 &&
            shouldClearIdleQueuedMessages({
              awaitingAssistant: working.awaitingAssistant,
              processActive: working.processActive,
              provider: sessionKind,
              queuedMessagesLength: working.queuedMessages.length,
              streamPhase: working.streamPhase,
            })
          ) {
            // idleStable: the most recent activity/phase transition must be
            // older than the quiet window. We take the NEWEST of the two
            // available activity timestamps (phaseChangedAt, lastJsonlEntryAt)
            // — whichever moved most recently is what defines "last activity".
            // A null timestamp means that channel has never fired, so it
            // can't argue for recent activity and is ignored. If BOTH are
            // null the session has produced no observable activity at all,
            // which (given queuedMessages > 0 and the idle predicate already
            // true) is itself a quiesced state, so we treat it as stable.
            const lastActivityAt = Math.max(
              working.phaseChangedAt ?? 0,
              working.lastJsonlEntryAt ?? 0,
            )
            const idleStable = lastActivityAt === 0 || now - lastActivityAt >= QUEUE_IDLE_RECONCILE_MS
            if (idleStable) {
              if (sessionKind === 'codex') {
                working = appendQueuedSubmissionReleases(
                  working,
                  working.queuedMessages,
                  'idle-convergence',
                )
              }
              working = withDerivedSessionStatus(
                appendFeedDebugLog(
                  { ...working, queuedMessages: [] },
                  {
                    layer: 'STATE',
                    kind: 'queue_idle_reconcile',
                    summary: 'cleared stale local queue after idle convergence',
                    data: { clearedQueuedMessages: working.queuedMessages.length },
                  },
                ),
              )
            }
          }

          if (working !== runtime) {
            next[sessionId] = working
            changed = true
          }
        }
        return changed ? next : prev
      })
    }, GHOST_ORPHAN_SWEEP_MS)
    // Memory gauges (#375 part A) — reads the ref mirrors, never React
    // state, so the sweep is O(sessions) with zero render impact. Lives in
    // this effect (not its own hook) so it shares the one atomic teardown
    // with every other subscription. The emitter gates before traversing or
    // serializing anything when telemetry is off. Keep the timer alive so a
    // late initializePerformance response can enable collection without
    // reattaching every session subscription.
    const memoryGaugeTimer = window.setInterval(() => {
      emitRendererMemoryGauges(
        refs.latestRuntimesRef.current,
        refs.seenUuidsRef.current,
      )
    }, MEMORY_GAUGE_INTERVAL_MS)
    const refreshWorktrees = (cwd: string | null | undefined): void => {
      // The reconciler owns failure/retry/coalescing. This listener intentionally
      // does not await decorative Git metadata and therefore cannot delay a
      // SessionFeed event or turn a failed probe into an unhandled rejection.
      void worktreeReconciler.refresh(cwd)
    }

    const quarantinesSessionFeed = (sessionId: string): boolean =>
      refs.latestRuntimesRef.current[sessionId]?.recoveryFailureCode ===
      'ownership-conflict'

    // WHY every SessionFeed channel is fenced, rather than only transcript
    // ingestion: session ids are renderer-chosen routing keys, not proof that
    // the backend process currently attached to that key belongs to this
    // workspace pane. A failed recovery can discover that another cwd/provider
    // already owns the id after a few feed messages have arrived. Accepting even
    // "harmless" lifecycle or screen events after that point can overwrite the
    // quarantined runtime, clear its warning, or expose another agent's content.
    // The conflict marker therefore acts as a fail-closed ownership fence until
    // a later recovery has positively validated both provider kind and cwd.

    const offStarted = feed.onSessionStarted(({ sessionId, sessionRunId, projectDir }) => {
      if (quarantinesSessionFeed(sessionId)) return
      updateRuntime(sessionId, {
        // A started event is the backend-lifetime boundary. Missing identity
        // must reset to unknown instead of retaining the predecessor's run id:
        // older recordings/remote transports intentionally make the field
        // optional, and attributing their successor to the previous process
        // would be a false join. Exit deliberately does NOT clear this field;
        // delayed observations still belong to the retired lifetime.
        sessionRunId: sessionRunId ?? null,
        projectDir,
        processStatus: 'started',
        processError: null,
      })
      const cwd = refs.stateRef.current.sessions[sessionId]?.cwd ?? projectDir
      refreshWorktrees(cwd)
      appendFeedDebug(sessionId, {
        layer: 'STATE',
        kind: 'session_started',
        summary: `session started${projectDir ? ` · ${projectDir}` : ''}`,
        data: { projectDir, sessionRunId: sessionRunId ?? null },
      })
    })

    const offInputReadiness = feed.onSessionInputReadiness(({ sessionId, input }) => {
      if (quarantinesSessionFeed(sessionId)) return
      setRuntimes(prev => {
        const current = prev[sessionId] ?? emptyRuntime()
        if (input.revision <= current.inputReadinessRevision) return prev
        // WHY revisions are compared in the renderer instead of trusting IPC
        // arrival order: a recovery snapshot is requested over invoke while
        // live readiness travels over the feed. Either can win the race. Main's
        // monotonic revision is the only ordering shared by both paths, so an
        // older seed must never disable (or enable) a newer provider verdict.
        return {
          ...prev,
          [sessionId]: appendFeedDebugLog(
            {
              ...current,
              inputReady: input.ready,
              inputReadinessRevision: input.revision,
              inputReadinessReason: input.reason ?? null,
              // Only restamped when the state actually changes, so a repeated
              // identical verdict does not keep resetting the clock and hide a
              // long stall behind a permanently small number.
              inputReadinessChangedAt:
                current.inputReady === input.ready && current.inputReadinessReason === (input.reason ?? null)
                  ? current.inputReadinessChangedAt
                  : Date.now(),
            },
            {
              layer: 'STATE',
              kind: 'input_readiness',
              summary: `input ${input.ready ? 'ready' : 'blocked'} · rev ${input.revision}`,
              data: { revision: input.revision, reason: input.reason ?? null },
            },
          ),
        }
      })
    })

    const offScreen = feed.onSessionScreen(
      ({ sessionId, plain, markdown, recent, recentMarkdown }) => {
        if (quarantinesSessionFeed(sessionId)) return
        const startedAt = performance.now()
        // WHY only the screen strings are applied here (#762): frames now
        // arrive only while a debug surface holds a screen lease, so this
        // handler feeds DebugPanel and the dev modules, nothing live. The
        // frame's `picker` is NOT written: the composer's slash picker is
        // owned by the conditions channel (applyConditionSnapshot), and a
        // second writer here was split authority that could re-show a
        // picker the conditions had just cleared. The Enter-baseline ref and
        // the screen-tail trace this used to feed are gone: the baseline was
        // dead code, and main records the trace from every frame.

        setRuntimes(prev => {
          const current = prev[sessionId] ?? emptyRuntime()
          // Screen snapshots fire continuously (CC redraws its TUI
          // at ~60Hz) but the actual text is usually identical
          // between frames — CC is redrawing chrome, cursor, or a
          // spinner that our parser already strips. Without a
          // bail-out, every idle frame triggers a new `runtimes`
          // state → useWorkspace re-render → TileTree/TileLeaf
          // reconcile → Feed.memo check (which does then skip, but
          // reconciliation to that point isn't free). Comparing
          // strings by reference first, then by value, and bailing
          // before setState entirely saves that whole pass on
          // every no-op frame. This is the difference between
          // "scheduled work on every frame" and "scheduled work
          // only when the screen actually changed".
          if (current.screen === plain && current.recentScreen === recent) {
            const durationMs = performance.now() - startedAt
            if (durationMs > 8) {
              perf.metric('workspace.ipc.screen.noop.slow', durationMs, 'sample', {
                sessionId,
                recentLength: recent.length,
              })
            }
            return prev
          }
          const changed: string[] = []
          if (current.screen !== plain) changed.push('screen')
          if (current.recentScreen !== recent) changed.push('recent')
          // Screen frames can differ only by transient TUI chrome
          // (cursor blink, spinner tick, timestamp) while the
          // visible transcript is unchanged. We still commit the
          // latest strings so DebugPanel/ReaderView stay faithful,
          // but skip the debug-log append for this shape of frame
          // to keep feed-debug readable.
          //
          // WHY markdown is intentionally absent from the no-op and changed-key
          // gates above: `screenMarkdown` / `recentScreenMarkdown` are debug
          // surfaces derived from the same provider snapshot as the plain
          // strings. The live UI is driven by `plain`/`recent`; if those are
          // identical, scheduling a workspace-wide runtime update solely because
          // the markdown projection changed would spend 60Hz render budget on
          // debug-only fields. We still store markdown whenever a plain frame
          // changes so debug bundles remain faithful; we just do not make it a
          // separate invalidation source.
          const chromeTickOnly =
            changed.every(k => k === 'screen' || k === 'recent') &&
            changed.length > 0 &&
            recent.length === current.recentScreen.length

          const nextBody = {
            ...current,
            screen: plain,
            screenMarkdown: markdown,
            recentScreen: recent,
            recentScreenMarkdown: recentMarkdown,
            // activityStatus is owned by the process-state IPC
            // handler below — it carries the provider-correct verb
            // (Claude's spinner verb, Codex's bottom-row text).
            // Recomputing it here from `detectActivity(plain)` was
            // Claude-specific and would overwrite Codex's status
            // with null on every frame, racing the process-state
            // writer.
          }
          const nextCurrent = chromeTickOnly
            ? nextBody
            : appendFeedDebugLog(
                nextBody,
                {
                  layer: 'STATE',
                  kind: 'screen_update',
                  summary: `screen update · ${changed.join(', ')}`,
                  data: {
                    changed,
                    recentLength: recent.length,
                  },
                },
              )
          const durationMs = performance.now() - startedAt
          if (durationMs > 8) {
            perf.metric('workspace.ipc.screen.apply.slow', durationMs, 'sample', {
              sessionId,
              changed,
              recentLength: recent.length,
            })
          }
          return {
            ...prev,
            [sessionId]: nextCurrent,
          }
        })
      },
    )

    // The singular session:jsonl-entry IPC handler used to live
    // here. It owned: codex providerSessionId capture, codex
    // approval request/resolve, claude queue-operation
    // bookkeeping, claude providerSessionId capture,
    // condition snapshot updates and the entry append itself.
    //
    // It caused the bootstrap-replay cascade. On a resume Claude /
    // Codex emits ~200 jsonl-entry events synchronously; main used
    // to dual-emit those as 200 separate session:jsonl-entry IPC
    // sends PLUS one coalesced session:jsonl-entries burst. The
    // 200 singular messages always reached the renderer first
    // (they were enqueued first), and the singular handler did 200
    // separate setRuntimes calls — one full re-render per entry,
    // plus the auto-scroll pin and lazy-mount cascade per entry.
    // By the time the bulk message arrived, every uuid was already
    // in seenUuidsRef and the bulk path no-op'd — the bootstrapping
    // flag never asserted.
    //
    // The fix: drop the singular IPC emit on main entirely (see
    // main/sessions/forwarder.ts); make the bulk handler below own
    // every side-effect that used to live here. Live single
    // entries arrive as 1-element bursts with ~1ms setImmediate
    // latency.
    //
    // If you need to re-introduce a single-entry consumer, route
    // it through the bulk channel as a 1-element burst. Do NOT add
    // a second IPC channel that races the bulk one.

    const offErr = feed.onSessionJsonlError(({ sessionId, message }) => {
      if (quarantinesSessionFeed(sessionId)) return
      flushSemanticEventQueue()
      // eslint-disable-next-line no-console
      console.warn(`[jsonl ${sessionId.slice(0, 8)}]`, message)
      // Pi's bridge never connected. The durable transcript keeps working
      // (it is read from Pi's file), so this is not a transcript error. It is
      // a live-channel warning that must outlast the next row and clear only
      // when the bridge connects (the diagnostic handler below).
      if (message.includes(PI_BRIDGE_UNREACHABLE)) {
        updateRuntime(sessionId, { liveChannelWarning: message })
        return
      }
      // These adapter diagnostics name a channel that cannot recover by
      // loading a snapshot. Electron preserves the message, not Error.code.
      // The nonfatal durable diagnostics deliberately remain transient:
      // sink delivery can recover, and exit-drain exhaustion ends the backend.
      //
      // #1114 adds two more, and they matter because NOTHING ever clears a
      // lifetime banner (see the gate below, which only matches
      // provider_server_unreachable). `db_path_retrying` names a lookup that is
      // still being retried — a pane that then heals must not stay marked
      // broken, in this banner, in Agent Status, and in the
      // `transcript_unavailable` every orchestration parent reads. And
      // `db_path_recovered_late` reports a channel that IS working, just with a
      // hole in what it caught; calling that "stopped" would be false.
      // `db_path_unavailable` keeps its #864 AC8 meaning — permanent — and is
      // now only emitted when the retry ladder is spent and that is true.
      const channelStopped = message.startsWith('OpenCode durable channel (')
        && !message.includes('(sink_failed)')
        && !message.includes('(final_drain_incomplete)')
        && !message.includes('(db_path_retrying)')
        && !message.includes('(db_path_recovered_late)')
      const sessionSwitched = message.includes('(provider_session_switched)')
      // #881. The TUI's server never came up — its port was taken between our
      // loopback probe and its bind. The pane cannot be re-pointed at another
      // port, and the process neither paints nor exits, so this is as
      // permanent as a stopped channel and belongs in the lifetime banner: the
      // alternative is a blank pane with a warning that scrolled away.
      const serverUnreachable = message.includes(OPENCODE_SERVER_UNREACHABLE)
      updateRuntime(sessionId, {
        transcriptStatus: 'error',
        transcriptError: message,
        ...((channelStopped || sessionSwitched || serverUnreachable) ? { transcriptChannelError: message } : {}),
      })
      // #1117. The late-opened channel is positioned at the database's
      // current head, so everything the TUI committed while the path was
      // unavailable counts as already seen and is never emitted. The package
      // cannot heal that — it cannot tell a dark-window row from last week's —
      // but a history read can: it admits only uuids this pane does not hold
      // and places them in order around the rows it does (placeHistoryEntries).
      // So the reload the message asks the user for is done here, once, the
      // moment the channel is readable again. A load that succeeds writes
      // `ready` over this error (nothing set the lifetime banner above).
      //
      // WHY a failed heal raises the LIFETIME banner (#1229 review): the load
      // writes its own error, but the next committed row on this now-working
      // channel writes `ready` over any error that is not a channel error, so
      // the pane went back to looking whole while the rows committed in the
      // dark window were still missing. They stay missing until the user
      // reloads, which is exactly what this message says, so it is the one
      // that must stand.
      if (message.includes('(db_path_recovered_late)')) {
        void loadInitialHistoryForSession({ sessionId, refs, setRuntimes }).then(healed => {
          if (healed) return
          // Only onto a pane that still exists: updateRuntime would create an
          // orphan runtime for one closed while the heal was in flight.
          setRuntimes(prev => {
            const current = prev[sessionId]
            if (!current) return prev
            return {
              ...prev,
              [sessionId]: { ...current, transcriptStatus: 'error', transcriptError: message, transcriptChannelError: message },
            }
          })
        })
      }
    })

    // #881. The one diagnostic the renderer acts on, and the reason the
    // channel is subscribed at all.
    //
    // `server-unreachable` is a DEADLINE verdict, not a death certificate: the
    // package keeps reconnecting for the life of the instance, so a TUI whose
    // server was merely late — a cold start, a restore herd, a sleep/wake
    // straddling the 30 s connect deadline — connects afterwards and works.
    // The banner that says otherwise is a lifetime banner by design, and
    // nothing else ever clears one: a pane that recovered kept telling the
    // user to reload it, and `managedTranscriptUnavailableReason` kept
    // answering `transcript_unavailable` to every parent agent reading that
    // child, over a conversation that was intact.
    //
    // Narrow on purpose: only a live-state that says CONNECTED, and only over
    // an error this same fault raised. Any other transcript error is somebody
    // else's to clear.
    const offDiagnostic = feed.onSessionTranscriptDiagnostic(({ sessionId, diagnostic }) => {
      if (quarantinesSessionFeed(sessionId)) return
      // Which fault this diagnostic proves recovered is the shared rule the
      // phone applies too (session-runtime/liveChannelRecovery.ts, #1177).
      const recovered = faultRecoveredByDiagnostic(diagnostic)
      // Pi's bridge is the same kind of late-connecting live channel, but its
      // "never connected" warning lives in liveChannelWarning (its transcript
      // still works), and it clears the moment the bridge connects.
      if (recovered === PI_BRIDGE_UNREACHABLE) {
        if (refs.latestRuntimesRef.current[sessionId]?.liveChannelWarning) updateRuntime(sessionId, { liveChannelWarning: null })
        return
      }
      if (recovered === null) return
      const current = refs.latestRuntimesRef.current[sessionId]
      if (!current?.transcriptChannelError?.includes(recovered)) return
      updateRuntime(sessionId, {
        transcriptChannelError: null,
        transcriptError: null,
        // Back to the state a pane with no transcript fault has. The next
        // history load or record batch decides `ready` vs `loading` as usual;
        // what matters here is that the sticky override is gone.
        transcriptStatus: 'ready',
      })
    })

    const offProviderSessionChanged = feed.onSessionProviderSessionChanged(({ sessionId, providerSessionId }) => {
      if (quarantinesSessionFeed(sessionId)) return
      // The pane follows its runtime into another provider session (Pi /new,
      // /resume, /fork). Rebind the durable identity, and forget the burst
      // gate's expectation for the old id so the new session's rows are
      // judged against the new one. The conversation itself is replaced by
      // the history-boundary reset that follows this event.
      setState(prev => {
        const meta = prev.sessions[sessionId]
        if (!meta) return prev
        const next = applyProviderSessionSwitch(meta, providerSessionId)
        if (!next) return prev
        return { ...prev, sessions: { ...prev.sessions, [sessionId]: next } }
      })
      jsonlProviderStreamBySession.delete(sessionId)
    })

    const offHistoryBoundary = feed.onSessionHistoryBoundary(({ sessionId, ...boundary }) => {
      if (quarantinesSessionFeed(sessionId)) return
      // Same ordering discipline as the jsonl bulk and exit boundaries: a
      // queued delta crossing the reset would repaint the wiped window after
      // the reset applied, so flush the compact semantic queue first.
      flushSemanticEventQueue()
      // The shared pure owner decides; this hook only applies. See
      // session-runtime/historyBoundary.ts for every rule.
      const windows = refs.historyWindowsRef.current
      const window = (windows[sessionId] ??= emptyHistoryWindow())
      const decision = decideHistoryBoundary(window, boundary)
      windows[sessionId] = applyDecisionToWindow(window, decision)
      if (decision.kind !== 'apply-reset') return
      // Apply the reset: the superseded generation's committed rows, dedup
      // set, history cursor and live turn state all go; conditions, busy
      // state and exit state survive (the shared preserve list — a transcript
      // rewrite is not a process death). Semantic suffixes wait for a fresh
      // turn_started via the gate in handleSemanticEvent.
      refs.seenUuidsRef.current[sessionId] = new Set()
      // The trimmed-uuid ledger shares the dedup set's lifecycle
      // (liveEntryWindow.ts: trimmed ⊆ ever-seen). The live path rejects
      // seen ∪ trimmed, so keeping it past this reset dropped every replayed
      // row the old window had trimmed: a Pi /tree back to an early branch
      // of a long conversation came back with gaps (Astra review, finding 2).
      // The entries are wiped below, so there is nothing trimmed left to page.
      clearLiveEntryWindowSession(sessionId)
      refs.historyAwaitingTurnStartRef.current.add(sessionId)
      codexCurrentTurnIdBySession.delete(sessionId)
      jsonlProviderStreamBySession.delete(sessionId)
      setRuntimes(prev => {
        const current = prev[sessionId] ?? emptyRuntime()
        const next = withDerivedSessionStatus({
          ...current,
          entries: [],
          totalEntries: 0,
          historyOldestMarker: null,
          queuedMessages: [],
          semantic: { ...current.semantic, currentTurn: null },
        })
        return { ...prev, [sessionId]: next }
      })
    })

    const offExit = feed.onSessionExit(({ sessionId, exitCode }) => {
      if (quarantinesSessionFeed(sessionId)) return
      flushSemanticEventQueue()
      worktreeReconciler.forgetSession(sessionId)
      claudeQueueBySession.delete(sessionId)
      codexCurrentTurnIdBySession.delete(sessionId)
      jsonlProviderStreamBySession.delete(sessionId)
      setRuntimes(prev => {
        const current = prev[sessionId] ?? emptyRuntime()
        const sessionKind = refs.stateRef.current.sessions[sessionId]?.kind
        const observedCurrent = sessionKind === 'codex'
          ? appendQueuedSubmissionReleases(
              current,
              current.queuedMessages,
              'session-exit',
            )
          : current
        const next = withDerivedSessionStatus(
          appendFeedDebugLog(
            {
              ...observedCurrent,
              exited: exitCode,
              awaitingAssistant: false,
              queuedMessages: [],
              activityStatus: null,
              processActive: false,
              processStatus: 'exited',
              processError: null,
              // WHY terminalForeground is also cleared on exit (M3): main DOES
              // untrack the session on exit — the terminal exit handler
              // (main/sessionManager.ts ~3110) calls cleanupSessionState,
              // which calls this.terminalForeground.untrack(sessionId) (~903)
              // — but that clears a SEPARATE structure: TerminalForegroundMonitor's
              // own `last`-emitted map, which only decides when main should
              // emit at all. It says nothing about this renderer-side runtime
              // field, a second independent copy that applyTerminalForeground
              // (session-runtime/terminalForeground.ts ~42) diffs every new
              // sample against. Left uncleared, a same-id respawn's first
              // (idle) sample would be compared against the dead
              // predecessor's stale `busy: true` sitting here — busy
              // genuinely differs, so that is NOT a suppressed no-op, it is a
              // real busy→idle transition, and applyTerminalForeground fires
              // withUnread on it: a SPURIOUS "new work" mark on a pane where
              // nothing actually happened, the shell just started. Clearing
              // it here also stops a dead shell's last command (e.g. `npm`)
              // from lingering as a badge with no live process left to
              // correct it.
              terminalForeground: null,
              inputReady: false,
              // Restamped on exit for the same reason as every other readiness
              // write: without it the pane would report how long ago the DEAD
              // backend became ready.
              inputReadinessReason: null,
              inputReadinessChangedAt: Date.now(),
              // Clear phase on exit. The WorkIndicator renders
              // nothing for `idle`; letting a pre-exit phase
              // linger would leave the in-feed indicator saying
              // e.g. "Awaiting Bash" on a dead session. Matching
              // the existing activityStatus null.
              streamPhase: 'idle',
              streamPhasePendingToolName: null,
              streamPhasePendingToolUseId: null,
              turnStartedAt: null,
              phaseChangedAt: null,
              submittedAt: null,
              semantic: {
                ...current.semantic,
                currentTurn: null,
              },
              // Hard lifecycle boundary: a dead process cannot own live provider
              // prompts. Clear the condition snapshot, slash picker, and the
              // legacy pending* mirrors together so no stale approval/trust/
              // permission/resume/compaction overlay survives the exit and so the
              // pane is not held in Hybrid display purely by a non-null snapshot.
              // (conditions audit Finding 2 / roadmap E7)
              ...clearConditionRuntimeState(),
            },
            {
              layer: 'STATE',
              kind: 'session_exit',
              summary: `session exited code=${exitCode}`,
              data: { exitCode },
            },
          ),
        )
        return { ...prev, [sessionId]: next }
      })
    })

    // Provider-emitted activity state. Both providers now derive
    // this from their own screen spinner detector — Claude's
    // rotating-glyph line, Codex's bottom "Working (...)" row —
    // and forward the verb/status string alongside the boolean.
    // When status arrives we adopt it directly; the renderer used
    // to redundantly run Claude's detectActivity on every screen
    // frame to derive the verb, which was both wasteful and wrong
    // for Codex (the parser is Claude-specific). On idle
    // transitions, status is undefined and we clear activityStatus
    // too.
    const offProcessState = feed.onSessionProcessState(
      ({ sessionId, active, status }) => {
        if (quarantinesSessionFeed(sessionId)) return
        flushSemanticEventQueue()
        setRuntimes(prev => {
          const current = prev[sessionId] ?? emptyRuntime()
          const sessionKind = refs.stateRef.current.sessions[sessionId]?.kind
          const shouldClearIdleQueue = shouldClearIdleQueuedMessages({
            awaitingAssistant: false,
            processActive: active,
            provider: sessionKind,
            queuedMessagesLength: current.queuedMessages.length,
            streamPhase: current.streamPhase,
          })
          const observedCurrent = shouldClearIdleQueue && sessionKind === 'codex'
            ? appendQueuedSubmissionReleases(
              current,
              current.queuedMessages,
              'process-idle',
            )
            : current
          const next = withDerivedSessionStatus(
            appendFeedDebugLog(
              {
                ...observedCurrent,
                processActive: active,
                processStatus: current.exited === null ? 'started' : current.processStatus,
                processError: null,
                activityStatus: active ? (status ?? null) : null,
                awaitingAssistant: false,
                queuedMessages: shouldClearIdleQueue
                  ? []
                  : current.queuedMessages,
              },
              {
                layer: 'STATE',
                kind: 'process_state',
                summary: active
                  ? `process active${status ? ` · ${status}` : ''}`
                  : shouldClearIdleQueue
                    ? 'process idle · cleared stale local queue'
                    : 'process idle',
                data: {
                  active,
                  status: status ?? null,
                  clearedQueuedMessages: shouldClearIdleQueue
                    ? current.queuedMessages.length
                    : 0,
                },
              },
            ),
          )
          return { ...prev, [sessionId]: next }
        })
      },
    )

    const handleSemanticEvent = (
      { sessionId, event }: SessionSemanticEvent,
      rawEventCount = 1,
    ): void => {
      // Re-check at fold time as well as enqueue time. A delta can be queued
      // immediately before recovery discovers an ownership conflict; letting
      // that queued payload through afterward would punch a hole in the fence.
      if (quarantinesSessionFeed(sessionId)) return
      // The shared history-boundary gate (grok Stage 5): after an applied
      // reset the window was wiped, and a stale semantic suffix from the
      // superseded generation must not repaint it. A fresh turn_started
      // reopens the fold; api_error passes because it is diagnostic.
      {
        const awaiting = refs.historyAwaitingTurnStartRef.current
        if (awaiting.has(sessionId)) {
          const type = (event as { type?: unknown })?.type
          if (type === 'turn_started') awaiting.delete(sessionId)
          else if (type !== 'api_error') return
        }
      }
      const span = perf.span('workspace.ipc.semantic.fold', { sessionId })
      let spanClosed = false
      const closeSpan = (data: Record<string, unknown>) => {
        if (spanClosed) return
        spanClosed = true
        span.end({ ...data, rawEventCount })
      }
      if (isResponseOutput(event)) noteMonitorOutput(sessionId)
      const semanticEvent = asRecord(event) ?? {}
      const observedProvider = providerSessionObservedEvent(event)
      if (observedProvider) {
        setState(prev => {
          const meta = prev.sessions[sessionId]
          if (!meta) return prev
          if (meta.providerSessionId) return prev
          return {
            ...prev,
            sessions: {
              ...prev.sessions,
              [sessionId]: {
                ...meta,
                providerSessionId: observedProvider.providerSessionId,
                providerSessionIdSource: 'proxy-header',
              },
            },
          }
        })
        setRuntimes(prev => {
          const current = prev[sessionId] ?? emptyRuntime()
          // No disconnect verdict here (#290). The first proxy header of a
          // fresh pane arrives before Claude has written a single JSONL line,
          // so "no committed entries yet" is the normal state at this moment;
          // judging it here alarmed on every new pane, which is why the old
          // predicate refused 'ready' and so could never fire in the real
          // broken state either. The verdict is made after a completed turn
          // plus a grace: see `scheduleTranscriptCommitCheck`.
          const next = appendFeedDebugLog(current, {
            layer: 'SEM',
            kind: 'provider_session_observed',
            summary: 'provider session observed',
            data: observedProvider,
          })
          return { ...prev, [sessionId]: next }
        })
        closeSpan({
          sessionId,
          eventType: 'provider_session_observed',
          changed: true,
        })
        return
      }
      // ---- Usage-limit signal (#821), the live channel ----
      // Codex reports an exhausted subscription window as an `api_error` with
      // `errorType: 'usage_limit_reached'` — classified in codex-headless
      // precisely so it is distinguishable from a plain retryable 429 (see
      // packages/codex-headless/src/channels/types.ts). The conversation stays
      // open afterward, so this event is the only thing that separates "the
      // agent is thinking" from "the agent cannot think until 14:32".
      //
      // Computed outside the updater for the same reason as the JSONL path: one
      // Date.now() per event, not one per React re-invocation.
      //
      // The event's own `ts` wins when it is a wall clock. Unlike the JSONL
      // path this is a LIVE event, never a replay, so `Date.now()` is a correct
      // fallback rather than a lie — but the event's own time is still better,
      // because a backpressured queue can hold an event for a while before it
      // is folded. The plausibility floor exists because `ts` is only typed
      // `number`: a provider (or a test) that emits a small relative counter
      // would otherwise write `limitHit.at = 3`, which loses every comparison
      // against `turnStartedAt` and silently disarms the guard's exception.
      const semanticLimitHitAt =
        semanticEvent.type === 'api_error' && semanticEvent.errorType === 'usage_limit_reached'
          ? (typeof semanticEvent.ts === 'number' && semanticEvent.ts >= WALL_CLOCK_MS_FLOOR
              ? semanticEvent.ts
              : Date.now())
          : null
      // Captured by the updater, committed after setRuntimes returns.
      let pendingStaleQueue: ClaudeQueueState | null = null
      setRuntimes(prev => {
        const current = prev[sessionId] ?? emptyRuntime()
        // WHY `?? DEFAULT_PROVIDER` default: Claude is the pre-fix
        // behavior (auto-replace / self-heal on turnId mismatch).
        // Falling back to the looser behavior during a
        // teardown-race where the session meta is momentarily
        // absent avoids silently dropping events we'd actually
        // want to keep. See
        // docs/superpowers/plans/2026-04-17-claude-semantic-provider-gating.md.
        const sessionKind = refs.stateRef.current.sessions[sessionId]?.kind ?? DEFAULT_PROVIDER

        // Fold + stream phase through the step the phone runs too (#1177;
        // session-runtime/ingest/liveSemantic.ts owns the order and the
        // out-of-band routing). The stream_phase reducer is the SHARED machine
        // in semantic/streamPhaseMachine.ts (extracted 2026-07-06 so the remote
        // phone client runs the identical reducer instead of a hand-copied
        // fork), run on the POST-fold turn per its caller contract.
        const step = stepLiveSemantic(
          current.semantic,
          {
            streamPhase: current.streamPhase,
            streamPhasePendingToolName: current.streamPhasePendingToolName,
            streamPhasePendingToolUseId: current.streamPhasePendingToolUseId,
            turnStartedAt: current.turnStartedAt,
            phaseChangedAt: current.phaseChangedAt,
            submittedAt: current.submittedAt,
          },
          semanticEvent,
          sessionKind,
          current.sessionRunId,
        )

        // prompt_suggestion is an ephemeral next-prompt hint, NOT a turn. It
        // must never enter foldSemanticEvent / semantic history (that is the
        // #174 leak). The shared step refuses to fold it; the desktop applies
        // it out-of-band to the per-session chip and returns before the turn
        // / ghost / phase machinery runs.
        if (step.kind === 'out-of-band') {
          const updated = applyPromptSuggestionToRuntime(current, semanticEvent)
          if (updated === current) {
            closeSpan({ sessionId, eventType: 'prompt_suggestion', changed: false })
            return prev
          }
          closeSpan({ sessionId, eventType: 'prompt_suggestion', changed: true })
          return { ...prev, [sessionId]: updated }
        }

        const nextSemantic = step.semantic
        const eventType = typeof semanticEvent.type === 'string' ? semanticEvent.type : ''
        const clearOptimisticAwaiting =
          isSemanticTurnRunning(nextSemantic.currentTurn) ||
          eventType === 'turn_completed' ||
          eventType === 'turn_stopped' ||
          eventType === 'api_error' ||
          eventType === 'stream_error'

        // stream_phase — in-feed indicator state, already reduced by the
        // shared step above on the POST-fold turn.
        const {
          streamPhase,
          streamPhasePendingToolName,
          streamPhasePendingToolUseId,
          turnStartedAt,
          phaseChangedAt,
          submittedAt,
        } = step.phase

        // Ghost bridge — refresh the provisional ghost map from
        // the new semantic turn. This runs on every semantic tick;
        // `ghostsFromSemanticTurn` is idempotent and
        // reference-stable so no-op ticks (e.g. usage_updated
        // events) do not churn the map. See
        // docs/design/ghost-system.md for the canonical explanation.
        //
        // WHY here and not inside `foldSemanticEvent`:
        //   foldSemanticEvent is intentionally agnostic to
        //   SessionRuntime — it reduces the SemanticRuntimeState
        //   sub-slice and knows nothing about sessionId or the
        //   outer runtime. The ghost map lives on SessionRuntime
        //   because it needs to survive across semantic history
        //   archival (when `currentTurn` flips to null). Calling the
        //   ghost reducer at this
        //   outer boundary keeps the layering clean.
        const nextGhosts = ghostsFromSemanticTurn(
          nextSemantic.currentTurn,
          sessionId,
          current.ghosts,
        )

        // Full no-op short-circuit. foldSemanticEvent now returns
        // `state` unchanged for events that didn't mutate semantic
        // state; the ghost and phase paths are reference-stable
        // after the 2026-04-20 fixes. If all six signals agree
        // this event changed nothing and we're not clearing an
        // optimistic wait, bail out before appendFeedDebugLog to
        // avoid the SEM log noise bootstrap tool_results produced
        // in the evidence timeline (id:1-8). See 2026-04-20
        // rendering-fixes Task 8.
        const semanticUnchanged = nextSemantic === current.semantic
        const phaseUnchanged =
          streamPhase === current.streamPhase &&
          streamPhasePendingToolName === current.streamPhasePendingToolName &&
          streamPhasePendingToolUseId === current.streamPhasePendingToolUseId &&
          turnStartedAt === current.turnStartedAt &&
          phaseChangedAt === current.phaseChangedAt &&
          submittedAt === current.submittedAt
        const ghostsUnchanged = nextGhosts === current.ghosts
        const awaitingUnchanged = clearOptimisticAwaiting
          ? current.awaitingAssistant === false
          : true
        const nextAwaitingAssistant = clearOptimisticAwaiting
          ? false
          : current.awaitingAssistant
        const shouldClearIdleQueue = shouldClearIdleQueuedMessages({
          awaitingAssistant: nextAwaitingAssistant,
          processActive: current.processActive,
          provider: sessionKind,
          queuedMessagesLength: current.queuedMessages.length,
          streamPhase,
        })
        const observedCurrent = shouldClearIdleQueue && sessionKind === 'codex'
          ? appendQueuedSubmissionReleases(
            current,
            current.queuedMessages,
            'semantic-idle',
          )
          : current

        // Claude's counterpart to the idle CLEAR above: mark, never delete.
        // The optimistic-echo providers own their queue rows locally, so
        // clearing is safe for them; Claude's queue is provider-owned and its
        // unattributable residue (chiefly the unlogged `clearCommandQueue()`)
        // can only be surfaced, not resolved. Same idle signal, opposite and
        // deliberately weaker action.
        //
        // Only marks an EXISTING reconciler state. A session with no map entry
        // has no queue to mark, and an earlier version defaulted to a freshly
        // created state and compared it against `undefined` — which read as
        // "changed" on every idle event, wiping queuedMessages to the empty
        // pending list and defeating the no-op bail below.
        const existingQueue = claudeQueueBySession.get(sessionId)
        const claudeQueueIdle =
          sessionKind === 'claude' &&
          existingQueue !== undefined &&
          !current.processActive &&
          streamPhase === 'idle' &&
          !nextAwaitingAssistant
        const markedQueue =
          claudeQueueIdle && existingQueue ? markStaleWhenIdle(existingQueue, true) : null
        // markStaleWhenIdle is reference-stable, so identity is the change test.
        const staleChanged = markedQueue !== null && markedQueue !== existingQueue
        if (staleChanged) pendingStaleQueue = markedQueue

        // A completed turn is the one unambiguous proof that the limit episode
        // is over: the provider answered. `turn_stopped` deliberately does NOT
        // clear it — a turn can stop precisely BECAUSE the limit was hit, and
        // clearing there would erase the signal in the same tick it arrived.
        //
        // `turn_started` clears it too, and that is the fix for a pane the
        // guard would otherwise get killed. A Claude pane that hit a limit and
        // then auto-continues once the window resets keeps its ORIGINAL
        // `turnStartedAt` — `streamPhaseMachine` only assigns that field when
        // it is null (semantic/streamPhaseMachine.ts, the `turnStartedAt ===
        // null` guards), so the timestamp still belongs to the turn that hit
        // the limit, and it is necessarily OLDER than `limitHit.at`. With
        // `limitHit` still armed, `isLimitIdle` therefore keeps reading true
        // while Claude is busy answering again, the switch modal labels the
        // pane idle, and switching kills a live turn — the one thing the
        // exception was written not to do.
        //
        // A turn the provider ACCEPTED is proof enough: the request got past
        // the limit. It is weaker proof than a completed turn (the request
        // could still 429 mid-flight), which is exactly why this is safe — a
        // fresh 429 re-arms `limitHit` with a newer `at`, and that timestamp
        // now beats the same stale `turnStartedAt` again.
        //
        // Same value comparison as the JSONL path: a redelivered event carries
        // the same `ts`, so it must not manufacture a runtime change.
        const nextLimitHit: SessionRuntime['limitHit'] =
          semanticLimitHitAt !== null
            ? (current.limitHit?.at === semanticLimitHitAt && current.limitHit.source === 'api_error'
                ? current.limitHit
                : { at: semanticLimitHitAt, source: 'api_error' })
            : eventType === 'turn_completed' || eventType === 'turn_started'
              ? null
              : current.limitHit
        const limitHitChanged = nextLimitHit !== current.limitHit

        if (
          semanticUnchanged &&
          phaseUnchanged &&
          ghostsUnchanged &&
          awaitingUnchanged &&
          !shouldClearIdleQueue &&
          !staleChanged &&
          !limitHitChanged
        ) {
          closeSpan({
            sessionId,
            eventType: eventType || 'semantic',
            changed: false,
          })
          return prev
        }

        const nextCurrent = withDerivedSessionStatus(
          appendFeedDebugLog(
            {
              ...observedCurrent,
              awaitingAssistant: nextAwaitingAssistant,
              queuedMessages: shouldClearIdleQueue
                ? []
                : staleChanged && markedQueue
                  ? markedQueue.pending
                  : current.queuedMessages,
              // A suggestion is an offer about the NEXT input; once a new
              // turn begins it is stale, so clear it on turn_started. The
              // chip's apply/dismiss/submit paths clear it directly too.
              promptSuggestion:
                eventType === 'turn_started' ? null : current.promptSuggestion,
              semantic: nextSemantic,
              streamPhase,
              streamPhasePendingToolName,
              streamPhasePendingToolUseId,
              turnStartedAt,
              phaseChangedAt,
              submittedAt,
              ghosts: nextGhosts,
              limitHit: nextLimitHit,
            },
            {
              layer: 'SEM',
              kind: eventType || 'semantic',
              summary: shouldClearIdleQueue
                ? `${summarizeSemanticEventForDebug(semanticEvent)} · cleared stale local queue`
                : summarizeSemanticEventForDebug(semanticEvent),
              // Raw-payload compaction (#375 part C): this used to store
              // the ENTIRE raw semantic event per SEM row — at
              // FEED_DEBUG_LOG_CAP=500 rows/session, one of the largest
              // steady-state heap slabs the investigation found. The
              // `summary` above already carries the human-readable digest;
              // the full payload only earns its heap when someone is
              // actively debugging, so it rides the same dev-debug flag as
              // the semantic.log raw capture (see rawCapture.ts).
              data: {
                eventType: eventType || 'semantic',
                ...(shouldClearIdleQueue
                  ? { clearedQueuedMessages: current.queuedMessages.length }
                  : {}),
                ...(isSemanticRawCaptureEnabled() ? { event: semanticEvent } : {}),
              },
            },
          ),
        )
        const finishedTurn =
          eventType === 'turn_completed' || eventType === 'turn_stopped'
        const nextCurrentWithUnread = finishedTurn
          ? withUnread(nextCurrent, 'output')
          : nextCurrent
        return {
          ...prev,
          [sessionId]: nextCurrentWithUnread,
        }
      })
      // Same rule as the burst path: the map is committed after setRuntimes
      // returns, never from inside it. Writing the stale marks inside the
      // updater meant a re-invocation read its own write, computed
      // staleChanged=false, and hit the `return prev` bail — silently
      // discarding that event's ENTIRE semantic update (fold, stream phase,
      // ghosts) while the map recorded the items as already marked, so no
      // later tick re-marked them.
      if (pendingStaleQueue !== null) {
        claudeQueueBySession.set(sessionId, pendingStaleQueue)
      }
      if (semanticEvent.type === 'turn_completed') scheduleTranscriptCommitCheck(sessionId)
      closeSpan({
        sessionId,
        eventType: typeof semanticEvent.type === 'string' ? semanticEvent.type : 'semantic',
        processed: true,
      })
    }

    const semanticEventQueue = new SemanticEventBackpressureQueue()
    let semanticFlushTimer: number | null = null
    /**
     * Pending "did this turn ever commit?" checks, one per session (#290).
     *
     * WHY at the end of a TURN and after a grace period: Claude writes its
     * JSONL as the turn happens (the user row at submit, assistant rows as
     * blocks finish), so by `turn_completed` a healthy pane has entries. A
     * pane that has finished a turn, waited TRANSCRIPT_COMMIT_GRACE_MS more,
     * and still has zero entries and no durable transcript id is the recorded
     * #290 state: live streaming, nothing durable, a resume that will find
     * nothing. The grace absorbs the tail watcher's latency; the first
     * arriving record resets the status to 'ready' on its own, so a slow
     * transcript clears the banner instead of leaving it stuck.
     *
     * One pending check per session (the first completed turn starts the
     * clock; later turns do not push it back), cleared on unmount.
     */
    const transcriptCommitChecks = new Map<SessionId, number>()
    const scheduleTranscriptCommitCheck = (sessionId: SessionId): void => {
      if (transcriptCommitChecks.has(sessionId)) return
      const meta = refs.stateRef.current.sessions[sessionId]
      // Claude only: the proxy-header provisional identity this guards is a
      // Claude mechanism, and other providers commit on their own schedules.
      if (!meta || (meta.kind ?? 'claude') !== 'claude') return
      transcriptCommitChecks.set(sessionId, window.setTimeout(() => {
        transcriptCommitChecks.delete(sessionId)
        const current = refs.latestRuntimesRef.current[sessionId]
        const latestMeta = refs.stateRef.current.sessions[sessionId]
        // Re-checked at FIRE time too: a provider switch keeps the session id
        // and resets the runtime, so a Claude turn's pending check must not
        // put a Claude-worded warning on the Codex pane that replaced it.
        if (!latestMeta || (latestMeta.kind ?? 'claude') !== 'claude') return
        if (!current || !shouldMarkProviderSessionDisconnected(current, latestMeta)) return
        setRuntimes(prev => {
          const runtime = prev[sessionId]
          if (!runtime || !shouldMarkProviderSessionDisconnected(runtime, refs.stateRef.current.sessions[sessionId])) return prev
          const id = latestMeta?.providerSessionId
          return {
            ...prev,
            [sessionId]: appendFeedDebugLog(
              {
                ...runtime,
                transcriptStatus: 'disconnected',
                transcriptError:
                  `Claude finished a turn${id ? ` in session ${id}` : ''}, ` +
                  'but no committed JSONL transcript has arrived. This conversation may not resume.',
              },
              {
                layer: 'SEM',
                kind: 'transcript_never_committed',
                summary: 'turn completed · no committed transcript after grace',
                data: { providerSessionId: id ?? null, graceMs: TRANSCRIPT_COMMIT_GRACE_MS },
              },
            ),
          }
        })
      }, TRANSCRIPT_COMMIT_GRACE_MS))
    }
    const flushSemanticEventQueue = (): void => {
      if (semanticFlushTimer !== null) {
        window.clearTimeout(semanticFlushTimer)
        semanticFlushTimer = null
      }
      for (const pending of semanticEventQueue.drain()) {
        handleSemanticEvent(pending.message, pending.rawEventCount)
      }
    }
    const scheduleSemanticEventFlush = (): void => {
      if (semanticFlushTimer !== null) return
      semanticFlushTimer = window.setTimeout(() => {
        semanticFlushTimer = null
        for (const pending of semanticEventQueue.drain()) {
          handleSemanticEvent(pending.message, pending.rawEventCount)
        }
      }, SEMANTIC_DELTA_FLUSH_MS)
    }
    const offSemantic = feed.onSessionSemanticEvent(message => {
      if (quarantinesSessionFeed(message.sessionId)) return
      if (semanticEventQueue.tryPush(message)) {
        scheduleSemanticEventFlush()
        return
      }

      // WHY structural events flush first: delaying only deltas is safe because
      // their snapshots supersede one another. Delaying block_completed,
      // tool_result, turn_completed, or error boundaries would reorder them
      // against process/JSONL channels and could resurrect already-finished
      // turns. Flush the compact latest state, then fold the boundary now.
      flushSemanticEventQueue()
      handleSemanticEvent(message, message.rawEventCount ?? 1)
    })

    const offConditions = feed.onSessionConditions(({ sessionId, snapshot }) => {
      if (quarantinesSessionFeed(sessionId)) return
      setRuntimes(prev => {
        const current = prev[sessionId] ?? emptyRuntime()
        const next = applyConditionSnapshot(current, snapshot)
        const conditionCount = Object.keys(snapshot.conditions).length
        // WHY this reads the condition snapshot, not the legacy pending* mirrors
        // (conditions audit Finding 5 + Additional B): the mirror-based check
        // silently EXCLUDED AskUserQuestion, so a backgrounded pane never went
        // unread when the agent was blocked on a question — the one prompt type
        // whose entire purpose is to collect user input. `conditionRequiresAttention`
        // is the single attention policy (visibility-aware, so it matches the old
        // mirror behavior for trust/resume/permission AND adds AUQ + codex
        // approval/trust). `current.conditions` is the pre-update snapshot and
        // `next.conditions` is the new one, so this still detects the no-attention
        // → attention transition the unread badge keys on.
        const hadAttention = conditionRequiresAttention(current.conditions)
        const hasAttention = conditionRequiresAttention(next.conditions)
        const logged = appendFeedDebugLog(
          next,
          {
            layer: 'STATE',
            kind: 'conditions',
            summary: `${snapshot.provider} conditions · ${conditionCount}`,
            data: snapshot,
          },
        )
        return {
          ...prev,
          [sessionId]: !hadAttention && hasAttention
            ? withUnread(logged, 'attention')
            : logged,
        }
      })
    })

    // Subagent fleet state. Main pushes the FULL per-session map on every
    // change (it's small — agentType/description + a capped tool-call
    // timeline), so we just replace the field wholesale. Reference-equal bail
    // keeps Feed from re-rendering when an unrelated session updates.
    const offSubAgents = feed.onSessionSubAgents(({ sessionId, subAgents }) => {
      if (quarantinesSessionFeed(sessionId)) return
      setRuntimes(prev => {
        const current = prev[sessionId] ?? emptyRuntime()
        if (current.subAgents === subAgents) return prev
        return { ...prev, [sessionId]: { ...current, subAgents } }
      })
    })

    // Bulk jsonl-entry path — the ONLY entry handler now that main
    // no longer dual-emits singular events. Folds a whole burst in
    // one setRuntimes + at most one setState, grows the tool
    // indices incrementally, and sets `bootstrapping = true` for
    // the duration so Feed can suspend per-append auto-scroll +
    // lazy-mount cascades. See the deleted-handler comment above
    // and docs/superpowers/plans/2026-04-15-bootstrap-replay-perf.md
    // for the full rationale.
    //
    // Side-effects absorbed from the old singular handler:
    //   1. Codex providerSessionId capture (from session_meta).
    //   2. Codex approval request / resolve now lives in codex-headless
    //      conditions; this handler only consumes entries/feed effects.
    //   3. Claude queue-operation bookkeeping (per entry).
    //   4. Claude providerSessionId capture (from any entry's sessionId).
    //   5. provider-owned durable compaction entries.
    //   6. Optimistic-Codex-user reconciliation against the head row.
    const offEntries = feed.onSessionJsonlEntries(({ sessionId, entries }) => {
      if (quarantinesSessionFeed(sessionId)) return
      if (!entries || entries.length === 0) return
      // JSONL/process/exit live on sibling SessionFeed channels but still form
      // ordering boundaries with semantic state. Letting a queued delta cross
      // one would make committed reconciliation or process shutdown observe an
      // older semantic turn, then apply the stale preview afterward. The queue
      // is already compact, so boundary flush cost is proportional to active
      // semantic owners rather than raw transport events.
      flushSemanticEventQueue()
      const span = perf.span('workspace.ipc.jsonl.bulk', {
        sessionId,
        burstSize: entries.length,
      })
      let spanClosed = false
      const closeSpan = (data: Record<string, unknown>) => {
        if (spanClosed) return
        spanClosed = true
        span.end(data)
      }
      // Two passes per burst:
      //   A — accumulate workspace-state captures (providerSessionId).
      //       Apply via ONE setState if anything changed.
      //   B — accumulate runtime mutations (entries, queue,
      //       approval, compaction). Apply via ONE setRuntimes.
      // Splitting them keeps workspace.json in sync with new
      // providerSessionId on the same tick the entries land,
      // without doing N setState calls during a 200-entry burst.

      // ---- Pass A: workspace-state captures ----
      // EVERY registered provider's extractor runs on every line ON
      // PURPOSE — deliberately NOT routed by session kind (#394 phase
      // 2c-3). This pass feeds the #290 foreign-transcript
      // quarantine, which must OBSERVE a conflicting provider id even
      // when the line belongs to a different provider than this pane;
      // kind-routing here would blind the conflict detector to
      // exactly the misattach it exists to catch. The extractors are
      // mutually exclusive by wire shape (claude: entry-level
      // sessionId; codex: session_meta payload.id), so cross-matches
      // can't happen; observed-id precedence follows
      // AGENT_PROVIDER_KINDS order, preserving the historical
      // claude-then-codex behavior.
      const capturedIdByKind = new Map<AgentProviderKind, string>()
      for (const { entry: raw } of entries) {
        if (capturedIdByKind.size === AGENT_PROVIDER_KINDS.length) break
        for (const k of AGENT_PROVIDER_KINDS) {
          if (capturedIdByKind.has(k)) continue
          const id = getRendererProviderCapabilities(k).extractProviderSessionId(raw)
          if (id) capturedIdByKind.set(k, id)
        }
      }
      const metaForProviderGate = refs.stateRef.current.sessions[sessionId] ?? null
      const observedProviderSessionId =
        AGENT_PROVIDER_KINDS.map(k => capturedIdByKind.get(k)).find(Boolean) ?? null
      const providerDecision = decideJsonlProviderBurst({
        previous: jsonlProviderStreamBySession.get(sessionId),
        expectedProviderSessionId: resumableProviderSessionId(metaForProviderGate),
        observedProviderSessionId,
      })
      jsonlProviderStreamBySession.set(sessionId, providerDecision.state)
      if (!providerDecision.accept) {
        // WHY this drops data instead of just refusing the metadata update:
        //
        // A duplicated/resumed pane has a durable providerSessionId before the
        // JSONL tailer replays anything. If a later committed burst proves a
        // different provider id, that burst is not "history for this pane" — it
        // is another agent's transcript arriving on this renderer route. The old
        // guard only protected SessionMeta, then still mapped the wrong entries
        // into Feed, which made duplicated agents render each other's messages.
        // The small in-memory sidecar remembers a proven mismatch so follow-up
        // Codex rollout lines without another session_meta stay quarantined until
        // a matching provider id proves the stream recovered.
        console.warn('[workspace] dropping JSONL burst for conflicting providerSessionId', {
          sessionId,
          expectedProviderSessionId: providerDecision.expectedProviderSessionId,
          observedProviderSessionId: providerDecision.observedProviderSessionId,
          reason: providerDecision.reason,
          burstSize: entries.length,
        })
        setRuntimes(prev => {
          const current = prev[sessionId] ?? emptyRuntime()
          return {
            ...prev,
            [sessionId]: appendFeedDebugLog(
              {
                ...current,
                transcriptStatus: 'error',
                transcriptError:
                  `Ignored JSONL from provider session ${providerDecision.observedProviderSessionId ?? 'unknown'} ` +
                  `because this pane is bound to ${providerDecision.expectedProviderSessionId}.`,
              },
              {
                layer: 'STATE',
                kind: 'jsonl_provider_conflict',
                summary: 'dropped JSONL burst from another provider session',
                data: {
                  expectedProviderSessionId: providerDecision.expectedProviderSessionId,
                  observedProviderSessionId: providerDecision.observedProviderSessionId,
                  reason: providerDecision.reason,
                  burstSize: entries.length,
                },
              },
            ),
          }
        })
        closeSpan({
          sessionId,
          burstSize: entries.length,
          dropped: true,
          reason: providerDecision.reason,
        })
        return
      }

      const sessionCwd = metaForProviderGate?.cwd
      const worktreeCwd =
        sessionCwd ??
        refs.latestRuntimesRef.current[sessionId]?.projectDir ??
        ''
      const observedWorktreeProjection = worktreeReconciler.observe(
        sessionId,
        worktreeCwd,
        entries,
        refs.latestRuntimesRef.current[sessionId] ?? emptyRuntime(),
      )
      refreshWorktrees(sessionCwd)

      if (observedProviderSessionId) {
        setState(prev => {
          const meta = prev.sessions[sessionId]
          if (!meta) return prev
          const id = observedProviderSessionId
          if (!id) return prev
          const resolution = applyJsonlProviderSessionId(meta, id)
          if (resolution.status === 'unchanged') {
            return prev
          }
          if (resolution.status === 'conflict') {
            // WHY a conflicting durable id is not auto-adopted:
            //
            // The #290 symptom is not just "missing transcript"; it is a pane
            // becoming attached to the wrong committed provider transcript and
            // then rendering another agent's conversation as if it were its own.
            // Once a resume request or earlier JSONL entry has established a
            // durable identity, a later different id is more likely an ambiguous
            // attach/replay bug than useful recovery data. The one exception is
            // proxy-header state: that is intentionally provisional, so the
            // first JSONL-backed id is allowed to replace it.
            console.warn('[workspace] ignoring conflicting providerSessionId from JSONL', {
              sessionId,
              current: resolution.current,
              incoming: resolution.incoming,
              currentSource: resolution.currentSource,
            })
            return prev
          }
          return {
            ...prev,
            sessions: {
              ...prev.sessions,
              [sessionId]: resolution.meta,
            },
          }
        })
      }

      // ---- Pass B: runtime mutations ----
      // Captured by the updater, committed to claudeQueueBySession after
      // setRuntimes returns. Never written from inside the updater — React may
      // run it twice and the map is the updater's own input.
      let pendingClaudeQueue: ClaudeQueueState | null = null
      setRuntimes(prev => {
        const current = prev[sessionId] ?? emptyRuntime()
        // Transcript observations accumulate on the existing feed-debug log
        // while this pure fold runs. The post-commit outbox effect mirrors only
        // the runtime React actually accepts, so an abandoned updater cannot
        // claim that an optimistic/queued owner was reconciled or released.
        let observationRuntime = current
        const seen = (refs.seenUuidsRef.current[sessionId] ??= new Set())
        // The desktop keeps trimmed tombstones in liveEntryWindow's per-session
        // registry (shared with the trim below and the older-history pager);
        // the admission rule itself is the shared one (committedRecords.ts).
        const seenLedger: CommittedSeenLedger = {
          seen,
          isTrimmed: uuid => isUuidTrimmed(sessionId, uuid),
          releaseTrimmed: uuid => releaseTrimmedUuid(sessionId, uuid),
        }
        const appended: Entry[] = []
        let oldestMarker: string | null = current.historyOldestMarker
        let queuedMessages = current.queuedMessages
        // Attribution bookkeeping is keyed by session and survives bursts; the
        // runtime keeps only the derived `pending` list it paints.
        let claudeQueue = claudeQueueBySession.get(sessionId) ?? createClaudeQueueState()
        let awaitingAssistant = current.awaitingAssistant
        // Computed outside the React updater because the reconciler owns a
        // bounded evidence window. React may invoke an updater more than once;
        // mutating that window here would duplicate an IPC burst just as surely
        // as the old queue-debt bug duplicated queue operations.
        let workActivity = observedWorktreeProjection.workActivity
        let workContext = observedWorktreeProjection.workContext
        // Every distinct Codex user entry in one coalesced burst can reconcile
        // a different optimistic row. A single "last text" slot made the
        // observation stream claim prompt A was released while the product
        // state removed only prompt B, leaving A duplicated beside its durable
        // rollout row. Retain the complete burst set so mutation, rendering,
        // and the Stage 0 evidence all describe the same handoff.
        const reconciledOptimisticTexts = new Set<string>()

        // Reuse the existing map references so downstream consumers
        // that hold them live (Feed contexts) keep working without
        // a re-subscribe. The runtime object itself gets a new
        // top-level reference below so React re-renders.
        const toolUseIndex = current.toolUseIndex
        const toolResultIndex = current.toolResultIndex
        // Accumulates whether any tool_use/tool_result key was inserted or
        // re-pointed during this burst. Drives the `toolIndexVersion` bump
        // below so Feed's tool-index context invalidates memoized rows whose
        // paired result/use just changed in a different entry (feed audit
        // Finding 1). The maps mutate in place, so this flag is the only
        // signal React gets that a cross-entry pairing moved.
        let toolIndexChanged = false

        // Registry-owned transcript mapping (#394 phase 2b).
        //
        // Routing is by SESSION KIND (state.sessions[id].kind), no
        // longer by per-line shape sniffing. WHY: shape sniffing was
        // the fourth hand-synced copy of "what does a codex line look
        // like," and it silently misclassified a third provider's
        // lines as Claude (#394 §4.5). The session kind is the
        // authoritative routing key — one transcript file per session,
        // one provider format per file.
        //
        // Fallback: bursts can land before the session's meta exists
        // (restore races). In that window `mappingKind` is null and we
        // fall back to the old per-line sniff so early codex
        // session_meta lines aren't misrouted. Once meta exists, kind
        // wins — and a SHADOW comparison counts lines where the sniff
        // disagrees with the kind route. Mismatches mean either a
        // #290-class wrong-transcript attach (foreign provider's lines
        // in this session's stream) or discriminator drift; both are
        // exactly what we want visible in feed-debug instead of
        // silently rendering as someone else's conversation.
        //
        // The Codex mapper's rolling turn cursor (formerly the local
        // `codexCurrentTurnId`) is seeded from and persisted back to
        // `codexCurrentTurnIdBySession` after the loop — the cursor
        // must survive across bursts because the authoritative user
        // message that replaces an optimistic prompt can arrive in a
        // later burst with only `payload.turn_id` tying it back.
        const mappingKindRaw = metaForProviderGate?.kind ?? (metaForProviderGate ? DEFAULT_PROVIDER : null)
        const mappingKind: AgentProviderKind | null =
          mappingKindRaw !== null && isAgentProviderKind(mappingKindRaw) ? mappingKindRaw : null
        const mappersByKind = new Map<AgentProviderKind, TranscriptEntryMapper>()
        const mapperFor = (kind: AgentProviderKind): TranscriptEntryMapper => {
          let m = mappersByKind.get(kind)
          if (!m) {
            m = getRendererProviderCapabilities(kind).createTranscriptEntryMapper(
              kind === 'codex' ? codexCurrentTurnIdBySession.get(sessionId) ?? null : null,
            )
            mappersByKind.set(kind, m)
          }
          return m
        }
        let routeShadowMismatches = 0
        let routeShadowSample: string | null = null

        for (const { entry: raw, observation } of entries) {
          // ---- Claude queue-operation branch ----
          // Checked BEFORE the mapper on purpose: queue-operation
          // entries produce NO feed entries (the claude mapper filters
          // them) but carry side effects on queuedMessages /
          // awaitingAssistant that only exist at this live site. The
          // raw-type check is provider-safe — codex rollout lines
          // never carry type 'queue-operation'.
          //
          // All attribution lives in session-runtime/claudeQueue/. This site
          // only forwards evidence to it and reads back the derived list; it
          // must never decide membership itself. See
          // docs/decomposition/claude-queue-reconciliation.md.
          const entryType = (raw as { type?: string }).type
          const shapeSaysCodex = isCodexRolloutEntry(raw)
          // A Pi row (pi-terminal-headless PiSessionRow) always carries its
          // file `line` and a `parentId` key, and the runtime's identity
          // envelope has its own type. Without this, a Pi burst that arrives
          // before the pane's metadata would be routed to the Claude mapper —
          // the silent binary-provider fallthrough #394 warns about.
          const record = raw as Record<string, unknown>
          const shapeSaysPi = record.type === PI_IDENTITY_ENVELOPE_TYPE || (typeof record.line === 'number' && 'parentId' in record)
          const routedKind: AgentProviderKind =
            mappingKind ?? (shapeSaysCodex ? 'codex' : shapeSaysPi ? 'pi' : 'claude')
          if (entryType === 'queue-operation' && routedKind === 'claude') {
            const op = raw as { operation?: string; content?: string; timestamp?: string }
            claudeQueue = applyQueueOperation(claudeQueue, {
              operation: op.operation ?? '',
              content: op.content,
              // Producer clock only. A local Date.now() fallback would make an
              // op record compare unequal to itself on redelivery and defeat
              // the enqueue idempotence guard.
              timestamp: op.timestamp,
            })
            queuedMessages = claudeQueue.pending
            // Force the streaming flag on whenever the queue has
            // items so the streaming card doesn't disappear
            // between turns while CC is draining queued work.
            if (queuedMessages.length > 0) awaitingAssistant = true
            continue
          }

          // ---- Claude legacy-remove identity pass ----
          // Modern remove records carry content directly. Older records do
          // not, but Claude persists the consumed command a few JSONL lines
          // later as attachment/queued_command. Project provider grammar once
          // through the adapter and let the pure queue reconciler join it to
          // bounded remove debt; this live site must never choose a victim.
          const queuedCommand =
            routedKind === 'claude'
              ? decodeClaudeQueuedCommand(raw as Entry)
              : null
          if (queuedCommand !== null && queuedCommand.promptText !== null) {
            const nextClaudeQueue = applyQueuedCommandObservation(claudeQueue, {
              uuid: queuedCommand.uuid,
              mode: queuedCommand.mode,
              text: queuedCommand.promptText,
            })
            // Most modern queued-command attachments carry no legacy remove
            // debt. The pure reconciler deliberately returns the SAME object
            // for that no-op; copying its separately-created empty pending
            // array into queuedMessages would manufacture a React-visible
            // change from nothing and bypass the noChange guard below. Only a
            // real attribution transition owns a new queue array/reference.
            if (nextClaudeQueue !== claudeQueue) {
              claudeQueue = nextClaudeQueue
              queuedMessages = claudeQueue.pending
            }
          }

          // ---- Claude queue identity pass ----
          // A committed `user` entry is how a `dequeue` delivery becomes
          // PROVABLE: 98.5% of them carry the queued item verbatim (measured,
          // testing/fixtures/queue-operations/catalog.md). Feeding them in is
          // what separates this from the guesswork it replaces — without it
          // every dequeue would fall back to the cohort rule.
          //
          // Runs for every provider's entries but is a no-op unless a Claude
          // dequeue debt is outstanding, so there is no codex/opencode cost and
          // no provider branch to keep in sync.
          if (entryType === 'user' && claudeQueue.debt !== null) {
            const text = claudeUserEntryText(raw)
            if (text !== null) {
              claudeQueue = applyCommittedUserEntry(claudeQueue, {
                uuid: (raw as { uuid?: string }).uuid,
                text,
              })
              queuedMessages = claudeQueue.pending
            }
          }

          // ---- Unified mapper routing ----
          if (mappingKind !== null && shapeSaysCodex !== (mappingKind === 'codex')) {
            routeShadowMismatches += 1
            if (!routeShadowSample) {
              routeShadowSample = String((raw as { type?: unknown }).type ?? 'unknown')
            }
          }
          const { entries: mapped, historyMarker: marker } =
            mapperFor(routedKind).map(raw)
          // Marker policy: first KEPT line of the burst anchors older-
          // history pagination. NOTE deliberate unification: the old
          // claude live path recorded the marker before its filter
          // (any uuid-bearing line, even filtered system lines); the
          // bootstrap/older sites only recorded kept lines. Kept-only
          // is now uniform — worst case pagination re-reads a few
          // filtered lines, which the filter drops again.
          if (!oldestMarker && isPaginationAnchor(mapped, marker)) oldestMarker = marker

          // Optimistic-user reconciliation runs for every provider that
          // SEEDS optimistic rows — gate on the capability, not on
          // `routedKind === 'codex'` (the 2026-07-06 opencode duplicate-
          // user-row bug: opencode has usesOptimisticUserEcho:true, so
          // useComposerKeybinds minted the optimistic row, but the
          // codex-literal gate here meant the committed user entry never
          // removed it — one submit, two user rows forever). Claude is
          // false → unchanged; codex is true → unchanged; opencode is
          // true → fixed. The `Codex`-named helpers below are correct
          // for opencode too: addOptimisticCodexUserEntry is the SHARED
          // minting path for all optimistic-echo providers, and the
          // 'optimistic-codex-user:' uuid prefix is the shared marker it
          // stamps regardless of provider.
          if (getRendererProviderCapabilities(routedKind).usesOptimisticUserEcho) {

            // Optimistic-user reconciliation.
            //
            // The optimistic row is appended directly to
            // `current.entries` by addOptimisticCodexUserEntry on
            // submit. It stays there until either (a) the PTY write
            // failed (catch branch in useComposerKeybinds calls
            // removeOptimisticCodexUserEntry) or (b) the committed
            // user entry lands here and this block drops it.
            //
            // WHY two parallel checks, not an if/else:
            //
            // The old implementation only considered the optimistic
            // row when it was the feed tail, or when an optimistic-like
            // entry happened to be the last item appended in this same
            // burst. That was too positional for Codex. In the
            // 2026-04-24 bundle, the authoritative user prompt arrived
            // after three tool-result user rows, so the optimistic row
            // was no longer the tail by the time the real prompt was
            // committed. The optimistic row survived and the same user
            // text rendered twice.
            //
            // The fix is to run both checks independently. They
            // target different data (appended[] is this burst's
            // accumulator; current.entries is the pre-burst state),
            // so there's no logical conflict.
            const firstMapped = mapped[0]
            if (firstMapped?.type === 'user') {
              const mappedText = entryTextContent(firstMapped)
              // Reconcile optimistic prompts by identity, not by tail
              // position. In the captured failure, the optimistic user row
              // stayed visible while Codex committed three tool-result user
              // entries before the real user prompt. A tail-only removal
              // therefore looked at the last tool result, missed the
              // optimistic prompt, and rendered the same user text twice.
              // Restrict this to optimistic Codex user rows so a genuine
              // repeated user prompt remains visible.
              for (let idx = appended.length - 1; idx >= 0; idx -= 1) {
                const item = appended[idx]
                if (
                  isOptimisticCodexUserEntry(item) &&
                  entryTextContent(item) === mappedText
                ) {
                  if (routedKind === 'codex') {
                    observationRuntime = appendCommittedSubmissionReconcile(
                      observationRuntime,
                      item,
                      'exact-text',
                      observation,
                    )
                  }
                  appended.splice(idx, 1)
                  if (mappedText !== null) reconciledOptimisticTexts.add(mappedText)
                }
              }
              const reconciledCurrentEntries = current.entries.filter(entry =>
                isOptimisticCodexUserEntry(entry) &&
                entryTextContent(entry) === mappedText,
              )
              if (reconciledCurrentEntries.length > 0) {
                for (const entry of reconciledCurrentEntries) {
                  if (routedKind === 'codex') {
                    observationRuntime = appendCommittedSubmissionReconcile(
                      observationRuntime,
                      entry,
                      'exact-text',
                      observation,
                    )
                  }
                }
                if (mappedText !== null) reconciledOptimisticTexts.add(mappedText)
              }
              // Mid-turn Codex submits are intentionally kept in
              // queuedMessages instead of appended to entries (see
              // addOptimisticCodexUserEntry). The authoritative rollout
              // user row is the point where that local "queued" feed item
              // must disappear; otherwise the queue surface becomes the new
              // stale-bottom duplicate after the transcript catches up.
              if (queuedMessages.some(q => codexPromptsMatchForOwnership(q.content, mappedText))) {
                // WHY queued prompt reconciliation is normalized:
                // queuedMessages is only a temporary local surface for
                // a mid-turn submit. The authoritative user row comes
                // from Codex rollout, and rollout can differ from the
                // original submit by CRLF normalization, unicode form,
                // or block-join whitespace. Exact matching leaves the
                // queued prompt stuck after the real transcript row has
                // arrived, recreating the stale-bottom artifact this
                // renderer rewrite is meant to eliminate. Preserve the
                // original displayed text in the queue, but compare by
                // the same ownership key we use for render dedupe.
                const reconciledQueuedMessages = queuedMessages.filter(q =>
                  codexPromptsMatchForOwnership(q.content, mappedText),
                )
                for (const queuedMessage of reconciledQueuedMessages) {
                  if (routedKind === 'codex') {
                    observationRuntime = appendQueuedSubmissionReconcile(
                      observationRuntime,
                      queuedMessage,
                      observation,
                    )
                  }
                }
                queuedMessages = queuedMessages.filter(q =>
                  !codexPromptsMatchForOwnership(q.content, mappedText),
                )
                if (mappedText !== null) reconciledOptimisticTexts.add(mappedText)
              }
            }
          }

          // ---- Shared append path (every provider) ----
          // The live rule (#375 part B): dedupe against seen ∪ trimmed, so a
          // resume bootstrapTail replay never re-appends trimmed old rows at
          // the tail — only the older-history loader may bring them back, in
          // order, at the head. Each admitted entry carries this line's
          // pagination marker (a non-enumerable rider, see liveEntryWindow.ts)
          // so the trim below can re-anchor historyOldestMarker at the oldest
          // RETAINED entry. The rule lives in session-runtime/ingest/
          // committedRecords.ts (#1177), which the phone's store runs too.
          //
          // Dedupe order note: the old claude branch added uuids of
          // FILTERED lines to `seen` too (dedupe ran before the
          // conversation filter). The mapper filters first, so
          // filtered lines never reach dedupe — inconsequential,
          // because a re-arriving filtered line is filtered again.
          const admission = admitMappedEntries(mapped, marker, 'live', seenLedger, {
            indexes: { toolUseIndex, toolResultIndex },
          })
          appended.push(...admission.admitted)
          if (admission.toolIndexChanged) toolIndexChanged = true
        }

        const baseEntries = reconciledOptimisticTexts.size > 0
          ? current.entries.filter(entry => {
              const optimisticText = entryTextContent(entry)
              return !(
                isOptimisticCodexUserEntry(entry) &&
                optimisticText !== null &&
                reconciledOptimisticTexts.has(optimisticText)
              )
            })
          : current.entries

        // Track the newest JSONL entry timestamp this session has
        // ever observed. selectMergedEntries uses this to decide
        // whether an orphaned ghost is past the JSONL tail (render —
        // proxy stalled past disk) or covered by it (hide — JSONL
        // kept writing past this ghost, so it's a sidecar leak
        // Claude Code never logs to its rollout). Comparison uses
        // entry.timestamp (ISO 8601 on both Claude and Codex
        // entries), NOT Date.now(), because on resume after a crash
        // we want apples-to-apples wall-clock semantics with ghost
        // _atp.updatedAt — both sides represent "when the producer
        // observed this," so a yesterday-vs-yesterday comparison
        // remains valid even if "now" is hours later.
        //
        // Non-conversation entries that lack `timestamp` (compact
        // boundaries, queue ops) silently pass through the
        // typeof-string guard without moving the cursor. That is
        // the correct behaviour: those entries do not represent a
        // fresh "JSONL is alive" signal at the wall clock the rest
        // of the predicate cares about.
        const lastJsonlEntryAt = latestCommittedTimestamp(current.lastJsonlEntryAt, appended)

        // ---- Usage-limit carrier (#821) ----
        // Claude persists an exhausted-quota turn as an assistant record with
        // `isApiErrorMessage: true` and `error: "rate_limit"`. That is the ONLY
        // durable evidence the renderer gets: no semantic event is emitted for
        // it, and the pane keeps its process (and its "continuing
        // automatically" banner) so nothing else in the runtime changes.
        // Recording the hit lets `isLimitIdle` release the provider-switch
        // guard for exactly these panes (providerSwitchCore.ts).
        //
        // The predicate matches the census: seven local transcripts carry this
        // record and every one of them has both fields
        // (docs/decomposition/evidence/provider-switch/census.md §#820). The
        // literal `rate_limit` code does NOT survive fixture redaction, which
        // is why it is checked against LIVE records here — do not "fix" a
        // fixture test by loosening this to `isApiErrorMessage` alone, which
        // also matches ordinary API failures that have nothing to do with
        // quota.
        //
        // WHY it scans `appended` and not the raw burst: `appended` is the
        // post-dedupe set (uuids already in `seen` never reach it), and a
        // RESUMED pane replays its last ~200 lines through this exact channel
        // (main/sessions/sessionFeedTap.ts). Scanning the burst meant every
        // restart re-detected old carriers — and the census found one session
        // with 63 consecutive rate-limit records, so a replay could re-arm the
        // guard's exception dozens of times for an episode that ended days ago.
        // The Claude mapper passes conversation records through unchanged, so
        // the carrier's own fields survive into `appended`.
        //
        // WHY the timestamp comes from the record and NEVER from the wall
        // clock — the same rule `lastJsonlEntryAt` follows immediately above:
        // `limitHit.at` is compared against `turnStartedAt` to decide whether a
        // pane is parked or working, and stamping a replayed days-old record
        // with `Date.now()` makes it look newer than any turn. A carrier with
        // no parseable timestamp is deliberately ignored rather than stamped
        // with now: an unplaceable event cannot be ordered against a turn, and
        // a wrong order is worse than no signal.
        let limitHitAt: number | null = null
        for (const entry of appended) {
          const record = asRecord(entry)
          if (
            record?.type !== 'assistant' ||
            record.isApiErrorMessage !== true ||
            record.error !== 'rate_limit'
          ) continue
          const ts = record.timestamp
          if (typeof ts !== 'string') continue
          const ms = Date.parse(ts)
          if (!Number.isFinite(ms)) continue
          if (limitHitAt === null || ms > limitHitAt) limitHitAt = ms
        }
        // Monotonic and idempotent: a replayed burst reproduces the same `at`
        // and therefore the same object identity, so the noChange bail below
        // still fires. Only a strictly newer carrier replaces the record.
        const nextLimitHit: SessionRuntime['limitHit'] =
          limitHitAt !== null && (current.limitHit === null || limitHitAt > current.limitHit.at)
            ? { at: limitHitAt, source: 'transcript' }
            : current.limitHit

        // Ghost reconciliation — when authoritative entries land,
        // supersede any live ghost they replace (Claude: message id;
        // Codex: provider item id, #1231; either: tool_use id). Runs per appended entry so ghost→real
        // handoff is synchronous with the entry becoming visible;
        // the ghost drops out of the merged view in the same
        // render as the real entry appears.
        //
        // `reconcileUpstream` is a no-op when there are no ghosts,
        // and returns the same-size Map when no ghost matched, so
        // this is cheap in the common case. Non-conversation
        // entries (system, compact_boundary) pass through
        // untouched.
        let nextGhosts = current.ghosts
        for (const entry of appended) {
          nextGhosts = reconcileUpstream(entry, nextGhosts)
        }

        // Persist the codex mapper's rolling turn cursor across bursts.
        // Only when a codex mapper was actually used this burst — a
        // claude-kind session leaves the map untouched (equivalent to
        // the old read-then-write-back of the same value).
        const codexMapper = mappersByKind.get('codex')
        if (codexMapper) {
          const cursor = codexMapper.getTurnCursor()
          if (cursor === null) {
            codexCurrentTurnIdBySession.delete(sessionId)
          } else {
            codexCurrentTurnIdBySession.set(sessionId, cursor)
          }
        }

        // Queue attribution and React-visible runtime state have different
        // commit boundaries. A legacy content-free remove changes only
        // `removeDebt`: pending membership stays the same and the queue has
        // already forced awaitingAssistant on. That burst is correctly a
        // React no-op, but the NEXT watcher burst needs its debt to join the
        // durable queued-command attachment to the pending item. Capturing the
        // pure state before the no-change return lets the post-updater commit
        // below preserve that invisible handoff without cloning the runtime or
        // forcing a render. Keep the map write outside this updater—React may
        // invoke an updater twice, and reading our own first write would count
        // the same departure twice.
        pendingClaudeQueue = claudeQueue

        // Bail only when literally nothing changed. Approval,
        // queue, and compaction transitions can fire on bursts
        // that don't append any feed entries at all. Include ghost
        // reference equality in the no-change check:
        // reconcileUpstream preserves the same Map reference when
        // no ghost matched, so this only fires setRuntimes when
        // ghosts actually changed. Matches the treatment of
        // queuedMessages and the rest of this guard.
        const ghostsChanged = nextGhosts !== current.ghosts
        const lastJsonlChanged = lastJsonlEntryAt !== current.lastJsonlEntryAt
        // A VALUE comparison, not "a carrier was present": the carrier arrives
        // as an appended entry, so this is normally implied by appended.length
        // — but it must not be able to defeat the bootstrap-burst bail below on
        // every single replay of a transcript that happens to contain one.
        const limitHitChanged = nextLimitHit !== current.limitHit
        const noChange =
          appended.length === 0 &&
          reconciledOptimisticTexts.size === 0 &&
          queuedMessages === current.queuedMessages &&
          awaitingAssistant === current.awaitingAssistant &&
          workContext === current.workContext &&
          workActivity === current.workActivity &&
          !ghostsChanged &&
          !lastJsonlChanged &&
          !limitHitChanged &&
          // A tool-index mutation with no other change must still force a
          // runtime update so the version bump below reaches Feed's context.
          // (In practice toolIndexChanged implies an appended entry, but this
          // keeps the guard honest if that ever stops holding.)
          !toolIndexChanged
        if (noChange) {
          closeSpan({
            sessionId,
            burstSize: entries.length,
            appendedCount: 0,
            changed: false,
          })
          return prev
        }

        const nextEntries = appended.length > 0 || reconciledOptimisticTexts.size > 0
          ? [...baseEntries, ...appended]
          : current.entries

        // ---- Live entries window (#375 part B) ----
        // The live append path above is what used to make `entries`
        // unbounded — bootstrap loads 120, older pages 200, but a long-
        // running agent appends forever. Trim the OLDEST entries back out
        // of the window here (the only place the array grows without a
        // user gesture) once it exceeds EITHER budget: entry count
        // (MAX_LIVE_ENTRIES) or estimated bytes (MAX_LIVE_ENTRY_BYTES —
        // a few hundred entries dragging huge tool_results are the actual
        // #375 pathology, and a count-only cap would never fire on them).
        //
        // Scroll safety: skip while older-history pagination is in flight
        // and for a grace period after a prepend. Feed has no shrink-
        // anchoring — removing rows above the viewport yanks the scroll —
        // and a user who recently paged history in is reading exactly the
        // rows a trim would remove. Skipping is always safe: the window is
        // a memory bound, not an invariant, and the next quiet burst trims.
        //
        // The ledger needs NO notification: its adapter caches are keyed on
        // the entries array REFERENCE, so the sliced array triggers exactly
        // one clean recompute of the committed plane.
        let finalEntries = nextEntries
        let entriesTrimmed = 0
        let trimmedOldestMarker: string | null = null
        let trimProtectBoundMs: number | null = null
        let trimPreTrimBytes: number | null = null
        let trimRetainedBytes: number | null = null
        // Cheap guards first — liveEntryWindowOverBudget walks the window's
        // per-entry byte cache, so it goes last in the &&-chain.
        if (
          !current.loadingOlderHistory &&
          !withinOlderPrependGrace(sessionId) &&
          liveEntryWindowOverBudget(nextEntries)
        ) {
          // Bounds come from CURRENT semantic state (this handler never
          // folds semantic events), POST-reconcile ghosts (a ghost this
          // burst just superseded no longer needs its committed owner
          // protected), and the POST-burst JSONL tail so orphans this burst
          // just passed stop pinning the bound (#724). See planLiveEntryTrim
          // for the constraint set — it returns null whenever trimming would
          // be unsafe.
          const plan = planLiveEntryTrim(nextEntries, current.semantic, nextGhosts, lastJsonlEntryAt)
          if (plan) {
            finalEntries = nextEntries.slice(plan.cut)
            entriesTrimmed = plan.cut
            trimmedOldestMarker = plan.nextOldestMarker
            trimProtectBoundMs = plan.protectBeforeMs
            trimPreTrimBytes = plan.preTrimBytesEstimate
            trimRetainedBytes = plan.retainedBytesEstimate
            markUuidsTrimmed(sessionId, plan.trimmedUuids)
            // Rebuild the tool indices FROM RETAINED ENTRIES ONLY.
            // Per-id deletion is wrong here: the maps hold cross-entry
            // pairings (a retained tool_result row resolves its command
            // via toolUseIndex — ToolResultRow), so deleting a trimmed
            // entry's tool_use id would orphan the retained result row.
            // This rebuild is only PAIR-COMPLETE because the planner's
            // constraint 5 guarantees the boundary never separates a
            // tool pair: every retained tool_result's source tool_use
            // entry is itself retained, so re-indexing the retained
            // window reproduces every pairing a retained row can ask
            // for. If that constraint ever regresses, the symptom is a
            // retained result row silently losing its rich rendering
            // (Read/Edit/git cards degrade to the generic fallback).
            // A wholesale rebuild is O(window) and only runs at trim
            // frequency (~once per 500 appends). In-place clear keeps the
            // stable map references Feed holds through context; the
            // version bump below is what tells React the contents moved.
            toolUseIndex.clear()
            toolResultIndex.clear()
            for (const e of finalEntries) {
              indexEntryIntoMaps(e, toolUseIndex, toolResultIndex)
            }
            toolIndexChanged = true
          }
        }

        const nextRuntimeBase = withDerivedSessionStatus(
          appendFeedDebugLog(
            {
              ...observationRuntime,
              entries: finalEntries,
              // Bump totalEntries by however many real entries just
              // landed via this burst. `appended` is already deduped
              // against the `seen` UUID set seeded from the initial
              // history chunk, so it specifically excludes replay of
              // entries we already counted. The optimistic-reconcile
              // case doesn't need adjustment either: we never counted
              // the optimistic toward totalEntries when it was first
              // pushed (it's a transient UI placeholder), so when the
              // real entry lands and replaces it the total grows by
              // exactly one. The whole point of this field is "how
              // much work has happened on disk" — the ScrollIndicator
              // above the composer reads it as the denominator so the
              // user can tell at a glance how much further the
              // conversation has progressed while they were focused
              // on another pane.
              //
              // The live-window trim NEVER decrements this: totalEntries
              // is the on-disk denominator and `entries` was always
              // documented as a window over it (state.ts). A trim is
              // indistinguishable from "never paged those in".
              totalEntries: current.totalEntries + appended.length,
              // On trim, pagination re-anchors at the oldest RETAINED
              // entry so loadOlderHistory ("strictly before marker") can
              // fetch the trimmed region back from disk.
              historyOldestMarker: entriesTrimmed > 0
                ? trimmedOldestMarker
                : oldestMarker,
              // A marker learned here has no byte position: live frames do
              // not carry offsets and a trim re-anchors on a retained entry
              // whose line position was never recorded. Drop the offset so
              // the next older page takes the loader's marker-only path
              // (slower, terminating) and re-arms the exact cursor from the
              // offsets that page returns. Untouched when the marker is.
              historyOldestOffset: entriesTrimmed > 0 || oldestMarker !== current.historyOldestMarker
                ? null
                : current.historyOldestOffset,
              ...(entriesTrimmed > 0 ? { hasOlderHistory: true } : {}),
              bootstrapping: true,
              queuedMessages,
              awaitingAssistant,
              // A later record proves data arrived, not that a stopped
              // channel or a TUI session mismatch repaired itself.
              transcriptStatus: current.transcriptChannelError ? 'error' : 'ready',
              transcriptError: current.transcriptChannelError ?? null,
              workContext,
              workActivity,
              toolUseIndex,
              toolResultIndex,
              // Bump only on a real map change so bootstrap bursts of
              // already-seen entries don't needlessly invalidate context.
              toolIndexVersion: toolIndexChanged
                ? current.toolIndexVersion + 1
                : current.toolIndexVersion,
              ghosts: nextGhosts,
              lastJsonlEntryAt,
              // Only ever SET here. Clearing belongs to `turn_completed` in the
              // semantic handler: a burst that carries no limit record is not
              // evidence the limit is over (Claude writes 63 consecutive
              // rate-limit records in one session — census RL-6), it is just a
              // burst about something else.
              limitHit: nextLimitHit,
            },
            {
              layer: 'JSONL',
              kind: 'jsonl_entries',
              summary:
                appended.length > 0 || reconciledOptimisticTexts.size > 0
                  ? `entries +${appended.length}${reconciledOptimisticTexts.size > 0 ? ` · reconciled optimistic users ${reconciledOptimisticTexts.size}` : ''}`
                  : 'jsonl side-effects only',
              data: {
                burstSize: entries.length,
                appendedCount: appended.length,
                reconciledOptimisticUser: reconciledOptimisticTexts.size > 0,
                // WHY these counts are more important than they look:
                // optimistic Codex user rows intentionally disappear
                // when the durable rollout user message arrives. In
                // the haunted failure mode, the UI symptom is exactly
                // the same as a correct reconcile ("my optimistic row
                // went away") except the replacement row is missing
                // or filtered. Logging the before/base/appended/after
                // counts lets the next debug trace distinguish a
                // healthy handoff from a removal gap without needing
                // to reproduce under a debugger.
                entryCountBefore: current.entries.length,
                entryCountBaseAfterOptimisticReconcile: baseEntries.length,
                entryCountAfter: nextEntries.length,
                reconciledOptimisticTexts: [...reconciledOptimisticTexts],
                appended: appended.slice(-8).map(summarizeEntryForDebug),
                queuedMessages: queuedMessages.length,
                worktreeReconciliation: worktreeReconciler.summarize({
                  sessionId,
                  cwd: worktreeCwd,
                  projection: { workContext, workActivity },
                }),
                conditions: current.conditions,
                // Shadow route comparison (#394 phase 2b): count of
                // lines this burst where the legacy shape sniff
                // disagreed with the session-kind route. Nonzero means
                // a #290-class foreign-transcript attach or
                // discriminator drift — see the routing comment at the
                // top of this handler.
                routeShadowMismatches,
                routeShadowSampleType: routeShadowSample,
              },
            },
          ),
        )
        // WHY JSONL append does not mark ordinary output unread:
        // transcript entries can arrive many times during a single model
        // turn, and Dispatch's NEW marker is meant to mean "the agent's turn
        // is complete and ready to review." The semantic handler above marks
        // ordinary unread on `turn_completed` / `turn_stopped`; this bulk
        // ingest path only commits durable entries and side effects. Keeping
        // unread out of this path also avoids reviving the old per-append NEW
        // behavior when provider-specific condition handling changes.
        //
        // The trim record is a SEPARATE feed-debug entry (not folded into the
        // jsonl_entries data) so debug bundles stay explainable: "why did the
        // entry count drop by 500 between two bursts" must be answerable by
        // a grep for entries_trimmed, not by diffing burst counts.
        const nextRuntime = entriesTrimmed > 0
          ? appendFeedDebugLog(nextRuntimeBase, {
              layer: 'STATE',
              kind: 'entries_trimmed',
              summary: `live window trimmed ${entriesTrimmed} · ${finalEntries.length} retained`,
              data: {
                trimmedCount: entriesTrimmed,
                retainedCount: finalEntries.length,
                preTrimCount: nextEntries.length,
                // Byte estimates answer "which budget fired": a trim with
                // preTrimCount <= MAX_LIVE_ENTRIES was byte-driven, and
                // retainedBytesEstimate >> TRIM_TO_LIVE_ENTRY_BYTES means
                // the safety constraints stopped it short of the target.
                preTrimBytesEstimate: trimPreTrimBytes,
                retainedBytesEstimate: trimRetainedBytes,
                newOldestMarker: trimmedOldestMarker,
                protectBoundMs: trimProtectBoundMs === null ||
                  !Number.isFinite(trimProtectBoundMs)
                  ? null
                  : trimProtectBoundMs,
                totalEntries: current.totalEntries + appended.length,
              },
            })
          : nextRuntimeBase
        closeSpan({
          sessionId,
          burstSize: entries.length,
          appendedCount: appended.length,
          reconciledOptimisticUser: reconciledOptimisticTexts.size > 0,
          ghostsChanged,
          queuedMessages: queuedMessages.length,
          entriesTrimmed,
        })
        return {
          ...prev,
          [sessionId]: nextRuntime,
        }
      })

      // Commit the queue attribution AFTER setRuntimes returns, exactly once
      // per burst. Doing it inside the updater made the map both the input and
      // the output of a function React may invoke twice, so a re-invocation
      // read its own previous write and double-counted the dequeue debt —
      // retiring an item that was never delivered. See claudeQueueBySession.
      if (pendingClaudeQueue !== null) {
        claudeQueueBySession.set(sessionId, pendingClaudeQueue)
      }

      // Schedule the bootstrap flip. Each burst resets the debounce
      // timer — the phase ends after ~150ms of quiet (long enough
      // to cover a laggy resume replay, short enough that the user
      // doesn't notice a deferred scroll pin).
      const existing = refs.bootstrapTimersRef.current.get(sessionId)
      if (existing) clearTimeout(existing)
      const timer = setTimeout(() => {
        refs.bootstrapTimersRef.current.delete(sessionId)
        setRuntimes(prev => {
          const current = prev[sessionId]
          if (!current || !current.bootstrapping) return prev

          // Reconcile flags that JSONL replay opened but never
          // explicitly closed. Two distinct shapes have been
          // observed in production debug bundles, both producing
          // sessionStatus='running' on rehydrated panes that the
          // user has not touched in days:
          //
          //   1) Claude queue-op replay leaves awaitingAssistant=true.
          //      The queue-op handler in handleBulkJsonl forces
          //      `awaitingAssistant = true` on enqueue (so the
          //      streaming card spans cross-turn queue drain) but
          //      has no symmetric clear on the final dequeue.
          //      During live operation the next `turn_completed` /
          //      `turn_stopped` semantic event clears it via
          //      clearOptimisticAwaiting; during JSONL replay no
          //      semantic events re-fire, so the flag stays true.
          //      Evidence: scripts/diag-stuck-running.mjs against
          //      production debug bundles, Claude case
          //      `sessionStatusSource: "submit"` with
          //      `submittedAt: null` (beginOptimisticSubmit never
          //      ran — only the queue-op path could have set the
          //      flag).
          //
          //   2) Codex rollout replay leaves
          //      semantic.currentTurn open. A rollout-sourced
          //      `turn_started` opens currentTurn, but no matching
          //      `turn_completed`/`turn_stopped` arrives in the
          //      replay stream. Same diagnostic confirms 7+
          //      Codex sessions stuck this way after the user's
          //      last app restart.
          //
          // Why HERE: this callback fires once the bulk-JSONL bursts
          // for a session have been quiet for 150ms — i.e. replay
          // has finished. Reconciling earlier (per-burst) would
          // race a still-streaming live tail; reconciling later
          // (e.g. on idle timer) would let dispatch render
          // 'running' for the entire window. The bootstrap_complete
          // boundary is the natural "replay is done, take stock"
          // seam.
          //
          // Safety: we only reconcile when there's NO live signal
          // (processActive=false AND streamPhase='idle'). If the
          // pane is genuinely mid-turn at the moment the timer
          // fires, processActive will be true (resume spinner) or
          // streamPhase non-idle and we leave state untouched. A
          // resumed-but-genuinely-running pane that briefly drops
          // both signals between events would only get its stuck
          // flag reset for one tick before live events reopen it,
          // which is a far better failure mode than the existing
          // "permanently lying about running for days."
          const hasLiveSignal =
            current.processActive || current.streamPhase !== 'idle'
          const sessionKind = refs.stateRef.current.sessions[sessionId]?.kind
          let next = current
          const reconciled: string[] = []

          if (
            !hasLiveSignal &&
            next.awaitingAssistant &&
            next.queuedMessages.length === 0
          ) {
            next = { ...next, awaitingAssistant: false }
            reconciled.push('awaitingAssistant')
          }

          if (
            shouldClearIdleQueuedMessages({
              // At bootstrap-complete, no live process/stream signal means
              // the optimistic submit owner has already lost its provider
              // evidence. Let the local-queue invariant clear the local row
              // even if `awaitingAssistant` is itself one of the stale replay
              // flags left behind by the same missing rollout handoff.
              awaitingAssistant: false,
              processActive: current.processActive,
              provider: sessionKind,
              queuedMessagesLength: next.queuedMessages.length,
              streamPhase: current.streamPhase,
            })
          ) {
            if (sessionKind === 'codex') {
              next = appendQueuedSubmissionReleases(
                next,
                next.queuedMessages,
                'bootstrap-complete',
              )
            }
            next = { ...next, awaitingAssistant: false, queuedMessages: [] }
            if (!reconciled.includes('awaitingAssistant')) {
              reconciled.push('awaitingAssistant')
            }
            reconciled.push('queuedMessages')
          }

          const currentTurn = next.semantic.currentTurn
          if (
            !hasLiveSignal &&
            isSemanticTurnRunning(currentTurn)
          ) {
            // Mirror the turn_completed close path in foldEvent.ts —
            // archive into history with endedAt stamped, then clear
            // currentTurn. We do NOT call hasPendingSemanticTools()
            // here: that gate exists to keep currentTurn alive while
            // a cross-turn tool_result is in flight, which is a
            // live-only concern. After replay quiesces with no live
            // signal, any pending tool result has already been
            // missed and there's no value in keeping the turn open.
            const closedTurn = {
              ...currentTurn,
              endedAt: currentTurn.endedAt ?? Date.now(),
            }
            next = {
              ...next,
              semantic: {
                ...next.semantic,
                // WHY appendSemanticHistory and not a raw append (#1290):
                // every other archive path replaces by turnId. A replayed
                // turn already in history can reopen as currentTurn (the
                // ledger hides the copy while it is live); a raw append here
                // then held that turn twice, repeating its `sem:T:i`
                // candidate ids and `semantic-block:T:i` React keys.
                // …and never lets a THINNER replay copy displace the archived
                // one (#1391 review a): see archiveReplayedTurn.
                history: archiveReplayedTurn(next.semantic.history, closedTurn),
                currentTurn: null,
              },
            }
            reconciled.push('semantic.currentTurn')
          }

          // withDerivedSessionStatus re-runs the
          //   exited > semantic > process > submit > idle
          // priority chain so sessionStatus matches the cleaned
          // inputs. Without it the runtime would keep the stale
          // 'running' string alongside the cleared inputs.
          const finalized = withDerivedSessionStatus({
            ...next,
            bootstrapping: false,
          })

          return {
            ...prev,
            [sessionId]: appendFeedDebugLog(
              finalized,
              {
                layer: 'STATE',
                kind: 'bootstrap_complete',
                summary: reconciled.length === 0
                  ? 'bootstrap replay quiet window elapsed'
                  : `bootstrap replay closed: ${reconciled.join(', ')}`,
                data: reconciled.length === 0 ? undefined : { reconciled },
              },
            ),
          }
        })
      }, 150)
      refs.bootstrapTimersRef.current.set(sessionId, timer)
      closeSpan({
        sessionId,
        burstSize: entries.length,
        scheduled: true,
      })
    })

    return () => {
      worktreeReconciler.dispose()
      window.clearInterval(orphanSweepTimer)
      window.clearInterval(memoryGaugeTimer)
      if (semanticFlushTimer !== null) window.clearTimeout(semanticFlushTimer)
      for (const timer of transcriptCommitChecks.values()) window.clearTimeout(timer)
      transcriptCommitChecks.clear()
      semanticEventQueue.drain()
      offStarted()
      offInputReadiness()
      offScreen()
      // No singular offEntry() — see the deleted-handler comment
      // above. The bulk path is the only one.
      offEntries()
      offHistoryBoundary()
      offProviderSessionChanged()
      offErr()
      offDiagnostic()
      offProcessState()
      offSemantic()
      offConditions()
      offSubAgents()
      offExit()
      for (const t of refs.bootstrapTimersRef.current.values()) clearTimeout(t)
      refs.bootstrapTimersRef.current.clear()
    }
  }, [appendFeedDebug, feed, refs, setRuntimes, setState, updateRuntime])
}

