import { memo, useMemo, useSyncExternalStore } from 'react'
import { useShallow } from 'zustand/react/shallow'
import { useAppStore } from '@renderer/app-state/hooks'
import { useCodexTranscriptObservationOutbox } from '@renderer/lifecycle/codexTranscriptObservationOutbox'
import { usePickerSanity } from '@renderer/workspace/hook/invalidation/effects'
import type { WorkspaceRefs } from '@renderer/workspace/hook/refs'
import type { WorkspaceState } from '@renderer/workspace/types'
import { useAutoSave } from './useAutoSave'

/** Autosave invalidation belongs to the persistence service, not App's React
 * state. Typing should update one composer and its save deadline, not execute
 * the entire workspace controller just to increment an invisible counter. */
export function createDraftChanges() {
  let version = 0
  const listeners = new Set<() => void>()
  return {
    getSnapshot: () => version,
    subscribe: (listener: () => void) => {
      listeners.add(listener)
      return () => { listeners.delete(listener) }
    },
    bump: () => {
      version++
      for (const listener of listeners) listener()
    },
  }
}

const SessionRuntimeObserver = memo(function SessionRuntimeObserver({ sessionId, pickerCancel }: {
  sessionId: string
  pickerCancel: (sessionId: string) => void
}) {
  const runtime = useAppStore(state => state.workspaceRuntimes[sessionId])
  const snapshot = useMemo(() => runtime ? { [sessionId]: runtime } : {}, [runtime, sessionId])
  // Keep mutation-before-visible-surface chronology: the outbox still flushes
  // in a layout effect. A one-second timer would change forensic ordering.
  useCodexTranscriptObservationOutbox(snapshot)
  usePickerSanity(snapshot, pickerCancel)
  return null
})

export function WorkspaceRuntimeServices({ state, refs, bootstrapComplete, draftChanges, pickerCancel, onSaveHealth }: {
  state: WorkspaceState
  refs: WorkspaceRefs
  bootstrapComplete: boolean
  draftChanges: ReturnType<typeof createDraftChanges>
  pickerCancel: (sessionId: string) => void
  onSaveHealth: (failure: string | null) => void
}) {
  const ids = useAppStore(useShallow(store => Object.keys(store.workspaceRuntimes)))
  const draftVersion = useSyncExternalStore(draftChanges.subscribe, draftChanges.getSnapshot)
  useAutoSave(state, draftVersion, refs, bootstrapComplete, onSaveHealth)
  return <>{ids.map(sessionId =>
    <SessionRuntimeObserver key={sessionId} sessionId={sessionId} pickerCancel={pickerCancel} />,
  )}</>
}

import { useEffect } from 'react'

import type { PersistedWorkspace } from '@renderer/workspace/persistence'

import type {
  WorkspaceSetRuntimes,
  WorkspaceSetState,
} from '@renderer/workspace/hook/context'
import type { WorkspaceRefs } from '@renderer/workspace/hook/refs'

import type { SessionKind } from '@renderer/workspace/types'
import type { SetupCheckResult } from '@shared/types/setup'
import { awaitFirstRunDecision, ensureSetupCheck } from '@renderer/features/setup/store'
import { rehydrateWorkspace } from '@renderer/workspace/hook/persistence/rehydrate'
import { reconcileStuckTranscriptLoads } from '@renderer/workspace/hook/actions/initialHistory'
import * as perf from '@renderer/performance/client'

// #283 auto-heal cadence. After rehydrate, panes whose committed-transcript
// load was dropped mid-flight sit stuck (spinner or empty feed) with nothing
// driving them. We sweep a few times with growing spacing: the first pass
// gives a genuinely slow first load time to finish (the reconciler skips
// in-flight loads), and later passes catch panes that only became stuck once
// their dropped load settled. Detached timers (not awaited) so this never
// delays first paint.
const STUCK_TRANSCRIPT_HEAL_DELAYS_MS = [1500, 4000, 8000]

// Once-only mount effect.
//
// If there's persisted state, respawn every session in its saved
// cwd (minting fresh sessionIds because main process ids are
// ephemeral) and remap the tree to use the new ids. If there's no
// saved state, spawn one default session in the default cwd.
//
// The bootRef guard makes the effect safe under React 18 StrictMode
// (which intentionally runs mount effects twice in dev).

// Bootstrap outcomes that downstream UI cares about. Autosave is only
// allowed on `fresh` (nothing on disk to protect) and `complete-restore`
// (every session respawned). The two failure shapes — `partial-restore`
// and `persisted-fallback` — surface as a banner so the user knows their
// disk state is being protected and that "just keep working" silently
// loses anything they edit until the underlying spawn/proxy issue is
// fixed and the app is restarted.
export type WorkspaceRestoreStatus =
  | 'pending'
  | 'fresh'
  | 'complete-restore'
  | 'partial-restore'
  | 'persisted-fallback'
  | 'bootstrap-error'

export function useBootstrap(
  refs: WorkspaceRefs,
  setState: WorkspaceSetState,
  setRuntimes: WorkspaceSetRuntimes,
  newTab: (cwd: string, resumeSessionId?: string, kind?: SessionKind) => Promise<unknown>,
  setBootstrapComplete: (complete: boolean) => void,
  // Mirrors setBootstrapComplete in lifetime — set once at the end of
  // bootstrap to one of the WorkspaceRestoreStatus values. The composer
  // exposes the value on the Workspace return shape so a banner can
  // render the partial/fallback states without each call site needing
  // to recompute "is autosave actually running right now".
  setRestoreStatus: (status: WorkspaceRestoreStatus) => void,
  // `defaultWorkspaceMode` was a param here until #992 stage 8: the
  // "Default Workspace Mode" setting chose between grid and Dispatch on a
  // fresh install, and there is one layout now. Deleted with the setting.
  // Two more params lived here until the stage became a required field:
  // `enterDispatchMode` (fresh installs could boot into classic Dispatch) and
  // `enterTiledDispatch`, which an `ensureStage` helper called after every
  // boot path to give a workspace a lane grid if it lacked one. Neither is
  // needed: the store's initial state already holds a one-lane stage, newTab
  // fills its empty focused lane with the first agent, and rehydrate
  // publishes the migrated stage in its very first commit. Boot no longer
  // knows that lanes exist.
): void {
  useEffect(() => {
    if (refs.bootRef.current) return
    refs.bootRef.current = true
    void (async () => {
      const bootstrapSpan = perf.span('workspace.bootstrap')
      let canAutosaveBootState = false
      let finalStatus: WorkspaceRestoreStatus = 'bootstrap-error'
      try {
        const json = await perf.measure('workspace.bootstrap.loadWorkspace', () =>
          window.api.loadWorkspace(),
        )
        if (!json) {
          // Fresh install — create one default tab.
          const cwd = await perf.measure('workspace.bootstrap.defaultCwd', () =>
            window.api.defaultCwd(),
          )
          // #995: wait for the setup verdict before choosing what to spawn.
          // This returns at once when any provider is usable; with none, it
          // waits for the user to answer the setup panel (see
          // awaitFirstRunDecision for why spawning underneath it was wrong).
          const setup = await perf.measure('workspace.bootstrap.firstRunDecision', () =>
            awaitFirstRunDecision(),
          )
          try {
            await perf.measure('workspace.bootstrap.initialNewTab', () => openFirstProject(newTab, cwd, setup))
            canAutosaveBootState = refs.latestStateRef.current.tabs.length > 0
            finalStatus = 'fresh'
            // A fresh install lands on ONE row × ONE lane showing its one
            // agent (plan §4.5 — nothing to explain before the first agent
            // exists; growth is user-paced). That shape is the store's
            // initial `freshStage()` plus newTab's empty-lane placement; no
            // step here creates it.
            bootstrapSpan.end({ mode: 'fresh' })
          } catch (err) {
            bootstrapSpan.fail(err, { mode: 'fresh' })
            console.warn('[workspace] initial session spawn failed:', err)
          }
          return
        }
        try {
          // Single-user dev app — no schema versioning. If the load
          // fails for any reason (corrupt JSON, unexpected shape,
          // spawn error during rehydrate) we fall through to the
          // catch below and start fresh. No migrations, no version
          // gates.
          const parsed = JSON.parse(json) as { workspace: PersistedWorkspace }
          const restoreResult = await perf.measure(
            'workspace.bootstrap.rehydrate',
            () =>
              rehydrateWorkspace(
                parsed.workspace,
                refs,
                setState,
                setRuntimes,
                newTab,
              ),
            {
              // v3 files list `projects`; v2 files list `tabs`.
              tabs: (parsed.workspace.projects ?? parsed.workspace.tabs ?? []).length,
              // `?? {}`: a telemetry attribute must not be what throws a
              // restorable workspace into the recovery shell (#1245).
              sessions: Object.keys(parsed.workspace.sessions ?? {}).length,
            },
          )
          canAutosaveBootState =
            restoreResult.complete && refs.latestStateRef.current.tabs.length > 0
          finalStatus = restoreResult.complete ? 'complete-restore' : 'partial-restore'

          // #283 auto-heal: re-drive any pane left stuck (spinner or empty
          // feed) because its transcript load was dropped during rehydrate id
          // churn. Equivalent to the user manually reloading each stuck pane,
          // done automatically. Conservative — a no-op when nothing is stuck.
          for (const delayMs of STUCK_TRANSCRIPT_HEAL_DELAYS_MS) {
            setTimeout(() => {
              reconcileStuckTranscriptLoads({ refs, setRuntimes })
            }, delayMs)
          }
          if (!restoreResult.complete) {
            // WHY partial rehydrate is treated as "view-only until fixed":
            //
            // Rehydrate commits useful partial UI as soon as each session
            // respawns so users are not staring at a blank app while one
            // provider/proxy is wedged. That incremental rendering is good for
            // diagnosis, but it is poisonous as a persistence source: saving a
            // partial layout permanently deletes every pane that failed to
            // respawn during this launch. The packaged app hit exactly that
            // case when proxy startup failed and autosave wrote a 7-session
            // subset over a 13-session workspace.
            //
            // Complete restore is the only moment where the in-memory model is
            // allowed to become authoritative for disk. Until then the previous
            // workspace.json is still the source of truth, and the user can
            // restart after fixing the underlying spawn/proxy problem.
            console.warn('[workspace] rehydrate incomplete; autosave remains disabled:', restoreResult)
          }
          // An imported v2 workspace without a stored lane grid arrives here
          // already on the migration default [2] (seeded) — NOT the fresh
          // [1]: an importing user demonstrably has agents; the second lane
          // is what shows a lane is a slot (plan §6.4). rehydrate published
          // it through migrateWorkspaceToStage.
          bootstrapSpan.end({ mode: 'rehydrate' })
        } catch (err) {
          bootstrapSpan.fail(err, { mode: 'rehydrate' })
          // eslint-disable-next-line no-console
          console.warn('[workspace] load failed, starting fresh:', err)
          const cwd = await perf.measure('workspace.bootstrap.fallbackDefaultCwd', () =>
            window.api.defaultCwd(),
          )
          try {
            // The recovery shell must come up on a machine without the
            // default provider too, so it follows the same readiness verdict.
            // It does not WAIT for the setup panel: a returning user with a
            // broken file needs a surface now, not a first-run question.
            const setup = await ensureSetupCheck()
            await perf.measure('workspace.bootstrap.fallbackNewTab', () => openFirstProject(newTab, cwd, setup))
            finalStatus = 'persisted-fallback'
            // The recovery shell gets the minimal [1] stage by the same route
            // as the fresh path: this is not the user's real workspace, just
            // enough surface to work in while the real file stays protected.
            // WHY this intentionally does NOT unlock autosave:
            //
            // We only reach this path after a persisted workspace existed but
            // could not be parsed or restored. A fallback tab is a recovery UI,
            // not the user's actual workspace. Saving it would replace the
            // previous file with a one-tab workspace and make a transient load
            // failure durable. Fresh installs unlock autosave above because
            // there is no previous disk state to protect; persisted-workspace
            // fallback must leave disk untouched.
          } catch (spawnErr) {
            console.warn('[workspace] fallback session spawn failed:', spawnErr)
          }
        }
      } catch (err) {
        bootstrapSpan.fail(err, { mode: 'bootstrap' })
        console.warn('[workspace] bootstrap failed:', err)
      } finally {
        // Autosave is deliberately locked behind "we have something real to
        // save", not merely "the bootstrap async function returned".
        //
        // Why this guard exists:
        //   A packaged-app launch can fail every session restore (for example
        //   when Proxy Streaming is enabled but mitmproxy cannot start in the
        //   GUI app environment). Before this guard, bootstrap caught the
        //   restore failure, tried a fallback fresh tab, caught that failure
        //   too, and still marked bootstrap complete in `finally`. That
        //   unlocked useAutoSave while Zustand still held the initial empty
        //   workspace (`tabs: []`), overwriting the user's real
        //   ~/.config/agent-code/workspace.json with an empty file.
        //
        // We would rather leave the previous disk state untouched and show a
        // broken in-memory launch than make a transient startup failure
        // durable. Once at least one tab exists, autosave can resume normally.
        if (canAutosaveBootState) {
          setBootstrapComplete(true)
        } else {
          console.warn('[workspace] bootstrap produced no tabs; autosave remains disabled')
        }
        // Publish the final outcome regardless of autosave state, so the
        // banner can distinguish "fresh install, autosave on" from "partial
        // restore, autosave intentionally off". Without this the renderer
        // would have to infer it from absent state.
        setRestoreStatus(finalStatus)
      }
    })()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])
}

/**
 * Opens the first project of a run that has nothing to restore (#995).
 *
 * WHY a terminal is the last resort, after the chosen kind fails: a run with
 * no tabs is the worst outcome bootstrap can produce. It keeps autosave off
 * for the whole run (the no-tabs guard above), and the user faces an empty
 * window with nothing to type into. That is what a clean Mac got before
 * #995: Claude was spawned unconditionally, failed because it was not
 * installed, and left nothing. A terminal needs no provider, and it is where
 * the user runs the install commands the setup panel shows.
 *
 * `setup` null (the check itself failed) keeps the pre-#995 choice, the
 * default provider: an unknown machine is not an empty one.
 */
async function openFirstProject(
  newTab: (cwd: string, resumeSessionId?: string, kind?: SessionKind) => Promise<unknown>,
  cwd: string,
  setup: SetupCheckResult | null,
): Promise<void> {
  const kind = setup?.firstSessionKind
  try {
    await newTab(cwd, undefined, kind)
  } catch (err) {
    if (kind === 'terminal') throw err
    console.warn('[workspace] first project spawn failed; opening a terminal instead:', err)
    await newTab(cwd, undefined, 'terminal')
  }
}

import { useEffect, useRef } from 'react'

import type { SessionId } from '@renderer/workspace/types'
import type { SessionRuntime } from '@renderer/session-runtime/state'

import type { WorkspaceRefs } from '@renderer/workspace/hook/refs'
import { useAppStore } from '@renderer/app-state/hooks'
import { useDevDebugConfig } from '@renderer/features/debug/devDebugConfig'

// Ship runtime feed-debug entries on a fixed cadence, when persistence is enabled (see
// useFeedDebugPersistenceEnabled). The main-side queue writes them to
// STATE_DIR/feed-debug/<sessionId>.jsonl.
//
// `persistedFeedDebugIdRef` tracks the largest feed-debug entry id
// main has confirmed as written. `inFlightFeedDebugIdRef` tracks the
// largest id currently reserved by an unresolved append IPC. We need
// both cursors: persisted-only preserves retry-on-failure, but it
// leaves the same pending entries visible to every render while the
// IPC is still waiting on main-side disk work; in-flight-only would
// suppress retries after a failure. The pair gives us backpressure
// without weakening durability.

export type FeedDebugAppendBatch = {
  entries: SessionRuntime['feedDebugLog']
  maxPendingId: number
  /** Which generation of ids this batch belongs to (#770). Main keys its
   *  de-dup cursor on it, so a soft reload's restart at id 1 is written
   *  instead of being filtered as already-seen. */
  epochMs: number | null
}

export const FEED_DEBUG_FLUSH_INTERVAL_MS = 1000

export function selectFeedDebugAppendBatch(
  runtime: SessionRuntime,
  lastPersistedId: number,
  lastInFlightId: number,
): FeedDebugAppendBatch | null {
  if (runtime.feedDebugLog.length === 0) return null
  if (lastInFlightId > lastPersistedId) return null
  // Most sessions are quiet on any given tick. Their monotonic tail id proves
  // that there is nothing to persist without scanning up to 500 retained rows.
  if (runtime.feedDebugLog[runtime.feedDebugLog.length - 1]!.id <= lastPersistedId) return null
  const pending = runtime.feedDebugLog.filter(entry => entry.id > lastPersistedId)
  if (pending.length === 0) return null
  return {
    entries: pending,
    maxPendingId: pending[pending.length - 1]?.id ?? lastPersistedId,
    epochMs: runtime.feedDebugEpochMs,
  }
}

/**
 * Whether the session is still in the id generation a batch was cut from.
 *
 * WHY the settle handlers ask (#770 follow-up): a soft reload restarts ids at
 * 1 and deletes both cursors, but an append from the OLD generation can still
 * be in flight. When it settles afterwards, `maxPendingId` is an id from the
 * old numbering — writing it into the persisted cursor makes every new entry
 * at or below it look already written, which is #770's silent loss reopened
 * by timing. The epoch is the generation's identity (minted with the first
 * entry, re-minted after a reload), so a stale settle is recognised by it and
 * dropped. Dropping is safe: main keyed that write on the old epoch, and the
 * new generation's entries are sent on their own.
 *
 * A null current epoch means the reload has happened but the new generation
 * has no entries yet — still not the batch's generation.
 */
function isSameGeneration(refs: WorkspaceRefs, sessionId: SessionId, epochMs: number | null): boolean {
  return (refs.latestRuntimesRef.current[sessionId]?.feedDebugEpochMs ?? null) === epochMs
}

/**
 * Whether the feed-debug ring is also written to disk (#767 item 1).
 *
 * WHY off unless diagnostics were asked for: this ran for every session in every build, one IPC
 * and one append per second, up to 128 MiB per session file and 22 % of the debug budget, with no
 * switch at all. The ring itself keeps recording regardless — Save Debug Logs and the Feed Debug
 * panel read the in-memory ring (saveDebugBundle `runtime.feedDebugLog`), not this file — so what
 * the default loses is only the after-crash copy. Either existing switch turns it on:
 * AGENT_CODE_DEV_DEBUG=1 (the developer diagnostics switch) or the "aggressive debug persistence"
 * setting ("keep more debug data on disk"). Turning it on mid-session persists the ring's retained
 * tail on the next tick, since the cursors start at zero.
 */
export function useFeedDebugPersistenceEnabled(): boolean {
  const devDebug = useDevDebugConfig(state => state.enabled)
  const aggressive = useAppStore(state => state.settings.aggressiveDebugPersistence)
  return devDebug || aggressive === true
}

export function useFeedDebugPersist(refs: WorkspaceRefs): void {
  const enabled = useFeedDebugPersistenceEnabled()
  // The CURRENT switch, read by the cleanup below. The cleanup runs both on unmount and when
  // `enabled` flips to false; only the first may flush (review of #1349: turning persistence off
  // still wrote one last batch to disk).
  const enabledRef = useRef(enabled)
  enabledRef.current = enabled
  // The release bookkeeping (see releaseGone) lives in a ref, not in the
  // effect: the effect re-runs whenever persistence is switched on or off,
  // and a set recreated there forgot every id it was tracking, so a pane
  // closed across a persistence toggle was never released (#1392 review c).
  const releaseStateRef = useRef({
    known: new Set<SessionId>(),
    releasing: new Set<SessionId>(),
    seenSinceRelease: new Set<SessionId>(),
  })
  useEffect(() => {
    const flushSession = (sessionId: SessionId, runtime: SessionRuntime): void => {
      if (runtime.feedDebugLog.length === 0) return
      const lastPersistedId = refs.persistedFeedDebugIdRef.current[sessionId] ?? 0
      const lastInFlightId = refs.inFlightFeedDebugIdRef.current[sessionId] ?? 0
      const batch = selectFeedDebugAppendBatch(runtime, lastPersistedId, lastInFlightId)
      if (!batch) return
      const { entries: pending, maxPendingId, epochMs } = batch
      refs.inFlightFeedDebugIdRef.current[sessionId] = maxPendingId
      // Advance the durable cursor ONLY after the IPC append actually
      // resolves. A previous version advanced optimistically before
      // the write, so a transient failure (disk full, IPC timeout,
      // main-process not ready) marked entries as persisted and the
      // next effect pass skipped them forever. The in-flight cursor
      // above is the separate backpressure mechanism: it reserves the
      // pending id range while the IPC is unresolved, then this `.then`
      // makes that reservation durable once main confirms the append.
      //
      // Re-entrancy note: slow disk work can outlive multiple timer ticks
      // and a workspace teardown. We allow only ONE unresolved
      // append per session, not just one append per id range. Sending
      // a newer range while an older range is unresolved would re-open
      // a subtle data-loss case: if the older disk write failed but
      // the newer one succeeded, advancing `persisted` to the newer id
      // would make the failed older entries look durable. Serializing
      // at the renderer keeps retry semantics simple. The NEXT TIMER tick
      // picks up newer entries: immediately draining from `.then` recreates
      // one IPC/write per streaming update whenever disk keeps up. Failures
      // also wait for that tick, so a broken disk cannot cause a retry storm.
      void window.api
        .appendFeedDebugLog({
          sessionId,
          ...(epochMs === null ? {} : { epochMs }),
          entries: pending.map(entry => ({
            id: entry.id,
            ts: entry.ts,
            tMs: entry.tMs,
            layer: entry.layer,
            kind: entry.kind,
            summary: entry.summary,
            data: entry.data,
          })),
        })
        .then(() => {
          if (!isSameGeneration(refs, sessionId, epochMs)) return
          refs.persistedFeedDebugIdRef.current[sessionId] = maxPendingId
          if (refs.inFlightFeedDebugIdRef.current[sessionId] === maxPendingId) {
            delete refs.inFlightFeedDebugIdRef.current[sessionId]
          }
        })
        .catch(err => {
          if (
            isSameGeneration(refs, sessionId, epochMs)
            && refs.inFlightFeedDebugIdRef.current[sessionId] === maxPendingId
          ) {
            delete refs.inFlightFeedDebugIdRef.current[sessionId]
          }
          // eslint-disable-next-line no-console
          console.warn(`[feed-debug ${sessionId.slice(0, 8)}] append failed`, err)
        })
    }

    // Sessions this hook has seen a runtime for. A session whose runtime is
    // gone (pane closed, or replaced by a new id) can never append again, so
    // it is released here: its flush cursors, and main's per-session state
    // (#1392). Main's own forget runs at PROCESS exit, but the pane outlives
    // the process (exit rows, a same-id wake) and its later appends
    // re-created that state with nothing left to forget it.
    //
    // Entries not yet flushed when the runtime was removed are lost, as they
    // were before: this changes only what is forgotten, not what is written.
    //
    // An id leaves `known` only once main has ACKNOWLEDGED the release: a
    // failed IPC is retried on the next tick (#1392 review a, round 3), or
    // main would keep that session's state until the process exits.
    // `releasing` stops a slow acknowledgement from sending it twice.
    //
    // A release covers only the lifetime it was SENT for (#1392 review b,
    // round 4): if the id reappears (and appends, re-creating main's state)
    // while an acknowledgement is still in flight, that late ACK must not
    // retire the later lifetime. `seenSinceRelease` records a reappearance;
    // the ACK then leaves the id in `known`, and the next absence sends a new
    // release.
    //
    // Releasing keeps running while persistence is OFF (#767): a session that
    // appended while persistence was on still has state in main after the
    // user switches persistence off (#1392 review c). The release then tells
    // main not to persist unmarked drops, so it causes no disk write either
    // (review c, round 2).
    //
    // Known residual: a release that fails during the hook's own teardown
    // (workspace unmount) has no later tick to retry it. Main keeps that one
    // session's few numbers until it exits.
    const { known, releasing, seenSinceRelease } = releaseStateRef.current
    const releaseGone = (): void => {
      const runtimes = refs.latestRuntimesRef.current
      for (const sessionId of known) {
        if (runtimes[sessionId] || releasing.has(sessionId)) continue
        delete refs.persistedFeedDebugIdRef.current[sessionId]
        delete refs.inFlightFeedDebugIdRef.current[sessionId]
        releasing.add(sessionId)
        seenSinceRelease.delete(sessionId)
        // Promise.resolve().then: a synchronous throw (a test double without
        // the method) becomes a rejection, retried like any failed release,
        // instead of escaping the interval with `releasing` held.
        void Promise.resolve()
          // Off means no disk writes, including main's final drop marker
          // (#1392 review c, round 2); read at send time, not effect time.
          .then(() => window.api.forgetFeedDebugLog({ sessionId, persistUnmarkedDrops: enabledRef.current }))
          .then(() => { if (!seenSinceRelease.has(sessionId)) known.delete(sessionId) }, () => {})
          .finally(() => releasing.delete(sessionId))
      }
    }

    const flush = (): void => {
      for (const [sessionId, runtime] of Object.entries(refs.latestRuntimesRef.current)) {
        known.add(sessionId)
        if (releasing.has(sessionId)) seenSinceRelease.add(sessionId)
        // Disk writes only while persistence is on; releases always.
        if (enabled) flushSession(sessionId, runtime)
      }
      releaseGone()
    }

    // WHY an interval independent of runtimes: busy agents replace that map
    // dozens of times per second. An effect-triggered flush costs one IPC and
    // filesystem append each time; a debounced effect can instead starve until
    // the stream stops. A fixed timer reads current refs and provides both a
    // write-rate bound and progress for the final record after a quiet turn.
    // The ring is best-effort diagnostics, so accepting up to one additional
    // second of loss on abrupt crash is preferable to slowing provider input.
    const timer = window.setInterval(flush, FEED_DEBUG_FLUSH_INTERVAL_MS)
    return () => {
      window.clearInterval(timer)
      // Best effort for ordinary workspace teardown. Existing in-flight writes
      // retain their cursor reservation; never race them with a final batch.
      // Not when persistence was just switched off: the user asked for no
      // more disk writes.
      if (enabledRef.current) flush()
      else releaseGone()
    }
  }, [
    enabled,
    refs.inFlightFeedDebugIdRef,
    refs.latestRuntimesRef,
    refs.persistedFeedDebugIdRef,
  ])
}

